        public bool InitEntityOk = false;
        public bool InitDBOk = false;
        bool ShowInitMsg = true;
        public bool Init()
        {
            ReadGameServerEnableTable();
            CheckSqlConnect();

            GetDBBackUpUserID();

            GetVnpayBankList();
            GetLobbyBonusList();
            GetDBVersionData();
            GetDBLockGameData();
            GetEnergyRateData();

            GetDBLandPlatformData(); //1.先取平台設定
            GetCountrySetting(); //2.先取地區設定
            GetDBEntityData();   //3.再取代理商設定
            GetDBUserData();    //4.最後取玩家設定, 這4個順序不可變更
            InitEntityOk = true;

            GetDBMachineData(); //machineDataList 最後要廢掉 //sroptim
            if (ShowInitMsg) Console.WriteLine("Init:G 1");
            InitGameInstanceTable(); //sroptim
            if (ShowInitMsg) Console.WriteLine("Init:G 2");

            RankEventProcInit(); //#250924 排行榜 開機取DB值
            if (ShowInitMsg) Console.WriteLine("Init:G 3");

            GetAnnouncementInfo();
            GetCustomerInfo();
            GetDBAnnouncePostTable(); //#250325 公告訊息

            GetDBUserSessionAccount();
            GetDBJPSettingData();

            GetLobbyMode();
            GetUserGameData();
            GetDBjpCountDataData();
            GetDBTopBoardSetting();

            if (ShowInitMsg) Console.WriteLine("Init:G 4");
            #region Load GameSetting
            #region Arcades
            if (IsGameServerEnable(GameServerCode.XiyouGame))
            {
                GetDBXiyouGlobalSetting();  //先Load GlobalSetting
                GetDBXiyouGameSettingData(); //再Load GameSetting
                GetXiyouAccountData();
                GetXiyouAccountDetailData();
            }

            if (IsGameServerEnable(GameServerCode.AstonMartin))
            {
                GetDBAstonMartinGlobalSetting();
                GetDBAstonMartinGameSettingData();
                GetAstonMartinAccountData();
                GetAstonMartinAccountDetailData();
            }

            if (IsGameServerEnable(GameServerCode.BMW3D))
            {
                GetDBBmw3DGlobalSetting();
                GetDBBmw3DGameSettingData();
                GetBmw3DAccountData();
                GetBmw3DAccountDetailData();
            }

            if (IsGameServerEnable(GameServerCode.Ferrari))
