        static GameServerCode GetGameServerCode(string mode)
        {
            //if (mode != string.Empty && Enum.TryParse(mode, true, out FreeTrigMode result)) // 第二個參數設為 true 表示忽略大小寫
            if (mode != string.Empty && Enum.TryParse(mode, out GameServerCode result))
            {
                return result;
            }
            else
            {
                return GameServerCode.None; // 預設值
            }
        }
        /// <summary>是註解行</summary>
        static bool IsCommLine(string line)
        {
            if (string.IsNullOrEmpty(line)) return true;
            char ch = line.SkipWhile(char.IsWhiteSpace).FirstOrDefault();
            if (ch == '/') return true;
            return false;
        }
        static string StripComment(string input)
        {
            if (IsCommLine(input)) return string.Empty;

            int index = input.IndexOf("//");
            if (index >= 0)
            {
                return input.Substring(0, index).Trim();
            }
            return input.Trim();
        }


