        /// <summary>獲取每日 JP 排行榜</summary>
        public void GetDailyJPRanking()
        {
            //#250325 公告訊息
            DateTime yesterday = DateTime.Now.AddDays(-1); //範圍=昨天
            string where = "DATE(Buildtime)=" + "'" + yesterday.ToString("yyyy-MM-dd") + "'";

            var datalist = myAcess.select("JpAccountTable", "*", where);

            if (datalist.Count > 0)
            {
                //MyConsole.WriteLine($"獲取每日 JP 排行榜 DB資料:"); //UNDONE: 公告訊息 TEST

                Dictionary<int, double> playerAccList = new(); //真人
                Dictionary<int, double> botAccList = new();   //機器人

                for (int i = 0; i < datalist.Count; i++)
                {
                    int userUid = Convert.ToInt32(datalist[i]["UserID"]);
                    double TotalWin = Convert.ToDouble(datalist[i]["TotalWin"]);

                    JpLotteryType LotteryType = (JpLotteryType)Convert.ToInt32(datalist[i]["LotteryType"]);

                    if (LotteryType != JpLotteryType.FAKE || AnnouncePostTable.RankingGetMode == 1) //只取真正出的Bonus
                    {
                        if (playerAccList.ContainsKey(userUid))
                        {
                            playerAccList[userUid] += TotalWin;
                        }
                        else
                        {
                            playerAccList.Add(userUid, TotalWin);
                        }
                    }
                    else
                    {
                        if (botAccList.ContainsKey(userUid))
                        {
                            botAccList[userUid] += TotalWin;
                        }
                        else
                        {
                            botAccList.Add(userUid, TotalWin);
                        }
                    }

                    //公告訊息 以下為DEBUG用
                    //int UID = Convert.ToInt32(datalist[i]["UID"]);
                    //string GameName = datalist[i]["GameName"];
                    //string BuildTime = Convert.ToDateTime(datalist[i]["Buildtime"]).ToString("yyyy/MM/dd HH:mm:ss");
                    //int award = Convert.ToInt32(datalist[i]["JpAward"]);
                    //string JPType = datalist[i]["JpType"];
                    //JpLotteryType LotteryType = (JpLotteryType)Convert.ToInt32(datalist[i]["LotteryType"]);
                    //JpLotteryCast LotteryCast = (JpLotteryCast)Convert.ToInt32(datalist[i]["LotteryCast"]);
                    //MyConsole.WriteLine($"    ID={UID}, 獎項={award}({JPType}), 贏分={TotalWin}, 遊戲={GameName}, 種類={LotteryType}, 時間={BuildTime}"); //UNDONE: 公告訊息 TEST
                }

                if (playerAccList.Count > 0)
                {
                    List<KeyValuePair<int, double>> sortedList = playerAccList
                                .OrderByDescending(x => x.Value)
                                .ToList();

                    //foreach (var info in sortedList) { MyConsole.WriteLine($"Key: {info.Key}, Value: {info.Value}"); } //Debug

                    List<KeyValuePair<string, string>> rankList = new();

                    for (int i = 0; i < sortedList.Count; i++)
                    {
                        int userUid = sortedList[i].Key;

                        lock (UserDataList)
                        {
                            if (UserDataList.ContainsKey(userUid))
                            {
                                string userName = UserDataList[userUid].Nickname;
                                string win = CountrySetting.TransToDisplayString(sortedList[i].Value);
                                //double win = CountrySetting.TransToDisplayScore(sortedList[i].Value);
                                rankList.Add(new KeyValuePair<string, string>(userName, win));
                            }
                        }
                    }


                    MyConsole.WriteLine($"重新設定公告排行榜:日期[{yesterday.ToString("yyyy-MM-dd")}], 人數[{rankList.Count}]");
                    foreach (var info in rankList)
                    {
                        MyConsole.WriteLine($"    玩家: {info.Key}, 得分: {info.Value}");
                    }


                    AnnouncePostTable.SetRanking(rankList);
                    MyConsole.WriteLine($"  獲取每日公告 JP 排行榜: 完成");
                    return;
                }
                else
                {
                    MyConsole.WriteLine($"  獲取每日公告 JP 排行榜: 無玩家中獎資料!!");
                }
            }
            else
            {
                MyConsole.WriteLine($"  獲取每日公告 JP 排行榜: 無資料!!");
            }

            AnnouncePostTable.SetRanking(new List<KeyValuePair<string, string>>());
        }


        /// <summary>公告解碼測試</summary>
        public void AnnoPostDecodeTest(string annoPostData)
        {
            //用 "#PS#" 分出 "公告設定" 和 "公告資訊"
            string[] basArray = annoPostData.Split(new string[] { "#PS#" }, StringSplitOptions.RemoveEmptyEntries);
            if (basArray.Length < 2)
            {
                return; //Data Error
            }

            //basArray[0] //公告設定
            //basArray[1] //公告資訊
            MyConsole.WriteLine($"解 #PS# 數量 : {basArray.Length}");
            MyConsole.WriteLine($"解 #PS# [0]= {basArray[0]}"); //公告設定
            MyConsole.WriteLine($"解 #PS# [1]= {basArray[1]}"); //公告資訊

            //將 "公告資訊" 以 "#AP#" 分出 各個公告種類
            string[] strArray = basArray[1].Split(new string[] { "#AP#" }, StringSplitOptions.RemoveEmptyEntries);
            if (strArray.Length == 0)
            {
                return;
            }

            Console.WriteLine($"解 #AP# 數量 : {strArray.Length}");
            Console.WriteLine($"解 #AP# [0]= {strArray[0]}");
            Console.WriteLine($"解 #AP# [1]= {strArray[1]}");

            List<AnnoPostInfo> annPostInfoList = new List<AnnoPostInfo>();

            foreach (string str in strArray)
            {
                //以 "\f" 分出各部資訊. 第0個為"種類設定" 第1個之後為各個"語言包"
                string[] strArray2 = str.Split(new string[] { "\f" }, StringSplitOptions.RemoveEmptyEntries);

                if (strArray2.Length > 0)
                {
                    AnnoPostInfo annPostInfo = new AnnoPostInfo();

                    //取得訊息"種類設定". (strArray2[0] )
                    if (annPostInfo.GetAnnoPostPara(strArray2[0]))
                    {
                        //strArray2[1]之後為各個"語言包"
                        for (int i = 1; i < strArray2.Length; i++)
                        {
                            //分出各訊息語言包細項資訊
                            AnnPostLang annPostLang = new AnnPostLang();
                            if (annPostLang.GetAnnPostLang(strArray2[i]))
                            {
                                annPostInfo.LangList.Add(annPostLang);
                            }
                        }

                        if (annPostInfo.LangList.Count > 0 || annPostInfo.Type == 2) //有語言包才加入 or "登入公告"
                        {
                            annPostInfoList.Add(annPostInfo);
                        }
                    }
                }
            }


            //除錯用
            Console.WriteLine($"=============== 開始驗證: 公告總類數量={annPostInfoList.Count}");
            int mcnt = 1;
            foreach (AnnoPostInfo annPostInfo in annPostInfoList)
            {
                Console.WriteLine($"第{mcnt}組 : 公告總類={annPostInfo.Type}, 秒數={annPostInfo.DisplayDuration}, 模式={annPostInfo.DisplayMode}, 語言數量={annPostInfo.LangList.Count}");

                int scnt = 1;
                foreach (AnnPostLang annPostLang in annPostInfo.LangList)
                {
                    Console.WriteLine($"第{scnt}種語言 : {annPostLang.LangEm}  行數={annPostLang.Msg.Count}");
                    int xcnt = 1;
                    foreach (string msg in annPostLang.Msg)
                    {
                        //string escapedStr = msg.Replace("\n", "\\n").Replace("\t", "\\t").Replace("\r", "\\r");
                        //Console.WriteLine($"{xcnt}: [{escapedStr}]");
                        Console.WriteLine($"{xcnt}: [{msg}]");
                        xcnt++;
                    }
                    scnt++;
                    if (scnt < annPostInfo.LangList.Count) Console.WriteLine("");
                }
                Console.WriteLine("-----------------");
                mcnt++;
            }
            Console.WriteLine($"=============== 驗證完成!");

            while (true)
            {
                Thread.Sleep(50000);
            }
        }
