        /// <summary>玩家獲取 返水資訊</summary>
        public void GetRebateInfo(UserData userData, EntityData entity, ref Dictionary<string, string> extraInfo)
        {
            //MyConsole.WriteLine($"玩家[{userData.UserID}] 獲取返水資訊 [{entity.CheckRebateEventON().ToString()}], [{entity.RebateValid}] OR [{userData.HasRebateWallet()}] AND [{entity.CheckRebateClaimDate()}]");
            //玩家 獲取返水資訊
            //if (entity.CheckRebateEventON())
            {
                //if (userData.HasRebateWallet() && (entity.CheckRebateClaimDate() || entity.RebateValid)) //(返水錢包有錢) 且 (在領獎期限內 或 在活動期限內)
                //if (entity.CheckRebateClaimDate() && (userData.HasRebateWallet() || entity.RebateValid)) //(在領獎期限內) 且 (返水錢包有錢 或 在活動期限內)
                //if (entity.RebateValid || (userData.HasRebateWallet() && entity.CheckRebateClaimDate())) //(在活動期限內) 或 (在領獎期限內 且 返水錢包有錢)
                {
                    if (entity.CheckRebateEventON())
                    {
                        //以下為 返水設定值
                        extraInfo.Add("RebateStat", "1"); //返水功能狀態
                        //extraInfo.Add("RebatePers", entity.ValidBetsLevelPers(userData.ValidBets).ToString("f2")); //返水%數 改為在返水錢包裡面取值 
                        extraInfo.Add("RebateMinOut", entity.RebateMinOut.ToString()); //最小返水退分限制
                        extraInfo.Add("RebateEventDateSt", entity.RebateEventDateSt.ToString("yyyy/MM/dd") + entity.RebateEventStartTimeStr); //
                        extraInfo.Add("RebateEventDateEnd", entity.RebateEventDateEnd.ToString("yyyy/MM/dd") + entity.RebateEventEndTimeStr); //
                        extraInfo.Add("RebateClaimDateEnd", entity.RebateClaimDateEnd.ToString("yyyy/MM/dd") + entity.RebateEventEndTimeStr); //
                        //extraInfo.Add("RebateStat", entity.RebateValid ? "1" : "0"); //返水功能狀態
                        //extraInfo.Add("RebateOutFg", entity.RebateOut ? "1" : "0"); //返水分數可退款
                        //extraInfo.Add("LockH5Fg", entity.RebateH5 ? "1" : "0"); //鎖H5不可玩
                    }
                    else
                    {
                        extraInfo.Add("RebateStat", "0"); //返水功能狀態
                    }
                    //以下為 返水錢包
                    GetRebateWallet(userData, entity, ref extraInfo);
                }
            }
        }

        /// <summary>玩家獲取 返水錢包 資訊</summary>
        public void GetRebateWallet(UserData userData, EntityData entity, ref Dictionary<string, string> extraInfo)
        {
            if (entity.CheckRebateEventON())
            {
                extraInfo.Add("RebatePers", entity.ValidBetsLevelPers(userData.ValidBets).ToString("f2")); //返水%數

                extraInfo.Add("RebateSeq", userData.GetRebateSeq()); //返水廣播序號
                //extraInfo.Add("CreditRebateFg", userData.CreditRebateFg ? "1" : "0"); //Credit=返水
                //有效押分
                extraInfo.Add("ValidBets", userData.ValidBets.ToString("f4"));

                //當期返水值
                if (userData.ValidBets == 0)
                    extraInfo.Add("CountRebate", "0");
                else
                    extraInfo.Add("CountRebate", userData.CountRebate.ToString("f4"));

                //可領返水值
                double tRebate = userData.Rebate;
                if (entity.RebateSettlementType == 0)
                {
                    tRebate += userData.CountRebate; //即時模式 須加上當期返水
                }
                extraInfo.Add("Rebate", tRebate.ToString("f4"));
            }
            else
            {
                extraInfo.Add("RebateSeq", userData.GetRebateSeq()); //返水廣播序號
                extraInfo.Add("ValidBets", "0");
                extraInfo.Add("CountRebate", "0");
                extraInfo.Add("Rebate", "0");
            }
        }

        /// <summary>檢查返水設定(重讀Entity時呼叫)</summary>
        void RecheckRebateSetting(EntityData entityx)
        {
            if (entityx == null)
            {
                DateTime now = DateTime.Now;

                lock (EntityDataList)
                {
                    foreach (EntityData entity2 in EntityDataList.Values)
                    {
                        bool chgfg1 = entity2.RebateFgChanged();
                        bool chgfg2 = entity2.RebateSettlementTypeChanged();
                        bool chgfg3 = entity2.RebateActionChanged();
                        if (chgfg1 || chgfg2 || chgfg3) //返水開關有變動, 或是結算方式有變動
                        {
                            //重新計算結算日
                            entity2.SetNextSettlementDate(now);
                            //寫入Entity SaveData
                            UpdateDBRebateSaveData(entity2);

                            //若返水設定有變, 加入待結算列表
                            if (chgfg1 || entity2.RebateFg) //返水開關有變動 或是 返水開啟下-結算方式有變動
                            {
                                if (RebateDbFg) MyConsole.WriteLine($"檢查返水設定A: 代理[{entity2.EntityId}({entity2.Name})]結算返水[{chgfg1},{chgfg2},{entity2.RebateFg}]");
                                entity2.SetRebateSettlementFg();
                                AddRebateSettlementList(entity2.EntityId);
                            }
                        }

                        if (entity2.RebateRangeValueChanged())
                        {
                            //投注量%值 變動重算玩家 當期返水值
                            entity2.SetRebateRecountFg();
                            AddRebateSettlementList(entity2.EntityId);
                        }
                    }
                }
            }
            else
            {
                bool chgfg1 = entityx.RebateFgChanged();
                bool chgfg2 = entityx.RebateSettlementTypeChanged();
                bool chgfg3 = entityx.RebateActionChanged();
                if (chgfg1 || chgfg2 || chgfg3) //返水開關有變動, 或是結算方式有變動
                {
                    //重新計算結算日
                    entityx.SetNextSettlementDate(DateTime.Now);
                    //寫入Entity SaveData
                    UpdateDBRebateSaveData(entityx);

                    //若返水設定有變, 加入待結算列表
                    if (chgfg1 || entityx.RebateFg) //返水開關有變動 或是 返水開啟下-結算方式有變動
                    {
                        if (RebateDbFg) MyConsole.WriteLine($"檢查返水設定B: 代理[{entityx.EntityId}({entityx.Name})]結算返水[{chgfg1},{chgfg2},{entityx.RebateFg}]");
                        entityx.SetRebateSettlementFg();
                        AddRebateSettlementList(entityx.EntityId);
                    }
                }

                if (entityx.RebateRangeValueChanged())
                {
                    //投注量%值 變動重算玩家 當期返水值
                    entityx.SetRebateRecountFg();
                    AddRebateSettlementList(entityx.EntityId);
                }
            }
        }

        /// <summary>更新代理商 SaveData</summary>
        void UpdateDBRebateSaveData(EntityData entity)
        {
            int entityId = entity.EntityId;
            string savedata = entity.GetRebateSaveData();

            Dictionary<string, string> updata = new Dictionary<string, string>();
            updata.Add("SaveData", "'" + savedata + "'");
            OperTionDBBox TempOperTionDBBox = new OperTionDBBox(OpertionCode.update1, "Entity", updata, "id", entityId.ToString());
            lock (Program.opertionDBBoxs)
            {
                Program.opertionDBBoxs.Add(TempOperTionDBBox);
            }
        }

        bool CheckSettlementFg = false;
        /// <summary>返水每日程序 (每日零時呼叫一次)</summary>
        public void RebateOverDayProc()
        {
            CheckSettlementFg = false; //每日重新判斷結算日
        }
        /// <summary>各代理返水結算判斷</summary>
        public void RebateSettlementProc()
        {
            if (!InitDBOk) return;
            if (CheckSettlementFg) return; //避免重覆執行

            DateTime now = DateTime.Now;
            TimeOnly SettlementTime = new TimeOnly(EntityData.RebateHour, 0, 0); //中午12:00
            //TimeOnly SettlementTime = new TimeOnly(15, 02, 0); //UNDONE: 改為可設定結算時間
            TimeOnly timeNow = TimeOnly.FromDateTime(now);

            if (timeNow >= SettlementTime) //如果現在時間已經過了結算時間
            {
                if (RebateDbFg) MyConsole.WriteLine("開始今日返水結算作業:");

                List<int> chgEntityList = new List<int>(); //需要變更設定的EntityId清單

                //返水結算
                lock (EntityDataList)
                {
                    foreach (var info in EntityDataList)
                    {
                        EntityData entity = info.Value;

                        if (entity.CheckRebateEventON() == false)
                        {
                            continue;
                        }

                        entity.CheckRebateValidDate(now);

                        if (entity.CheckRebateEventInAction() == false)
                        {
                            continue; //尚未開始
                        }

                        if (entity.CheckRebateClaimDate())
                        {
                            if (entity.CheckRebateSettlementDate(now.Date))
                            {
                                entity.SetNextSettlementDate(now.Date);
                                chgEntityList.Add(info.Key);
                                UpdateDBRebateSaveData(entity);
                                if (RebateDbFg) MyConsole.WriteLine($"  今日返水結算代理[{entity.Name}]");
                            }
                            else if (entity.RebateActionChanged())
                            {
                                UpdateDBRebateSaveData(entity);
                                if (RebateDbFg) MyConsole.WriteLine($"  代理[{entity.Name}]儲存返水狀態");
                            }
                        }
                        else //已過領獎期限
                        {
                            if (entity.CheckRebateFgSave())
                            {
                                entity.SetRebateEventOff();
                                UpdateDBRebateSaveData(entity);
                                ClearEntityAllPlayerRebateAndBroadcast(entity.EntityId);
                                //if (RebateDbFg) 
                                MyConsole.WriteLine($"  已過領獎期限, 清除代理[{entity.Name}({entity.EntityId})]所屬全部玩家返水");
                            }
                        }
                    }
                }

                if (chgEntityList.Count > 0)
                {
                    RebateSettlement(chgEntityList);
                }
                else
                {
                    if (RebateDbFg) MyConsole.WriteLine("  今日返水無代理結算");
                }

                CheckSettlementFg = true;
            }
        }

        /// <summary>指定代理 返水結算</summary>
        void RebateSettlement(List<int> entityList)
        {
            lock (UserDataList)
            {
                foreach (UserData user in UserDataList.Values)
                {
                    if (entityList.Contains(user.EntityId))
                    {
                        bool settfg = user.RebateSettlement(); //結算玩家返水
                        //if(settfg) AddRebateBroadcastPlayerList(user.UserUID);
                        AddRebateBroadcastPlayerList(user.UserUID);
                        AddUserdataUpdateList(user.UserUID);
                    }
                }
            }
        }
        /// <summary>指定代理 返水結算</summary>
        void RebateSettlementEntity(int entityId)
        {
            EntityData entity = GetEntityData(entityId);

            lock (UserDataList)
            {
                int totalCount = 0;
                int updateCount = 0;
                foreach (UserData user in UserDataList.Values)
                {
                    if (user.EntityId == entityId)
                    {
                        totalCount++;
                        double rebate = user.Rebate;
                        double countRebate = user.CountRebate;
                        double validBets = user.ValidBets;

                        if (!entity.RebateFg)
                        {
                            user.ClearValidBets();
                            user.ClearRebat();
                        }
                        else
                        {
                            if (entity.IsRebateSettlementFg)
                            {
                                bool settfg = user.RebateSettlement(); //結算玩家返水
                            }
                            if (entity.IsRebateRecountFg)
                            {
                                if (entity.RebateSettlementType == 0)
                                {
                                    //即時
                                    double rebatePers = entity.ImmedPers();
                                    user.CountImmedRebate(rebatePers);
                                }
                                else
                                {
                                    //週期
                                    double rebatePers = entity.ValidBetsLevelPers(user.ValidBets);
                                    user.CountCountRebate(rebatePers);
                                }
                                //計算當期返水值
                                //if (RebeatDbFg) MyConsole.WriteLine($"  重新計算玩家[{user.UserID}]當期返水值={user.CountRebate}");
                            }
                        }
                        //if(settfg) AddRebateBroadcastPlayerList(user.UserUID);
                        AddRebateBroadcastPlayerList(user.UserUID);

                        if (rebate != user.Rebate ||
                            countRebate != user.CountRebate ||
                            validBets != user.ValidBets) //值有變動才加入更新列表
                        {
                            AddUserdataUpdateList(user.UserUID);
                            updateCount++;
                        }
                    }
                }
                //if (RebateDbFg) 
                MyConsole.WriteLine($"  代理[{entity.Name}]返水結算完成, 玩家總數={totalCount}, 更新玩家數量={updateCount}");
            }

            entity.ResetRebateSettlementRecountFg();
        }

