        /// <summary>Entity返水結算處理程序</summary>
        public void RebateSettlementProcess()
        {
            lock (RebateSettlementEntityList)
            {
                if (RebateSettlementEntityList.Count > 0)
                {
                    int entityId = RebateSettlementEntityList[0];
                    RebateSettlementEntityList.RemoveAt(0);
                    RebateSettlementEntity(entityId);
                    if (RebateDbFg) MyConsole.WriteLine($"返水結算列表處理程序: 代理={entityId}"); //RebateDebug
                }
            }
