        /// <summary>計算玩家返水</summary>
        void CountPlayerRebate(UserData userData, EntityData entity, double totBet)
        {
            //#250807 計算玩家返水
            if (userData.CreditRebateFg)
            {
                if (!entity.RebateValidBets) return; //返水無效投注量
            }

            if (!entity.RebateValid) return; //返水=OFF
            //if (!entity.RebateEventValid) return; //返水活動已過期

            if (entity.RebateSettlementType == 0)
            {
                //即時
                double validBets = userData.CountValidBets(totBet);
                double rebatePers = entity.ImmedPers();
                userData.CountImmedRebate(rebatePers);
            }
            else
            {
                //週期
                double validBets = userData.CountValidBets(totBet);
                double rebatePers = entity.ValidBetsLevelPers(validBets);
                userData.CountCountRebate(rebatePers);
            }
            AddUserdataUpdateList(userData.UserUID);
        }

        /// <summary>玩家提領返水</summary>
        public int JudgeRebateGet(int userUid, out string rewardResult, out double getRebate, ref Dictionary<string, string> rebateInfo)
        {
            getRebate = 0;
            UserData userData = Getuser(userUid);
            var entity = GetEntityData(userData.EntityId);

            if (!entity.CheckRebateClaimDate())
            {
                rewardResult = "E03"; //超過領獎期限
                return -3;
            }

            double tRebate = userData.Rebate;
            if (entity.RebateSettlementType == 0)
            {
                tRebate += userData.CountRebate; //即時模式 領取時須加上當期返水
            }

            if (tRebate < entity.RebateMinOut)
            {
                rewardResult = "E01"; //返水分數不足
                return -1;
            }


            //8/22改為->返水一律不限制
            bool cdRestrictedFg = false;
            //bool cdRestrictedFg = entity.CheckCreditRestricted(); //Credit受限旗號
            //if (cdRestrictedFg != userData.CreditRebateFg) //如果本次取款"受限旗號"和原本不同
            //{
            //    if (userData.UserBalance > 0)
            //    {
            //        rewardResult = "E02"; //玩家Credit為0時才可領取返水.
            //        return -2;
            //    }
            //}

            double balanceBefore = userData.UserBalance; //交易前玩家本地餘額

            if (entity.RebateSettlementType == 0)
            {
                userData.RebateSettlement(); //即時模式 提領前先結算
                //userData.ClearValidBets();
            }

            getRebate = userData.GetRebate(cdRestrictedFg);

            UpdateUserBalance(getRebate, userUid); //更新玩家餘額


            //紀錄"領取返水" (MangerToUserTradeRecord)
            Dictionary<string, string> data = new Dictionary<string, string>();
            data.Add("TradeType", "'PlayerBalanceDeal'");
            data.Add("OperationType", "'Rebate'");
            data.Add("TransactionType", "'4'");
            data.Add("Status", "'Completed'");
            data.Add("StatusValue", "'2'");

            data.Add("OperatorId", "'" + userData.AspNetUserId + "'");
            data.Add("OperatorEntityId", "'" + userData.EntityId.ToString() + "'");
            data.Add("EntityID", "'" + userData.EntityId.ToString() + "'");
            data.Add("UserUID", "'" + userData.UserUID.ToString() + "'");
            data.Add("UserID", "'" + userData.UserID + "'");

            data.Add("BeforeBalance", "'" + balanceBefore.ToString("f4") + "'"); //交易前玩家本地餘額
            data.Add("Amount", "'" + getRebate.ToString("f4") + "'"); //本次交易金額

            DateTime currenttime = DateTime.Now;
            data.Add("SearchIndex", "'" + Program.GetLogSearchIndex(currenttime, userData.UserUID).ToString() + "'");
            data.Add("TimeStamp", Program.GetLogTimeStamp(currenttime).ToString());

            OperTionDBBox TempData = new OperTionDBBox(OpertionCode.insert, "MangerToUserTradeRecord", data);
            lock (Program.opertionDBBoxs)
            {
                Program.opertionDBBoxs.Add(TempData);
            }


            //製作返水資訊 (隨返水結果返還給玩家)
            //rebateInfo.Add("CreditRebateFg", userData.CreditRebateFg ? "1" : "0"); //Credit=返水
            rebateInfo.Add("RebateSeq", userData.GetRebateSeq()); //返水廣播序號
            rebateInfo.Add("ValidBets", userData.ValidBets.ToString("f4")); //有效押分
            rebateInfo.Add("CountRebate", userData.CountRebate.ToString("f4")); //當期返水值
            rebateInfo.Add("Rebate", userData.Rebate.ToString("f4")); //可領返水值

            rewardResult = "OK:" + getRebate.ToString("f4");
            return 0;
        }

        /// <summary>歸零 指定代理商全部玩家 返水, 並廣播給玩家</summary>
        void ClearEntityAllPlayerRebateAndBroadcast(int entityId)
        {
            //歸零LocalCache全部玩家 返水
            lock (UserDataList)
            {
                foreach (UserData user in UserDataList.Values)
                {
                    if (user.EntityId == entityId)
                    {
                        if (user.HasRebateWallet())
                        {
                            user.ClearValidBets();
                            user.ClearRebat();

                            //MyConsole.WriteLine($"歸零玩家[{user.UserID}]返水");

                            AddRebateBroadcastPlayerList(user.UserUID);
                            AddUserdataUpdateList(user.UserUID);
                        }
                    }
                }
            }

            //歸零DB全部玩家 返水
            Dictionary<string, string> updatadata = new Dictionary<string, string>
            {
                { "ValidBets", "0" },
                { "CountRebate", "0" },
                { "Rebate", "0" }
            };
            //updatadata.Add("FirstKeyInOfDay", "0");
            OperTionDBBox TempOperTionDBBox = new OperTionDBBox(OpertionCode.update1, "Usertable", updatadata, "EntityId", entityId.ToString()); //指定EntityId歸零
            lock (Program.opertionDBBoxs)
            {
                Program.opertionDBBoxs.Add(TempOperTionDBBox);
            }
        }
