        /// <summary>大廳幣值格式設定字串</summary>
        public string GetCurrencyLobbySetting(EntityData entity)
        {
            if (entity.LandID == 0 || !LandPlatformDataList.ContainsKey(entity.LandID))
            {
                return CountrySetting.GetCurrencyLobbySetting();
            }

            int dispMode = LandPlatformDataList[entity.LandID].UnitDisplayMode;
            string historyDispMode;
            string creditSwitch;
            if (dispMode == 0)
            {
                //顯示幣值
                historyDispMode = "0;";
                creditSwitch = "3;"; //CreditSwitch=3 固定顯示幣
            }
            else
            {
                //顯示分值
                historyDispMode = "1;";
                creditSwitch = "0;"; //CreditSwitch=0 固定顯示分
            }

            return CountrySetting.LobbyRatio + ";" +
                historyDispMode +
                CountrySetting.HistoryCoinRatio + ";" +
                CountrySetting.HistoryScoreRatio + ";" +
                CountrySetting.HistoryDispDigits + ";" +
                CountrySetting.HistoryScrDispDigits + ";" +
                creditSwitch +
                CountrySetting.CreditDisplayLimit + ";" +
                CountrySetting.CountryNo;
        }
