        public DBCacheData PlayerEnterGameServer(UserData userData, GameServerCode gameServer)
        {
            GameTypeCode gameType = GameServerCodeToGameTypeCode(gameServer);
            userData.ChangeGameServer(gameServer, gameType, 0);
            RemoveFRBBonusPushInfo(userData);

            DBCacheData DbcacheData = new();

            lock (GetGameServerReserveInfolock)
            {
                DbcacheData.UpdataHistoryData = GetGameServerReserveInfo(gameServer, userData.UserUID); //#250620 GameServer保留資料
            }

            //玩家額外資訊 #251112
            DbcacheData.UpdateXiyouAccountDetailData = userData.GetIpInfoEnterGame(gameServer);

            EntityData entity = GetEntityData(userData.EntityId);
            entity.GetEntityExDataEnterGame(DbcacheData.UpdateXiyouAccountDetailData);

            //返水 #260909
            Dictionary<string, string> rebateInfo = new();
            GetRebateInfo(userData, entity, ref rebateInfo);
