        int lastDay = 0; //初始設無效值, 以保證開機時第一次呼叫可以進去
        /// <summary>每日跨日判斷</summary>
        public bool CountryOverDayJudge()
        {
            DateTime nowDay = DateTime.Now;
            if (nowDay.Day == lastDay) return false; //1日判斷1次即可
            lastDay = nowDay.Day;

            DateTime today = nowDay.Date;
            if (today.CompareTo(CountrySetting.BusinessLastResetDate) == 0) return false;//日期相同

            //紀錄本次歸零日期
            CountrySetting.BusinessLastResetDate = today.Date;
            Dictionary<string, string> updatadata2 = new Dictionary<string, string>
            {
                { "BusinessLastResetDate", "'" + CountrySetting.BusinessLastResetDate.ToString("yyyy-MM-dd") + "'" }
            };
            OperTionDBBox TempOperTionDBBoxRD = new OperTionDBBox(OpertionCode.update2, "Country", updatadata2, "UID=1");

            lock (Program.opertionDBBoxs)
            {
                Program.opertionDBBoxs.Add(TempOperTionDBBoxRD);
            }

            return true;
        }


