        /// <summary>取得GameServer保留資料</summary>
        Dictionary<string, string> GetGameServerReserveInfo(GameServerCode gameServer, int userUid)
        {
            var datalist = myAcess.select("GameServerReserveInfo",
                                            "`Machine`,`ReserveInfo`,`Buildtime`",
                                            String.Format("GameServerCode={0} AND UserUid={1}", (int)gameServer, userUid),
                                            "Buildtime DESC", "1");
            if (datalist.Count > 0)
            {
                Dictionary<string, string> reserveInfo = new Dictionary<string, string>();

                //Console.WriteLine($"GetGameServerReserveInfo: 已存在GameServerReserveInfo資料, GameServerCode={gameServer}, UserUid={userUid}"); //Debug Show

                foreach (var data in datalist)
                {
                    foreach (var info in data)
                    {
                        reserveInfo.Add(info.Key, info.Value);
                    }

                    //轉換Buildtime為指定格式
                    //DateTime dateTime = Convert.ToDateTime(data["Buildtime"]);
                    //string formattedDate = dateTime.ToString("yyyy/MM/dd HH:mm:ss");
                    //reserveInfo.Add("Machine", data["Machine"]);
                    //reserveInfo.Add("ReserveInfo", data["ReserveInfo"]);
                    //reserveInfo.Add("Buildtime", formattedDate);

                    break; //只取最新一筆資料
                }

                //foreach (var info in reserveInfo) { Console.WriteLine($"    {info.Key} = {info.Value}"); } //Debug Show

                return reserveInfo;
            }
            return new Dictionary<string, string>(); //無資料則回傳空字典
        }
