        #region 版本資訊
        /// <summary>
        /// 獲取版本號DB資料
        /// </summary>
        public void GetDBVersionData()
        {
            var datalist = myAcess.select("Versiontable", "*");
            if (datalist.Count > 0)
            {
                lock (versionDataList)
                {
                    versionDataList.Clear();
                    GameServerVersionTable.Clear();

                    for (int i = 0; i < datalist.Count; i++)
                    {
                        versionDataList.Add(new VersionData());
                        versionDataList[i].VersionUID = Convert.ToInt32(datalist[i]["VersionUID"]);
                        versionDataList[i].ServerType = datalist[i]["ServerType"];
                        versionDataList[i].Version = datalist[i]["Version"];
                        versionDataList[i].IosVersion = datalist[i]["IosVersion"];
                        versionDataList[i].ServerCode = Convert.ToInt32(datalist[i]["ServerCode"]);

                        //20230410
                        if (versionDataList[i].ServerCode > 0)
                        {
                            if (!GameServerVersionTable.ContainsKey(versionDataList[i].ServerCode))
                            {
                                GameServerVersionTable.Add(versionDataList[i].ServerCode, versionDataList[i].VersionUID);
                            }
                            else
                            {
                                Console.WriteLine("GetDBVersionData:ServerCode Error!");
                            }
                        }
                    }
                }
            }
        }

        /// <summary>
        /// 獲取List中VersionData
        /// </summary>
        /// <param name="type"></param>
        /// <returns></returns>
        public List<VersionData> GetVersionData(VersionCode type)
        {
            List<VersionData> tmepList = new List<VersionData>();
            lock (versionDataList)
            {
                switch (type)
                {
                    case VersionCode.APK:
                        foreach (var temp in versionDataList)
                        {
                            if (temp.VersionUID == 1)
                            {
                                tmepList.Add(temp);
                                break;
                            }
                        }
                        break;
                    case VersionCode.Lobby:
                        foreach (var temp in versionDataList)
                        {
                            if (temp.VersionUID == 2)
                            {
                                tmepList.Add(temp);
                                break;
                            }
                        }
                        break;
                    case VersionCode.押分機:
                        foreach (var temp in versionDataList)
                        {
                            if (temp.VersionUID > 300 && temp.VersionUID < 400)
                                tmepList.Add(temp);
                        }
                        break;
                    case VersionCode.老虎機:
                        foreach (var temp in versionDataList)
                        {
                            if (temp.VersionUID > 400 && temp.VersionUID < 500)
                                tmepList.Add(temp);
                        }
                        break;
                    case VersionCode.捕魚機:
                        foreach (var temp in versionDataList)
                        {
                            if (temp.VersionUID > 500 && temp.VersionUID < 600)
                                tmepList.Add(temp);
                        }
                        break;
                    case VersionCode.AllGames:
                        foreach (var temp in versionDataList)
                        {
                            if (temp.VersionUID > 300)
                                tmepList.Add(temp);
                        }
                        break;
                    case VersionCode.AD:
                        foreach (var temp in versionDataList)
                        {
                            if (temp.ServerType == "AD")
                            {
                                tmepList.Add(temp);
                                break;
                            }
                        }
                        break;
                }
            }

            return tmepList;
        }

        public List<VersionData> GetVersionData(VerVersionCode type)
        {
            List<VersionData> tmepList = new List<VersionData>();
            lock (versionDataList)
            {
                switch (type)
                {
                    case VerVersionCode.APK:
                        foreach (var temp in versionDataList)
                        {
                            if (temp.VersionUID == 1)
                            {
                                tmepList.Add(temp);
                                break;
                            }
                        }
                        break;
                }
            }

            return tmepList;
        }

        /// <summary>
        /// 檢查VersionData
        /// </summary>
        /// <param name="type"></param>
        /// <param name="Count"></param>
        /// <returns></returns>
        public Dictionary<int, string> CheckVersion(VersionCode type, int Count)
        {
            Dictionary<int, string> tempVersion = new Dictionary<int, string>();

            List<VersionData> datas = GetVersionData(type);

            if (datas.Count > 1) //Game使用'VersionUID'key值
            {
                for (int i = 0; i < datas.Count; i++)
                {
                    //tempVersion.Add(datas[i].VersionUID, datas[i].Version + ";" + datas[i].IosVersion);
                    tempVersion.Add(datas[i].ServerCode, datas[i].Version + ";" + datas[i].IosVersion); //改版本Key
                }
            }
            else if (datas.Count > 0) //APK和大廳 使用原本'0'key值
            {
                tempVersion.Add(0, datas[0].Version + ";" + datas[0].IosVersion);
            }

            return tempVersion;
        }

        /// <summary>
        /// 檢查VersionData
        /// </summary>
        /// <param name="type"></param>
        /// <param name="Count"></param>
        /// <returns></returns>
        public Dictionary<int, string> CheckVersion(VerVersionCode type, int Count)
        {
            Dictionary<int, string> tempVersion = new Dictionary<int, string>();

            List<VersionData> datas = GetVersionData(type);

            if (datas.Count > 0)
            {
                tempVersion.Add(0, datas[0].Version + ";" + datas[0].IosVersion);
            }

            return tempVersion;
        }

