        /// <summary>WEB修改CalcSet</summary>
        public bool EditCalcSet(List<string> infoData)
        {
            //infoData[0]=種類 0=網吧 1=玩家
            //infoData[1]=EntityUid 或 UserUid
            //infoData[2]=資料

            if (infoData == null || infoData.Count < 3)
            {
                return false;
            }

            if (int.TryParse(infoData[1], out int uid))
            {
                if (infoData[0] == "0") //網吧
                {
                    return SetDefinitionData(uid, infoData[2]);
                }
                else if (infoData[0] == "1") //玩家
                {
                    UserData user = Getuser(uid);
                    if (user != null)
                    {
                        user.SetCalcSet(infoData[2]);
                        return true;
                    }
                }
            }

            MyConsole.WriteLine($"        重設代理商[玩家]Definition設定 失敗[Type={infoData[0]}, Uid={infoData[1]}]");
            return false;
        }
        /// <summary>重設 指定代理商 玩家機率內定值</summary>
        bool SetDefinitionData(int entityID, string calaSet)
        {
            if (calaSet == null || calaSet.Length == 0)
            {
                return false;
            }

            EntityData entity = null;
            lock (EntityDataList)
            {
                if (EntityDataList.ContainsKey(entityID) == false)
                {
                    return false;
                }

                entity = EntityDataList[entityID];
                entity.SetDefinitionData(calaSet);
                MyConsole.WriteLine($"    重設代理商[{entity.Name}]Definition設定[{calaSet}]");
            }

            //將代理商底下全部玩家重設
            int setCount = 0;
            lock (UserDataList)
            {
                foreach (var user in UserDataList.Values)
                {
                    if (user.EntityId == entityID)
                    {
                        user.SetCalcSet(calaSet);
                        setCount++;
                        if (setCount < 5) MyConsole.WriteLine($"        重設玩家[{user.UserID}]CalcSet設定[{calaSet}]");
                    }
                }
            }
            MyConsole.WriteLine($"        重設玩家CalcSet設定 共[{setCount}]人");
            return true;
        }

        /// <summary>WEB修改玩家CalcData</summary>
        public bool EditCalcData(List<string> infoData)
        {
            //infoData[0]=種類 0=網吧 1=玩家
            //infoData[1]=EntityUid 或 UserUid
            //infoData[2]=資料

            if (infoData == null || infoData.Count < 3)
            {
                return false;
            }

            if (int.TryParse(infoData[1], out int uid))
            {
                string calaData = infoData[2];

                if (infoData[0] == "0") //網吧
                {
                    //將代理商底下全部玩家重設
                    int setCount = 0;
                    lock (UserDataList)
                    {
                        foreach (var user in UserDataList.Values)
                        {
                            if (user.EntityId == uid)
                            {
                                user.SetCalcData(calaData);
                                setCount++;
                                if (setCount < 5) MyConsole.WriteLine($"        重設玩家[{user.UserID}]CalcData設定[{calaData}]");
                            }
                        }
                        MyConsole.WriteLine($"        重設玩家CalcData設定 共[{setCount}]人");
                    }
                    return true;
                }
                else if (infoData[0] == "1") //玩家
                {
                    UserData user = Getuser(uid);
                    if (user != null && user.Usersituation < 2) //玩家遊戲時不可重設
                    {
                        user.SetCalcData(calaData);
                        return true;
                    }
                }
            }

            MyConsole.WriteLine($"        重設玩家CalcData設定 失敗[Type={infoData[0]}, Uid={infoData[1]}]");
            return false;
        }

