        /// <summary>取得代理商客服資訊</summary>
        public string GetEntityServiveInfo(int EntityId)
        {
            if (EntityDataList.ContainsKey(EntityId))
            {
                try
                {

                    string databasename = "";

                    using (StreamReader sr = new StreamReader("SqlConnection.txt"))
                    {
                        String text;

                        while ((text = sr.ReadLine()) != null)
                        {
                            string[] words = text.Split(':');

                            switch (words[0])
                            {
                                case "DBDataBase":
                                    databasename = words[1];
                                    break;
                            }

                            if (databasename != "") break;
                        }

                        sr.Close();
                    }

                    if (databasename == "eekingDB")
                    {
                        var task = EEPay.EEGetSupportToolList();

                        EESupportToolResult result = task.Result;

                        string serverinfo = "";

                        List<string> name = new List<string>();

                        name.Add("telegram");
                        name.Add("whatsapp");
                        name.Add("livechat");
                        name.Add("zalo");
                        name.Add("line");
                        name.Add("skype");
                        name.Add("wechat");

                        for (int i = 0; i < name.Count; i++)
                        {
                            if (i != 0) serverinfo = serverinfo + ";";

                            if (result.data.Where(x => x.supportToolType.ToLower() == name[i]).Count() > 0)
                            {
                                serverinfo = serverinfo + result.data.Where(x => x.supportToolType.ToLower() == name[i]).FirstOrDefault().link;
                            }
                        }

                        return "#" + serverinfo;
                    }
                    else
                    {
                        if (EntityDataList[EntityId].ServiceInfo != null && EntityDataList[EntityId].ServiceInfo != "")
                        {
                            //MyConsole.WriteLine("取得代理商[" + EntityId + "]客服資訊[" + "#" + EntityDataList[EntityId].ServiceInfo + "]");
                            return "#" + EntityDataList[EntityId].ServiceInfo;
                        }
                    }
                }
                catch (Exception ex)
                {
                    return "#";
                }

            }
            //MyConsole.WriteLine("取得代理商[" + EntityId + "]客服資訊失敗");
            return "";
        }

