        /// <summary>進分獎勵解除計算程序</summary>
        void ExtraBonusKeyOutUnlockProc(UserData userData, double totalBet)
        {
            if (CountrySetting.ExtraBonusFg)
            {
                if (userData.KeyInAward && userData.KeyOutLimit)
                {
                    lock (UserDataList)
                    {
                        userData.PlayerPlayTotal += (decimal)totalBet;
                    }

                    if (userData.PlayerPlayTotal >= (decimal)CountrySetting.ExtraBonusKeyOutRL_U ||
                        userData.UserBalance <= CountrySetting.ExtraBonusKeyOutRL_L)
                    {
                        userData.KeyOutLimit = false;
                        UpdateUsertable(userData.UserUID, new Dictionary<string, string> { { "KeyOutLimit", TransBool2String(userData.KeyOutLimit) } });
                    }
                    AddUserdataUpdateList(userData.UserUID);
                }
            }
        }
