        /// <summary>GameServer 取得Entity網吧炒場設定資訊</summary>
        public string GetEntityHypeInfo(int EntityId)
        {
            if (EntityDataList.ContainsKey(EntityId))
            {
                lock (EntityDataList)
                {
                    return EntityDataList[EntityId].GetHypeInfo();
                }
            }
            return "";
        }
        /// <summary>取得Entity網吧炒場當前水庫值</summary>
        public double AskEntityHypeBigWaterValue(int EntityId, double AskMoney, GameServerCode gameSrv)
        {
            if (!EntityDataList.ContainsKey(EntityId))
            {
                return 0; //EntityId Error
            }
            lock (EntityDataList)
            {
                if (EntityDataList[EntityId].HypeFg == false) //開關ON才能取值
                {
                    return 0; //網吧炒場 開關OFF
                }

                if (EntityDataList[EntityId].HypeServerFg) //須判斷Server列表
                {
                    if (EntityDataList[EntityId].HypeServer != null)
                    {
                        if (EntityDataList[EntityId].HypeServer.Contains(gameSrv) == false)
                        {
                            return 0; //不在網吧炒場Server列表
                        }
                    }
                }

                double water = EntityDataList[EntityId].CurrentHypeBigWater;

                if (water < 10 * CountrySetting.CurrencyFactor) //低於10幣就不出了
                {
                    return 0; //水庫餘額不足
                }

                if (AskMoney <= 0) AskMoney = 5000 * CountrySetting.CurrencyFactor; //沒要求金額的話, 限制5000幣

                if (water > AskMoney) water = AskMoney;

                return water;
            }
        }
        /// <summary>取用Entity網吧炒場水庫(從玩家歷程InsertUserGamedata2上傳)</summary>
        public bool TakeEntityHypeBigWater(int EntityId, int UserUID, double hypeBigWaterTake, int GameLogUID, GameServerCode gameServerCode, int MachineUID)
        {
            if (EntityDataList.ContainsKey(EntityId))
            {
                double beforeHypeBigWater;
                double afterHypeBigWater;

                lock (EntityDataList)
                {
                    beforeHypeBigWater = EntityDataList[EntityId].CurrentHypeBigWater;
                    afterHypeBigWater = beforeHypeBigWater - hypeBigWaterTake;

                    //if (afterHypeBigWater < 0) { afterHypeBigWater = 0; }

                    EntityDataList[EntityId].CurrentHypeBigWater = afterHypeBigWater;
                }

                //更新DB水庫值
                UpdataEntityHypeBigWaterDB(EntityId, afterHypeBigWater);

                //寫入HypeBigWaterLog紀錄
                WriteEntityHypeBigWaterLog(EntityId, hypeBigWaterTake, beforeHypeBigWater, afterHypeBigWater, UserUID, GameLogUID, gameServerCode, MachineUID, 1); //1=遊戲
                //MyConsole.WriteLine("網吧炒場水庫Log紀錄: 玩家[" + UserUID + "] 得分=" + hypeBigWaterTake + ", 遊戲=" + gameServerCode); //UNDONE: 網吧炒場水庫Log紀錄
            }
            return false;
        }
        /// <summary>取用Entity網吧炒場水庫(打包上傳)</summary>
        public bool TakeEntityHypeBigWater(HypeBigWater hyInfo, Dictionary<int, int> gameGuidList)
        {
            int EntityId = hyInfo.EntityID;
            if (EntityDataList.ContainsKey(EntityId))
            {
                //if (hyInfo.Type == HypeBigWater.TypeCode.GetBigWater)
                {
                    double hypeBigWaterTake = hyInfo.BigWater; //水庫取用金額(要從水庫扣錢的總金額)
                    double beforeHypeBigWater;
                    double afterHypeBigWater;

                    lock (EntityDataList)
                    {
                        beforeHypeBigWater = EntityDataList[EntityId].CurrentHypeBigWater;
                        afterHypeBigWater = beforeHypeBigWater - hypeBigWaterTake;

                        //if (afterHypeBigWater < 0) { afterHypeBigWater = 0; }

                        EntityDataList[EntityId].CurrentHypeBigWater = afterHypeBigWater;
                    }

                    //更新DB水庫值
                    UpdataEntityHypeBigWaterDB(EntityId, afterHypeBigWater);
                    //MyConsole.WriteLine("網吧炒場水庫Log紀錄: 總得分=" + hypeBigWaterTake);
                    //寫入HypeBigWaterLog紀錄
                    if (hyInfo.UserWin.Count > 0)
                    {
                        //double hypeTotalTake = 0;
                        double playAfterHype = beforeHypeBigWater;

                        foreach (KeyValuePair<int, double> info in hyInfo.UserWin)
                        {
                            int UserUID = info.Key;
                            int GameLogUID;
                            if (gameGuidList.ContainsKey(UserUID)) GameLogUID = gameGuidList[UserUID]; else GameLogUID = 0;

                            double playBeforeHype = playAfterHype;
                            double playWin = info.Value;
                            playAfterHype -= playWin;
                            //hypeTotalTake += playWin;
                            WriteEntityHypeBigWaterLog(EntityId, playWin, playBeforeHype, playAfterHype, UserUID, GameLogUID, hyInfo.GameServer, hyInfo.MachineUID, 1); //1=遊戲
                            //MyConsole.WriteLine("網吧炒場水庫Log紀錄: 玩家[" + UserUID + "] 得分=" + playWin);
                        }

                        //if (hypeTotalTake != hypeBigWaterTake)
                        //{
                        //    MyConsole.WriteLine("網吧炒場水庫Log紀錄有誤: 總得分=" + hypeBigWaterTake);
                        //    //StringBuilder tstr = new StringBuilder();
                        //    foreach (KeyValuePair<int, double> info in hyInfo.UserWin)
                        //    {
                        //        //tstr.AppendLine("  玩家[" + info.Key + "]得分=" + info.Value);
                        //        MyConsole.WriteLine("  玩家[" + info.Key + "]得分=" + info.Value);
                        //    }
                        //}
                    }
                    return true;
                }
            }
            return false;
        }
        /// <summary>計算Entity網吧炒場當前水庫抽放水</summary>
        public bool CountEntityHypeBigWater(int EntityId, double hypeBigWaterBase, double bigWaterLimit)
        {
            if (EntityDataList.ContainsKey(EntityId))
            {
                double beforeHypeBigWater;
                double afterHypeBigWater;

                lock (EntityDataList)
                {
                    beforeHypeBigWater = EntityDataList[EntityId].CurrentHypeBigWater;
                    afterHypeBigWater = beforeHypeBigWater + hypeBigWaterBase;

                    if (bigWaterLimit > 0 && afterHypeBigWater > bigWaterLimit)
                    {
                        return false; //Over Limit
                    }

                    if (afterHypeBigWater < 0)
                    {
                        afterHypeBigWater = 0;
                    }

                    EntityDataList[EntityId].CurrentHypeBigWater = afterHypeBigWater;
                }

                //更新DB水庫值
                UpdataEntityHypeBigWaterDB(EntityId, afterHypeBigWater);
                //寫入HypeBigWaterLog紀錄
                WriteEntityHypeBigWaterLog(EntityId, hypeBigWaterBase, beforeHypeBigWater, afterHypeBigWater, 0); //0=網頁
                return true;
            }
            return false; //No Entity
        }
        /// <summary>更新Entity網吧炒場DB水庫值</summary>
        public void UpdataEntityHypeBigWaterDB(int EntityId, double currentHypeBigWater)
        {
            Dictionary<string, string> updata = new Dictionary<string, string>();
            updata.Add("CurrentHypeBigWater", currentHypeBigWater.ToString());

            //OperTionDBBox TempOperTionDBBox = new OperTionDBBox(OpertionCode.update1, "Entity", updata, "id", "'" + EntityId + "'");
            OperTionDBBox TempOperTionDBBox = new OperTionDBBox(OpertionCode.update1, "Entity", updata, "id", EntityId.ToString());
            lock (Program.opertionDBBoxs)
            {
                Program.opertionDBBoxs.Add(TempOperTionDBBox);
            }
        }
        /// <summary>寫入Entity網吧炒場水庫Log紀錄</summary>
        public void WriteEntityHypeBigWaterLog(int EntityId, double WaterValue, double BeforeHypeBigWater, double AfterHypeBigWater, int Type)
        {
            int userUID = 0;
            int gameLogUID = 0;
            GameServerCode serverCode = GameServerCode.None;
            int machineUid = 0;
            WriteEntityHypeBigWaterLog(EntityId, WaterValue, BeforeHypeBigWater, AfterHypeBigWater, userUID, gameLogUID, serverCode, machineUid, Type);
        }
        /// <summary>寫入Entity網吧炒場水庫Log紀錄</summary>
        public void WriteEntityHypeBigWaterLog(int EntityId, double WaterValue, double BeforeHypeBigWater, double AfterHypeBigWater, int UserUID, int GameLogUID, GameServerCode GameServerCode, int MachineUid, int Type)
        {
            Dictionary<string, string> updata = new Dictionary<string, string>();
            updata.Add("EntityId", EntityId.ToString());
            updata.Add("WaterValue", WaterValue.ToString());
            updata.Add("BeforeHypeBigWater", BeforeHypeBigWater.ToString());
            updata.Add("AfterHypeBigWater", AfterHypeBigWater.ToString());
            updata.Add("UserUID", UserUID.ToString());
            updata.Add("GameLogUID", GameLogUID.ToString());
            updata.Add("Type", Type.ToString()); //操作類型 0網頁 1遊戲
            updata.Add("GameServerCode", ((int)GameServerCode).ToString());
            //updata.Add("MachineUid", MachineUid.ToString());

            OperTionDBBox TempOperTionDBBox = new OperTionDBBox(OpertionCode.insert, "HypeBigWaterLog", updata);
            lock (Program.opertionDBBoxs)
            {
                Program.opertionDBBoxs.Add(TempOperTionDBBox);
            }
        }
        /// <summary>製作Entity網吧炒場資訊封包 (變更炒場旗號)</summary>
        public GameData MakeEntityHypePackSetHypeFg(int EntityId)
        {
            GameData sendData = new GameData();
            sendData.operationCode = OperationCode.HypeBigWater;
            sendData.mHypeBigWater = new HypeBigWater();
            sendData.mHypeBigWater.Type = HypeBigWater.TypeCode.SetHypeFg;
            sendData.mHypeBigWater.EntityID = EntityId;
            sendData.mHypeBigWater.Info = GetEntityHypeInfo(EntityId);
            return sendData;
        }
        /// <summary>製作Entity網吧炒場資訊封包 (要求水庫值)</summary>
        //public GameData MakeEntityHypePackAskBigWater(int EntityId, double AskMoney, int MachUid)
        public GameData MakeEntityHypePackAskBigWater(HypeBigWater hypInfo)
        {
            int EntityId = hypInfo.EntityID;
            double AskMoney = hypInfo.BigWater;
            GameServerCode gameSrv = hypInfo.GameServer;

            double BigWaterValue = AskEntityHypeBigWaterValue(EntityId, AskMoney, gameSrv);

            GameData sendData = new GameData();
            sendData.operationCode = OperationCode.HypeBigWater;
            sendData.mHypeBigWater = new HypeBigWater();
            sendData.mHypeBigWater.Type = HypeBigWater.TypeCode.AskBigWater;
            sendData.mHypeBigWater.BigWater = BigWaterValue;
            sendData.mHypeBigWater.EntityID = EntityId;
            sendData.mHypeBigWater.MachineUID = hypInfo.MachineUID;
            sendData.mHypeBigWater.UserWin = hypInfo.UserWin; //回傳發出要求的玩家
            //MyConsole.WriteLine("機台[" + MachUid + "]取得網吧炒場當前水庫值[" + BigWaterValue + "], EntityID=" + EntityId);
            return sendData;
        }

