        /// <summary>
        /// 獲取使用者DB資料
        /// </summary>
        public void GetDBUserData()
        {
            var datalist = myAcess.select("Usertable", "*");

            if (datalist.Count > 0)
            {
                lock (UserDataList)
                {
                    if (UserDataList.Count > 0) { UserDataList.Clear(); }


                    for (int i = 0; i < datalist.Count; i++)
                    {
                        UserData userData = new UserData();

                        userData.GetDBData(datalist[i], CoinPerStar, out bool upfg);
                        ExpandUserParaData(datalist[i], userData);

                        EntityData entity = GetEntityData(userData.EntityId);
                        userData.RebateGetDBData(datalist[i], entity);

                        lock (UserDataList)
                        {
                            UserDataList.Add(userData.UserUID, userData);
                        }

                        if (upfg)
                        {
                            AddUserdataUpdateList(userData.UserUID); //資料有變, 須寫回DB
                        }
                    }

                    //獲取 各遊戲的玩家個人水庫
                    var datalist2 = myAcess.select("UserBankTable", "*");
                    for (int i = 0; i < datalist2.Count; i++)
                    {
                        int userUid = Convert.ToInt32(datalist2[i]["UserUID"]);
                        if (UserDataList.ContainsKey(userUid))
                        {
                            UserDataList[userUid].SetDBExtraData(datalist2[i]);
                        }
                    }

                    //獲取 玩家每日遊玩遊戲列表
                    var datalist3 = myAcess.select("UserInOutReport", "UserUID,DayPlayGames,IndepDayPlayGames,ExbetDayPlayGames");
                    for (int i = 0; i < datalist3.Count; i++)
                    {
                        int userUid = Convert.ToInt32(datalist3[i]["UserUID"]);
                        if (UserDataList.ContainsKey(userUid))
                        {
                            UserDataList[userUid].GetDBDataDayPlayGames(datalist3[i]["DayPlayGames"], datalist3[i]["IndepDayPlayGames"], datalist3[i]["ExbetDayPlayGames"]);
                        }
                    }

                    InitDemoPlayer(); //#251209
                }
            }
        }

        /// <summary>
        /// 獲取使用者DB資料
        /// </summary>
        public void GetDBBackUpUserID()
        {
            var datalist = myAcess.select("Usertable_Backup", "UserID");

            if (datalist.Count > 0)
            {
                lock (BackUpUserIDList)
