        /// <summary>從資料庫撈出一位新玩家並加入UserDataList</summary>
        private void GetDBSingleUserData(int UserUID)
        {
            var datalist = myAcess.select("Usertable", "*", String.Format("UserUID = {0}", UserUID));

            if (datalist.Count > 0)
            {
                //for (int i = 0; i < datalist.Count; i++)
                {
                    UserData userData = new UserData();

                    userData.GetDBData(datalist[0], CoinPerStar, out bool upfg);
                    ExpandUserParaData(datalist[0], userData);

                    EntityData entity = GetEntityData(userData.EntityId);
                    userData.RebateGetDBData(datalist[0], entity);

                    if (!UserDataList.ContainsKey(userData.UserUID))
                    {
                        lock (UserDataList)
                        {
                            UserDataList.Add(userData.UserUID, userData);
                        }

                        CheckAndAddDemoPlayer(userData);

                        if (upfg)
                        {
                            AddUserdataUpdateList(userData.UserUID); //資料有變, 須寫回DB
                        }
                    }
                }

                //獲取 各遊戲的玩家個人水庫
                var datalist2 = myAcess.select("UserBankTable", "*", String.Format("UserUID = {0}", UserUID));
                if (datalist2.Count > 0)
                {
                    if (UserDataList.ContainsKey(UserUID))
                    {
                        UserDataList[UserUID].SetDBExtraData(datalist2[0]);
                    }
                }
            }
        }

