        public UserData CheckUserID(string memberID, string memberPW)
        {
            lock (UserDataList)
            {
                List<UserData> ResultUser = UserDataList.Values.Where(x => x.UserID.ToLower() == memberID.ToLower() && x.UserPwd.ToLower() == memberPW.ToLower()).ToList();

                if (ResultUser != null)
                {
                    if (ResultUser.Count > 0)
                    {
                        return ResultUser[0]; //有找到玩家且密碼正確
                    }
                }
            }

            return null;
        }

