        /// <summary>
        /// 新增一位玩家
        /// </summary>
        /// <param name="EntityUID"></param>
        /// <param name="OperatorId"></param>
        /// <param name="PlayerID"></param>
        /// <param name="PlayerPwd"></param>
        /// <param name="NickName"></param>
        /// <param name="Balance"></param>
        public int InsertUserData(int EntityUID, string OperatorId, string PlayerID, int Sex, string PlayerPwd, string NickName, string Email, double Balance, string phoneNum, bool CalFg)
        {
            var datalist = new Dictionary<string, string>();

            AddEntityDefaultSetting(EntityUID, ref datalist);

            datalist.Add("EntityId", EntityUID.ToString());
            datalist.Add("AspNetUserId", "'" + OperatorId + "'");
            datalist.Add("UserID", "'" + PlayerID + "'");
            datalist.Add("Sex", "'" + Sex + "'");
            datalist.Add("UserPwd", "'" + PlayerPwd + "'");
            datalist.Add("Nickname", "'" + NickName + "'");
            datalist.Add("Email", "'" + Email + "'");
            datalist.Add("UserBalance", Balance.ToString());
            datalist.Add("PhoneNum", "'" + phoneNum + "'");
            datalist.Add("IsBot", "0");

            if (CalFg) datalist.Add("CalFg", "1");
            else datalist.Add("CalFg", "0");

            try
            {
                int userUID = myAcess.insert("Usertable", datalist);

                if (userUID != 0)
                {
                    GetDBSingleUserData(userUID); //新增玩家 (ApiCreatePlayer)

                    if (Balance > 0)
                    {
                        Dictionary<string, string> info = new Dictionary<string, string>();

                        info.Add("Creadit", Balance.ToString("f2"));
                    }

                    return userUID;
                }
                else
                {
                    return -1;
                }
            }
            catch (Exception e)
            {
                string log = "CacheManeger: 1048";

                Console.WriteLine(log);

                return -1;
            }
        }

        /// <summary>將新增玩家資料裡 加入代理內定值</summary>
        void AddEntityDefaultSetting(int EntityUID, ref Dictionary<string, string> datalist)
        {
            var entityData = myAcess.select("Entity_DefinitionUsertable", "CalcSet,ParaData,RedBonusServer,WaterInServer", $"EntityId={EntityUID}");

            if (entityData != null && entityData.Count > 0)
            {
                if (entityData[0].ContainsKey("ParaData"))
                {
                    datalist.Add("ParaData", "'" + entityData[0]["ParaData"] + "'");
                }

                if (entityData[0].ContainsKey("CalcSet"))
                {
                    datalist.Add("CalcSet", "'" + entityData[0]["CalcSet"] + "'");
                }

                if (entityData[0].ContainsKey("RedBonusServer"))
                {
                    datalist.Add("RedBonusServer", "'" + entityData[0]["RedBonusServer"] + "'");
                }

                if (entityData[0].ContainsKey("WaterInServer"))
                {
                    datalist.Add("WaterInServer", "'" + entityData[0]["WaterInServer"] + "'");
                }
            }
            else
            {
                MyConsole.WriteLine("    Entity_DefinitionUsertable Data Not Found!");
            }
        }

