        // The V2 database transaction has already persisted these fields.  Keep the
        // in-memory cache in sync without scheduling a second Usertable write.
        public void SynchronizeCommittedBatchDepositV2(BatchDepositV2Result result)
        {
            foreach (var detail in result.Details)
            {
                UserData user;
                lock (UserDataList)
                {
                    if (!UserDataList.TryGetValue(detail.UserUID, out user)) continue;
                    user.UserBalance = (double)detail.AfterBalance;
                    user.SessionID = detail.SessionId;
                    if (detail.ExtraBonus > 0)
                    {
                        user.KeyInAward = true;
                        user.KeyOutLimit = true;
                    }

                    //建立玩家新的上升額度 #260821
                    bool isKeyin = detail.OperationMode == BatchDepositV2OperationMode.Deposit;
                    CreateRewardSession(user, isKeyin,  detail.RequestAmount, detail.BeforeBalance);
                }
                UpdateKeyInOutRec(user, (double)detail.RequestAmount);
            }
        }

        public bool TryGetBatchDepositV2BalanceBaseline(int userUid, out double balance,
            out double sessionId, out long baselineFenceId)
        {
            balance = 0;
            sessionId = 0;
            baselineFenceId = 0;

            using (AcquireBatchDepositV2PlayerLocks(new[] { userUid }, TimeSpan.FromSeconds(5)))
            {
                lock (UserDataList)
                {
                    if (!UserDataList.TryGetValue(userUid, out UserData user)) return false;
                    balance = user.UserBalance;
                    sessionId = user.SessionID;
                }

                baselineFenceId = myAcess.ExecuteInReadCommitted(connection =>
                {
                    using (var command = new MySqlCommand(
                        "SELECT COALESCE(MAX(OutboxId), 0) FROM BatchDepositOutboxV2 WHERE UserUID = @userUid",
                        connection))
                    {
                        command.Parameters.AddWithValue("@userUid", userUid);
                        return Convert.ToInt64(command.ExecuteScalar());
                    }
                });
                return true;
            }
        }

        public IDisposable AcquireBatchDepositV2PlayerLocks(IEnumerable<int> userUids, TimeSpan timeout)
        {
            var acquired = new List<object>();
            var started = Stopwatch.StartNew();
            try
            {
                foreach (int userUid in userUids.Distinct().OrderBy(x => x))
                {
                    object playerLock = BatchDepositV2PlayerLocks.GetOrAdd(userUid, _ => new object());
                    TimeSpan remaining = timeout - started.Elapsed;
                    if (remaining <= TimeSpan.Zero || !Monitor.TryEnter(playerLock, remaining))
                        throw new TimeoutException("BatchDepositV2 player lock timeout.");
                    acquired.Add(playerLock);
                }
                return new BatchDepositV2LockScope(acquired);
            }
            catch
            {
                for (int i = acquired.Count - 1; i >= 0; i--) Monitor.Exit(acquired[i]);
                throw;
            }
        }

        internal Dictionary<int, BatchDepositV2PlayerSnapshot> SnapshotBatchDepositV2Players(IEnumerable<int> userUids)
        {
            var result = new Dictionary<int, BatchDepositV2PlayerSnapshot>();
            lock (UserDataList)
            {
                foreach (int userUid in userUids.Distinct())
                {
                    if (!UserDataList.TryGetValue(userUid, out UserData user)) continue;
                    result[userUid] = new BatchDepositV2PlayerSnapshot
                    {
                        UserUid = user.UserUID,
                        UserId = user.UserID,
                        Balance = Convert.ToDecimal(user.UserBalance),
                        ManagerId = user.AspNetUserId,
                        EntityId = user.EntityId,
                        IsBlocked = user.blockFlag,
                        UserSituation = user.Usersituation,
                        KeyInAward = user.KeyInAward,
                        KeyOutLimit = user.KeyOutLimit,
                        CreditRebateFg = user.CreditRebateFg,
                        CanRebateKeyOut = CanRebateKeyOut(user)
                    };
                }
            }
            return result;
        }

        private sealed class BatchDepositV2LockScope : IDisposable
        {
            private List<object> acquiredLocks;
            internal BatchDepositV2LockScope(List<object> acquiredLocks) { this.acquiredLocks = acquiredLocks; }
            public void Dispose()
            {
                List<object> locks = Interlocked.Exchange(ref acquiredLocks, null);
                if (locks == null) return;
                for (int i = locks.Count - 1; i >= 0; i--) Monitor.Exit(locks[i]);
            }
        }

        public int CountBatchDepositV2BalanceDifferences(IReadOnlyDictionary<int, decimal> dbBalances)
        {
            int differences = 0;
            lock (UserDataList)
            {
                foreach (KeyValuePair<int, decimal> dbBalance in dbBalances)
                {
                    if (!UserDataList.TryGetValue(dbBalance.Key, out UserData user) ||
                        Math.Abs(Convert.ToDecimal(user.UserBalance) - dbBalance.Value) > 0.0001m)
                        differences++;
                }
            }
            return differences;
        }

