        /// <summary>歸零玩家 日,週,月 開洗分記錄</summary>
        public void ResetAllUserKeyInOutRec()
        {
            //MyConsole.WriteLine($"UserDailyWork : 玩家每日工作處理");
            DateTime now = DateTime.Now;
            bool isClearWeek = IsFirstDayOfWeek(now);
            bool isClearMonth = IsFirstDayOfMonth(now);

            lock (UserDataList)
            {
                foreach (var temp in UserDataList)
                {
                    temp.Value.ResetPayOutRecDay();
                    temp.Value.ResetDayPlayGames();

                    if (isClearWeek)
                    {
                        temp.Value.ResetPayOutRecWeek();
                    }

                    if (isClearMonth)
                    {
                        temp.Value.ResetPayOutRecMonth();
                    }
                }
            }

            MyConsole.WriteLine($"UserDailyWork : 歸零玩家報告 每日 開洗分記錄");
            OperTionDBBox TempOperTionDBBox = new OperTionDBBox(OpertionCode.update2, "Usertable", UserData.GetResetPayOutRecDayData(), UserData.GetResetPayOutRecDayWhere());
