                MyConsole.WriteLine($"UserDailyWork : 歸零玩家報告 每月 開洗分記錄");
                OperTionDBBox TempOperTionDBBox3 = new OperTionDBBox(OpertionCode.update2, "Usertable", UserData.GetResetPayOutRecMonthData(), UserData.GetResetPayOutRecMonthWhere());
                lock (Program.opertionDBBoxs)
                {
                    Program.opertionDBBoxs.Add(TempOperTionDBBox3);
                }
