            //玩家報告 #251203
            OperTionDBBox TempOperTionDBBoxR1 = new OperTionDBBox(OpertionCode.update2, "UserInOutReport", GetResetPRDay(), GetResetPRDayWhere());
            lock (Program.opertionDBBoxs)
            {
                Program.opertionDBBoxs.Add(TempOperTionDBBoxR1);
            }

            if (isClearWeek)
            {
                OperTionDBBox TempOperTionDBBoxR2 = new OperTionDBBox(OpertionCode.update2, "UserInOutReport", GetResetPRWeek(), GetResetPRWeekWhere());
                lock (Program.opertionDBBoxs)
                {
                    Program.opertionDBBoxs.Add(TempOperTionDBBoxR2);
                }
            }

            if (isClearMonth)
            {
                OperTionDBBox TempOperTionDBBoxR3 = new OperTionDBBox(OpertionCode.update2, "UserInOutReport", GetResetPRMonth(), GetResetPRMonthWhere());
