        /// <summary>更新玩家IP資訊 (玩家遊玩時)</summary>
        public void UpdateUserIpInfo(GameServerCode server, PlayGameMode gameMode, Dictionary<string, string> update, ref List<Dictionary<string, string>> ipInfoReturn)
        {
            try
            {
                int userUid = Convert.ToInt32(update["UserUID"]);
                double totBet = Convert.ToDouble(update["TotalBet"]);
                double totWin = Convert.ToDouble(update["TotalWin"]);

                double waterInTake = Convert.ToDouble(update["WaterInTake"]);
                double waterOutTake = Convert.ToDouble(update["WaterOutTake"]);
                //double redBonusTake = Convert.ToDouble(update["RedBonusTake"]);

                double waterColl = Convert.ToDouble(update["WaterColl"]);
                string calcData = update["CalcData"];
                string calcDataIndep = update["CalcDataIndep"];

                string betAverage = update.ContainsKey("BetAverage") ? update["BetAverage"] : "";
                string resultRec = update.ContainsKey("ResultRec") ? update["ResultRec"] : "";

                string note = update.ContainsKey("Note") ? update["Note"] : "";

                string rewardCacheData = update.ContainsKey("RewardCacheData") ? update["RewardCacheData"] : "";
                string extraInfo = update.ContainsKey("ExtraInfo") ? update["ExtraInfo"] : "";

                int playTimes = 1; //遊玩局數預設為1

                UserData user = null;

                lock (UserDataList)
                {
                    if (UserDataList.ContainsKey(userUid))
                    {
                        user = UserDataList[userUid];
                        user.CountIpInfo(totBet, totWin, playTimes, waterColl, waterInTake, waterOutTake, calcData, calcDataIndep, betAverage, resultRec);
                        user.UpdateRewardCacheData(rewardCacheData, extraInfo, server);
                        AddUserdataUpdateList(userUid);

                        if (user.rewardCacheDataModel != null && user.rewardCacheDataModel.RewardRecordId > 0)
                        {
                            UpdateSession(userUid, user.rewardCacheDataModel, user.UserBalance);
                        }
                    }
                }

                if (user != null)
                {
                    //回傳最新的IP資訊
                    ipInfoReturn.Add(user.GetIpInfoGameResult(server));

                    //玩家抽放水記錄
                    if (waterInTake != 0)
                    {
                        UserPrivateWaterRecord(user.EntityId, userUid, waterInTake, user.WaterInAcc, note, UPWaterRecType.放水取用, server);
                    }

                    //抽水負值為機率抽水
                    if (waterOutTake < 0)
                    {
                        UserPrivateWaterRecord(user.EntityId, userUid, waterOutTake, user.WaterOutAcc, note, UPWaterRecType.機率抽水, server);
                    }

                    //玩家遊戲報告 #260211 從 InsertUserGamedata2 移過來 (此處只有新版機率會進來)
                    GameTypeCode gameTypeCode = GameServerCodeToGameTypeCode(server);
                    PlayerReportBet(userUid, totBet, totWin, 1, gameTypeCode, gameMode);
                    PlayerReportBetOddsRatio(userUid, totBet, totWin, gameTypeCode, gameMode);
                    PlayerReportGameList(user, server, gameMode);
                }
            }
            catch (Exception e)
            {
                string log = $"UpdateUserIpInfo [{server}] Error: 1513";
                Console.WriteLine(log);
            }
        }

        /// <summary>開分時 建立玩家新的上升額度</summary>
        public void CreateRewardSession(UserData Userdata, bool isKEYIN, decimal _dealAmount, decimal _beforeBalance)
        {
            //#260821
            int userUid = Userdata.UserUID;
            double dealAmount = Convert.ToDouble(_dealAmount);
            double beforeBalance = Convert.ToDouble(_beforeBalance);
            //建立玩家新的上升額度 Session上升額度
            if (isKEYIN)
            {
                RewardCacheDataModel rewardCacheData = CreateSession(Userdata, userUid, dealAmount, beforeBalance, Userdata.RewardWebSetting);
                Userdata.CreateNewRewardCacheData(rewardCacheData, dealAmount);
                AddUserdataUpdateList(userUid);
            }
            else //is KeyOut
            {
                if (Userdata.rewardCacheDataModel.RewardRecordId > 0)
                {
                    RecordKeyOut(userUid, Userdata.rewardCacheDataModel.RewardRecordId, -dealAmount, beforeBalance);
                }
            }
        }

