                    //反還最新的IP資訊
                    //var retData = user.GetIpInfoGameResult(server);
                }
            }
        }

        /// <summary>WEB變更代理設定 處理程序</summary>
        public bool ChangeEntityIdSettingProc(List<string> settingInfo)
        {
            //Entity_DefinitionUsertable 紀錄Entity"所屬玩家"的新機率內定值, 此值變更時其下所有玩家需同步變更, 單獨變更單一玩家時則不會變更此值.
            //  只有 Entity_DefinitionUsertable 和 Usertable 資料庫 和 本地端 的 ParaData 欄位, 是由 DBCache 負責寫入更新.
            //  其餘欄位則是WEB會直接更新 資料庫, DBCache只處理 本地端 玩家資料的更新.
            //  取消 "檢查是否有變更" 的原因是, 雖然 Entity_DefinitionUsertable 的資料沒有變更, 但所屬玩家可能有不同, 因此玩家還是要統一覆寫一次才對.

            if (settingInfo == null || settingInfo.Count == 0)
            {
                return false;
            }

            var dataPara = WebIpSetPara.ExpandData(settingInfo[0]);
            int entityUid = dataPara.EntityId;
            EntityData entityData = GetEntityData(entityUid);
            if (entityData == null)
            {
                return false;
            }

            //從資料庫讀取原本的 ParaData
            var datalist = myAcess.select("Entity_DefinitionUsertable", "ParaData", $"EntityId={entityUid}");
            if (datalist == null || datalist.Count == 0 || datalist[0].ContainsKey("ParaData") == false)
            {
                MyConsole.WriteLine($"    ChangeEntityIdSettingProc Error: Entity[{entityData.Name}] data not found in Entity_DefinitionUsertable");
                return false;
            }
            string paraDataSrc = datalist[0]["ParaData"];

            //設定新的 ParaData
            string paraDataNew = IPGetWebSetParaData(dataPara, paraDataSrc);

            //資料變更檢查
            bool isParaChanged = paraDataNew != paraDataSrc; //ParaData有變更
            bool isSetChange = dataPara.IsSetDataChange();

            //檢查是否有變更
            //if (isParaChanged == false && isSetChange == false)
            //{
            //    MyConsole.WriteLine($"    ChangeEntityIdSettingProc Warning: No changes detected in All Setting Data for Entity[{entityData.Name}]");
            //    return true; //雖然ParaData沒有變更，但仍回傳 true 表示處理成功
            //}

            //更新 Entity 下的所有(本地端)玩家的 ParaData 和其餘 設定參數
            lock (UserDataList)
            {
                foreach (var user in UserDataList.Values)
                {
                    if (user.EntityId == entityUid)
                    {
                        if (isParaChanged) user.SetParaData(paraDataNew);
                        if (isSetChange) user.IPGetWebSet(dataPara);
                    }
                }
            }

            //檢查是否有變更
            //if (isParaChanged == false)
            //{
            //    MyConsole.WriteLine($"    ChangeEntityIdSettingProc Warning: No changes detected in ParaData for Entity[{entityData.Name}]");
            //    return true; //雖然ParaData沒有變更，但仍回傳 true 表示處理成功
            //}

            //寫回 Entity 資料庫的 ParaData
            Dictionary<string, string> updata = new Dictionary<string, string>();
            updata.Add("ParaData", "'" + paraDataNew + "'");
            OperTionDBBox TempOperTionDBBox = new OperTionDBBox(OpertionCode.update1, "Entity_DefinitionUsertable", updata, "EntityId", entityUid.ToString());
            Program.opertionDBBoxs.Add(TempOperTionDBBox);

            //更新 Entity 下的所有(資料庫)玩家的 ParaData
            OperTionDBBox TempOperTionDBBox2 = new OperTionDBBox(OpertionCode.update1, "Usertable", updata, "EntityId", entityUid.ToString());
            Program.opertionDBBoxs.Add(TempOperTionDBBox2);

            return true;
        }

        /// <summary>WEB變更玩家個人設定 處理程序</summary>
        public bool ChangePlayerIdSettingProc(List<string> settingInfo)
        {
            if (settingInfo == null || settingInfo.Count == 0)
            {
                return false;
            }

            foreach (string sData in settingInfo)
            {
                var dataPara = WebIpSetPara.ExpandData(sData);
                int userUid = dataPara.Uid;
                var user = Getuser(userUid);
                if (user != null)
                {
                    user.IPGetWebSet(dataPara);
                    user.SetParaData(IPGetWebSetParaData(dataPara, user.ParaData));
                    IpSetUpdateUserTable(user, dataPara);

                    bool bgChange = false;
                    if (dataPara.WaterIn > 0)
                    {
                        bgChange = true;
                        UserPrivateWaterRecord(user.EntityId, userUid, dataPara.WaterIn, user.WaterInAcc, "放水", UPWaterRecType.WEB放水);
                        PlayerReportWaterInOut(userUid, dataPara.WaterIn, 0, 0, 0);
                    }
                    if (dataPara.WaterOut > 0)
                    {
                        bgChange = true;
                        UserPrivateWaterRecord(user.EntityId, userUid, dataPara.WaterOut, user.WaterOutAcc, "抽水", UPWaterRecType.WEB抽水);
                        PlayerReportWaterInOut(userUid, 0, dataPara.WaterOut, 0, 0);
                    }
                    if (dataPara.RedWaterIn > 0)
                    {
                        bgChange = true;
                        UserPrivateWaterRecord(user.EntityId, userUid, dataPara.RedWaterIn, user.RedBonusPool, "紅包放水", UPWaterRecType.WEB放水紅包);
                        PlayerReportWaterInOut(userUid, 0, 0, dataPara.RedWaterIn, 0);
                    }
                    if (dataPara.RedWaterOut > 0)
                    {
                        bgChange = true;
                        UserPrivateWaterRecord(user.EntityId, userUid, dataPara.RedWaterOut, user.WaterOutAcc, "紅包抽水", UPWaterRecType.WEB抽水紅包);
                        PlayerReportWaterInOut(userUid, 0, 0, 0, dataPara.RedWaterOut);
                    }

                    if (dataPara.WaterInClear)
                    {
                        bgChange = true;
                        UserPrivateWaterRecord(user.EntityId, userUid, dataPara.WaterIn, user.WaterInAcc, "歸零待放水", UPWaterRecType.WEB放水);
                    }
                    if (dataPara.WaterOutClear)
                    {
                        bgChange = true;
                        UserPrivateWaterRecord(user.EntityId, userUid, dataPara.WaterOut, user.WaterOutAcc, "歸零待抽水", UPWaterRecType.WEB抽水);
                    }
                    if (dataPara.RedWaterInClear)
                    {
                        bgChange = true;
                        UserPrivateWaterRecord(user.EntityId, userUid, dataPara.RedWaterIn, user.RedBonusPool, "歸零紅包待放水", UPWaterRecType.WEB放水紅包);
                    }

                    if (bgChange) AddUserdataUpdateList(userUid);
                }
            }

            return true;
        }

