        /// <summary>玩家抽放水記錄Type定義</summary>
        public enum UPWaterRecType
        {
            WEB放水 = 0,
            放水取用 = 1,
            WEB抽水 = 2,
            抽水取用 = 3,
            WEB放水紅包 = 4,
            紅包取用 = 5,
            WEB抽水紅包 = 6,
            機率抽水 = 7,
        }
        /// <summary>新增一筆玩家抽放水記錄</summary>
        void UserPrivateWaterRecord(int etityID, int userUID, double amount, double afterWater, string note, UPWaterRecType type, GameServerCode server = GameServerCode.None)
        {
            Dictionary<string, string> update = new Dictionary<string, string>();
            update.Add("UserUID", userUID.ToString());
            update.Add("Type", ((int)type).ToString());
            update.Add("Amount", Math.Round(amount, Program.AccuracyDigitBal).ToString());
            update.Add("AfterWater", Math.Round(afterWater, Program.AccuracyDigitBal).ToString());
            update.Add("EntityID", etityID.ToString());
            update.Add("GameServer", ((int)server).ToString());
            update.Add("TimeStamp", Program.GetLogTimeStamp(DateTime.Now).ToString());

            if (note != null && note != "")
            {
                update.Add("Note", "'" + note + "'");
            }

            OperTionDBBox TempData = new OperTionDBBox(OpertionCode.insert, "UserPrivateWaterRecord", update);
            lock (Program.opertionDBBoxs)
            {
                Program.opertionDBBoxs.Add(TempData);
            }
        }
