        /// <summary>依據玩家數量選出GameServer</summary>
        public GameServerCode ChooseJPGameServer(JpAward outJp, out int playerUid)
        {
            //MARKLU: JP獎 依據玩家數量選出GameServer
            Random rand = new Random(Guid.NewGuid().GetHashCode());
            Dictionary<int, GameServerCode> avauserlist = new Dictionary<int, GameServerCode>();
            lock (UserDataList)
            {
                foreach (KeyValuePair<int, UserData> info in UserDataList)
                {
                    if (info.Value.Usersituation >= (int)GameServerCode.XiyouGame)
                    {
                        GameServerCode gserver = (GameServerCode)info.Value.Usersituation;
                        GameTypeCode gtype = GameServerCodeToGameTypeCode(gserver);

                        bool pass = true;

                        if (gtype == GameTypeCode.Arcade) //押分機 自然不出
                        {
                            pass = false;
                        }

                        //if (gtype == GameTypeCode.Arcade || gtype == GameTypeCode.Poker)
                        if (gtype == GameTypeCode.Poker)
                        {
                            if (rand.Next(1000) < 900)  // 押分機,撲克 縮減1/10
                            {
                                pass = false;
                            }
                        }

                        if (pass)
                        {
                            avauserlist.Add(info.Value.UserUID, gserver);
                        }
                    }
                }
            }

            if (avauserlist.Count > 0)
            {
                int totalPlayer = avauserlist.Count;
                int passrate;

                if (outJp == JpAward.MINOR || outJp == JpAward.MAJOR)
                {
                    if (totalPlayer >= 20) passrate = 1000;
                    else if (totalPlayer >= 16) passrate = 800;
                    else if (totalPlayer >= 12) passrate = 600;
                    else if (totalPlayer >= 8) passrate = 400;
                    else if (totalPlayer >= 4) passrate = 200;
                    else passrate = 100;
                }
                else
                {
                    if (totalPlayer >= 20) passrate = 1000;
                    else if (totalPlayer >= 15) passrate = 800;
                    else if (totalPlayer >= 10) passrate = 600;
                    else if (totalPlayer >= 5) passrate = 400;
                    else passrate = 200;
                }
                //UNDONE: JP獎 (指定/不指定玩家) ============
                if (rand.Next(1000) < passrate)
                {
                    int index = rand.Next(totalPlayer);
                    foreach (KeyValuePair<int, GameServerCode> info in avauserlist)
                    {
                        if (index == 0)
                        {
                            //playerUid = info.Key; //指定玩家
                            playerUid = 0;  //不指定玩家(由GameServer決定)
                            return info.Value;
                        }
                        index--;
                    }
                }
            }

            playerUid = 0;
            return GameServerCode.None;
        }

