        /// <summary>批量取出玩家DB更新清單</summary>
        public List<OperTionDBBox> GetUserDataDBUpdateData()
        {
            const int MaxBatchSize = 5000; //每次處理5000筆
            List<OperTionDBBox> DataList = new List<OperTionDBBox>();
            List<int> TempUserDataList = new List<int>();

            lock (userdataUpdateList)
            {
                int takeCount = Math.Min(userdataUpdateList.Count, MaxBatchSize);
                TempUserDataList = userdataUpdateList.Take(takeCount).ToList();
                userdataUpdateList.RemoveRange(0, takeCount);
            }

            lock (UserDataList)
            {
                foreach (int UID in TempUserDataList)
                {
                    if (UserDataList.ContainsKey(UID))
                    {
                        //由 UserGameDataDBCommend 處理, OpertionCode.update1是無關的
                        Dictionary<string, string> updatadata = UserDataList[UID].GetPlayUpdateData();
                        OperTionDBBox TempOperTionDBBox = new OperTionDBBox(OpertionCode.update1, "Usertable", updatadata, "UserUID", UserDataList[UID].UserUID.ToString());
                        DataList.Add(TempOperTionDBBox);
                    }
                }
            }

            return DataList;
        }

