        /// <summary>玩家 重新載入資源(解除閒置)</summary>
        public void ReleaseIdleUserAccount(string[] userUIDList)
        {
            if (userUIDList == null || userUIDList.Length <= 0)
                return;

            for (int i = 0; i < userUIDList.Length; i++)
            {
                int useruid = Convert.ToInt32(userUIDList[i]);
                GetDBSingleUserData(useruid); //解除閒置
            }
        }

        /// <summary>清除玩家的回水和有效投注量</summary>
        public bool ClearUserRebate(Dictionary<int, int> playerList)
        {
            //#250807
            foreach (var temp in playerList)
            {
                int useruid = temp.Key;

                lock (UserDataList)
                {
                    if (UserDataList.ContainsKey(useruid))
                    {
                        if ((temp.Value & (1 << 0)) != 0)  //bit(0)=清除"有效押注"
                        {
                            UserDataList[useruid].ClearValidBets();
                        }

                        if ((temp.Value & (1 << 1)) != 0)  //bit(1)=清除"返水分數"
                        {
                            UserDataList[useruid].ClearRebat();
                        }

                        AddUserdataUpdateList(useruid);
                    }
                }
            }
            return true;
        }
