        /// <summary>更新使用者Session Account資料</summary>
        public void UpdateUserSessionAccount(int userUid, int sessionId, string ip, double bet, double win, double jpwin)
        {
            lock (UserSessionAccountList)
            {
                if (UserSessionAccountList.ContainsKey(userUid))
                {
                    UserSessionAccount sessAcc = UserSessionAccountList[userUid];

                    if (sessAcc.SessionID == sessionId)
                    {
                        sessAcc.TotalBet += (decimal)bet;
                        sessAcc.TotalWin += (decimal)win;

                        if (jpwin == 0) //遊戲歷程紀錄
                        {
                            sessAcc.TotalRounds++;
                        }
                        else           //JP得分紀錄
                        {
                            sessAcc.TotalWin += (decimal)jpwin; //總得分包含JP得分
                            sessAcc.JpWin += (decimal)jpwin;
                        }

                        sessAcc.update = true;
                        //Dictionary<string, string> udata = new Dictionary<string, string>
                        //{
                        //    { "UserUID", sessAcc.UserUID.ToString() },
                        //    { "SessionID", sessAcc.SessionID.ToString() },
                        //    { "TotalRounds", sessAcc.TotalRounds.ToString() },
                        //    { "TotalBet", sessAcc.TotalBet.ToString() },
                        //    { "TotalWin", sessAcc.TotalWin.ToString() },
                        //    { "JpWin", sessAcc.JpWin.ToString() }
                        //};

                        //OperTionDBBox TempOperTionDBBox = new OperTionDBBox(OpertionCode.update1, "UserSessionAccount", udata, "AccountUID", "'" + sessAcc.AccountUID.ToString() + "'");
                        //lock (Program.UserSessionAccountUpdataDBBoxs)
                        //{
                        //    Program.UserSessionAccountUpdataDBBoxs.Add(TempOperTionDBBox);
                        //}
                        return;
                    }
                }
            }


            //User 或 sessionId不存在, 新創一筆
            string buildTime = string.Format("{0:yyyy/MM/dd HH:mm:ss}", DateTime.Now);
            Dictionary<string, string> udata2 = new Dictionary<string, string>
                {
                    { "UserUID", userUid.ToString() },
                    { "SessionID", sessionId.ToString() },
                    { "TotalRounds", "1" },
                    { "TotalBet", bet.ToString() },
                    { "TotalWin", win.ToString() },
                    { "JpWin", jpwin.ToString() },
                    { "IP", "'" + ip + "'" },
                    { "Buildtime", "'" + buildTime + "'" }
                };
            int accUid = myAcess.insert("UserSessionAccount", udata2);

            //Cache Update
            if (accUid > 0)
            {
                lock (UserSessionAccountList)
                {
                    if (UserSessionAccountList.ContainsKey(userUid))
                    {
                        UserSessionAccountList[userUid].AccountUID = accUid;
                        UserSessionAccountList[userUid].UserUID = userUid;
                        UserSessionAccountList[userUid].SessionID = sessionId;
                        UserSessionAccountList[userUid].TotalRounds = 1;
                        UserSessionAccountList[userUid].TotalBet = (decimal)bet;
                        UserSessionAccountList[userUid].TotalWin = (decimal)win;
                        UserSessionAccountList[userUid].JpWin = (decimal)jpwin;
                        UserSessionAccountList[userUid].IP = ip;
                        UserSessionAccountList[userUid].Buildtime = buildTime;
                    }
                    else
                    {
                        UserSessionAccount Temp = new UserSessionAccount
                        {
                            AccountUID = accUid,
                            UserUID = userUid,
                            SessionID = sessionId,
                            TotalRounds = 1,
                            TotalBet = (decimal)bet,
                            TotalWin = (decimal)win,
                            JpWin = (decimal)jpwin,
                            IP = ip,
                            Buildtime = buildTime
                        };

                        UserSessionAccountList.Add(userUid, Temp);
                    }
                }
            }
        }

