        /// <summary>
        /// 重置JP
        /// </summary>
        /// <param name="control"></param>
        public void ReseatjpCount(JPControl control)
        {
            //MARKLU: JP廣播 重置JP 20201008
            Dictionary<string, string> data = new Dictionary<string, string>();
            int initval = 0;
            switch (control.JPType)
            {
                case "SuperShow":
                    //initval = JPSettingData.SuperInit;
                    data.Add(control.JPType, initval.ToString());
                    jpCountData.SuperShow = initval;
                    control.ReseatInitPoint(initval);
                    break;
                case "MegaShow":
                    //initval = JPSettingData.MegaInit;
                    data.Add(control.JPType, initval.ToString());
                    jpCountData.MegaShow = initval;
                    control.ReseatInitPoint(initval);
                    break;
                case "MajorShow":
                    //initval = JPSettingData.MajorInit;
                    data.Add(control.JPType, initval.ToString());
                    jpCountData.MajorShow = initval;
                    control.ReseatInitPoint(initval);
                    break;
                case "MinorShow":
                    //initval = JPSettingData.MinorInit;
                    data.Add(control.JPType, initval.ToString());
                    jpCountData.MinorShow = initval;
                    control.ReseatInitPoint(initval);
                    break;
            }
            UpdateJpCountTable(data);
        }
        /// <summary>
        /// 重設JP減去拉下的金額
        /// </summary>
        /// <param name="control"></param>
        public void ReseatjpCount(JPControl control, double pullPoint)
        {
            //MARKLU: JP廣播 重設JP減去拉下的金額
            int restPoint;
            Dictionary<string, string> data = new Dictionary<string, string>();

            switch (control.JPType)
            {
                case "SuperShow":
                    restPoint = (int)(jpCountData.SuperShow - pullPoint);
                    if (restPoint < JPSettingData.SuperInit) restPoint = JPSettingData.SuperInit;

                    data.Add(control.JPType, restPoint.ToString());
                    jpCountData.SuperShow = restPoint;
                    control.ReseatInitPoint(restPoint);
                    break;
                case "MegaShow":
                    restPoint = (int)(jpCountData.MegaShow - pullPoint);
                    if (restPoint < JPSettingData.MegaInit) restPoint = JPSettingData.MegaInit;

                    data.Add(control.JPType, restPoint.ToString());
                    jpCountData.MegaShow = restPoint;
                    control.ReseatInitPoint(restPoint);
                    break;
                case "MajorShow":
                    restPoint = (int)(jpCountData.MajorShow - pullPoint);
                    if (restPoint < JPSettingData.MajorInit) restPoint = JPSettingData.MajorInit;

                    data.Add(control.JPType, restPoint.ToString());
                    jpCountData.MajorShow = restPoint;
                    control.ReseatInitPoint(restPoint);
                    break;
                case "MinorShow":
                    restPoint = (int)(jpCountData.MinorShow - pullPoint);
                    if (restPoint < JPSettingData.MinorInit) restPoint = JPSettingData.MinorInit;

                    data.Add(control.JPType, restPoint.ToString());
                    jpCountData.MinorShow = restPoint;
                    control.ReseatInitPoint(restPoint);
                    break;
            }
            UpdateJpCountTable(data);
        }
