            JpRealData.RealMajor += Convert.ToDouble(data["RealMajor"]);
            JpRealData.RealMinor += Convert.ToDouble(data["RealMinor"]);

            JpRealData.SuperTimer += Convert.ToInt32(data["SuperTimer"]);
            JpRealData.MegaTimer += Convert.ToInt32(data["MegaTimer"]);
            JpRealData.MajorTimer += Convert.ToInt32(data["MajorTimer"]);
            JpRealData.MinorTimer += Convert.ToInt32(data["MinorTimer"]);

            jpRealDataUpdateFg = true;  //跟著ShowJP資料一起更新DB
        }

