        /// <summary>取得JP最高LEVEL彩金值</summary>
        public double GetJPCountDataJPShow(JpAward jpType)
        {
            //MARKLU: 取得JP最高LEVEL彩金值 20201008
            double finalJP = 0;
            if (jpType == JpAward.MINOR)
            {
                finalJP = jpCountData.MinorShow + (JPSettingData.FJP_Level * JPSettingData.MinorInit);  // 累積值 + (啟動值 x Level值)
            }
            else if (jpType == JpAward.MAJOR)
            {
                finalJP = jpCountData.MajorShow + (JPSettingData.FJP_Level * JPSettingData.MajorInit);
            }
            else if (jpType == JpAward.MEGA)
            {
                finalJP = jpCountData.MegaShow + (JPSettingData.FJP_Level * JPSettingData.MegaInit);
            }
            else if (jpType == JpAward.SUPER)
            {
                finalJP = jpCountData.SuperShow + (JPSettingData.FJP_Level * JPSettingData.SuperInit);
            }
            return finalJP;
        }

        /// <summary>取得JP Show彩金值並判斷是否全拿</summary>
        public double GetJPCountDataJPShow(JpAward jpType, double userBet, out bool getAllJp)
        {
            //MARKLU: 取得JP Show彩金值並判斷是否全拿 20201008
            double finalJP = 0;
            getAllJp = true;

            if (userBet >= JPSettingData.HalfJPGetMinBet && jpType >= JpAward.MINOR && jpType <= JpAward.SUPER)
            {
                //取出啟動值 & 計算Level1彩金
                double jpBase;
                if (jpType == JpAward.MINOR)
                {
                    jpBase = JPSettingData.MinorInit;
                    finalJP = jpCountData.MinorShow;
                }
                else if (jpType == JpAward.MAJOR)
                {
                    jpBase = JPSettingData.MajorInit;
                    finalJP = jpCountData.MajorShow;
                }
                else if (jpType == JpAward.MEGA)
                {
                    jpBase = JPSettingData.MegaInit;
                    finalJP = jpCountData.MegaShow;
                }
                else //if (jpType == JpAward.SUPER)
                {
                    jpBase = JPSettingData.SuperInit;
                    finalJP = jpCountData.SuperShow;
                }

                int level = 0;
                double betLevel = 0;

                for (int i = 0; i < JPSettingData.FJP_Level; i++)
                {
                    betLevel += JPSettingData.AllJPGetMinBet; //押分層級+1
                    if (userBet >= betLevel)
                    {
                        finalJP += jpBase;
                        level++;
                    }
                    else
                    {
                        break;
                    }
                }

                if (level == 0)
                {
                    finalJP = Math.Round((jpBase + finalJP) / 2); //(啟動值+累積值)/2
                    getAllJp = false;
                }
            }
            return finalJP;
        }

        /// <summary>重置JP Show彩金值</summary>
        public void ResetJpShow(JpAward jpType) //, double pullPoint)
        {
            if (jpType == JpAward.MINOR)
            {
                //ReseatjpCount(minorJP, pullPoint);
                ReseatjpCount(minorJP); //20201008
            }
            else if (jpType == JpAward.MAJOR)
            {
                //ReseatjpCount(majorJP, pullPoint);
                ReseatjpCount(majorJP);
            }
            else if (jpType == JpAward.MEGA)
            {
                //ReseatjpCount(megaJP, pullPoint);
                ReseatjpCount(megaJP);
            }
            else if (jpType == JpAward.SUPER)
            {
                //ReseatjpCount(superJP, pullPoint);
                ReseatjpCount(superJP);
            }
        }

        /// <summary>插入一筆JP彩金出牌紀錄</summary>
        public int EnforceJPInsertAccountData(GameServerCode gcode, int useruid, JpAward jpType, double finalJP, string payerIP, string sessionId, JpLotteryType lotteryType, JpLotteryCast lotteryCast)
        {
            //MARKLU: 插入一筆JP彩金出牌紀錄
            string gameType = "";
            string gameName = "";

            if (gcode != GameServerCode.None)
            {
                gameType = GameTypeCodeToGameTypeName(GameServerCodeToGameTypeCode(gcode));
                gameName = GameServerCodeToGameName(gcode);
            }

            JPAcoountData jpdata = new JPAcoountData();
            jpdata.JpAward = (int)jpType;
            //jpdata.UID = nguid;
            //jpdata.JPType = jpType.ToString();
            jpdata.GameName = gameName;
            jpdata.GameType = gameType;
            jpdata.TotalWin = finalJP;
            jpdata.PlayerIP = payerIP;
            jpdata.LotteryType = lotteryType;
            jpdata.LotteryCast = lotteryCast;
            jpdata.BuildTime = string.Format("{0:yyyy/MM/dd HH:mm:ss}", DateTime.Now);

            Dictionary<string, string> udata = new Dictionary<string, string>();
            //udata.Add("LogID", "'" + data["LogID"] + "'");  //Enforce LogID先保留以防有需要
            udata.Add("SessionID", "'" + sessionId + "'");
            udata.Add("JpAward", "'" + jpdata.JpAward + "'");
            udata.Add("JpType", "'" + jpType.ToString() + "'");
            udata.Add("GameType", "'" + gameType + "'");
            udata.Add("GameName", "'" + gameName + "'");
            udata.Add("TotalWin", "'" + finalJP.ToString() + "'");
            udata.Add("UserID", "'" + useruid.ToString() + "'");
            udata.Add("PlayerIP", "'" + payerIP + "'");
            udata.Add("LotteryType", "'" + (int)lotteryType + "'");
            udata.Add("LotteryCast", "'" + (int)lotteryCast + "'");
            udata.Add("TimeStamp", ((DateTime.Now.Year * 10000) + (DateTime.Now.Month * 100) + DateTime.Now.Day).ToString());
            udata.Add("Buildtime", "'" + jpdata.BuildTime + "'");

            int nguid = myAcess.insert("JpAccountTable", udata);
            jpdata.UID = nguid;

            lock (UserDataList)
            {
                if (UserDataList.ContainsKey(useruid))
                {
                    jpdata.User = UserDataList[useruid].Nickname;
                }
            }

            jpAccountDataList.Add(jpdata);

            return nguid;
        }

