        /// <summary>JP盈餘校正檢查</summary>
        public bool CheckJPSurplusRegulate(GameServerCode gameServerCode, JpAward jpType, bool surplusRegulate)
        {
            if (surplusRegulate == false)
            {
                return true;  //不須校正
            }

            //MARKLU: JP盈餘校正/水庫校正
            //int recordCount = 0;  //有效的紀錄筆數
            //double totSurplus = 0; //有效盈餘
            //DateTime startDay = Convert.ToDateTime(DateTime.Now.ToString("yyyy/MM/dd"));
            //DateTime endDay = startDay.AddDays(-90); //檢查3個月
            //
            //if (gameServerCode == GameServerCode.XiyouGame)
            //{
            //    CountXiyouBigWaterProFitDays(startDay, endDay, out recordCount, out totSurplus);
            //}
            //else
            //{
            //    Console.WriteLine("檢查JP校正天數[ERROR]");
            //    return false;
            //}
            ////Console.WriteLine("檢查JP校正天數[" + gameServerCode + "] " + startDay + " - " + endDay + ",  有效盈餘=" + totSurplus + ", 有效紀錄=" + recordCount);

            double showJP = 0;
            double bankJP = 0;
            if (jpType == JpAward.MINOR)
            {
                showJP = jpCountData.MinorShow + 20.0;
                bankJP = JpRealData.RealMinor;
            }
            else if (jpType == JpAward.MAJOR)
            {
                showJP = jpCountData.MajorShow + 20.0;
                bankJP = JpRealData.RealMajor;
            }
            else if (jpType == JpAward.MEGA)
            {
                showJP = jpCountData.MegaShow + 20.0;
                bankJP = JpRealData.RealMega;
            }
            else if (jpType == JpAward.SUPER)
            {
                showJP = jpCountData.SuperShow + 20.0;
                bankJP = JpRealData.RealSuper;
            }

            //if (totSurplus > showJP)  //使用盈餘校正
            if (bankJP > showJP)    //使用水庫校正
            {
                return true;
            }
            return false;
        }

        /// <summary>重新Load金庫Timer</summary>
        public void InitialTreasuryTimers(DateTime dtNow)
        {
            Random rand = new Random(Guid.NewGuid().GetHashCode());
            int addRestSecond = (rand.Next(JPSettingData.TreasuryRest_L_Limit, JPSettingData.TreasuryRest_U_Limit) * 60) + rand.Next(60);
            //addRestSecond = 180;//UNDONE: ReLoad金庫休息3分鐘 DEBUG DEBUG DEBUG DEBUG DEBUG DEBUG
            JpRealData.TreasuryCountdownTime = dtNow.AddSeconds(addRestSecond);

            int addWinSecondRange = (rand.Next(JPSettingData.TreasuryEnable_L_Limit, JPSettingData.TreasuryEnable_U_Limit) * 60) + rand.Next(60);
            int iPersent = rand.Next(ConvDoubleToHInt(JPSettingData.TreasuryWin_L_Limit), ConvDoubleToHInt(JPSettingData.TreasuryWin_U_Limit));
            double dPersent = ConvHIntToDouble(iPersent);
            int addWinSecond = (int)((double)addWinSecondRange * dPersent);
            //addWinSecond = 180;//UNDONE: ReLoad金庫出現3分鐘 DEBUG DEBUG DEBUG DEBUG DEBUG DEBUG
            JpRealData.TreasuryWinTime = dtNow.AddSeconds(addWinSecond + addRestSecond);

            SetTreasuryActFg(1);

            //MyConsole.WriteLine("RestTime=" + JpRealData.TreasuryCountdownTime + ", Add=" + (addRestSecond/60) + ", Rest_L=" + JPSettingData.TreasuryRest_L_Limit + ", Rest_U=" + JPSettingData.TreasuryRest_U_Limit);
            //MyConsole.WriteLine("OpenTime=" + JpRealData.TreasuryWinTime + ", Add2=" + (addWinSecondRange/60) + ", Add3=" + (addWinSecond/60) + ", Enab_L=" + JPSettingData.TreasuryEnable_L_Limit + ", Enab_U=" + JPSettingData.TreasuryEnable_U_Limit + ", Pers=" + dPersent + "%");
            MyConsole.WriteLine("金庫時間 [出現時間:" + JpRealData.TreasuryCountdownTime + "] [中獎時間:" + JpRealData.TreasuryWinTime + "]");
        }
        /// <summary>金庫延遲中獎10分鐘</summary>
        public void DelayTreasuryTimers(DateTime dtNow)
        {
            int addWinSecond = 10 * 60; //延遲10分鐘
            //int addWinSecond = 2 * 60; //UNDONE: DEBUG DEBUG DEBUG 金庫延遲2分鐘 
            JpRealData.TreasuryWinTime = dtNow.AddSeconds(addWinSecond);
            //JpRealData.TreasuryWinTime
            SetTreasuryActFg(2);
            MyConsole.WriteLine("金庫時間 [中獎時間延遲至:" + JpRealData.TreasuryWinTime + "]");
        }
        /// <summary>設定金庫狀態</summary>
        public void SetTreasuryActFg(int stat)
        {
            JpRealData.TreasuryActFg = stat;
            if (stat == 2)
            {
                JpRealData.TreasuryStatus = 1;
            }
            else
            {
                JpRealData.TreasuryStatus = 0;
            }

            jpRealDataUpdateFg = true;
        }


        /// <summary>更新後台逼遊戲獎項Log</summary>
        public void EnforceAwardUpdateWebLog(GameServerCode gameServerCode, Dictionary<string, string> data)
        {
            string tablename = null;

            var gs = GetGSInstance(gameServerCode);
            if (gs != null)
            {
                if (gs.GameTypeCode == GameTypeCode.Slot)
                    tablename = "SlotCommonEnforceAwardLog";
                else if (gs.GameTypeCode == GameTypeCode.Arcade)
                    tablename = "ArcadesCommonEnforceAwardLog";
                else if (gs.GameTypeCode == GameTypeCode.Fish)
                    tablename = "FishCommonEnforceAwardLog";
            }
            else
            {
                switch (gameServerCode)
                {
                    //押分機 (#AddNewServer 24)
                    case GameServerCode.XiyouGame:
                    case GameServerCode.SuperKingDerby:
                    case GameServerCode.Ferrari:
                    case GameServerCode.DrollMonkey:
                    case GameServerCode.BMW3D:
                    case GameServerCode.AstonMartin:
                    case GameServerCode.SuperAltyn:
                    case GameServerCode.MonkeyKing2:
                    case GameServerCode.FIFA2022:
                    case GameServerCode.BigSmall:
                        tablename = "ArcadesCommonEnforceAwardLog";
                        break;
                    case GameServerCode.OceanKing:
                    case GameServerCode.OceanKing2:
                    case GameServerCode.OceanKing3:
                    case GameServerCode.OceanKing4:
                    case GameServerCode.OceanKing5:
                    case GameServerCode.OceanKing6:
                    case GameServerCode.OceanKing7:
                    case GameServerCode.OceanKing8:
                        tablename = "FishCommonEnforceAwardLog";
                        break;
                    //老虎機 (內定)
                    default:
                        tablename = "SlotCommonEnforceAwardLog";
                        break;
                }
            }

            if (tablename != null)
            {
                Dictionary<string, string> udata = new Dictionary<string, string>();
                udata.Add("Result", "'" + data["Result"] + "'");
                udata.Add("TotalBet", "'" + data["TotalBet"] + "'");
                udata.Add("TotalGet", "'" + data["TotalGet"] + "'");
                //udata.Add("PlayerIP", "'" + data["PlayerIP"] + "'");

                //myAcess.update(tablename, udata, "UID", "'" + data["UID"] + "'");
                OperTionDBBox TempOperTionDBBox = new OperTionDBBox(OpertionCode.update1, tablename, udata, "UID", "'" + data["UID"] + "'");
                lock (Program.opertionDBBoxs)
                {
                    Program.opertionDBBoxs.Add(TempOperTionDBBox);
                }
                //MyConsole.WriteLine("EnforceAwardUpdateWebLog: " + data["UID"] + ", " + data["Result"] + ", " + data["TotalBet"] + ", " + data["TotalGet"]);
            }
        }

