        #region JP出獎記錄
        /// <summary>獲取JP帳目資料</summary>
        private void GetDBJPAccountData()
        {
            var datalist = myAcess.select("JpAccountTable", "*", "", "UID DESC");

            if (datalist.Count > 0)
            {
                lock (UserDataList)
                {
                    int supercnt = 0, megacnt = 0, majorcnt = 0, minorcnt = 0;
                    for (int i = 0; i < datalist.Count; i++)
                    {
                        int userUid = Convert.ToInt32(datalist[i]["UserID"]);
                        if (UserDataList.ContainsKey(userUid))
                        {
                            bool recfg = true;
                            int award = Convert.ToInt32(datalist[i]["JpAward"]);
                            //if (award == 1) { minorcnt++; if (minorcnt <= 50) recfg = true; }
                            //else if (award == 2) { majorcnt++; if (majorcnt <= 50) recfg = true; }
                            //else if (award == 3) { megacnt++; if (megacnt <= 50) recfg = true; }
                            //else if (award == 4) { supercnt++; if (supercnt <= 50) recfg = true; }

                            if (recfg)
                            {
                                JPAcoountData ndata = new JPAcoountData
                                {
                                    UID = Convert.ToInt32(datalist[i]["UID"]),
                                    JpAward = award,
                                    GameName = datalist[i]["GameName"],
                                    GameType = datalist[i]["GameType"],
                                    TotalWin = Convert.ToDouble(datalist[i]["TotalWin"]),
                                    User = UserDataList[userUid].Nickname,
                                    BuildTime = Convert.ToDateTime(datalist[i]["Buildtime"]).ToString("yyyy/MM/dd HH:mm:ss"),
                                    PlayerIP = datalist[i]["PlayerIP"],
                                    LotteryType = (JpLotteryType)Convert.ToInt32(datalist[i]["LotteryType"]),
                                    LotteryCast = (JpLotteryCast)Convert.ToInt32(datalist[i]["LotteryCast"])
                                };
                                jpAccountDataList.Add(ndata);
                            }
                        }
                    }
                }
                if (jpAccountDataList.Count > 1) jpAccountDataList.Reverse();
            }
        }

        /// <summary>檢查JPAccount</summary>
        /// <param name="type"></param>
        /// <returns></returns>
        public List<JPAccountData> CheckJPAccountData(JpAward type)
        {
            List<JPAccountData> TempJPData = new List<JPAccountData>();
            int jpType = (int)type;
            //DateTime compareDate = DateTime.Now.Date.AddDays(-29); //搜尋30日
            int ListCount = 0;
            lock (jpAccountDataList)
            {
                int totcnt = jpAccountDataList.Count;
                for (int i = totcnt - 1; i >= 0; i--)
                {
                    if (jpAccountDataList[i].JpAward == jpType)
                    {
                        //DateTime DBDate = Convert.ToDateTime(jpAccountDataList[i].BuildTime);//.Date;
                        //if (DateTime.Compare(DBDate, compareDate) >= 0)  //>=指定日期
                        if (ListCount < 50)
                        {
                            ListCount++;
                            JPAccountData jpdata = new JPAccountData();
                            jpdata.JPType = type;
                            jpdata.GameNmae = jpAccountDataList[i].GameName;
                            jpdata.TotalWin = jpAccountDataList[i].TotalWin;
                            jpdata.User = jpAccountDataList[i].User;
                            jpdata.DateTime = jpAccountDataList[i].BuildTime;
                            //jpdata.DateTime = Convert.ToDateTime(jpAccountDataList[i].BuildTime).ToString("yyyy/MM/dd HH:mm:ss");
                            TempJPData.Add(jpdata);
                        }
                        else
                        {
                            break;
                        }
                    }
                }
            }
            return TempJPData;
        }
