        private void GetDBMachineData()
        {
            //var datalist = myAcess.select("machinetable", "*");
            var datalist = myAcess.select("MachineTableDefine", "*");

            if (datalist.Count > 0)
            {
                if (machineDataList.Count > 0) { machineDataList.Clear(); }

                for (int i = 0; i < datalist.Count; i++)
                {
                    GameServerCode gServer = (GameServerCode)Convert.ToInt32(datalist[i]["GameServerCode"]);
                    MachineData mdata = new MachineData
                    {
                        RoomBaseNumber = Convert.ToInt32(datalist[i]["RoomBaseNumber"]),
                        TotalCount = Convert.ToInt32(datalist[i]["TotalCount"]),
                        GameTypeCode = GameTypeNameToGameTypeCode(datalist[i]["GameType"])
                    };
                    machineDataList.Add(gServer, mdata);
                }
            }
        }

