        public GameServerCode GetDBMachineGameServerCode(int machUid)
        {
            foreach (KeyValuePair<GameServerCode, CommonGame> info in GameServerCodeTable)
            {
                if (info.Value.CompareMachineNo(machUid))
                {
                    return info.Key;
                }
            }

            foreach (KeyValuePair<GameServerCode, MachineData> info in machineDataList)
            {
                if (info.Value.CompareMachineNo(machUid))
                {
                    return info.Key;
                }
            }
            return GameServerCode.None;
        }
        /// <summary>
        /// 判斷Machine的GameServerCode是否相符
        /// </summary>
        public bool CheckDBMachineGameServerCode(int machUid, GameServerCode gServerCode)
        {
            var gs = GetGSInstance(gServerCode);
            if (gs != null)
            {
                return gs.CompareMachineNo(machUid);
            }

            if (machineDataList.ContainsKey(gServerCode))
            {
                return machineDataList[gServerCode].CompareMachineNo(machUid);
            }
            return false;
        }

        /// <summary></summary>
        int GetMachineNumberOfOpen(GameServerCode gServer)
        {
            //(#AddNewServer 05_1) //sroptim
            if (gServer == GameServerCode.XiyouGame) return xiyouGlobalSettingList.NumberOfOpen;
            if (gServer == GameServerCode.SuperKingDerby) return superKingDerbyGlobalSettingList.NumberOfOpen;
            if (gServer == GameServerCode.Ferrari) return ferrariGlobalSettingList.NumberOfOpen;
            if (gServer == GameServerCode.DrollMonkey) return drollMonkeyGlobalSettingList.NumberOfOpen;
            if (gServer == GameServerCode.BMW3D) return bmw3DGlobalSettingList.NumberOfOpen;
            if (gServer == GameServerCode.AstonMartin) return astonMartinGlobalSettingList.NumberOfOpen;
            if (gServer == GameServerCode.SuperAltyn) return superAltynGlobalSettingList.NumberOfOpen;
            if (gServer == GameServerCode.MonkeyKing2) return monkeyKing2GlobalSettingList.NumberOfOpen;
            if (gServer == GameServerCode.FIFA2022) return fifa2022GlobalSettingList.NumberOfOpen;
            if (gServer == GameServerCode.BigSmall) return bigSmallGlobalSetting.NumberOfOpen;
            if (gServer == GameServerCode.OceanKing) return oceanKingGlobalSettingList.NumberOfOpen;
            if (gServer == GameServerCode.OceanKing2) return oceanKing2GlobalSettingList.NumberOfOpen;
            if (gServer == GameServerCode.OceanKing3) return oceanKing3GlobalSettingList.NumberOfOpen;
            if (gServer == GameServerCode.OceanKing4) return oceanKing4GlobalSettingList.NumberOfOpen;
            if (gServer == GameServerCode.OceanKing5) return oceanKing5GlobalSettingList.NumberOfOpen;
            if (gServer == GameServerCode.OceanKing6) return oceanKing6GlobalSettingList.NumberOfOpen;
            if (gServer == GameServerCode.OceanKing7) return oceanKing7GlobalSettingList.NumberOfOpen;
            if (gServer == GameServerCode.OceanKing8) return oceanKing8GlobalSettingList.NumberOfOpen;
            return 0;
        }
        /// <summary>取得遊戲RoomBase號碼</summary>
        int GetMachineRoomBaseNumber(GameServerCode gServer)
        {
            if (machineDataList.ContainsKey(gServer))
            {
                return machineDataList[gServer].RoomBaseNumber;
            }
            return 0;
        }
        /// <summary>取得遊戲起始機號</summary>
        int GetMachineStartNumber(GameServerCode gServer)
        {
            var gs = GetGSInstance(gServer);
            if (gs != null)
            {
                return gs.MachineStartNumber;
            }

            if (machineDataList.ContainsKey(gServer))
            {
                return machineDataList[gServer].MachineStartNumber();
            }
            return 0;
        }
        /// <summary>Show Error Message</summary>
        void _GetDBGameSettingDataError(GameServerCode gServer)
        {
            Console.WriteLine("GetDB" + gServer + "GameSettingData Error!!");
        }
