        #region 西遊遊戲設定資訊
        /// <summary>
        ///  獲取遊戲設定DB資料
        /// </summary>
        public void GetDBXiyouGameSettingData()
        {
            if (GetDBCommonGameSettingAll(GameServerCode.XiyouGame, out var datalist, out var sRange))
            {
                if (xiyouGameSettingDataList.Count > 0)
                {
                    xiyouGameSettingDataList.Clear();
                }

                for (int i = 0; i < datalist.Count; i++)
                {
                    int machineUID = Convert.ToInt32(datalist[i]["MachineUID"]);
                    if (machineUID > 0)
                    {
                        XiyouGameSettingData ndata = new XiyouGameSettingData();
                        ndata.GetDBData(machineUID, datalist[i]);
                        xiyouGameSettingDataList.Add(ndata);
                    }
                    if (i >= xiyouGlobalSettingList.NumberOfOpen - 1) break;
                }
            }
        }
        /// <summary>
        /// 重新獲取單一筆遊戲設定DB資料
        /// </summary>
        /// <param name="MachineUID"></param>
        public void GetSingleDBXiyouGameSettingData(int MachineUID)
        {
            string sRange = string.Format("MachineUID = {0}", MachineUID);
            //var datalist = myAcess.select("XiyouGameSettingtable", "*", sRange);
            var datalist = GetDBCommonGameSetting(sRange, GameServerCode.XiyouGame);

            foreach (var temp in xiyouGameSettingDataList)
            {
                if (temp.MachineUID == MachineUID)
                {
                    temp.GetDBData(MachineUID, datalist[0]);
                    break;
                }
            }
        }
        /// <summary>
        /// 依房間取得XiyouGameSettingData
        /// </summary>
        /// <param name="roomindex">房間索引(由0開始)</param>
        public XiyouGameSettingData GetXiyouGameSettingData(int roomIndex)
        {
            if (roomIndex > 0 && roomIndex <= xiyouGameSettingDataList.Count)
            {
                return xiyouGameSettingDataList[roomIndex - 1];
            }
            else
            {
                return xiyouGameSettingDataList[0];
            }
        }
        /// <summary>
        /// 檢查XiyouGameSettingData
        /// </summary>
        /// <returns></returns>
        public List<Dictionary<string, string>> CheckXiyouGameSettingData(bool isAll, int MachineUID = 0)
        {
            List<Dictionary<string, string>> datalist = new List<Dictionary<string, string>>();

            if (isAll)
            {
                for (int i = 0; i < xiyouGameSettingDataList.Count; i++)
                {
                    datalist.Add(xiyouGameSettingDataList[i].GetSetting());
                }
            }
            else
            {
                for (int i = 0; i < xiyouGameSettingDataList.Count; i++)
                {
                    if (xiyouGameSettingDataList[i].MachineUID == MachineUID)
                        datalist.Add(xiyouGameSettingDataList[i].GetSetting());
                }
            }

            return datalist;
        }
