        #region 取得遊戲共用設定
        public bool GetDBCommonGameSettingAll(GameServerCode gameServerCode, out List<Dictionary<string, string>> datalist, out string sRange)
        {
            int roomBaseNum = GetMachineRoomBaseNumber(gameServerCode);
            if (roomBaseNum == 0)
            {
                sRange = string.Empty;
                datalist = null;
                return false;
            }

            sRange = $"MachineUID > {roomBaseNum} && MachineUID < {roomBaseNum + 1000}";
            datalist = GetDBCommonGameSetting(sRange, gameServerCode);
            return datalist.Count > 0;
        }
        /// <summary>獲取遊戲單機一般共通設定</summary>
        public List<Dictionary<string, string>> GetDBCommonGameSetting(string sRange, GameServerCode gameServerCode)
        {
            List<Dictionary<string, string>> datalist;

            GameTypeCode gType = GameServerCodeToGameTypeCode(gameServerCode);
            if (gType == GameTypeCode.Slot)
                datalist = myAcess.select("CommonGameSetting", "*", sRange);
            else if (gType == GameTypeCode.Arcade)
                datalist = myAcess.select("ArcadesCommonGameSetting", "*", sRange);
            else if (gType == GameTypeCode.Fish)
                datalist = myAcess.select("FishCommonGameSetting", "*", sRange);
            else
                datalist = new List<Dictionary<string, string>>(); //No Data

            return datalist;
        }
        /// <summary>獲取遊戲全區共用設定</summary>
        public List<Dictionary<string, string>> GetDBCommonGlobalGameSetting(GameServerCode gameServerCode)
        {
            List<Dictionary<string, string>> datalist;
            string gServer = string.Format("GameServerCode = {0}", (int)gameServerCode);

            GameTypeCode gType = GameServerCodeToGameTypeCode(gameServerCode);
            if (gType == GameTypeCode.Slot)
                datalist = myAcess.select("CommonGlobalGameSetting", "*", gServer);
            else if (gType == GameTypeCode.Arcade)
                datalist = myAcess.select("ArcadesCommonGlobalGameSetting", "*", gServer);
            else if (gType == GameTypeCode.Fish)
                datalist = myAcess.select("FishCommonGlobalGameSetting", "*", gServer);
            else
                datalist = new List<Dictionary<string, string>>(); //No Data

            return datalist;
        }
