                    bottableList[i].UserUID = Convert.ToInt32(datalist[i]["UserUID"]);
                    bottableList[i].GameName = datalist[i]["GameName"];
                    bottableList[i].MachineUID = Convert.ToInt32(datalist[i]["MachineUID"]);
                    bottableList[i].Seat = Convert.ToInt32(datalist[i]["Seat"]);
