        /// <summary>
        /// 取得機器人房間配置
        /// </summary>
        public List<BotData> GetBotSetting(string gameName, bool getSex = true)
        {
            List<BotData> botDatalist = new List<BotData>();
            foreach (var Bot in bottableList)
            {
                if (Bot.GameName == gameName)
                {
                    UserData user = Getuser(Bot.UserUID);

                    BotData newbot = new BotData();
                    newbot.memberUniquelID = Bot.UserUID;
                    newbot.IsBotBill = Bot.IsBotBill;
                    //newbot.Account = user.UserID;
                    newbot.Nickname = user.Nickname;
                    newbot.Balnce = user.UserBalance;
                    if (getSex) { newbot.Sex = user.Sex; }
                    botDatalist.Add(newbot);
                }
            }
            return botDatalist;
        }

