        /// <summary>
        /// 新增電腦玩家
        /// </summary>
        /// <param name="BotCount"></param>
        /// <param name="EntityUID"></param>
        /// <param name="AspNetUserId"></param>
        public void InsertBot(int BotCount, int EntityUID, string AspNetUserId)
        {
            lock (AddPlayerlock)
            {
                int botListCount = bottableList.Count;
                int CurrentBotCount = bottableList.Count + 1;
                float Male = 0;
                float female = 0;

                for (int i = CurrentBotCount; i <= BotCount + botListCount; i++)
                {
                    var Userdatalist = new Dictionary<string, string>();

                    //===============新增至UserTable===========================
                    Userdatalist.Add("EntityId", EntityUID.ToString());
                    Userdatalist.Add("AspNetUserId", "'" + AspNetUserId + "'");
                    string botid = "Bot" + i.ToString("000");
                    Userdatalist.Add("UserID", "'" + botid + "'");
                    Userdatalist.Add("UserPwd", "'" + "botpassword" + "'");
                    Userdatalist.Add("Nickname", "'" + botid + "'");
                    Userdatalist.Add("UserBalance", "0");
                    Userdatalist.Add("IsBot", "1");
                    //================================平衡機器人男女比例===========================
                    if (Male == 0 || female == 0)
                    {
                        Random randSex = new Random();
                        int ran = randSex.Next(0, 2);

                        if (ran == 0)
                            female++;
                        else
                            Male++;

                        Userdatalist.Add("Sex", string.Format("{0}", ran));
                    }
                    else
                    {
                        if (Male / (female + Male) < 0.7f)
                        {
                            Userdatalist.Add("Sex", "1");
                            Male++;
                        }
                        else if (Male / (female + Male) > 0.7f)
                        {
                            Userdatalist.Add("Sex", "0");
                            female++;
                        }
                        else
                        {
                            Random randSex = new Random();
                            int ran = randSex.Next(0, 2);

                            if (ran == 0)
                                female++;
                            else
                                Male++;

                            Userdatalist.Add("Sex", string.Format("{0}", ran));
                        }
                    }


                    int resultid = 0;

                    try
                    {
                        resultid = myAcess.insert("Usertable", Userdatalist);
                    }
                    catch (Exception e)
                    {
                        string log = "CacheManeger: 6347";

                        Console.WriteLine(log);
                    }


                    UserData _userdata = new UserData(resultid, EntityUID);

                    //_userdata.UserUID = resultid;
                    //_userdata.EntityId = EntityUID;
                    _userdata.AspNetUserId = AspNetUserId;
                    _userdata.UserID = botid;
                    _userdata.UserPwd = "botpassword";
                    _userdata.Nickname = botid;
                    _userdata.Sex = 0;
                    _userdata.UserBalance = 0;
                    _userdata.Email = "";
                    _userdata.blockFlag = false;
                    _userdata.IsBot = true;

                    lock (UserDataList)
                    {
                        UserDataList.Add(resultid, _userdata);
                    }

                    MyConsole.WriteLine("DBCache User LAST UID = {0}", _userdata.UserUID);
                    //==========================================================
                }

                for (int i = CurrentBotCount; i <= BotCount + botListCount; i++)
                {
                    var Botdatalist = new Dictionary<string, string>();
                    string botid = "Bot" + i.ToString("000");
                    //===============新增至BotTable==============================
                    int UID = GetuserUID(botid);
                    Botdatalist.Add("UserUID", UID.ToString());
                    //Botdatalist.Add("GameName", "");
                    Botdatalist.Add("MachineUID", "0");
                    Botdatalist.Add("Seat", "0");
                    Botdatalist.Add("IsEnabled", "0");
                    Botdatalist.Add("IsBotBill", "0");

                    try
                    {
                        int resultid = myAcess.insert("BotTable", Botdatalist);

                        bottableList.Add(new BotTableData());
                        bottableList[bottableList.Count - 1].BotUID = resultid;
                        bottableList[bottableList.Count - 1].UserUID = UID;
                        bottableList[bottableList.Count - 1].GameName = "";
                        bottableList[bottableList.Count - 1].MachineUID = 0;
                        bottableList[bottableList.Count - 1].Seat = 0;
                        bottableList[bottableList.Count - 1].IsEnabled = false;
                        bottableList[bottableList.Count - 1].IsBotBill = false;
                        MyConsole.WriteLine("DBCache Bot LAST UID = {0}", resultid);
                    }
                    catch (Exception e)
                    {
                        string log = "CacheManeger: 6406";

                        Console.WriteLine(log);
                    }

                    //==========================================================
                }
            }
        }

