        /// <summary>任選一個假玩機器人</summary>
        public void RandomChooseBot(out int botUid, out int machUid)
        {
            botUid = 0;
            machUid = 0;
            if (bottableList.Count > 0)
            {
                Random rand = new Random(Guid.NewGuid().GetHashCode());
                int botidx = rand.Next(bottableList.Count);

                botUid = bottableList[botidx].UserUID;
                if (bottableList[botidx].IsEnabled && bottableList[botidx].IsBotBill == false)
                {
                    machUid = bottableList[botidx].MachineUID;
                }
            }
        }
