        /// <summary>取得機器人所在GameServer</summary>
        public GameServerCode GetBotWhereServerType(int botUid)
        {
            GameServerCode serverType = GameServerCode.None;
            if (bottableList.Count > 0)
            {
                foreach (BotTableData info in bottableList)
                {
                    if (info.UserUID == botUid)
                    {
                        if (info.IsEnabled) // && info.IsBotBill)  //要入賬的機器人才算
                        {
                            serverType = GameNameToGameServerCode(info.GameName);
                        }
                    }
                }
            }
            return serverType;
        }

        /// <summary>清除全部機器人的Situation狀態</summary>
        public void ClearAllBotSituation()
        {
            //MyConsole.WriteLine("清除全部機器人的Situation狀態");
            lock (UserDataList)
            {
                foreach (UserData info in UserDataList.Values)
                {
                    if (info.IsBot)
                    {
                        info.Usersituation = 0;
                    }
                }
            }

            Dictionary<string, string> updatedata = new Dictionary<string, string> { { "Usersituation", "0" } };

            myAcess.update("Usertable", updatedata, "IsBot = 1");

        }

