        #region 機器人模型規則
        /// <summary>
        ///  取出DB機器人模式設定資料
        /// </summary>
        public void GetDBAllBotSetting()
        {
            var datalist = myAcess.select("BotSetting", "*");

            if (datalist.Count > 0)
            {
                lock (BotSettingDataDict)
                {
                    if (BotSettingDataDict.Count > 0)
                    {
                        BotSettingDataDict.Clear();
                    }
                }

                int serverCount = Enum.GetNames(typeof(GameServerCode)).Count();

                for (int i = 0; i < datalist.Count; i++)
                {
                    GameServerCode gserver = (GameServerCode)Convert.ToInt32(datalist[i]["GameServerCode"]);

                    if ((int)gserver < serverCount && gserver >= GameServerCode.XiyouGame)
                    {
                        BotSettingData botSetting = new BotSettingData();
                        botSetting.UID = Convert.ToInt32(datalist[i]["UID"]);
                        botSetting.RestType = Convert.ToInt32(datalist[i]["RestType"]);
                        botSetting.ModeType = Convert.ToInt32(datalist[i]["ModeType"]);
                        botSetting.EmptSeatNum = Convert.ToInt32(datalist[i]["EmptSeatNum"]);
                        lock (BotSettingDataDict)
                        {
                            BotSettingDataDict.Add(gserver, botSetting);
                        }
                    }
                }
            }
        }
        /// <summary>
        ///  獲取機器人押分規則資料
        /// </summary>
        public List<Dictionary<string, string>> GetDBBotRuleSetting(GameServerCode gserver)
        {
            var gs = GetGSInstance(gserver);
            if (gs != null)
            {
                var datalist = gs.GetDBBotRuleSetting();
                return datalist;
            }
            else
            {
                // (#AddNewServer 03)
