        public List<Dictionary<string, string>> GetDBBotRestSetting(GameServerCode gserver)
        {
            int gServerCode = (int)gserver;
            List<Dictionary<string, string>> datalist = myAcess.select("BotRestRule", "*", String.Format("GameServerCode = '{0}'", gServerCode));
            if (datalist.Count <= 0)
            {
                MyConsole.WriteLine(gserver + " BotRestRule Get Error");
            }
            return datalist;
        }
        /// <summary>
        ///  獲取機器人模式設定資料
        /// </summary>
        public Dictionary<string, string> GetDBBotModeSetting(GameServerCode gserver)
        {
            Dictionary<string, string> resdata = new Dictionary<string, string>();
            lock (BotSettingDataDict)
            {
                if (BotSettingDataDict.ContainsKey(gserver))
                {
                    resdata.Add("GameServer", gserver.ToString());
                    resdata.Add("RestType", BotSettingDataDict[gserver].RestType.ToString());
                    resdata.Add("ModeType", BotSettingDataDict[gserver].ModeType.ToString());
                }
            }
            return resdata;
        }
