        /// <summary>
        /// 獲取歷史紀錄DB資料
        /// </summary>
        private void GetDBhistoryInfo()
        {
            MakeHistoryInfo(GameServerCode.XiyouGame, xiyouGlobalSettingList.NumberOfOpen, 10);
            MakeHistoryInfo(GameServerCode.SuperKingDerby, superKingDerbyGlobalSettingList.NumberOfOpen, 10);
            MakeHistoryInfo(GameServerCode.Ferrari, ferrariGlobalSettingList.NumberOfOpen, 12);
            MakeHistoryInfo(GameServerCode.DrollMonkey, drollMonkeyGlobalSettingList.NumberOfOpen, 10);
            MakeHistoryInfo(GameServerCode.BMW3D, bmw3DGlobalSettingList.NumberOfOpen, 10);
            MakeHistoryInfo(GameServerCode.AstonMartin, astonMartinGlobalSettingList.NumberOfOpen, 10);
            MakeHistoryInfo(GameServerCode.SuperAltyn, superAltynGlobalSettingList.NumberOfOpen, 10);
            MakeHistoryInfo(GameServerCode.MonkeyKing2, monkeyKing2GlobalSettingList.NumberOfOpen, 10);
            MakeHistoryInfo(GameServerCode.FIFA2022, fifa2022GlobalSettingList.NumberOfOpen, 12);
            MakeHistoryInfo(GameServerCode.BigSmall, bigSmallGlobalSetting.NumberOfOpen, 12);
        }

        /// <summary>製作押分機 歷史紀錄 historyInfo DB表格</summary>
        /// <param name="gserver">GameServerCode</param>
        /// <param name="numberOfOpen">機台數</param>
        /// <param name="historyLength">歷史紀錄長度</param>
        private void MakeHistoryInfo(GameServerCode gserver, int numberOfOpen, int historyLength)
        {
            var gs = GetGSInstance(gserver);
            if (gs != null)
            {
                int machUid = gs.MachineStartNumber;
                MakeHistoryInfo(gserver, machUid, numberOfOpen, historyLength);
            }
            else
            {
                if (machineDataList.ContainsKey(gserver))
                {
                    int machUid = machineDataList[gserver].MachineStartNumber();
                    MakeHistoryInfo(gserver, machUid, numberOfOpen, historyLength);
                }
            }
        }
        private void MakeHistoryInfo(GameServerCode gServer, int machineStartNumber, int numberOfOpen, int historyLength)
        {
            int machUid = machineStartNumber;

            for (int i = 0; i < numberOfOpen; i++)
            {
                //MyConsole.WriteLine("MachineUID=" + machUid);

                var dataDic = myAcess.select("historytable", "", string.Format("MachineUID = {0}", machUid), "Buildtime ASC", historyLength.ToString());

                List<HistoryData> hisInfoList = new List<HistoryData>();

                int hisCount = 0;
                if (dataDic.Count > 0)
                {
                    for (; hisCount < dataDic.Count; hisCount++)
                    {
                        hisInfoList.Add(new HistoryData());
                        hisInfoList[hisCount].HistoryUID = Convert.ToInt32(dataDic[hisCount]["HistoryUID"]);
                        //hisInfoList[hisCount].MachineUID = Convert.ToInt32(dataDic[hisCount]["MachineUID"]);
                        hisInfoList[hisCount].PrizeData = dataDic[hisCount]["PrizeData"];
                    }
                }

                if (hisCount < historyLength)
                {
                    Dictionary<string, string> hRecData = new Dictionary<string, string>();
                    hRecData.Add("MachineUID", "'" + machUid + "'");
                    hRecData.Add("PrizeData", "'0'");

                    for (; hisCount < historyLength; hisCount++)
                    {
                        try
                        {
                            int huid = myAcess.insert("historytable", hRecData);

                            if (huid > 0)
                            {
                                hisInfoList.Add(new HistoryData());
                                hisInfoList[hisCount].HistoryUID = huid;
                                //hisInfoList[hisCount].MachineUID = machUid;
                                hisInfoList[hisCount].PrizeData = "0";
                            }
                            //MyConsole.WriteLine("Machine(" + machUid + ")補紀錄:" + huid);
                        }
                        catch (Exception e)
                        {
                            string log = "CacheManeger: 6995";

                            Console.WriteLine(log);
                        }
                    }
                }

                historyInfoDict.Add(machUid, hisInfoList);
                historyRecIndex.Add(machUid, hisInfoList[0].HistoryUID);
                machUid++;
            }
        }

