        /// <summary>
        /// 更新DB
        /// </summary>
        /// <param name="machineUID"></param>
        /// <param name="updatedata"></param>
        public void UpdateHistory(int historyUID, Dictionary<string, string> updatedata)
        {
            //int resullt = myAcess.update("historytable", updatedata, "HistoryUID", historyUID.ToString());
            OperTionDBBox TempOperTionDBBox = new OperTionDBBox(OpertionCode.update1, "historytable", updatedata, "HistoryUID", historyUID.ToString());
            lock (Program.opertionDBBoxs)
            {
                Program.opertionDBBoxs.Add(TempOperTionDBBox);
            }

            int machineUID = Convert.ToInt32(updatedata["MachineUID"]);

            if (historyInfoDict.ContainsKey(machineUID))
            {
                List<HistoryData> hisInfoList;
                historyInfoDict.TryGetValue(machineUID, out hisInfoList);

                int length = hisInfoList.Count;
                int cnt = 0;
                for (; cnt < length; cnt++)
                {
                    if (hisInfoList[cnt].HistoryUID == historyUID)
                    {
                        string removeWord = "'";
                        hisInfoList[cnt].PrizeData = updatedata["PrizeData"].Trim(removeWord.ToCharArray()); //引號問題
                        cnt++;
                        if (cnt >= length) cnt = 0;
                        historyRecIndex[machineUID] = hisInfoList[cnt].HistoryUID;
                        break;
                    }
                }

                //foreach (HistoryData data in hisInfoList)
                //{
                //    if (data.HistoryUID == historyUID)
                //    {
                //        data.PrizeData = updatedata["PrizeData"];
                //    }
                //}
                //historyRecIndex[machineUID] = historyUID;

                //Console.WriteLine("machineUID=" + machineUID + ", historyUID=" + historyUID + ", Next=" + historyRecIndex[machineUID]);
            }
        }
