        /// <summary>獲取玩家遊戲紀錄</summary>
        /// <param name="UserUID"></param>
        /// <param name="Start"></param>
        /// <param name="End"></param>
        public SearchUserGameAccountInfo SearchUserGameData(GameServerCode code, int UserUID, UserAccountData SearchInfo)
        {

            //var datalist = myAcess.select("UserGameDatatable", "*", "Buildtime");

            SearchUserGameAccountInfo TempInfo = new SearchUserGameAccountInfo();

            UserAccountData mUserAccountData = new UserAccountData();

            List<UserGameAccountData> TempUserGameData = new List<UserGameAccountData>();

            //List<UserGameData> values = new List<UserGameData>(userGameDataList);

            mUserAccountData.StartTime = SearchInfo.StartTime;
            mUserAccountData.EndTime = SearchInfo.EndTime;

            //string GameName = GameServerCodeToGameName(code);
            DateTime StartTime = Convert.ToDateTime(SearchInfo.StartTime);
            DateTime EndTime = Convert.ToDateTime(SearchInfo.EndTime);
            EndTime = EndTime.AddHours(23);
            EndTime = EndTime.AddMinutes(59);
            EndTime = EndTime.AddSeconds(59);
            long Search_L_Limit = 0;
            long Search_U_Limit = 0;
            int TotalDataNum = 0;
            int TotalPage = 0;
            int CurrentPage = 0;
            int DataUnitNum = 0;
            int GameEnumNum = (int)code;

            //switch(GameName)
            //{
            //    case "齐天大圣": GameEnumNum = 2; break;
            //    case "公路之王": GameEnumNum = 3; break;
            //    case "金鸡": GameEnumNum = 4; break;
            //    case "湛蓝": GameEnumNum = 5; break;
            //    case "海豚": GameEnumNum = 6; break;
            //    case "豹月": GameEnumNum = 7; break;
            //    case "高尔夫": GameEnumNum = 8; break;
            //    case "古怪猴子": GameEnumNum = 9; break;
            //    case "发发发": GameEnumNum = 10; break;
            //    case "黄金树": GameEnumNum = 11; break;
            //    case "小丑": GameEnumNum = 12; break;
            //    case "蝴蝶": GameEnumNum = 13; break;
            //    case "奖金熊": GameEnumNum = 14; break;
            //}

            CurrentPage = SearchInfo.CurrentPage;
            DataUnitNum = SearchInfo.DataUnitNum;
            DateTime basetime = new DateTime(2020, 1, 1);
            Search_L_Limit = (StartTime.Date - basetime).Days;
            Search_U_Limit = (EndTime.Date - basetime).Days;
            Search_L_Limit = ((long)UserUID * 100000000) + (GameEnumNum * 100000) + Search_L_Limit;
            Search_U_Limit = ((long)UserUID * 100000000) + (GameEnumNum * 100000) + Search_U_Limit;
            MysqlTest test = new MysqlTest();

            try
            {
                string searchcontext = "";

                if (Search_L_Limit == Search_U_Limit)
                {
                    searchcontext = string.Format("SearchIndex = {0} ", Search_L_Limit);
                }
                else
                {
                    searchcontext = string.Format("SearchIndex between {0} And {1}", Search_L_Limit, Search_U_Limit);
                }

                var datalist = test.select("UserGameDatatable", "Count(*)", searchcontext);

                TotalDataNum = Convert.ToInt32(datalist[0]["Count(*)"]);

                if ((TotalDataNum % DataUnitNum) > 0)
                {
                    TotalPage = (TotalDataNum / DataUnitNum) + 1;
                }
                else
                {
                    TotalPage = (TotalDataNum / DataUnitNum);
                }

                if (TotalPage == 0)
                {
                    CurrentPage = 0;
                }
                else if (CurrentPage > TotalPage)
                {
                    CurrentPage = TotalPage;
                }
                else if (CurrentPage <= 0)
                {
                    if (TotalPage >= 1) CurrentPage = 1;
                    else CurrentPage = 0;
                }

                int StartIndex = (CurrentPage - 1) * DataUnitNum;

                if (TotalPage >= 1)
                {
                    searchcontext = "";

                    if (Search_L_Limit == Search_U_Limit)
                    {
                        searchcontext = string.Format("SearchIndex = {0} ", Search_L_Limit);
                    }
                    else
                    {
                        searchcontext = string.Format("SearchIndex between {0} And {1}", Search_L_Limit, Search_U_Limit);
                    }

                    var datalist2 = test.select("UserGameDatatable", "`SerialNumber`,`PrizeData`,`JpAccountUID`,`UserBetData`,`Balancebefore`,`TotalBet`,`TotalWin`,`Balanceafter`,`Buildtime`",
                    searchcontext,
                    "UserGameUID desc",
                    string.Format("{0},{1}", StartIndex, DataUnitNum)
                    );

                    for (int i = 0; i < datalist2.Count; i++)
                    {
                        UserGameAccountData tempdata = new UserGameAccountData();
                        tempdata.SerialNo = datalist2[i]["SerialNumber"];
                        DateTime dt = Convert.ToDateTime(datalist2[i]["Buildtime"]);
                        tempdata.LogTime = dt.ToString("yyyy/MM/dd HH:mm:ss");
                        tempdata.startBalance = Convert.ToDouble(datalist2[i]["Balancebefore"]);
                        tempdata.TotalBet = Convert.ToDouble(datalist2[i]["TotalBet"]);
                        tempdata.TotalWin = Convert.ToDouble(datalist2[i]["TotalWin"]);
                        tempdata.EndBalance = Convert.ToDouble(datalist2[i]["Balanceafter"]);
                        tempdata.Result = datalist2[i]["PrizeData"];
                        tempdata.PlayInfo = datalist2[i]["UserBetData"];
                        tempdata.JPType = "";
                        tempdata.JPWin = "";
                        int jpuid = Convert.ToInt32(datalist2[i]["JpAccountUID"]);
                        if (jpuid > 0)
                        {
                            if (jpAccountDataList.Where(x => x.UID == jpuid).Count() > 0)
                            {
                                JPAcoountData jpdata = jpAccountDataList.Where(x => x.UID == jpuid).First();

                                switch (jpdata.JpAward)
                                {
                                    case 1: tempdata.JPType = "MINOR"; break;
                                    case 2: tempdata.JPType = "MAJOR"; break;
                                    case 3: tempdata.JPType = "MEGA"; break;
                                    case 4: tempdata.JPType = "SUPER"; break;
                                }

                                tempdata.JPWin = jpdata.TotalWin.ToString("f2");
                            }
                        }
                        TempUserGameData.Add(tempdata);
                    }
                }

                mUserAccountData.CurrentPage = CurrentPage;
                mUserAccountData.DataUnitNum = SearchInfo.DataUnitNum;
                mUserAccountData.TotalPage = TotalPage;

                TempInfo.mUserGameAccountDataList = TempUserGameData;
                TempInfo.mUserAccountData = mUserAccountData;

                return TempInfo;
            }
            catch (Exception e)
            {
                MyConsole.Write(e.Message);
                MyConsole.WriteLine(e.StackTrace);
                return null;
            }
        }

