        object userGameDataUGUIDLocker = new object();

        public void InsertUserGamedata2(Dictionary<string, string> insertData, int machineUid, string buildTime, out JpAward jpAward, out int userUid, out int uguid, GameServerCode gameServerCode)
        {
            userUid = Convert.ToInt32(insertData["UserUID"]);
            int jpType = Convert.ToInt32(insertData["JpAccountUID"]);  //先將JpType儲存起來
            double totBet = Convert.ToDouble(insertData["TotalBet"]);
            double totWin = Convert.ToDouble(insertData["TotalWin"]);
            int machUid = Convert.ToInt32(insertData["GameMachine"]);
            string gameName = insertData["GameName"];
            string gameType = insertData["GameType"];
            int rankType = Convert.ToInt32(insertData["RankType"]);
            string rankData = insertData["RankData"];
            int sessionId = Convert.ToInt32(insertData["SessionID"]);
            string userIP = insertData["UserIP"];


            lock (userGameDataUGUIDLocker)
            {
                userGameDataUGUID++; //2022/03/01 改為只記錄唯一碼
                uguid = (int)userGameDataUGUID;
            }


            double hyperBigWater = 0;
            if (insertData.ContainsKey("HypeTake")) //網吧炒場取用值
            {
                hyperBigWater = Convert.ToDouble(insertData["HypeTake"]);
                insertData.Remove("HypeTake"); //此為額外資訊, 取用後須刪除, 以免寫入DB出錯
                //MyConsole.WriteLine("網吧炒場[" + gameName + "]取用值=" + hyperBigWater); //UNDONE: 網吧炒場取用值
            }


            int roundTimes;
            double buddhasPalmBank = 0;
            if (GameServerCodeToGameTypeCode(gameServerCode) == GameTypeCode.Fish && insertData.ContainsKey("Rounds")) //230925 新增魚機發射數
            {
                roundTimes = Convert.ToInt32(insertData["Rounds"]);
                insertData.Remove("Rounds"); //此為魚機額外資訊, 取用後須刪除, 以免寫入DB出錯

                if (gameServerCode == GameServerCode.OceanKing8)
                {
                    if (insertData.ContainsKey("BuddhasPalm")) //BuddhasPalm 累計值
                    {
                        buddhasPalmBank = Convert.ToDouble(insertData["BuddhasPalm"]);
                        insertData.Remove("BuddhasPalm"); //此為魚機額外資訊, 取用後須刪除, 以免寫入DB出錯
                    }
                }
            }
            else
            {
                roundTimes = 1; //除魚機外, 其餘遊戲固定為1
            }


            //字串格式加入單引號
            insertData["SerialNumber"] = "'" + insertData["SerialNumber"] + "'";
            insertData["SessionID"] = "'" + insertData["SessionID"] + "'";
            insertData["GameName"] = "'" + insertData["GameName"] + "'";
            insertData["GameType"] = "'" + insertData["GameType"] + "'";
            insertData["PrizeData"] = "'" + insertData["PrizeData"] + "'";
            insertData["UserBetData"] = "'" + insertData["UserBetData"] + "'";
            insertData["UserIP"] = "'" + insertData["UserIP"] + "'";
            insertData["RankData"] = "'" + insertData["RankData"] + "'";

            insertData["JpAccountUID"] = "0";  //清掉JpType, 將來出JP時會覆寫為Jp出牌紀錄的UID
            //DateTime date = Convert.ToDateTime(buildTime);
            //insertData.Add("TimeStamp", ((date.Year*10000)+(date.Month*100)+ date.Day).ToString());  //加入目前時間 
            insertData.Add("Buildtime", "'" + buildTime + "'");  //加入目前時間 

            OperTionDBBox TempOperTionDBBox = new OperTionDBBox(OpertionCode.insert, "UserGameDatatable", insertData);
            lock (Program.UserGameDataDBBoxs)
            {
                Program.UserGameDataDBBoxs.Add(TempOperTionDBBox);
            }
            //userGameDataList[userGameDataList.Count - 1].UserGameUID = uguid;


            UpdateUserSessionAccount(userUid, sessionId, userIP, totBet, totWin, 0d);

            jpAward = (JpAward)jpType;

            UpdateRankRecordTable(userUid, totBet, totWin);

            //UpdateReportGameData(userUid, gameName, gameType, totBet, totWin, buildTime);
            UpdateReportGameData(userUid, gameServerCode, gameType, totBet, totWin, buildTime, roundTimes);

            if (rankType > 0)
            {
                UpdatePlayerGameRankTable(userUid, machUid, gameName, rankType, rankData, buildTime);
            }

            UserData userData = Getuser(userUid);
            if (userData != null)
            {
                if (userData.IsBot == false)
                {
                    //Console.WriteLine("更新任務進度(遊玩局數)" + userUid + "-" + gameServerCode);
                    Dictionary<string, string> mInfo = new Dictionary<string, string>();
                    mInfo.Add("GameServerCode", ((int)gameServerCode).ToString());
                    mInfo.Add("Round", roundTimes.ToString());
                    //mInfo.Add("Round", "1");
                    mInfo.Add("Bet", insertData["TotalBet"]);

                    ExtraBonusKeyOutUnlockProc(userData, totBet); //#20231128

                    //紅包炒場 //#250211
                    GameTypeCode gameTypeCode = GameTypeNameToGameTypeCode(gameType);
                    var entity = GetEntityData(userData.EntityId);
                    double frbBet = roundTimes < 2 ? totBet : Math.Round(totBet / roundTimes, 4); //魚機要將 總押 除以 發射數
                    userData.SetPlayerFRBTimerProc(gameServerCode, gameTypeCode, machineUid, entity, frbBet, roundTimes);
                    CountPlayerRebate(userData, entity, totBet); //#250807
                    //Console.WriteLine("更新能量" + userUid + "-" + insertData["TotalBet"]);
                    //ConvertUserBetToEnergy(userData, totBet);

                    //玩家報告 #251203  #260211 移至 UpdateUserIpInfo 裡面
                    //PlayerReportBet(userData.UserUID, totBet, totWin, roundTimes, gameTypeCode);
                    //排行榜 #250924 玩家遊玩紀錄
                    RankEventRecord(entity, userData, totWin, totBet, gameServerCode);
                }
                else //是機器人
                {
                    if (userData.SessionID != sessionId)
                    {
                        //Console.WriteLine("更新機器人SessionID:" + userData.SessionID + "->" + sessionId);
                        //UpdataUserSessionID(sessionId, userUid);
                        userData.SessionID = sessionId;
                        UpdateUsertable(userUid, new Dictionary<string, string> { { "SessionID", userData.SessionID.ToString() } });
                        //AddUserdataUpdateList(userUid);
                    }
                }

                if (gameServerCode == GameServerCode.OceanKing8)
                {
                    userData.BuddhasPalm = buddhasPalmBank;
                    //海王8 如來神掌累積值 Update DB
                    Dictionary<string, string> tmpData = new Dictionary<string, string>();
                    tmpData.Add("UserUID", userUid.ToString());
                    tmpData.Add("BuddhasPalm", buddhasPalmBank.ToString());

                    OperTionDBBox TempOperTionDBBox2 = new OperTionDBBox(OpertionCode.insertUpdate, "UserBankTable", tmpData);
                    lock (Program.opertionDBBoxs)
                    {
                        Program.opertionDBBoxs.Add(TempOperTionDBBox2);
                    }
                    //MyConsole.WriteLine("[" + userUid + "] BuddhasPalm 寫入DB:" + buddhasPalmBank);//UNDONE: BuddhasPalm 寫入DB
                }

                if (hyperBigWater > 0) //網吧炒場
                {
                    int EntityId = userData.EntityId;
                    TakeEntityHypeBigWater(EntityId, userUid, hyperBigWater, uguid, gameServerCode, machineUid);
                }
            }
        }

