        DateTime lastCheckDeleteDate = new DateTime(2020, 1, 1, 0, 0, 0);
        int CheckUserGameDateDelayTimer = 0;
        /// <summary>檢查並保持30天玩家遊戲紀錄(此功能目前為OFF狀態)</summary>
        public void CheckUserGameDateKeep30Day()
        {
            //MARKLU: 刪除指定日期玩家遊戲紀錄
            if (CheckUserGameDateDelayTimer > 0)
            {
                CheckUserGameDateDelayTimer--;
                return;
            }

            DateTime today = DateTime.Now.Date;
            if (lastCheckDeleteDate != today)
            {
                DateTime lastKeepDate = today.AddDays(-30); //保留30日
                //DateTime lastKeepDate = today.AddDays(-7);  //UNDONELU: 測試保留7日
                if (!DeleteUserGamedataUseDate(lastKeepDate))
                {
                    lastCheckDeleteDate = today;  //已刪除完畢
                }
                else
                {
                    CheckUserGameDateDelayTimer = 1; //延時4秒
                }
            }
            else
            {
                CheckUserGameDateDelayTimer = 30 * 10; //延時10分鐘 (此函式每10~15分鐘叫一次應該就可以)
            }
        }
        /// <summary>刪除指定日期以前的玩家遊戲紀錄 (此功能目前為OFF狀態)</summary>
        public bool DeleteUserGamedataUseDate(DateTime lastKeepDate)
        {
            return false;  //2022/03/01 修改為不做任何動作, 過期DB資料由手動來刪除.
            //移除 Local Cache 紀錄
            int removeCnt = 0;
            int removeuid = 0;
            int recLength = userGameDataList.Count;

            if (recLength > 0)
            {
                //DateTime timer_start = DateTime.Now;
                DateTime compDate = lastKeepDate;
                MyConsole.WriteLine("移除 " + compDate + " 之前的玩家遊戲紀錄");

                lock (userGameDataList)
                {
                    while (true)
                    {
                        DateTime DBDate = Convert.ToDateTime(userGameDataList[removeCnt].BuildTime);//.Date;
                        if (DateTime.Compare(DBDate, compDate) >= 0)  //>=指定日期
                        {
                            break;
                        }
                        else
                        {
                            removeCnt++;
                            if (removeCnt >= recLength || removeCnt >= 10000)
                            {
                                break;
                            }
                        }
                    }

                    if (removeCnt > 0)
                    {
                        removeuid = userGameDataList[removeCnt - 1].UserGameUID;  //最後1筆要移除的UID
                        userGameDataList.RemoveRange(0, removeCnt);
                    }
                }

                //DateTime timer_end = DateTime.Now;
                //double timp_span = (timer_end - timer_start).TotalMilliseconds;
                //Console.WriteLine("移除玩家遊戲紀錄" + removeCnt + "筆, 耗用" + timp_span + "毫秒.  總記錄" + recLength + "筆");
                MyConsole.WriteLine("移除玩家遊戲紀錄" + removeCnt + "筆, 總記錄" + recLength + "筆");
            }

            if (removeuid > 0)
            {
                //DateTime timer_start = DateTime.Now;
                //移除 DB 紀錄
                //DELETE FROM UserGameDatatable WHERE string.Format("BuildTime<'{0:yyyy-MM-dd 00:00:00}", deleteDate)'
                //int result = myAcess.delete("UserGameDatatable", string.Format("BuildTime<'{0:yyyy-MM-dd HH:mm:ss}'", compDate));
                int result = myAcess.delete("UserGameDatatable", string.Format("UserGameUID<='{0}'", removeuid));

                if (removeCnt != result)
                {
                    //遊戲紀錄移除數量有錯誤, 重取LocalCache
                    //userGameDataList.Clear();
                    //GetUserGameData();
                    MyConsole.WriteLine("遊戲紀錄移除數量有錯誤!!  (" + removeCnt + "," + result + ")", Console.ForegroundColor = ConsoleColor.Red);
                }

                //DateTime timer_end = DateTime.Now;
                //double timp_span = (timer_end - timer_start).TotalMilliseconds;
                //Console.WriteLine("移除DB耗用" + timp_span + "毫秒");
                return true;
            }
            else
            {
                return false;  //已刪除完畢
            }
        }

        DateTime RankCompareTime = new DateTime(2020, 10, 20);
        /// <summary>獲取玩家遊戲成就紀錄</summary>
        private void GetPlayerGameRankTable()
        {
            var datalist = myAcess.select("PlayerGameRankTable", "*");

            if (datalist.Count > 0)
            {
                if (PlayerGameRankTableList.Count > 0)
                {
                    PlayerGameRankTableList.Clear();
                }

                for (int i = 0; i < datalist.Count; i++)
                {
                    int userUid = Convert.ToInt32(datalist[i]["UserUID"]);
                    DateTime buildTime = Convert.ToDateTime(datalist[i]["Buildtime"]);
                    PlayerGameRankTable ntable = new PlayerGameRankTable
                    {
                        RecUid = Convert.ToInt32(datalist[i]["RecUid"]),
                        GameMachine = Convert.ToInt32(datalist[i]["GameMachine"]),
                        GameName = datalist[i]["GameName"],
                        RankType = Convert.ToInt32(datalist[i]["RankType"]),
                        RankData = datalist[i]["RankData"],
                        BuildTime = buildTime.ToString("yyyy/MM/dd HH:mm:ss"),
                        BuildSecond = (int)(buildTime - RankCompareTime).TotalSeconds
                    };

                    if (PlayerGameRankTableList.ContainsKey(userUid))
                    {
                        PlayerGameRankTableList[userUid].Add(ntable);
                    }
                    else
                    {
                        List<PlayerGameRankTable> templist = new List<PlayerGameRankTable> { ntable };
                        PlayerGameRankTableList.Add(userUid, templist);
                    }
                    //MyConsole.WriteLine("Uid:" + ntable.RecUid + ", Game:" + ntable.GameName + ", RankType:" + ntable.RankType + ", Times:" + ntable.BuildTime + ", Sec:" + ntable.BuildSecond);
                }
            }
        }
        /// <summary>玩家遊戲成就紀錄紀錄筆數</summary>
        int PlayerGameRankLength = 20;
        /// <summary>更新玩家遊戲成就紀錄</summary>
        private void UpdatePlayerGameRankTable(int userUid, int machUid, string gameName, int rankType, string rankData, string sBuildTime)
        {
            DateTime buildTime = Convert.ToDateTime(sBuildTime);

            Dictionary<string, string> insertData = new Dictionary<string, string>();
            insertData.Add("UserUID", userUid.ToString());
            insertData.Add("GameMachine", machUid.ToString());
            insertData.Add("GameName", "'" + gameName + "'");
            insertData.Add("RankType", rankType.ToString());
            insertData.Add("RankData", "'" + rankData + "'");
            insertData.Add("BuildTime", "'" + sBuildTime + "'");

            //搜尋此玩家全部紀錄, 並找出最舊的紀錄位置
            bool pexist = false;
            if (PlayerGameRankTableList.ContainsKey(userUid))
            {
                pexist = true;
                List<PlayerGameRankTable> templist = PlayerGameRankTableList[userUid];
                if (templist.Count >= PlayerGameRankLength)
                {
                    //紀錄足夠, 更新舊紀錄
                    int idx = 0;
                    int dts = (int)(DateTime.Now - RankCompareTime).TotalSeconds;
                    for (int i = 0; i < templist.Count; i++)
                    {
                        if (templist[i].BuildSecond < dts) //If時間比較舊 (BuildSecond越大時間越新)
                        {
                            dts = templist[i].BuildSecond;
                            idx = i;
                        }
                    }

                    PlayerGameRankTable tmpTab = templist[idx];
                    tmpTab.GameMachine = machUid;
                    tmpTab.GameName = gameName;
                    tmpTab.RankType = rankType;
                    tmpTab.RankData = rankData;
                    tmpTab.BuildTime = sBuildTime;
                    tmpTab.BuildSecond = (int)(buildTime - RankCompareTime).TotalSeconds;

                    OperTionDBBox TempOperTionDBBox = new OperTionDBBox(OpertionCode.update1, "PlayerGameRankTable", insertData, "RecUid", tmpTab.RecUid.ToString());
                    lock (Program.opertionDBBoxs)
                    {
                        Program.opertionDBBoxs.Add(TempOperTionDBBox);
                    }
                    return;
                }
            }

            //沒有此玩家紀錄, 或紀錄不足20筆 --> 新增
            try
            {
                PlayerGameRankTable ntable = new PlayerGameRankTable
                {
                    GameMachine = machUid,
                    GameName = gameName,
                    RankType = rankType,
                    RankData = rankData,
                    BuildTime = sBuildTime,
                    BuildSecond = (int)((buildTime - RankCompareTime).TotalSeconds)
                };

                try
                {

                    int nguid = myAcess.insert("PlayerGameRankTable", insertData);
                    ntable.RecUid = nguid;

                    if (pexist)
                    {
                        PlayerGameRankTableList[userUid].Add(ntable);
                    }
                    else
                    {
                        List<PlayerGameRankTable> templist = new List<PlayerGameRankTable> { ntable };
                        PlayerGameRankTableList.Add(userUid, templist);
                    }
                }
                catch (Exception e)
                {
                    string log = "CacheManeger: 8003";

                    Console.WriteLine(log);
                }

            }
            catch (Exception ex)
            {
            }
        }
        /// <summary>獲取玩家遊戲RANK資訊</summary>
        /// <param name="userUid">玩家Uid</param>
        /// <param name="getCnt">取得紀錄筆數</param>
        private List<UserRankStru> GetUserGameDataRank(int userUid, int getCnt)
        {
            //MARKLU: 獲取玩家遊戲RANK資訊
            if (PlayerGameRankTableList.ContainsKey(userUid))
            {
                if (PlayerGameRankTableList[userUid].Count > 0)
                {
                    List<UserRankStru> tempData = new List<UserRankStru>();
                    List<PlayerGameRankTable> rankList = PlayerGameRankTableList[userUid].ToList();
                    rankList.Sort((a, b) => b.BuildSecond.CompareTo(a.BuildSecond));
                    int cnt = 0;
                    foreach (PlayerGameRankTable info in rankList)
                    {
                        UserRankStru temp = new UserRankStru();
                        temp.GameName = info.GameName;
                        temp.RankType = info.RankType;
                        temp.RankData = info.RankData;
                        temp.BuildTime = info.BuildTime; //.ToString("yyyy/MM/dd HH:mm:ss");
                        tempData.Add(temp);
                        //MyConsole.WriteLine("Uid:" + info.RecUid + ", BuildTime=" + info.BuildTime + ", BuildSecond=" + info.BuildSecond);
                        cnt++;
                        if (cnt >= getCnt) break;
                    }
                    return tempData;
                }
            }
            return null;
        }
