        /// <summary>獲取別人玩家遊戲RANK資訊</summary>
        /// <param name="UserUID"></param>
        public List<UserRankStru> OtherUserGameDataRank(int UserUID)
        {
            int getCnt = 5; //取5筆紀錄
            bool isRealPlayer = true;
            bool botIsReall = false;
            for (int i = bottableList.Count - 1; i >= 0; i--)
            {
                if (bottableList[i].UserUID == UserUID)
                {
                    isRealPlayer = false;
                    if (bottableList[i].IsBotBill)
                    {
                        botIsReall = true;
                    }
                    break;
                }
            }

            if (isRealPlayer || botIsReall)
            {
                //搜尋真人遊戲資訊
                return GetUserGameDataRank(UserUID, getCnt);
            }
            else
            {
                //搜尋陪玩機器人遊戲資訊
                if (FakeBotRankTableList.ContainsKey(UserUID))
                {
                    if (FakeBotRankTableList[UserUID].Count > 0)
                    {
                        List<UserRankStru> tempData = new List<UserRankStru>();
                        List<FakeBotRankTable> rankList = FakeBotRankTableList[UserUID].ToList();
                        rankList.Sort((a, b) => b.BuildSecond.CompareTo(a.BuildSecond));
                        int cnt = 0;
                        foreach (FakeBotRankTable info in rankList)
                        {
                            UserRankStru temp = new UserRankStru();
                            temp.GameName = info.GameName;
                            temp.RankType = info.RankType;
                            temp.RankData = info.RankData;
                            temp.BuildTime = info.BuildTime; //.ToString("yyyy/MM/dd HH:mm:ss");
                            tempData.Add(temp);
                            //MyConsole.WriteLine("Uid:" + info.RecUid + ", BuildTime=" + info.BuildTime + ", BuildSecond=" + info.BuildSecond);
                            cnt++;
                            if (cnt >= getCnt) break;
                        }
                        return tempData;
                    }
                }
            }
            return null;
        }
