        private void GetReportGameData()
        {
            //string where = "TimeStamp=" + Program.GetLogTimeStamp(DateTime.Now).ToString(); //只取今日資料
            //string where = "Buildtime>=" + "'" + DateTime.Now.ToString("yyyy-MM-dd") + " 00:00:00" + "'"; //只取今日資料
