            var datalist = myAcess.select("ReportGameDatatable", "*");
            //var datalist = myAcess.select("ReportGameDatatable", "*", "", "Buildtime ASC");
            //Console.WriteLine("獲取玩家遊戲報告:" + datalist.Count);
            //MyConsole.WriteLine("WHERE = " + where);

