        /// <summary>紀錄玩家目前所在的 遊戲主機 和 報告紀錄UID</summary>
        private Dictionary<int, ReportGameDataRec> ReportGameDataRec = new Dictionary<int, ReportGameDataRec>();
        /// <summary>依據玩家目前所在遊戲位置找出ReportGameData紀錄</summary>
        private ReportGameData GetPlayerReportGameDataRecord(int userUid, GameServerCode gameServerCode, string gameName, DateTime dateTime)
        {
            if (ReportGameDataRec.ContainsKey(userUid))
            {
                if (ReportGameDataRec[userUid].GameServerCode == gameServerCode)
                {
                    if (ReportGameDataRec[userUid].Buildtime.Date == dateTime.Date)
                    {
                        int uguid = ReportGameDataRec[userUid].UserGameUID;
                        //lock (ReportGameDataList) //呼叫者已鎖
                        {
                            int totCount = ReportGameDataList.Count;
                            for (int i = totCount - 1; i >= 0; i--)
                            {
                                if (ReportGameDataList[i].UserGameUID == uguid)
                                {
                                    //MyConsole.WriteLine("找到已紀錄的 UID=" + ReportGameDataRec[userUid].UserGameUID);
                                    return ReportGameDataList[i];
                                    //fine = true;
                                }
                            }
                        }
                    }
                }
            }

            //找不到, 搜尋ReportGameDataList
            //lock (ReportGameDataList) //呼叫者已鎖
            {
                int totCount = ReportGameDataList.Count;
                for (int i = totCount - 1; i >= 0; i--)
                {
                    if (ReportGameDataList[i].UserUID == userUid && ReportGameDataList[i].GameName == gameName)
                    {
                        if (ReportGameDataList[i].Buildtime.Date == dateTime.Date)
                        {
                            //登錄玩家目前所在遊戲的資訊
                            if (ReportGameDataRec.ContainsKey(userUid))
                            {
                                ReportGameDataRec[userUid].UserGameUID = ReportGameDataList[i].UserGameUID;
                                ReportGameDataRec[userUid].GameServerCode = gameServerCode;
                                ReportGameDataRec[userUid].Buildtime = dateTime;
                                //MyConsole.WriteLine("找不到紀錄:玩家已登錄 UID=" + ReportGameDataRec[userUid].UserGameUID);
                            }
                            else
                            {
                                ReportGameDataRec temp = new ReportGameDataRec();
                                temp.UserGameUID = ReportGameDataList[i].UserGameUID;
                                temp.GameServerCode = gameServerCode;
                                temp.Buildtime = dateTime;
                                ReportGameDataRec.Add(userUid, temp);
                                //MyConsole.WriteLine("找不到紀錄:玩家未登錄 UID=" + ReportGameDataRec[userUid].UserGameUID);
                            }
                            return ReportGameDataList[i];
                        }
                    }
                }
            }

            //MyConsole.WriteLine("找不到紀錄今日遊玩紀錄, 玩家:" + userUid + ", 遊戲:" + gameName + ", 日期:" + dateTime.Date);
            return null;
        }

        /// <summary>更新玩家遊戲報告紀錄</summary>
        public void UpdateReportGameData(int userUid, GameServerCode gameServerCode, string gameType, double bet, double win, string sDateTime, int roundTimes)
        {
            DateTime dateTime = Convert.ToDateTime(sDateTime); //比對用
            string gameName = GameServerCodeToGameName(gameServerCode);

            lock (ReportGameDataList)
            {
                ReportGameData rgdata = GetPlayerReportGameDataRecord(userUid, gameServerCode, gameName, dateTime);
                if (rgdata != null)
                {
                    if (bet > 0)
                    {
                        rgdata.TotalBet += (decimal)bet;
                        rgdata.Rounds += roundTimes; //有押分才算局數
                    }
                    else
                    {
                        rgdata.FreeRoundWin += win; //押分=0 為 FreeGame
                    }
                    rgdata.TotalWin += (decimal)win;
                    rgdata.update = true;
                    return;
                }
            }

            InsertReportGameData(userUid, gameName, gameType, bet, win, 0, 0, 0, 0, dateTime);
        }
        /// <summary>更新玩家遊戲報告JP紀錄</summary>
        public void UpdateReportGameDataJP(GameServerCode gameServerCode, int userUid, double jpWin, string sDateTime)
        {
            DateTime dateTime = Convert.ToDateTime(sDateTime); //比對用
            string gameName = GameServerCodeToGameName(gameServerCode);

            lock (ReportGameDataList)
            {
                ReportGameData rgdata = GetPlayerReportGameDataRecord(userUid, gameServerCode, gameName, dateTime);
                if (rgdata != null)
                {
                    rgdata.JpWin += (decimal)jpWin;
                    rgdata.TotalWin += (decimal)jpWin;
                    rgdata.update = true;
                    return;
                }
            }

            string gameType = GameTypeCodeToGameTypeName(GameServerCodeToGameTypeCode(gameServerCode));
            InsertReportGameData(userUid, gameName, gameType, 0, 0, jpWin, 0, 0, 0, dateTime);
        }
        /// <summary>更新玩家遊戲報告紅包紀錄</summary>
        public void UpdateReportGameDataRedEnvelope(GameServerCode gameServerCode, int userUid, double redEnvelope, string sDateTime)
        {
            DateTime dateTime = Convert.ToDateTime(sDateTime); //比對用 
            string gameName = GameServerCodeToGameName(gameServerCode);

            lock (ReportGameDataList)
            {
                ReportGameData rgdata = GetPlayerReportGameDataRecord(userUid, gameServerCode, gameName, dateTime);
                if (rgdata != null)
                {
                    rgdata.GameRedEnvelope += redEnvelope;
                    rgdata.TotalWin += (decimal)redEnvelope;
                    rgdata.update = true;
                    return;
                }
            }

            string gameType = GameTypeCodeToGameTypeName(GameServerCodeToGameTypeCode(gameServerCode));
            InsertReportGameData(userUid, gameName, gameType, 0, 0, 0, redEnvelope, 0, 0, dateTime);
        }
        /// <summary>更新玩家遊戲報告紅包彩票獎勵紀錄</summary>
        public void UpdateReportGameDataReward(int userUid, string gameName, string gameType, double missionredenvelope, double lottoticketbonus, double freeroundwin, DateTime dateTime)
        {
            lock (ReportGameDataList)
            {
                int totCount = ReportGameDataList.Count;
                for (int i = totCount - 1; i >= 0; i--)
                {
                    if (ReportGameDataList[i].UserUID == userUid && ReportGameDataList[i].GameName == gameName)
                    {
                        if (ReportGameDataList[i].Buildtime.Date == dateTime.Date)
                        {
                            //MyConsole.WriteLine("更新 玩家遊戲報告 Date=" + dateTime.Date + ", " + ReportGameDataList[i].UserGameUID);
                            ReportGameDataList[i].MissionRedEnvelope += missionredenvelope;
                            ReportGameDataList[i].LottoTicketBonus += lottoticketbonus;
                            ReportGameDataList[i].FreeRoundWin += freeroundwin;
                            ReportGameDataList[i].TotalWin += ((decimal)missionredenvelope + (decimal)lottoticketbonus + (decimal)freeroundwin);
                            ReportGameDataList[i].update = true;
                            return;
                        }
                    }
                }
            }

            InsertReportGameData(userUid, gameName, gameType, 0, 0, 0, 0, missionredenvelope, lottoticketbonus, dateTime);
        }

        /// <summary>更新玩家遊戲報告大廳彩金紀錄</summary>
        public void UpdateReportGameDataReward(int userUid, string gameName, string gameType, double lobbybonus, DateTime dateTime)
        {
            lock (ReportGameDataList)
            {
                int totCount = ReportGameDataList.Count;
                for (int i = totCount - 1; i >= 0; i--)
                {
                    if (ReportGameDataList[i].UserUID == userUid && ReportGameDataList[i].GameName == gameName)
                    {
                        if (ReportGameDataList[i].Buildtime.Date == dateTime.Date)
                        {
