        }

        /// <summary>新增1筆玩家遊戲報告紀錄</summary>
        void InsertReportGameData(int userUid, string gameName, string gameType, double bet, double win, double jpWin, double redEnvelope, double missionredenvelope, double lottoticketbonus, DateTime dateTime)
        {
            int lastuguid = 0;
            ReportGameData rgData = new ReportGameData();
            lock (ReportGameDataList)
            {
                if (ReportGameDataList.Count > 0) lastuguid = ReportGameDataList[ReportGameDataList.Count - 1].UserGameUID;
                lastuguid += 1;
                //Console.WriteLine("新增 玩家遊戲報告 Date=" + dateTime.Date + ", " + lastuguid);
                rgData.UserGameUID = lastuguid;
                rgData.UserUID = userUid;
                rgData.GameName = gameName;
                rgData.GameType = gameType;
                rgData.TotalBet = (decimal)bet;
                rgData.TotalWin = ((decimal)win + (decimal)jpWin + (decimal)redEnvelope + (decimal)missionredenvelope + (decimal)lottoticketbonus); //+ freeroundwin); 2024/07/22 修正跨日FreeGame記帳Bug
                rgData.JpWin = (decimal)jpWin;
                rgData.GameRedEnvelope = redEnvelope;
                rgData.MissionRedEnvelope = missionredenvelope;
                rgData.LottoTicketBonus = lottoticketbonus;
                rgData.FreeRoundWin = (bet > 0) ? 0 : win; //押分=0 為 FreeGame
                rgData.Buildtime = dateTime;
                rgData.update = false;

                if (bet > 0) rgData.Rounds = 1;
                else rgData.Rounds = 0;

                ReportGameDataList.Add(rgData);
            }

            int entityId = 0;
