                entityId = userData.EntityId;
            }

            //Dictionary<string, string> insertData = rgData.GetUpdateData();
            Dictionary<string, string> insertData = new Dictionary<string, string>();
            insertData.Add("UserGameUID", lastuguid.ToString());
            insertData.Add("UserUID", userUid.ToString());
            insertData.Add("GameName", "'" + gameName + "'");
            insertData.Add("GameType", "'" + gameType + "'");
