            insertData.Add("LobbyBonus", "0");
            insertData.Add("FreeRoundWin", rgData.FreeRoundWin.ToString("f2"));
            insertData.Add("TimeStamp", Program.GetLogTimeStamp(dateTime).ToString());
            insertData.Add("Buildtime", "'" + dateTime.ToString("yyyy-MM-dd HH:mm:ss") + "'");
            insertData.Add("EntityUID", entityId.ToString());

            OperTionDBBox TempOperTionDBBox2 = new OperTionDBBox(OpertionCode.insert, "ReportGameDatatable", insertData);
            lock (Program.ReportInsertDBBoxs)
            {
                Program.ReportInsertDBBoxs.Add(TempOperTionDBBox2);
            }
