        /// <summary>檢查並保持90天玩家遊戲報告紀錄</summary>
        public void CheckReportGameDateKeep90Day()
        {
            //MARKLU: 刪除指定日期玩家遊戲紀錄
            if (CheckUserReportGameDateDelayTimer > 0)
            {
                CheckUserReportGameDateDelayTimer--;
                return;
            }

            DateTime today = DateTime.Now.Date;
            if (lastReportCheckDeleteDate != today)
            {
                DateTime lastKeepDate = today.AddDays(-90); //保留90日
                //DateTime lastKeepDate = today.AddDays(-2);  //UNDONELU: 測試保留2日
                if (!DeleteReportGamedataUseDate(lastKeepDate))
                {
                    lastReportCheckDeleteDate = today;  //已刪除完畢
                }
                else
                {
                    CheckUserReportGameDateDelayTimer = 1; //延時2秒
                }
            }
            else
            {
                CheckUserReportGameDateDelayTimer = 30 * 15; //延時15分鐘 (此函式每10~15分鐘叫一次應該就可以)
            }
        }
        /// <summary>刪除指定日期以前的玩家遊戲報告紀錄</summary>
        bool DeleteReportGamedataUseDate(DateTime lastKeepDate)
        {
            //移除 Local Cache 紀錄
            int removeCnt = 0;
            int removeuid = 0;
            int recLength = 0;

            lock (ReportGameDataList)
            {
                recLength = ReportGameDataList.Count;
                if (recLength > 0)
                {
                    //DateTime timer_start = DateTime.Now;
                    DateTime compDate = lastKeepDate;
                    MyConsole.WriteLine("移除 " + compDate + " 之前的玩家遊戲報告紀錄");

                    while (true)
                    {
                        DateTime DBDate = ReportGameDataList[removeCnt].Buildtime; //.Date;
                        if (DateTime.Compare(DBDate, compDate) >= 0)  //>=指定日期
                        {
                            break;
                        }
                        else
                        {
                            removeCnt++;
                            if (removeCnt >= recLength || removeCnt >= 10000)
                            {
                                break;
                            }
                        }
                    }

                    if (removeCnt > 0)
                    {
                        removeuid = ReportGameDataList[removeCnt - 1].UserGameUID;  //最後1筆要移除的UID
                        ReportGameDataList.RemoveRange(0, removeCnt);
                    }

                    //DateTime timer_end = DateTime.Now;
                    //double timp_span = (timer_end - timer_start).TotalMilliseconds;
                    //Console.WriteLine("移除玩家遊戲報告紀錄" + removeCnt + "筆, 耗用" + timp_span + "毫秒.  總記錄" + recLength + "筆");
                    MyConsole.WriteLine("移除玩家遊戲報告紀錄" + removeCnt + "筆, 總記錄" + recLength + "筆");
                }
            }

            if (removeuid > 0)
            {
                //DateTime timer_start = DateTime.Now;
                //移除 DB 紀錄
                //DELETE FROM UserGameDatatable WHERE string.Format("BuildTime<'{0:yyyy-MM-dd 00:00:00}", deleteDate)'
                //int result = myAcess.delete("UserGameDatatable", string.Format("BuildTime<'{0:yyyy-MM-dd HH:mm:ss}'", compDate));
                int result = myAcess.delete("ReportGameDatatable", string.Format("UserGameUID<='{0}'", removeuid));

                if (removeCnt != result)
                {
                    //遊戲報告紀錄移除數量有錯誤, 重取LocalCache
                    //ReportGameDataList.Clear();
                    GetReportGameData();
                    MyConsole.WriteLine("遊戲報告紀錄移除數量有錯誤!!  (" + removeCnt + "," + result + ")", Console.ForegroundColor = ConsoleColor.Red);
                }

                //DateTime timer_end = DateTime.Now;
                //double timp_span = (timer_end - timer_start).TotalMilliseconds;
                //Console.WriteLine("移除DB耗用" + timp_span + "毫秒");
                return true;
            }
            else
            {
                return false;  //已刪除完畢
            }
        }
        DateTime lastReportCheckDeleteDate = new DateTime(2019, 1, 1, 0, 0, 0);
        int CheckUserReportGameDateDelayTimer = 0;

