            lock (ReportGameDataList)
            {
                foreach (ReportGameData d in ReportGameDataList)
                {
                    if (d.update == true)
                    {
                        d.update = false;
                        Dictionary<string, string> updatadata = d.GetUpdateData();
                        OperTionDBBox TempOperTionDBBox = new OperTionDBBox(OpertionCode.update1, "ReportGameDatatable", updatadata, "UserGameUID", d.UserGameUID.ToString());
                        DataList.Add(TempOperTionDBBox);
                    }
                }
            }

            return DataList;
        }
