        /// <summary>
        /// 獲取內帳DB資料
        /// </summary>
        private void GetDBprobabilityData()
        {
            var datalist = myAcess.select("Probabilitytable", "*");

            if (datalist.Count > 0)
            {
                if (probabilityDataList.Count > 0) { probabilityDataList.Clear(); }

                for (int i = 0; i < datalist.Count; i++)
                {
                    int machUid = Convert.ToInt32(datalist[i]["MachineUID"]);
                    if (!probabilityDataList.ContainsKey(machUid))
                    {
                        ProbabilityData tmpdata = new();
                        tmpdata.GetDBData(machUid, datalist[i]);
                        probabilityDataList.Add(machUid, tmpdata);
                    }
                }
            }

            {
                //檢查各遊戲機率帳數量是否與開放台數相符
                foreach (GameServerCode gServer in Enum.GetValues(typeof(GameServerCode)))
                {
                    int numOfOpen = 0;

                    var gs = GetGSInstance(gServer);
                    if (gs != null)
                    {
                        if (gs.NewTypeServer)
                        {
                            //MyConsole.WriteLine($"    [{gServer}]是新類型伺服器, 跳過 機率重建");
                            continue;
                        }

                        numOfOpen = gs.GlobalSettingData.NumberOfOpen;
                    }
                    else
                    {
                        if (machineDataList.ContainsKey(gServer))
                        {
                            numOfOpen = GetMachineNumberOfOpen(gServer);
                        }
                    }

                    if (numOfOpen > 0)
                    {
                        int machineUID = machineDataList[gServer].MachineStartNumber();
                        int buildCnt = 0;
                        for (int i = 0; i < numOfOpen; i++, machineUID++)
                        {
                            if (!probabilityDataList.ContainsKey(machineUID))
                            {
                                InsertNewProbability(machineUID);
                                buildCnt++;
                            }
                        }
                        if (buildCnt > 0) MyConsole.WriteLine("重建 " + gServer + " Probability Table, 台數:" + buildCnt);
                    }
                }

                //foreach (GameServerCode gServer in Enum.GetValues(typeof(GameServerCode)))
                //{
                //    if (gServer != GameServerCode.None && gServer != GameServerCode.Login)
                //    {
                //        int baseNumber = GetMachineRoomBaseNumber(gServer);
                //        int numberOfOpen = GetMachineNumberOfOpen(gServer);
                //        if (baseNumber > 0 && numberOfOpen > 0)
                //        {
                //            int machineUID = baseNumber + 1;
                //            MyConsole.WriteLine("重建 " + gServer + " Probability Table, 台數:" + numberOfOpen);
                //            InsertNewProbability(machineUID, numberOfOpen);
                //        }
                //    }
                //}
            }


            //製作IP模式機率遊戲List  #251112
            var datalist2 = myAcess.select("GameServerCalcPool", "*");

            if (datalist2.Count > 0)
            {
                if (GameServerCalcPoolList.Count > 0) { GameServerCalcPoolList.Clear(); }

                for (int i = 0; i < datalist2.Count; i++)
                {
                    GameServerCode server = (GameServerCode)Convert.ToInt32(datalist2[i]["GameServer"]);
                    if (!GameServerCalcPoolList.ContainsKey(server))
                    {
                        GameServerCalcPool tmpdata = new();
                        tmpdata.GetDBData(server, datalist2[i]);
                        GameServerCalcPoolList.Add(server, tmpdata);
                    }
                }
            }

            foreach (GameServerCode gServer in Enum.GetValues(typeof(GameServerCode)))
            {
                //if (machineDataList.ContainsKey(gServer) == false)
                if (IsGameServerEnable(gServer) == false) //|| NonGameServerList.Contains(gServer))
                {
                    continue;
                }

                if (!GameServerCalcPoolList.ContainsKey(gServer))
                {
                    var gs = GetGSInstance(gServer);
                    if (gs == null || gs.NewTypeServer == false) continue;

                    string server = ((int)gServer).ToString();
                    string name = GameServerCodeToGameName(gServer);
                    if (name == "") name = gServer.ToString();

                    var ndata = new Dictionary<string, string>();
                    ndata.Add("GameServer", server);
                    ndata.Add("GameName", "'" + name + "'");

                    int uid = myAcess.insert("GameServerCalcPool", ndata);
                    if (uid > 0)
                    {
                        GameServerCalcPool tmpdata = new(gServer);
                        GameServerCalcPoolList.Add(gServer, tmpdata);
                        MyConsole.WriteLine($"    重建 {gServer}({name}) GameServerCalcPool");
                    }
                    else
                    {
                        MyConsole.WriteLine($"    重建 {gServer}({name}) 失敗 !! GameServerCalcPool");
                    }
                }
            }
        }

