        /// <summary>取出整份遊戲Probability資料(GameServer開機)</summary>
        public List<Dictionary<string, string>> GetProbabilityData(GameServerCode gServer)
        {
            List<Dictionary<string, string>> tempdatalist = new List<Dictionary<string, string>>();

            int numOfOpen = 0;
            int machineUID = 0;

            var gs = GetGSInstance(gServer);
            if (gs != null)
            {
                numOfOpen = gs.GlobalSettingData.NumberOfOpen;
                machineUID = gs.MachineStartNumber;
            }
            else if (machineDataList.ContainsKey(gServer))
            {
                numOfOpen = GetMachineNumberOfOpen(gServer);
                machineUID = machineDataList[gServer].MachineStartNumber();
            }

            if (numOfOpen > 0 && machineUID > 0)
            {
                for (int i = 0; i < numOfOpen; i++, machineUID++)
                {
                    if (probabilityDataList.ContainsKey(machineUID))
                    {
                        tempdatalist.Add(probabilityDataList[machineUID].GetProbabilityData());
                    }
                    else
                    {
                        InsertNewProbability(machineUID);
                        tempdatalist.Add(null); //加入null, Client端會製作一組新帳目
                    }
                }
            }
            return tempdatalist;
        }
