        private object ProbabilityLock = new object();
        /// <summary>插入一筆新的Probability資料</summary>
        /// <param name="machineUID">機號</param>
        /// <param name="count">插入數量</param>
        private void InsertNewProbability(int machineUID, int count = 1)
        {
            DateTime dt = DateTime.Now.Date;
            string today = string.Format("{0:yyyy-MM-dd}", dt);

            var datalist = new Dictionary<string, string>
            {
                { "MachineUID", "" },
                { "SerDate", "'" + today + "'" },
            };

            try
            {
                lock (ProbabilityLock)
                {
                    for (int i = 0; i < count; i++)
                    {
                        datalist["MachineUID"] = "'" + machineUID + "'";
                        int uid = myAcess.insert("Probabilitytable", datalist);
                        if (uid > 0)
                        {
                            ProbabilityData probData = new ProbabilityData
                            {
                                ProbabilityUID = uid,
                                MachineUID = machineUID,
                                //SerDate = dt,
                                SerDate = today,
                                update = false, //創建Local時不須更新DB
                            };

                            lock (probabilityDataList)
                            {
                                probabilityDataList.Add(machineUID, probData);
                            }

                            machineUID++;
                        }
                        else
                        {
                            break;
                        }
                    }
                }
            }
            catch (Exception e)
            {
                string log = "CacheManeger: 8906";

                MyConsole.WriteLine(log);
            }

        }
