        /// <summary></summary>
        public List<OperTionDBBox> GetXiyouAccountDBUpdateData()
        {
            List<OperTionDBBox> DataList = new List<OperTionDBBox>();

            List<int> Temp = new List<int>();

            lock (xiyouAccountDataUpdateList)
            {
                Temp = xiyouAccountDataUpdateList.Select(x => x).ToList();

                xiyouAccountDataUpdateList.Clear();
            }

            lock (xiyouAccountDataUpdateDict)
            {
                foreach (int machUid in Temp)
                {
                    if (xiyouAccountDataUpdateDict.TryGetValue(machUid, out List<XiyouAccountData> acclist))
                    {
                        foreach (XiyouAccountData d in acclist)
                        {
                            d.update = false;
                            Dictionary<string, string> updatadata = d.GetUpdateData(false);
                            OperTionDBBox TempOperTionDBBox = new OperTionDBBox(OpertionCode.update1, "XiyouAccountTable", updatadata, "AccountUID", d.AccountUID.ToString());
                            DataList.Add(TempOperTionDBBox);
                        }
                    }
                }
            }
            return DataList;
        }
