        #region 機率外帳(總帳) (#AddNewServer 07)
        /// <summary>建立機台號碼列表</summary>
        List<int> MakeMachineListTable(GameServerCode gServer, int totCnt)
        {
            int machNo = GetMachineStartNumber(gServer);
            List<int> machList = new List<int>();
            for (int i = 0; i < totCnt; i++) { machList.Add(machNo++); }
            return machList;
        }
        /// <summary>將機台號碼從機台號碼列表清除(設為0)</summary>
        bool RemoveMachineNo(int machNo, List<int> machList)
        {
            for (int i = 0; i < machList.Count; i++)
            {
                if (machList[i] == machNo)
                {
                    machList[i] = 0;
                    return true;
                }
            }
            return false;
        }
        /// <summary>計算機台號碼列表還有的機台數量</summary>
        int CheckMachineTotalCount(List<int> machList)
        {
            int tcnt = 0;
            for (int i = 0; i < machList.Count; i++)
            {
                if (machList[i] > 0)
                {
                    tcnt++;
                }
            }
            return tcnt;
        }


        #region Xiyou 機率外帳(總帳)
        /// <summary>獲取Xiyou外帳DB資料</summary>
        private void GetXiyouAccountData()
        {
            var datalist = myAcess.select("XiyouAccountTable", "*");

            int totCnt = xiyouGlobalSettingList.NumberOfOpen;
            List<int> machList = MakeMachineListTable(GameServerCode.XiyouGame, totCnt);

            if (datalist.Count > 0)
            {
                if (xiyouAccountDataUpdateDict.Count > 0) { xiyouAccountDataUpdateDict.Clear(); }
                for (int i = 0; i < datalist.Count; i++)
                {
                    XiyouAccountData accData = new XiyouAccountData();
                    accData.GetDBData(datalist[i], false);

                    if (xiyouAccountDataUpdateDict.ContainsKey(accData.MachineUID))
                    {
                        xiyouAccountDataUpdateDict[accData.MachineUID].Add(accData);
                    }
                    else
                    {
                        List<XiyouAccountData> tempList = new List<XiyouAccountData>();
                        tempList.Add(accData);
                        xiyouAccountDataUpdateDict.Add(accData.MachineUID, tempList);

                        RemoveMachineNo(accData.MachineUID, machList);
                    }
                }


            }

            int rebuilt = CheckMachineTotalCount(machList);
            if (rebuilt > 0)
            {
                MyConsole.WriteLine("重建 Xiyou Account Table 台數:" + rebuilt);
                for (int x = 0; x < totCnt; x++)
                {
                    if (machList[x] > 0)
                    {
                        insertXiyouAccountData(machList[x], 0);
                        insertXiyouAccountData(machList[x], 1);
                    }
                }
            }
        }
