        /// <summary>獲取BigSmall外帳DB資料</summary>
        private void GetBigSmallAccountData()
        {
            var datalist = myAcess.select("BigSmallAccountTable", "*");

            int totCnt = bigSmallGlobalSetting.NumberOfOpen;
            List<int> machList = MakeMachineListTable(GameServerCode.BigSmall, totCnt);

            if (datalist.Count > 0)
            {
                if (bigSmallAccountDataUpdateDict.Count > 0) { bigSmallAccountDataUpdateDict.Clear(); }
                for (int i = 0; i < datalist.Count; i++)
                {
                    BigSmallAccountData accData = new BigSmallAccountData();
                    accData.GetDBData(datalist[i], false);

                    if (bigSmallAccountDataUpdateDict.ContainsKey(accData.MachineUID))
                    {
                        bigSmallAccountDataUpdateDict[accData.MachineUID].Add(accData);
                    }
                    else
                    {
                        List<BigSmallAccountData> tempList = new List<BigSmallAccountData>();
                        tempList.Add(accData);
                        bigSmallAccountDataUpdateDict.Add(accData.MachineUID, tempList);

                        RemoveMachineNo(accData.MachineUID, machList);
                    }
                }
            }

            int rebuilt = CheckMachineTotalCount(machList);
            if (rebuilt > 0)
            {
                MyConsole.WriteLine("重建 BigSmall Account Table 台數:" + rebuilt);
                for (int x = 0; x < totCnt; x++)
                {
                    if (machList[x] > 0)
                    {
                        int machineUID = machList[x];
                        InsertBigSmallAccountData(machineUID, 0);
                        InsertBigSmallAccountData(machineUID, 1);
                    }
                }
            }
        }
        /// <summary>檢查BigSmallAccountData</summary>
        /// <param name="machineUID"></param>
        public void CheckBigSmallAccountData(int machineUID)
        {
            bool ishaveType0 = false;
            bool ishaveType1 = false;

            if (bigSmallAccountDataUpdateDict.TryGetValue(machineUID, out List<BigSmallAccountData> acclist))
            {
                foreach (BigSmallAccountData temp in acclist)
                {
                    if (temp.AccountType == 0)
                    {
                        ishaveType0 = true;
                    }
                    else if (temp.AccountType == 1)
                    {
                        ishaveType1 = true;
                    }
                }
            }

            if ((!ishaveType0))
            {
                InsertBigSmallAccountData(machineUID, 0);
            }

            if (!ishaveType1)
            {
                InsertBigSmallAccountData(machineUID, 1);
            }
        }
        /// <summary>插入一筆BigSmall外帳資料</summary>
        /// <param name="machineUID"></param>
        /// <param name="AccountType"></param>
        private void InsertBigSmallAccountData(int machineUID, int AccountType)
        {
            Dictionary<string, string> data = new Dictionary<string, string>();
            data.Add("MachineUID", machineUID.ToString());
            data.Add("AccountType", AccountType.ToString());
            int uid = myAcess.insert("BigSmallAccountTable", data);

            BigSmallAccountData hwdata = new BigSmallAccountData();
            hwdata.AccountUID = uid;
            hwdata.MachineUID = machineUID;
            hwdata.AccountType = AccountType;

            if (bigSmallAccountDataUpdateDict.ContainsKey(machineUID))
            {
                bigSmallAccountDataUpdateDict[machineUID].Add(hwdata);
            }
            else
            {
                List<BigSmallAccountData> tempList = new List<BigSmallAccountData>();
                tempList.Add(hwdata);
                bigSmallAccountDataUpdateDict.Add(machineUID, tempList);
            }
            AddBigSmallAccountUpdate(machineUID);
        }
        /// <summary>更新一筆BigSmall外帳資料</summary>
        /// <param name="machineUID"></param>
        /// <param name="AccountType"></param>
        public void UpdateBigSmallAccountData(int machineUID, Dictionary<string, string> refdata)
        {
            lock (bigSmallAccountDataUpdateDict)
            {
                if (bigSmallAccountDataUpdateDict.TryGetValue(machineUID, out List<BigSmallAccountData> acclist))
                {
                    foreach (BigSmallAccountData temp in acclist)
                    {
                        temp.AccumulatecGameData(refdata);
                        AddBigSmallAccountUpdate(machineUID);
                    }
                }
            }
        }
        /// <summary>歸零BigSmallAccountData</summary>
        /// <param name="machineUID">機號(0=全部機台)</param>
        /// <param name="accType0">內帳</param>
        /// <param name="accType1">外帳</param>
        public void ClearBigSmallAccountData(int machineUID, bool accType0, bool accType1)
        {
            lock (bigSmallAccountDataUpdateDict)
            {
                if (machineUID > 0) //清指定機台
                {
                    if (bigSmallAccountDataUpdateDict.TryGetValue(machineUID, out List<BigSmallAccountData> acclist))
                    {
                        foreach (BigSmallAccountData temp in acclist)
                        {
                            if ((temp.AccountType == 0 && accType0) || (temp.AccountType == 1 && accType1))
                            {
                                ClearBigSmallAccount(temp);
                                AddBigSmallAccountUpdate(machineUID);
                            }
                        }
                    }
                }
                else //清全部機台
                {
                    foreach (List<BigSmallAccountData> acclist in bigSmallAccountDataUpdateDict.Values)
                    {
                        foreach (BigSmallAccountData temp in acclist)
                        {
                            if ((temp.AccountType == 0 && accType0) || (temp.AccountType == 1 && accType1))
                            {
                                ClearBigSmallAccount(temp);
                                AddBigSmallAccountUpdate(temp.MachineUID);
                            }
                        }
                    }
                }
            }
        }
        /// <summary>歸零BigSmallAccountData</summary>
        private void ClearBigSmallAccount(BigSmallAccountData accData)
        {
            accData.ClearCache();
            accData.update = true;
        }
        #endregion


