            lock (oceanKing8AccountDataUpdateDict)
            {
                if (machineUID > 0) //清指定機台
                {
                    if (oceanKing8AccountDataUpdateDict.TryGetValue(machineUID, out List<OceanKing8AccountData> acclist))
                    {
                        foreach (OceanKing8AccountData temp in acclist)
                        {
                            if ((temp.AccountType == 0 && accType0) || (temp.AccountType == 1 && accType1))
                            {
                                ClearOceanKing8Account(temp);
                                AddOceanKing8AccountUpdate(machineUID);
                            }
                        }
                    }
                }
                else //清全部機台
                {
                    foreach (List<OceanKing8AccountData> acclist in oceanKing8AccountDataUpdateDict.Values)
                    {
                        foreach (OceanKing8AccountData temp in acclist)
                        {
                            if ((temp.AccountType == 0 && accType0) || (temp.AccountType == 1 && accType1))
                            {
                                ClearOceanKing8Account(temp);
                                AddOceanKing8AccountUpdate(temp.MachineUID);
                            }
                        }
                    }
                }
            }
        }
