        /// <summary>
        /// 獲取西遊日帳資料
        /// </summary>
        private void GetXiyouAccountDetailData()
        {
            var datalist = myAcess.select("XiyouAccountDetailtable", "*", "", "RecDate ASC");
            if (datalist.Count > 0)
            {
                //取出Cache用資料(只取當日)
                if (xiyouAccountDetailDataUpdateDict.Count > 0) xiyouAccountDetailDataUpdateDict.Clear();
                DateTime todat = DateTime.Today.Date;
                for (int i = 0; i < datalist.Count; i++)
                {
                    DateTime recDate = Convert.ToDateTime(datalist[i]["RecDate"]).Date;
                    //只有今日的Detail帳目會更新, 舊帳目不會再更新, 因此只須將今日的帳目Cache起來.
                    if (recDate == todat)
                    {
                        XiyouAccountData temp = new XiyouAccountData();
                        temp.GetDBData(datalist[i], true);

                        if (xiyouAccountDetailDataUpdateDict.ContainsKey(temp.MachineUID))
                        {
                            xiyouAccountDetailDataUpdateDict[temp.MachineUID].Add(temp);
                        }
                        else
                        {
                            List<XiyouAccountData> tempList = new List<XiyouAccountData>();
                            tempList.Add(temp);
                            xiyouAccountDetailDataUpdateDict.Add(temp.MachineUID, tempList);
                        }
                    }
                }

                //取出盈餘校正用資料
                if (xiyouSurplusRegulateDataDict.Count > 0) xiyouSurplusRegulateDataDict.Clear();
                for (int i = 0; i < datalist.Count; i++)
                {
                    XiyouAccountDetailData temp = new XiyouAccountDetailData();
                    temp.GetDBData(datalist[i]);

                    int machUid = temp.MachineUID;

                    if (xiyouSurplusRegulateDataDict.ContainsKey(machUid))
                    {
                        xiyouSurplusRegulateDataDict[machUid].Add(temp);
                    }
                    else
                    {
                        List<XiyouAccountDetailData> tempList = new List<XiyouAccountDetailData>();
                        tempList.Add(temp);
                        xiyouSurplusRegulateDataDict.Add(machUid, tempList);
                    }
                }
            }
        }
        /// <summary>更新HighWayKingAccountDetailData (Cache資料)</summary>
        public void UpdatexiyouAccountDetailData(int machineUID, Dictionary<string, string> refdata)
        {
            lock (xiyouAccountDetailDataUpdateDict)
            {
                if (xiyouAccountDetailDataUpdateDict.TryGetValue(machineUID, out List<XiyouAccountData> acclist))
                {
                    foreach (XiyouAccountData temp in acclist)
                    {
                        temp.AccumulatecGameData(refdata);
                        AddXiyouAccountDetailUpdate(machineUID);
                    }
                }
            }
        }
        private object XiyouDetailLock = new object();
        /// <summary>更新xiyouAccountDetailData (盈餘校正用資料)</summary>
        /// <param name="machineUID"></param>
        /// <param name="date"></param>
        /// <param name="data"></param>
        public int UpdatexiyouAccountDetailData(int machineUID, string date, Dictionary<string, string> data)
        {
            DateTime chToday = Convert.ToDateTime(date).Date; //比對用
            string dbToday = date.Replace('/', '-'); //寫入DB用'-'
            double betAdd = Convert.ToDouble(data["TotalBet"]);
            double winAdd = Convert.ToDouble(data["TotalWin"]);
            double bbetAdd = Convert.ToDouble(data["BPTotalBet"]);
            double bwinAdd = Convert.ToDouble(data["BPTotalWin"]);
            string accountTable = "XiyouAccountDetailtable";

            bool makeNewRecord = false;
            //Console.WriteLine("machineUID" + machineUID + ", Date=" + date);
            //1.找出 機號相同 且 日期相同 的紀錄
            //        若找到則更新Data.
            //        若找不到則
            //    2.找出 機號相同 的紀錄總數, 
            //            若數量不足則 新增2筆,
            //            若數量足夠則 找出最舊的2筆紀錄, 清除後寫入新Data.

            if (xiyouSurplusRegulateDataDict.ContainsKey(machineUID))
            {
                xiyouSurplusRegulateDataDict.TryGetValue(machineUID, out List<XiyouAccountDetailData> tempList);

                int upCount = 0, atype0 = 0, atype1 = 0;

                foreach (XiyouAccountDetailData xdata in tempList)
                {
                    if (xdata.RecDate == chToday)
                    {
                        //int result1 = DBLink.update(accountTable, dataDic, "AccountDatailUID", xdata.AccountUID.ToString());
                        //if (result1 <= 0)
                        //{
                        //    return result1;
                        //}

                        xdata.AccountPlay(betAdd, winAdd, bbetAdd, bwinAdd);

                        upCount++;
                        if (xdata.AccountType == 0) atype0++;
                        else if (xdata.AccountType == 1) atype1++;
                    }
                }

                if (upCount < 2)
                {
                    //沒有今日帳, 用最舊的紀錄修改
                    //if (tempList.Count >= 5 * 2)  //UNDONE: 單日帳 先測試5筆 -------------- 
                    if (tempList.Count >= 30 * 2 * 3)  //外帳30筆, 內帳30筆, 保留3個月
                    {
                        MysqlTest DBLink = new MysqlTest();
                        //Console.WriteLine("修改舊紀錄");
                        var dataDic3 = DBLink.select(accountTable, "AccountDatailUID, RecDate", string.Format("MachineUID = {0}", machineUID), "RecDate ASC", ""); //找出並排序全部紀錄
                        if (dataDic3 == null)
                        {
                            return 0;
                        }
                        Dictionary<string, string> dataDic2 = new Dictionary<string, string>();
                        dataDic2.Add("MachineUID", machineUID.ToString());
                        dataDic2.Add("RecDate", "'" + dbToday + "'");
                        //選出第1筆最舊的紀錄並清除內容
                        dataDic2.Add("AccountDatailUID", dataDic3[0]["AccountDatailUID"]);
                        dataDic2.Add("AccountType", "0");
                        int result2 = DBLink.replace(accountTable, dataDic2);
                        if (result2 <= 0)
                        {
                            return result2;
                        }
                        //選出第2筆最舊的紀錄並清除內容
                        dataDic2["AccountDatailUID"] = dataDic3[1]["AccountDatailUID"];
                        dataDic2["AccountType"] = "1";
                        //Clear DB紀錄
                        int result3 = DBLink.replace(accountTable, dataDic2);
                        if (result3 <= 0)
                        {
                            return result3;
                        }
                        //Update DB紀錄
                        //int result4 = DBLink.update(accountTable, dataDic, string.Format("MachineUID = {0} AND RecDate = '{1}'", machineUID, dbToday));
                        //if (result4 <= 0)
                        //{
                        //    return result4;
                        //}

                        int accuid1 = Convert.ToInt32(dataDic3[0]["AccountDatailUID"]);
                        int accuid2 = Convert.ToInt32(dataDic3[1]["AccountDatailUID"]);

                        //Update Cache 紀錄
                        ReplaceXiyouAccountDetailData(machineUID, chToday, accuid1, accuid2);

                        //Update 盈餘校正用資料 紀錄
                        foreach (XiyouAccountDetailData xdata in tempList)
                        {
                            if (xdata.AccountUID == accuid1 || xdata.AccountUID == accuid2)
                            {
                                xdata.AccountPlay(betAdd, winAdd, bbetAdd, bwinAdd);
                                xdata.RecDate = chToday;
                            }
                        }

                        DBLink.CloseCoon();
                        DBLink = null;
                    }
                    else  //紀錄總數不足
                    {
                        makeNewRecord = true;
                        //Console.WriteLine("紀錄總數不足, 新增紀錄");
                    }
                }
            }
            else  //無此機號, 新增此機號Key值
            {
                List<XiyouAccountDetailData> tempList = new List<XiyouAccountDetailData>();
                xiyouSurplusRegulateDataDict.Add(machineUID, tempList);
                makeNewRecord = true;
                //Console.WriteLine("無此機號, 新增此機號Key值");
            }


            if (makeNewRecord)
            {
                MysqlTest DBLink = new MysqlTest();
                //Console.WriteLine("創建新紀錄");
                Dictionary<string, string> dataDic2 = new Dictionary<string, string>();
                dataDic2.Add("MachineUID", machineUID.ToString());
                dataDic2.Add("RecDate", "'" + dbToday + "'");

                int accuid1, accuid2;
                lock (XiyouDetailLock) //鎖住Insert程序, 避免回傳AccUid錯誤. 2021/04/29
                {
                    dataDic2.Add("AccountType", "0");
                    accuid1 = DBLink.insert(accountTable, dataDic2);
                    if (accuid1 <= 0)
                    {
                        return accuid1;
                    }

                    dataDic2["AccountType"] = "1";
                    accuid2 = DBLink.insert(accountTable, dataDic2);
                    if (accuid2 <= 0)
                    {
                        return accuid2;
                    }
                }
                //Update DB紀錄
                //int result5 = DBLink.update(accountTable, dataDic, string.Format("MachineUID = {0} AND RecDate = '{1}'", machineUID, dbToday));
                //if (result5 <= 0)
                //{
                //    return result5;
                //}

                //Cache 加入新紀錄
                ReplaceXiyouAccountDetailData(machineUID, chToday, accuid1, accuid2);

                //盈餘校正用資料 加入新紀錄
                XiyouAccountDetailData tempAcc1 = new XiyouAccountDetailData();
                XiyouAccountDetailData tempAcc2 = new XiyouAccountDetailData();
                tempAcc1.AccountPlay(betAdd, winAdd, bbetAdd, bwinAdd);
                tempAcc2.AccountPlay(betAdd, winAdd, bbetAdd, bwinAdd);

                tempAcc1.AccountUID = accuid1;
                tempAcc2.AccountUID = accuid2;

                tempAcc1.RecDate = chToday;
                tempAcc2.RecDate = chToday;

                tempAcc1.MachineUID = machineUID;
                tempAcc2.MachineUID = machineUID;

                tempAcc1.AccountType = 0;
                tempAcc2.AccountType = 1;

                xiyouSurplusRegulateDataDict[machineUID].Add(tempAcc1);
                xiyouSurplusRegulateDataDict[machineUID].Add(tempAcc2);

                DBLink.CloseCoon();
                DBLink = null;
            }

            return 1;
        }
        /// <summary>置換XiyouAccountDetailData (Cache資料)</summary>
        public void ReplaceXiyouAccountDetailData(int machineUID, DateTime chToday, int accuid1, int accuid2)
        {
            bool ac1 = false, ac2 = false;
            lock (xiyouAccountDetailDataUpdateDict)
            {
                if (xiyouAccountDetailDataUpdateDict.TryGetValue(machineUID, out List<XiyouAccountData> values))
                {
                    foreach (XiyouAccountData info in values)
                    {
                        info.RecDate = chToday;
                        info.ClearCache();
                        info.update = true;

                        if (info.AccountType == 0)
                        {
                            info.AccountUID = accuid1;
                            ac1 = true;
                        }
                        else
                        {
                            info.AccountUID = accuid2;
                            ac2 = true;
                        }
                    }
                }
                else
                {
                    List<XiyouAccountData> tempList = new List<XiyouAccountData>();
                    xiyouAccountDetailDataUpdateDict.Add(machineUID, tempList);
                }

                if (!ac1)
                {
                    XiyouAccountData temp = new XiyouAccountData();
                    temp.AccountUID = accuid1;
                    temp.MachineUID = machineUID;
                    temp.RecDate = chToday;
                    temp.AccountType = 0;
                    temp.update = true;
                    xiyouAccountDetailDataUpdateDict[machineUID].Add(temp);
                }
                if (!ac2)
                {
                    XiyouAccountData temp = new XiyouAccountData();
                    temp.AccountUID = accuid2;
                    temp.MachineUID = machineUID;
                    temp.RecDate = chToday;
                    temp.AccountType = 1;
                    temp.update = true;
                    xiyouAccountDetailDataUpdateDict[machineUID].Add(temp);
                }
                AddXiyouAccountDetailUpdate(machineUID);
            }
        }
