        /// <summary>獲取Ferrari日帳資料</summary>
        private void GetFerrariAccountDetailData()
        {
            var datalist = myAcess.select("FerrariAccountDetailTable", "*", "", "RecDate ASC");
            if (datalist.Count > 0)
            {
                //取出Cache用資料(只取當日)
                if (ferrariAccountDetailDataUpdateDict.Count > 0) ferrariAccountDetailDataUpdateDict.Clear();
                DateTime todat = DateTime.Today.Date;
                for (int i = 0; i < datalist.Count; i++)
                {
                    DateTime recDate = Convert.ToDateTime(datalist[i]["RecDate"]).Date;
                    //只有今日的Detail帳目會更新, 舊帳目不會再更新, 因此只須將今日的帳目Cache起來.
                    if (recDate == todat)
                    {
                        FerrariAccountData temp = new FerrariAccountData();
                        temp.GetDBData(datalist[i], true);

                        if (ferrariAccountDetailDataUpdateDict.ContainsKey(temp.MachineUID))
                        {
                            ferrariAccountDetailDataUpdateDict[temp.MachineUID].Add(temp);
                        }
                        else
                        {
                            List<FerrariAccountData> tempList = new List<FerrariAccountData>();
                            tempList.Add(temp);
                            ferrariAccountDetailDataUpdateDict.Add(temp.MachineUID, tempList);
                        }
                    }
                }

                //取出盈餘校正用資料
                if (ferrariSurplusRegulateDataDict.Count > 0) ferrariSurplusRegulateDataDict.Clear();
                for (int i = 0; i < datalist.Count; i++)
                {
                    ArcadesGameAccountRegulateData temp = new ArcadesGameAccountRegulateData();
                    temp.GetDBData(datalist[i]);

                    int machUid = temp.MachineUID;

                    if (ferrariSurplusRegulateDataDict.ContainsKey(machUid))
                    {
                        ferrariSurplusRegulateDataDict[machUid].Add(temp);
                    }
                    else
                    {
                        List<ArcadesGameAccountRegulateData> tempList = new List<ArcadesGameAccountRegulateData>();
                        tempList.Add(temp);
                        ferrariSurplusRegulateDataDict.Add(machUid, tempList);
                    }
                }
            }
        }
