            //            若數量不足則 新增2筆,
            //            若數量足夠則 找出最舊的2筆紀錄, 清除後寫入新Data.

            if (drollMonkeySurplusRegulateDataDict.ContainsKey(machineUID))
            {
                drollMonkeySurplusRegulateDataDict.TryGetValue(machineUID, out List<ArcadesGameAccountRegulateData> tempList);

                int upCount = 0, atype0 = 0, atype1 = 0;

                foreach (ArcadesGameAccountRegulateData xdata in tempList)
                {
                    if (xdata.RecDate == chToday)
                    {
                        //int result1 = DBLink.update(accountTable, udata, "AccountUID", xdata.AccountUID.ToString());
                        //if (result1 <= 0)
                        //{
                        //    return result1;
                        //}

                        xdata.AccountPlay(betAdd, winAdd);

                        upCount++;
                        if (xdata.AccountType == 0) atype0++;
                        else if (xdata.AccountType == 1) atype1++;
                    }
                }

                if (upCount < 2)
                {
                    //沒有今日帳, 用最舊的紀錄修改
                    //if (tempList.Count >= 5 * 2)  //UNDONE: 單日帳 先測試5筆 -------------- 
                    if (tempList.Count >= 30 * 2 * 3)  //外帳30筆, 內帳30筆, 保留3個月
                    {
                        MysqlTest DBLink = new MysqlTest();
                        //Console.WriteLine("修改舊紀錄");
                        var dataDic3 = DBLink.select(accountTable, "AccountUID, RecDate", string.Format("MachineUID = {0}", machineUID), "RecDate ASC", ""); //找出並排序全部紀錄
                        if (dataDic3 == null)
                        {
                            return 0;
                        }
                        Dictionary<string, string> dataDic2 = new Dictionary<string, string>();
                        dataDic2.Add("MachineUID", machineUID.ToString());
                        dataDic2.Add("RecDate", "'" + dbToday + "'");
                        //選出第1筆最舊的紀錄並清除內容
                        dataDic2.Add("AccountUID", dataDic3[0]["AccountUID"]);
                        dataDic2.Add("AccountType", "0");
                        int result2 = DBLink.replace(accountTable, dataDic2);
                        if (result2 <= 0)
                        {
                            return result2;
                        }
                        //選出第2筆最舊的紀錄並清除內容
                        dataDic2["AccountUID"] = dataDic3[1]["AccountUID"];
                        dataDic2["AccountType"] = "1";
                        //Clear DB紀錄
                        int result3 = DBLink.replace(accountTable, dataDic2);
                        if (result3 <= 0)
                        {
                            return result3;
                        }
                        //Update DB紀錄
                        //int result4 = DBLink.update(accountTable, udata, string.Format("MachineUID = {0} AND RecDate = '{1}'", machineUID, dbToday));
                        //if (result4 <= 0)
                        //{
                        //    return result4;
                        //}

                        int accuid1 = Convert.ToInt32(dataDic3[0]["AccountUID"]);
                        int accuid2 = Convert.ToInt32(dataDic3[1]["AccountUID"]);

                        //Update Cache 紀錄
                        ReplaceDrollMonkeyAccountDetailData(machineUID, chToday, accuid1, accuid2);

                        //Update 盈餘校正用資料 紀錄
                        foreach (ArcadesGameAccountRegulateData xdata in tempList)
                        {
                            if (xdata.AccountUID == accuid1 || xdata.AccountUID == accuid2)
                            {
                                xdata.AccountPlay(betAdd, winAdd);
                                xdata.RecDate = chToday;
                            }
                        }

                        DBLink.CloseCoon();
                        DBLink = null;
                    }
                    else  //紀錄總數不足
                    {
                        makeNewRecord = true;
                        //Console.WriteLine("紀錄總數不足, 新增紀錄");
                    }
                }
            }
            else  //無此機號, 新增此機號Key值
            {
                List<ArcadesGameAccountRegulateData> tempList = new List<ArcadesGameAccountRegulateData>();
                drollMonkeySurplusRegulateDataDict.Add(machineUID, tempList);
