                dataDic2.Add("MachineUID", machineUID.ToString());
                dataDic2.Add("RecDate", "'" + dbToday + "'");

                int accuid1, accuid2;
                lock (DrollMonkeyDetailLock) //鎖住Insert程序, 避免回傳AccUid錯誤. 2021/04/29
                {
                    dataDic2.Add("AccountType", "0");
                    accuid1 = DBLink.insert(accountTable, dataDic2);
                    if (accuid1 <= 0)
                    {
                        return accuid1;
                    }

                    dataDic2["AccountType"] = "1";
                    accuid2 = DBLink.insert(accountTable, dataDic2);
                    if (accuid2 <= 0)
                    {
                        return accuid2;
                    }
                }
                //Update DB紀錄
                //int result5 = DBLink.update(accountTable, udata, string.Format("MachineUID = {0} AND RecDate = '{1}'", machineUID, dbToday));
                //if (result5 <= 0)
                //{
                //    return result5;
                //}

                //Cache 加入新紀錄
                ReplaceDrollMonkeyAccountDetailData(machineUID, chToday, accuid1, accuid2);

                //盈餘校正用資料 加入新紀錄
                ArcadesGameAccountRegulateData tempAcc1 = new ArcadesGameAccountRegulateData();
                ArcadesGameAccountRegulateData tempAcc2 = new ArcadesGameAccountRegulateData();
                tempAcc1.AccountPlay(betAdd, winAdd);
                tempAcc2.AccountPlay(betAdd, winAdd);

                tempAcc1.AccountUID = accuid1;
                tempAcc2.AccountUID = accuid2;

                tempAcc1.RecDate = chToday;
                tempAcc2.RecDate = chToday;

                tempAcc1.MachineUID = machineUID;
                tempAcc2.MachineUID = machineUID;

                tempAcc1.AccountType = 0;
                tempAcc2.AccountType = 1;

                drollMonkeySurplusRegulateDataDict[machineUID].Add(tempAcc1);
                drollMonkeySurplusRegulateDataDict[machineUID].Add(tempAcc2);

                DBLink.CloseCoon();
                DBLink = null;
            }
            return 1;
        }
        /// <summary>置換DrollMonkeyAccountDetailData (Cache資料)</summary>
        public void ReplaceDrollMonkeyAccountDetailData(int machineUID, DateTime chToday, int accuid1, int accuid2)
        {
            bool ac1 = false, ac2 = false;
            lock (drollMonkeyAccountDetailDataUpdateDict)
            {
                if (drollMonkeyAccountDetailDataUpdateDict.TryGetValue(machineUID, out List<DrollMonkeyAccountData> values))
                {
                    foreach (DrollMonkeyAccountData info in values)
                    {
                        info.RecDate = chToday;
                        info.ClearCache();
                        info.update = true;

                        if (info.AccountType == 0)
                        {
                            info.AccountUID = accuid1;
                            ac1 = true;
                        }
                        else
                        {
                            info.AccountUID = accuid2;
                            ac2 = true;
                        }
                    }
                }
                else
                {
                    List<DrollMonkeyAccountData> tempList = new List<DrollMonkeyAccountData>();
                    drollMonkeyAccountDetailDataUpdateDict.Add(machineUID, tempList);
                }

                if (!ac1)
                {
                    DrollMonkeyAccountData temp = new DrollMonkeyAccountData();
                    temp.AccountUID = accuid1;
                    temp.MachineUID = machineUID;
                    temp.RecDate = chToday;
                    temp.AccountType = 0;
                    temp.update = true;
                    drollMonkeyAccountDetailDataUpdateDict[machineUID].Add(temp);
                }
                if (!ac2)
                {
                    DrollMonkeyAccountData temp = new DrollMonkeyAccountData();
                    temp.AccountUID = accuid2;
                    temp.MachineUID = machineUID;
                    temp.RecDate = chToday;
                    temp.AccountType = 1;
                    temp.update = true;
                    drollMonkeyAccountDetailDataUpdateDict[machineUID].Add(temp);
                }
                AddDrollMonkeyAccountDetailUpdate(machineUID);
            }
        }
