        /// <summary>獲取3DBMW日帳資料</summary>
        private void GetBmw3DAccountDetailData()
        {
            var datalist = myAcess.select("BMW3DAccountDetailTable", "*", "", "RecDate ASC");
            if (datalist.Count > 0)
            {
                //取出Cache用資料(只取當日)
                if (bmw3DAccountDetailDataUpdateDict.Count > 0) bmw3DAccountDetailDataUpdateDict.Clear();
                DateTime todat = DateTime.Today.Date;
                for (int i = 0; i < datalist.Count; i++)
                {
                    DateTime recDate = Convert.ToDateTime(datalist[i]["RecDate"]).Date;
                    //只有今日的Detail帳目會更新, 舊帳目不會再更新, 因此只須將今日的帳目Cache起來.
                    if (recDate == todat)
                    {
                        Bmw3DAccountData temp = new Bmw3DAccountData();
                        temp.GetDBData(datalist[i], true);

                        if (bmw3DAccountDetailDataUpdateDict.ContainsKey(temp.MachineUID))
                        {
                            bmw3DAccountDetailDataUpdateDict[temp.MachineUID].Add(temp);
                        }
                        else
                        {
                            List<Bmw3DAccountData> tempList = new List<Bmw3DAccountData>();
                            tempList.Add(temp);
                            bmw3DAccountDetailDataUpdateDict.Add(temp.MachineUID, tempList);
                        }
                    }
                }

                //取出盈餘校正用資料
                if (bmw3DSurplusRegulateDataDict.Count > 0) bmw3DSurplusRegulateDataDict.Clear();
                for (int i = 0; i < datalist.Count; i++)
                {
                    ArcadesGameAccountRegulateData temp = new ArcadesGameAccountRegulateData();
                    temp.GetDBData(datalist[i]);

                    int machUid = temp.MachineUID;

                    if (bmw3DSurplusRegulateDataDict.ContainsKey(machUid))
                    {
                        bmw3DSurplusRegulateDataDict[machUid].Add(temp);
                    }
                    else
                    {
                        List<ArcadesGameAccountRegulateData> tempList = new List<ArcadesGameAccountRegulateData>();
                        tempList.Add(temp);
                        bmw3DSurplusRegulateDataDict.Add(machUid, tempList);
                    }
                }
            }
        }
