        /// <summary>置換AstonMartinAccountDetailData (Cache資料)</summary>
        public void ReplaceAstonMartinAccountDetailData(int machineUID, DateTime chToday, int accuid1, int accuid2)
        {
            bool ac1 = false, ac2 = false;
            lock (astonMartinAccountDetailDataUpdateDict)
            {
                if (astonMartinAccountDetailDataUpdateDict.TryGetValue(machineUID, out List<AstonMartinAccountData> values))
                {
                    foreach (AstonMartinAccountData info in values)
                    {
                        info.RecDate = chToday;
                        info.ClearCache();
                        info.update = true;

                        if (info.AccountType == 0)
                        {
                            info.AccountUID = accuid1;
                            ac1 = true;
                        }
                        else
                        {
                            info.AccountUID = accuid2;
                            ac2 = true;
                        }
                    }
                }
                else
                {
                    List<AstonMartinAccountData> tempList = new List<AstonMartinAccountData>();
                    astonMartinAccountDetailDataUpdateDict.Add(machineUID, tempList);
                }

                if (!ac1)
                {
                    AstonMartinAccountData temp = new AstonMartinAccountData();
                    temp.AccountUID = accuid1;
                    temp.MachineUID = machineUID;
                    temp.RecDate = chToday;
                    temp.AccountType = 0;
                    temp.update = true;
                    astonMartinAccountDetailDataUpdateDict[machineUID].Add(temp);
                }
                if (!ac2)
                {
                    AstonMartinAccountData temp = new AstonMartinAccountData();
                    temp.AccountUID = accuid2;
                    temp.MachineUID = machineUID;
                    temp.RecDate = chToday;
                    temp.AccountType = 1;
                    temp.update = true;
                    astonMartinAccountDetailDataUpdateDict[machineUID].Add(temp);
                }
                AddAstonMartinAccountDetailUpdate(machineUID);
            }
        }
