        /// <summary>獲取SuperAltyn日帳資料</summary>
        private void GetSuperAltynAccountDetailData()
        {
            var datalist = myAcess.select("SuperAltynAccountDetailTable", "*", "", "RecDate ASC");
            if (datalist.Count > 0)
            {
                //取出Cache用資料(只取當日)
                if (superAltynAccountDetailDataUpdateDict.Count > 0) superAltynAccountDetailDataUpdateDict.Clear();
                DateTime todat = DateTime.Today.Date;
                for (int i = 0; i < datalist.Count; i++)
                {
                    DateTime recDate = Convert.ToDateTime(datalist[i]["RecDate"]).Date;
                    //只有今日的Detail帳目會更新, 舊帳目不會再更新, 因此只須將今日的帳目Cache起來.
                    if (recDate == todat)
                    {
                        SuperAltynAccountData temp = new SuperAltynAccountData();
                        temp.GetDBData(datalist[i], true);

                        if (superAltynAccountDetailDataUpdateDict.ContainsKey(temp.MachineUID))
                        {
                            superAltynAccountDetailDataUpdateDict[temp.MachineUID].Add(temp);
                        }
                        else
                        {
                            List<SuperAltynAccountData> tempList = new List<SuperAltynAccountData>();
                            tempList.Add(temp);
                            superAltynAccountDetailDataUpdateDict.Add(temp.MachineUID, tempList);
                        }
                    }
                }

                //取出盈餘校正用資料
                if (superAltynSurplusRegulateDataDict.Count > 0) superAltynSurplusRegulateDataDict.Clear();
                for (int i = 0; i < datalist.Count; i++)
                {
                    ArcadesGameAccountRegulateData temp = new ArcadesGameAccountRegulateData();
                    temp.GetDBData(datalist[i]);

                    int machUid = temp.MachineUID;

                    if (superAltynSurplusRegulateDataDict.ContainsKey(machUid))
                    {
                        superAltynSurplusRegulateDataDict[machUid].Add(temp);
                    }
                    else
                    {
                        List<ArcadesGameAccountRegulateData> tempList = new List<ArcadesGameAccountRegulateData>();
                        tempList.Add(temp);
                        superAltynSurplusRegulateDataDict.Add(machUid, tempList);
                    }
                }
            }
        }
