        /// <summary>置換MonkeyKing2AccountDetailData (Cache資料)</summary>
        public void ReplaceMonkeyKing2AccountDetailData(int machineUID, DateTime chToday, int accuid1, int accuid2)
        {
            bool ac1 = false, ac2 = false;
            lock (monkeyKing2AccountDetailDataUpdateDict)
            {
                if (monkeyKing2AccountDetailDataUpdateDict.TryGetValue(machineUID, out List<MonkeyKing2AccountData> values))
                {
                    foreach (MonkeyKing2AccountData info in values)
                    {
                        info.RecDate = chToday;
                        info.ClearCache();
                        info.update = true;

                        if (info.AccountType == 0)
                        {
                            info.AccountUID = accuid1;
                            ac1 = true;
                        }
                        else
                        {
                            info.AccountUID = accuid2;
                            ac2 = true;
                        }
                    }
                }
                else
                {
                    List<MonkeyKing2AccountData> tempList = new List<MonkeyKing2AccountData>();
                    monkeyKing2AccountDetailDataUpdateDict.Add(machineUID, tempList);
                }

                if (!ac1)
                {
                    MonkeyKing2AccountData temp = new MonkeyKing2AccountData();
                    temp.AccountUID = accuid1;
                    temp.MachineUID = machineUID;
                    temp.RecDate = chToday;
                    temp.AccountType = 0;
                    temp.update = true;
                    monkeyKing2AccountDetailDataUpdateDict[machineUID].Add(temp);
                }
                if (!ac2)
                {
                    MonkeyKing2AccountData temp = new MonkeyKing2AccountData();
                    temp.AccountUID = accuid2;
                    temp.MachineUID = machineUID;
                    temp.RecDate = chToday;
                    temp.AccountType = 1;
                    temp.update = true;
                    monkeyKing2AccountDetailDataUpdateDict[machineUID].Add(temp);
                }
                AddMonkeyKing2AccountDetailUpdate(machineUID);
            }
        }
