        /// <summary>獲取FIFA2022日帳資料</summary>
        private void GetFIFA2022AccountDetailData()
        {
            var datalist = myAcess.select("FIFA2022AccountDetailTable", "*", "", "RecDate ASC");
            if (datalist.Count > 0)
            {
                //取出Cache用資料(只取當日)
                if (fifa2022AccountDetailDataUpdateDict.Count > 0) fifa2022AccountDetailDataUpdateDict.Clear();
                DateTime todat = DateTime.Today.Date;
                for (int i = 0; i < datalist.Count; i++)
                {
                    DateTime recDate = Convert.ToDateTime(datalist[i]["RecDate"]).Date;
                    //只有今日的Detail帳目會更新, 舊帳目不會再更新, 因此只須將今日的帳目Cache起來.
                    if (recDate == todat)
                    {
                        FIFA2022AccountData temp = new FIFA2022AccountData();
                        temp.GetDBData(datalist[i], true);

                        if (fifa2022AccountDetailDataUpdateDict.ContainsKey(temp.MachineUID))
                        {
                            fifa2022AccountDetailDataUpdateDict[temp.MachineUID].Add(temp);
                        }
                        else
                        {
                            List<FIFA2022AccountData> tempList = new List<FIFA2022AccountData>();
                            tempList.Add(temp);
                            fifa2022AccountDetailDataUpdateDict.Add(temp.MachineUID, tempList);
                        }
                    }
                }

                //取出盈餘校正用資料
                if (fifa2022SurplusRegulateDataDict.Count > 0) fifa2022SurplusRegulateDataDict.Clear();
                for (int i = 0; i < datalist.Count; i++)
                {
                    ArcadesGameAccountRegulateData temp = new ArcadesGameAccountRegulateData();
                    temp.GetDBData(datalist[i]);

                    int machUid = temp.MachineUID;

                    if (fifa2022SurplusRegulateDataDict.ContainsKey(machUid))
                    {
                        fifa2022SurplusRegulateDataDict[machUid].Add(temp);
                    }
                    else
                    {
                        List<ArcadesGameAccountRegulateData> tempList = new List<ArcadesGameAccountRegulateData>();
                        tempList.Add(temp);
                        fifa2022SurplusRegulateDataDict.Add(machUid, tempList);
                    }
                }
            }
        }
