        /// <summary>獲取OceanKing日帳資料</summary>
        private void GetOceanKingAccountDetailData()
        {
            var datalist = myAcess.select("OceanKingAccountDetailTable", "*", "", "RecDate ASC");
            if (datalist.Count > 0)
            {
                //取出Cache用資料(只取當日)
                if (oceanKingAccountDetailDataUpdateDict.Count > 0) oceanKingAccountDetailDataUpdateDict.Clear();
                DateTime todat = DateTime.Today.Date;
                for (int i = 0; i < datalist.Count; i++)
                {
                    DateTime recDate = Convert.ToDateTime(datalist[i]["RecDate"]).Date;
                    //只有今日的Detail帳目會更新, 舊帳目不會再更新, 因此只須將今日的帳目Cache起來.
                    if (recDate == todat)
                    {
                        OceanKingAccountData temp = new OceanKingAccountData();
                        temp.GetDBData(datalist[i], true);

                        if (oceanKingAccountDetailDataUpdateDict.ContainsKey(temp.MachineUID))
                        {
                            oceanKingAccountDetailDataUpdateDict[temp.MachineUID].Add(temp);
                        }
                        else
                        {
                            List<OceanKingAccountData> tempList = new List<OceanKingAccountData>();
                            tempList.Add(temp);
                            oceanKingAccountDetailDataUpdateDict.Add(temp.MachineUID, tempList);
                        }
                    }
                }

                //取出盈餘校正用資料
                if (oceanKingSurplusRegulateDataDict.Count > 0) oceanKingSurplusRegulateDataDict.Clear();
                for (int i = 0; i < datalist.Count; i++)
                {
                    FishGameAccountRegulateData temp = new FishGameAccountRegulateData();
                    temp.GetDBData(datalist[i]);

                    int machUid = temp.MachineUID;

                    if (oceanKingSurplusRegulateDataDict.ContainsKey(machUid))
                    {
                        oceanKingSurplusRegulateDataDict[machUid].Add(temp);
                    }
                    else
                    {
                        List<FishGameAccountRegulateData> tempList = new List<FishGameAccountRegulateData>();
                        tempList.Add(temp);
                        oceanKingSurplusRegulateDataDict.Add(machUid, tempList);
                    }
                }
            }
        }
