                //MyConsole.WriteLine("創建新紀錄");
                Dictionary<string, string> dataDic2 = new Dictionary<string, string>();
                dataDic2.Add("MachineUID", machineUID.ToString());
                dataDic2.Add("RecDate", "'" + dbToday + "'");

                int accuid1, accuid2;
