        #region OceanKing3 機率外帳(日帳)
        /// <summary>獲取OceanKing3日帳資料</summary>
        private void GetOceanKing3AccountDetailData()
        {
            var datalist = myAcess.select("OceanKing3AccountDetailTable", "*", "", "RecDate ASC");
            if (datalist.Count > 0)
            {
                //取出Cache用資料(只取當日)
                if (oceanKing3AccountDetailDataUpdateDict.Count > 0) oceanKing3AccountDetailDataUpdateDict.Clear();
                DateTime todat = DateTime.Today.Date;
                for (int i = 0; i < datalist.Count; i++)
                {
                    DateTime recDate = Convert.ToDateTime(datalist[i]["RecDate"]).Date;
                    //只有今日的Detail帳目會更新, 舊帳目不會再更新, 因此只須將今日的帳目Cache起來.
                    if (recDate == todat)
                    {
                        OceanKing3AccountData temp = new OceanKing3AccountData();
                        temp.GetDBData(datalist[i], true);

                        if (oceanKing3AccountDetailDataUpdateDict.ContainsKey(temp.MachineUID))
                        {
                            oceanKing3AccountDetailDataUpdateDict[temp.MachineUID].Add(temp);
                        }
                        else
                        {
                            List<OceanKing3AccountData> tempList = new List<OceanKing3AccountData>();
                            tempList.Add(temp);
                            oceanKing3AccountDetailDataUpdateDict.Add(temp.MachineUID, tempList);
                        }
                    }
                }

                //取出盈餘校正用資料
                if (oceanKing3SurplusRegulateDataDict.Count > 0) oceanKing3SurplusRegulateDataDict.Clear();
                for (int i = 0; i < datalist.Count; i++)
                {
                    FishGameAccountRegulateData temp = new FishGameAccountRegulateData();
                    temp.GetDBData(datalist[i]);

                    int machUid = temp.MachineUID;

                    if (oceanKing3SurplusRegulateDataDict.ContainsKey(machUid))
                    {
                        oceanKing3SurplusRegulateDataDict[machUid].Add(temp);
                    }
                    else
                    {
                        List<FishGameAccountRegulateData> tempList = new List<FishGameAccountRegulateData>();
                        tempList.Add(temp);
                        oceanKing3SurplusRegulateDataDict.Add(machUid, tempList);
                    }
                }
            }
        }
