        /// <summary>獲取OceanKing5日帳資料</summary>
        private void GetOceanKing5AccountDetailData()
        {
            var datalist = myAcess.select("OceanKing5AccountDetailTable", "*", "", "RecDate ASC");
            if (datalist.Count > 0)
            {
                //取出Cache用資料(只取當日)
                if (oceanKing5AccountDetailDataUpdateDict.Count > 0) oceanKing5AccountDetailDataUpdateDict.Clear();
                DateTime todat = DateTime.Today.Date;
                for (int i = 0; i < datalist.Count; i++)
                {
                    DateTime recDate = Convert.ToDateTime(datalist[i]["RecDate"]).Date;
                    //只有今日的Detail帳目會更新, 舊帳目不會再更新, 因此只須將今日的帳目Cache起來.
                    if (recDate == todat)
                    {
                        OceanKing5AccountData temp = new OceanKing5AccountData();
                        temp.GetDBData(datalist[i], true);

                        if (oceanKing5AccountDetailDataUpdateDict.ContainsKey(temp.MachineUID))
