        /// <summary>更新OceanKing5AccountDetailData (盈餘校正用資料)</summary>
        /// <param name="machineUID"></param>
        /// <param name="date"></param>
        /// <param name="udata"></param>
        public int UpdateOceanKing5AccountDetailData(int machineUID, string date, Dictionary<string, string> refdata)
        {
            DateTime chToday = Convert.ToDateTime(date).Date; //比對用
            string dbToday = date.Replace('/', '-'); //寫入DB用'-'
            double betAdd = Convert.ToDouble(refdata["TotalBet"]);
            double winAdd = Convert.ToDouble(refdata["TotalWin"]);
            string accountTable = "OceanKing5AccountDetailTable";

            bool makeNewRecord = false;
            //Console.WriteLine("machineUID" + machineUID + ", Date=" + date);
            //1.找出 機號相同 且 日期相同 的紀錄
            //        若找到則更新Data.
            //        若找不到則
            //    2.找出 機號相同 的紀錄總數, 
            //            若數量不足則 新增2筆,
            //            若數量足夠則 找出最舊的2筆紀錄, 清除後寫入新Data.

            if (oceanKing5SurplusRegulateDataDict.ContainsKey(machineUID))
            {
                oceanKing5SurplusRegulateDataDict.TryGetValue(machineUID, out List<FishGameAccountRegulateData> tempList);

                int upCount = 0, atype0 = 0, atype1 = 0;

                foreach (FishGameAccountRegulateData xdata in tempList)
                {
                    if (xdata.RecDate == chToday)
                    {
                        //int result1 = DBLink.update(accountTable, udata, "AccountUID", xdata.AccountUID.ToString());
                        //if (result1 <= 0)
                        //{
                        //    return result1;
                        //}

                        xdata.AccountPlay(betAdd, winAdd);

                        upCount++;
                        if (xdata.AccountType == 0) atype0++;
                        else if (xdata.AccountType == 1) atype1++;
                    }
                }

                if (upCount < 2)
                {
                    //沒有今日帳, 用最舊的紀錄修改
                    //if (tempList.Count >= 5 * 2)  //UNDONE: 單日帳 先測試5筆 -------------- 
                    if (tempList.Count >= 30 * 2 * 3)  //外帳30筆, 內帳30筆, 保留3個月
                    {
                        MysqlTest DBLink = new MysqlTest();
                        //Console.WriteLine("修改舊紀錄");
                        var dataDic3 = DBLink.select(accountTable, "AccountUID, RecDate", string.Format("MachineUID = {0}", machineUID), "RecDate ASC", ""); //找出並排序全部紀錄
                        if (dataDic3 == null)
                        {
                            return 0;
                        }
                        Dictionary<string, string> dataDic2 = new Dictionary<string, string>();
                        dataDic2.Add("MachineUID", machineUID.ToString());
                        dataDic2.Add("RecDate", "'" + dbToday + "'");
                        //選出第1筆最舊的紀錄並清除內容
                        dataDic2.Add("AccountUID", dataDic3[0]["AccountUID"]);
                        dataDic2.Add("AccountType", "0");
                        int result2 = DBLink.replace(accountTable, dataDic2);
                        if (result2 <= 0)
                        {
                            return result2;
                        }
                        //選出第2筆最舊的紀錄並清除內容
                        dataDic2["AccountUID"] = dataDic3[1]["AccountUID"];
                        dataDic2["AccountType"] = "1";
                        //Clear DB紀錄
                        int result3 = DBLink.replace(accountTable, dataDic2);
                        if (result3 <= 0)
                        {
                            return result3;
                        }
                        //Update DB紀錄
                        //int result4 = DBLink.update(accountTable, udata, string.Format("MachineUID = {0} AND RecDate = '{1}'", machineUID, dbToday));
                        //if (result4 <= 0)
                        //{
                        //    return result4;
                        //}

                        int accuid1 = Convert.ToInt32(dataDic3[0]["AccountUID"]);
                        int accuid2 = Convert.ToInt32(dataDic3[1]["AccountUID"]);

                        //Update Cache 紀錄
                        ReplaceOceanKing5AccountDetailData(machineUID, chToday, accuid1, accuid2);

                        //Update 盈餘校正用資料 紀錄
                        foreach (FishGameAccountRegulateData xdata in tempList)
                        {
                            if (xdata.AccountUID == accuid1 || xdata.AccountUID == accuid2)
                            {
                                xdata.AccountPlay(betAdd, winAdd);
                                xdata.RecDate = chToday;
                            }
                        }

                        DBLink.CloseCoon();
                        DBLink = null;
                    }
                    else  //紀錄總數不足
                    {
                        makeNewRecord = true;
                        //Console.WriteLine("紀錄總數不足, 新增紀錄");
                    }
                }
            }
            else  //無此機號, 新增此機號Key值
            {
                List<FishGameAccountRegulateData> tempList = new List<FishGameAccountRegulateData>();
                oceanKing5SurplusRegulateDataDict.Add(machineUID, tempList);
                makeNewRecord = true;
                //Console.WriteLine("無此機號, 新增此機號Key值");
            }


            if (makeNewRecord)
            {
                MysqlTest DBLink = new MysqlTest();
                //MyConsole.WriteLine("創建新紀錄");
                Dictionary<string, string> dataDic2 = new Dictionary<string, string>();
                dataDic2.Add("MachineUID", machineUID.ToString());
                dataDic2.Add("RecDate", "'" + dbToday + "'");

                int accuid1, accuid2;
                lock (OceanKing5DetailLock) //鎖住Insert程序, 避免回傳AccUid錯誤. 2021/04/29
                {
                    dataDic2.Add("AccountType", "0");
                    accuid1 = DBLink.insert(accountTable, dataDic2);
                    if (accuid1 <= 0)
                    {
                        return accuid1;
                    }

                    dataDic2["AccountType"] = "1";
                    accuid2 = DBLink.insert(accountTable, dataDic2);
                    if (accuid2 <= 0)
                    {
                        return accuid2;
                    }
                }
                //Update DB紀錄
                //int result5 = DBLink.update(accountTable, udata, string.Format("MachineUID = {0} AND RecDate = '{1}'", machineUID, dbToday));
                //if (result5 <= 0)
                //{
                //    return result5;
                //}

                //Cache 加入新紀錄
                ReplaceOceanKing5AccountDetailData(machineUID, chToday, accuid1, accuid2);

                //盈餘校正用資料 加入新紀錄
                FishGameAccountRegulateData tempAcc1 = new FishGameAccountRegulateData();
                FishGameAccountRegulateData tempAcc2 = new FishGameAccountRegulateData();
                tempAcc1.AccountPlay(betAdd, winAdd);
                tempAcc2.AccountPlay(betAdd, winAdd);

                tempAcc1.AccountUID = accuid1;
                tempAcc2.AccountUID = accuid2;

                tempAcc1.RecDate = chToday;
                tempAcc2.RecDate = chToday;

                tempAcc1.MachineUID = machineUID;
                tempAcc2.MachineUID = machineUID;

                tempAcc1.AccountType = 0;
                tempAcc2.AccountType = 1;

                oceanKing5SurplusRegulateDataDict[machineUID].Add(tempAcc1);
                oceanKing5SurplusRegulateDataDict[machineUID].Add(tempAcc2);

                DBLink.CloseCoon();
                DBLink = null;
            }
            return 1;
        }
