        /// <summary>獲取OceanKing7日帳資料</summary>
        private void GetOceanKing7AccountDetailData()
        {
            var datalist = myAcess.select("OceanKing7AccountDetailTable", "*", "", "RecDate ASC");
            if (datalist.Count > 0)
            {
                //取出Cache用資料(只取當日)
                if (oceanKing7AccountDetailDataUpdateDict.Count > 0) oceanKing7AccountDetailDataUpdateDict.Clear();
                DateTime todat = DateTime.Today.Date;
                for (int i = 0; i < datalist.Count; i++)
                {
                    DateTime recDate = Convert.ToDateTime(datalist[i]["RecDate"]).Date;
                    //只有今日的Detail帳目會更新, 舊帳目不會再更新, 因此只須將今日的帳目Cache起來.
                    if (recDate == todat)
                    {
                        OceanKing7AccountData temp = new OceanKing7AccountData();
                        temp.GetDBData(datalist[i], true);

                        if (oceanKing7AccountDetailDataUpdateDict.ContainsKey(temp.MachineUID))
                        {
                            oceanKing7AccountDetailDataUpdateDict[temp.MachineUID].Add(temp);
                        }
                        else
                        {
                            List<OceanKing7AccountData> tempList = new List<OceanKing7AccountData>();
                            tempList.Add(temp);
                            oceanKing7AccountDetailDataUpdateDict.Add(temp.MachineUID, tempList);
                        }
                    }
                }

                //取出盈餘校正用資料
                if (oceanKing7SurplusRegulateDataDict.Count > 0) oceanKing7SurplusRegulateDataDict.Clear();
                for (int i = 0; i < datalist.Count; i++)
                {
                    FishGameAccountRegulateData temp = new FishGameAccountRegulateData();
                    temp.GetDBData(datalist[i]);

                    int machUid = temp.MachineUID;

                    if (oceanKing7SurplusRegulateDataDict.ContainsKey(machUid))
                    {
                        oceanKing7SurplusRegulateDataDict[machUid].Add(temp);
                    }
                    else
                    {
                        List<FishGameAccountRegulateData> tempList = new List<FishGameAccountRegulateData>();
                        tempList.Add(temp);
                        oceanKing7SurplusRegulateDataDict.Add(machUid, tempList);
                    }
                }
            }
        }
