        /// <summary>更新日帳</summary>
        /// <param name="machineUID"></param>
        /// <param name="date"></param>
        /// <param name="data"></param>
        public int UpdateAccountDetailData(GameServerCode gameServerCode, int machineUID, int kiosMode, string date, Dictionary<string, string> data)
        {
            var gs = GetGSInstance(gameServerCode);
            if (gs != null)
            {
                int rtcode;
                if (gs.NewTypeServer)
                {
