        #region 檢查大水庫校正天數(使用日帳資料)
        /// <summary>檢查各遊戲大水庫校正天數</summary>
        public Dictionary<string, string> CheckBigWaterProFitDays(GameServerCode gameServerCode, Dictionary<string, string> updateData)
        {
            //(#AddNewServer 10)
            Dictionary<string, string> tempdata = new Dictionary<string, string>();

            if (updateData != null && updateData.Count > 0)
            {
                DateTime startDay = Convert.ToDateTime(updateData["start"]).Date;
                DateTime endDay = Convert.ToDateTime(updateData["end"]).Date;
                //Console.WriteLine("檢查校正天數測試[" + machineUID + "] " + startDay + " - " + endDay);

                string kios; //#250616 Kios
                if (updateData.ContainsKey("kios"))
                {
                    kios = updateData["kios"];
                }
                else
                {
                    kios = "0"; //預設為0
                }

                string indep; //#250616 Kios
                if (updateData.ContainsKey("indep"))
                {
                    indep = updateData["indep"];
                }
                else
                {
                    indep = "0"; //預設為0(false)
                }

                int recordCount = 0;
                double totSurplus = 0;

                var gs = GetGSInstance(gameServerCode);
                if (gs != null)
                {
                    CountCommonGameBigWaterProFitDays(startDay, endDay, out recordCount, out totSurplus, gs.SurplusRegulateDataDict);

                    tempdata.Add("Result", "Ok");
                    tempdata.Add("TotalSurplus", totSurplus.ToString()); //傳回盈餘值
                    tempdata.Add("RecordCount", recordCount.ToString());  //有效的紀錄筆數
                    tempdata.Add("kios", kios);
                    tempdata.Add("indep", indep);
                    return tempdata;
                }

                ///sroptim
                if (gameServerCode == GameServerCode.OceanKing)
                    CountFishGameBigWaterProFitDays(startDay, endDay, out recordCount, out totSurplus, oceanKingSurplusRegulateDataDict);
                else if (gameServerCode == GameServerCode.OceanKing2)
                    CountFishGameBigWaterProFitDays(startDay, endDay, out recordCount, out totSurplus, oceanKing2SurplusRegulateDataDict);
                else if (gameServerCode == GameServerCode.OceanKing3)
                    CountFishGameBigWaterProFitDays(startDay, endDay, out recordCount, out totSurplus, oceanKing3SurplusRegulateDataDict);
                else if (gameServerCode == GameServerCode.OceanKing4)
                    CountFishGameBigWaterProFitDays(startDay, endDay, out recordCount, out totSurplus, oceanKing4SurplusRegulateDataDict);
                else if (gameServerCode == GameServerCode.OceanKing5)
                    CountFishGameBigWaterProFitDays(startDay, endDay, out recordCount, out totSurplus, oceanKing5SurplusRegulateDataDict);
                else if (gameServerCode == GameServerCode.OceanKing6)
                    CountFishGameBigWaterProFitDays(startDay, endDay, out recordCount, out totSurplus, oceanKing6SurplusRegulateDataDict);
                else if (gameServerCode == GameServerCode.OceanKing7)
                    CountFishGameBigWaterProFitDays(startDay, endDay, out recordCount, out totSurplus, oceanKing7SurplusRegulateDataDict);
                else if (gameServerCode == GameServerCode.OceanKing8)
                    CountFishGameBigWaterProFitDays(startDay, endDay, out recordCount, out totSurplus, oceanKing8SurplusRegulateDataDict);

                else if (gameServerCode == GameServerCode.XiyouGame)
                    CountXiyouBigWaterProFitDays(startDay, endDay, out recordCount, out totSurplus);
                else if (gameServerCode == GameServerCode.SuperKingDerby)
                    CountArcadesGameBigWaterProFitDays(startDay, endDay, out recordCount, out totSurplus, superKingDerbySurplusRegulateDataDict);
                else if (gameServerCode == GameServerCode.DrollMonkey)
                    CountArcadesGameBigWaterProFitDays(startDay, endDay, out recordCount, out totSurplus, drollMonkeySurplusRegulateDataDict);
                else if (gameServerCode == GameServerCode.Ferrari)
                    CountArcadesGameBigWaterProFitDays(startDay, endDay, out recordCount, out totSurplus, ferrariSurplusRegulateDataDict);
                else if (gameServerCode == GameServerCode.BMW3D)
                    CountArcadesGameBigWaterProFitDays(startDay, endDay, out recordCount, out totSurplus, bmw3DSurplusRegulateDataDict);
                else if (gameServerCode == GameServerCode.AstonMartin)
                    CountArcadesGameBigWaterProFitDays(startDay, endDay, out recordCount, out totSurplus, astonMartinSurplusRegulateDataDict);
                else if (gameServerCode == GameServerCode.SuperAltyn)
                    CountArcadesGameBigWaterProFitDays(startDay, endDay, out recordCount, out totSurplus, superAltynSurplusRegulateDataDict);
                else if (gameServerCode == GameServerCode.MonkeyKing2)
                    CountArcadesGameBigWaterProFitDays(startDay, endDay, out recordCount, out totSurplus, monkeyKing2SurplusRegulateDataDict);
                else if (gameServerCode == GameServerCode.FIFA2022)
                    CountArcadesGameBigWaterProFitDays(startDay, endDay, out recordCount, out totSurplus, fifa2022SurplusRegulateDataDict);
                else if (gameServerCode == GameServerCode.BigSmall)
                    CountArcadesGameBigWaterProFitDays(startDay, endDay, out recordCount, out totSurplus, bmw3DSurplusRegulateDataDict);

                tempdata.Add("Result", "Ok");
                tempdata.Add("TotalSurplus", totSurplus.ToString()); //傳回盈餘值
                tempdata.Add("RecordCount", recordCount.ToString());  //有效的紀錄筆數
                tempdata.Add("kios", kios);
                tempdata.Add("indep", indep);
                return tempdata;
            }

            tempdata.Add("Result", "Error");
            return tempdata;
        }

        /// <summary>計算西遊校正天數有效盈餘</summary>
        public void CountXiyouBigWaterProFitDays(DateTime startDay, DateTime endDay, out int recordCount, out double totSurplus)
        {
            recordCount = 0;  //有效的紀錄筆數
            totSurplus = 0; //有效盈餘

            foreach (List<XiyouAccountDetailData> tempList in xiyouSurplusRegulateDataDict.Values)
            {
                foreach (XiyouAccountDetailData info in tempList)
                {
                    if (info.AccountType == 0)  //只檢查外帳
                    {
                        if (info.RecDate <= startDay && info.RecDate >= endDay)
                        {
                            recordCount++;
                            totSurplus += info.TotalSurplus;
                            //Console.WriteLine("UID[" + info.AccountUID + "] 日期:" + info.RecDate + "  盈餘=" + info.TotalSurplus + ", 總盈餘=" + totSurplus);
                        }
                    }
                }
            }
        }

