        /// <summary>從DB獲取 各遊戲大水庫資料</summary>
        private void GetDBBigWaterPoolData()
        {
            var datalist = myAcess.select("GameServerBigWaterPool", "*");
            //var datalist = myAcess.select("GameServerBigWaterPool", "Server");

            if (datalist.Count > 0)
            {
                if (GameServerPoolDataList.Count > 0)
                {
                    GameServerPoolDataList.Clear();
                }

                foreach (Dictionary<string, string> info in datalist)
                {
                    GameServerCode serverCode = (GameServerCode)Convert.ToInt32(info["Server"]);
                    BigWaterPoolData tmpdata = new BigWaterPoolData();
                    tmpdata.GetDBData(info);
                    GameServerPoolDataList.Add(serverCode, tmpdata);
                    //MyConsole.WriteLine("加入大水庫:" + serverCode + " - " + info["GameName"]);
                }
            }

            var datalist2 = myAcess.select("GameServerBigWaterPoolFish", "*");
            if (datalist2.Count > 0)
            {
                if (GameServerPoolDataFishList.Count > 0)
                {
                    GameServerPoolDataFishList.Clear();
                }

                foreach (Dictionary<string, string> info in datalist2)
                {
                    GameServerCode serverCode = (GameServerCode)Convert.ToInt32(info["Server"]);
                    BigWaterPoolDataFish tmpdata = new BigWaterPoolDataFish();
                    tmpdata.GetDBData(info);
                    GameServerPoolDataFishList.Add(serverCode, tmpdata);
                    //MyConsole.WriteLine("加入捕魚機大水庫:" + serverCode + " - " + info["GameName"]);
                }
            }


            foreach (GameServerCode gcode in Enum.GetValues(typeof(GameServerCode)))
            {
                if (gcode != GameServerCode.None && gcode != GameServerCode.Login)
                {
                    if (!IsGameServerEnable(gcode)) continue; //如果遊戲伺服器未啟用, 則不建立大水庫

                    GameTypeCode gType = GameServerCodeToGameTypeCode(gcode);

                    if (gType == GameTypeCode.Fish)
                    {
                        if (!GameServerPoolDataFishList.ContainsKey(gcode))
                        {
                            Dictionary<string, string> updateData = new Dictionary<string, string>();
                            string name = GameServerCodeToGameName(gcode);
                            updateData.Add("Server", "'" + (int)gcode + "'");
                            updateData.Add("GameName", "'" + name + "'");
                            int serId = myAcess.insert("GameServerBigWaterPoolFish", updateData);
                            BigWaterPoolDataFish tmpdata = new BigWaterPoolDataFish { SerId = serId };
                            GameServerPoolDataFishList.Add(gcode, tmpdata);
                            MyConsole.WriteLine($"    重建大水庫:[{gcode} - {name}]");
                        }
                    }
                    else if (gType != GameTypeCode.Other) //Other類型不需要建立大水庫
                    {
                        if (!GameServerPoolDataList.ContainsKey(gcode))
                        {
                            Dictionary<string, string> updateData = new Dictionary<string, string>();
                            string name = GameServerCodeToGameName(gcode);
                            updateData.Add("Server", "'" + (int)gcode + "'");
                            updateData.Add("GameName", "'" + name + "'");
                            int serId = myAcess.insert("GameServerBigWaterPool", updateData);
                            BigWaterPoolData tmpdata = new BigWaterPoolData { SerId = serId };
                            GameServerPoolDataList.Add(gcode, tmpdata);
                            MyConsole.WriteLine($"    重建大水庫:[{gcode} - {name}]");
                        }
                    }
                }
            }
        }
        /// <summary>GameServer要求獲取 遊戲大水庫資料</summary>
        public Dictionary<string, string> GetBigWaterPoolData(GameServerCode gameServerCode)
        {
            GameTypeCode gType = GameServerCodeToGameTypeCode(gameServerCode);
            if (gType == GameTypeCode.Fish)
            {
                if (GameServerPoolDataFishList.ContainsKey(gameServerCode))
                {
                    return GameServerPoolDataFishList[gameServerCode].GetUpdateData();
                }
            }
            else
            {
                if (GameServerPoolDataList.ContainsKey(gameServerCode))
                {
                    return GameServerPoolDataList[gameServerCode].GetUpdateData();
                }
            }
            return new Dictionary<string, string>();
        }
        /// <summary>更新各遊戲大水庫</summary>
        public void UpdateBigWaterPool(GameServerCode gameServerCode, Dictionary<string, string> updateData)
        {
            GameTypeCode gType = GameServerCodeToGameTypeCode(gameServerCode);

            if (gType == GameTypeCode.Fish)
            {
                if (GameServerPoolDataFishList.ContainsKey(gameServerCode))
                {
                    OperTionDBBox TempOperTionDBBox = new OperTionDBBox(OpertionCode.update1, "GameServerBigWaterPoolFish", updateData, "SerId", GameServerPoolDataFishList[gameServerCode].SerId.ToString());
                    lock (Program.opertionDBBoxs)
                    {
                        Program.opertionDBBoxs.Add(TempOperTionDBBox);
                    }

                    GameServerPoolDataFishList[gameServerCode].SetUpdateData(updateData, gameServerCode);
                }
            }
            else
            {
                if (GameServerPoolDataList.ContainsKey(gameServerCode))
                {
                    OperTionDBBox TempOperTionDBBox = new OperTionDBBox(OpertionCode.update1, "GameServerBigWaterPool", updateData, "SerId", GameServerPoolDataList[gameServerCode].SerId.ToString());
                    lock (Program.opertionDBBoxs)
                    {
                        Program.opertionDBBoxs.Add(TempOperTionDBBox);
                    }

                    GameServerPoolDataList[gameServerCode].SetUpdateData(updateData, gameServerCode);
                }
            }
        }

        /// <summary> 各遊戲大水庫抽放水</summary>
        public bool PumpInDrainOutBigWaterPool(GameServerCode gServerCode, PumpInDrainOutValue pumpInfo, bool pumpIn, int poolType = 0, int KiosMode = 0)
        {
            string poolmode = poolType != 0 ? "獨立買" : "共用";
            string pdmode = pumpIn ? "放水" : "抽水";
            MyConsole.WriteLine($"[{gServerCode}]{poolmode}大水庫 {pdmode}:{pumpInfo.Value}幣, Kios=[{KiosMode}]");
            //#250616 Kios
            GameTypeCode gType = GameServerCodeToGameTypeCode(gServerCode);
            string sServerCode = ((int)gServerCode).ToString();
            if (gType == GameTypeCode.Fish)
            {
                if (GameServerPoolDataFishList.ContainsKey(gServerCode))
                {
                    BigWaterPoolDataFish poolData = GameServerPoolDataFishList[gServerCode];
                    string logType;
                    double value = pumpInfo.Value; //抽放水幣值
                    string poolVal;
                    string poolName;

                    poolType = 0; //魚機大水庫目前只有一種, poolType=0
                    if (pumpIn)
                    {
                        logType = "1"; //放水
                        (poolName, poolVal) = poolData.SetPumpInData(value, poolType, KiosMode);
                    }
                    else
                    {
                        logType = "0"; //抽水
                        (poolName, poolVal) = poolData.SetDrainOutData(value, poolType, KiosMode);
                    }

                    ////Update大水庫
                    Dictionary<string, string> updateData = new Dictionary<string, string> { { poolName, poolVal } };
                    //OperTionDBBox TempOperTionDBBox1 = new OperTionDBBox(OpertionCode.update1, "GameServerBigWaterPoolFish", updateData, "Server", sServerCode);
                    OperTionDBBox TempOperTionDBBox1 = new OperTionDBBox(OpertionCode.update1, "GameServerBigWaterPoolFish", updateData, "SerId", poolData.SerId.ToString());
                    lock (Program.opertionDBBoxs)
                    {
                        Program.opertionDBBoxs.Add(TempOperTionDBBox1);
                    }

                    //寫入Log紀錄
                    SetBigWaterPumpDrainLogData(pumpInfo.ManagerUID,
                                                sServerCode,
                                                logType,
                                                value,
                                                pumpInfo.IP_Address,
                                                KiosMode);
                    return true;
                }
            }
            else
            {
                if (GameServerPoolDataList.ContainsKey(gServerCode))
                {
                    BigWaterPoolData poolData = GameServerPoolDataList[gServerCode];

                    string logType;
                    double value = pumpInfo.Value; //抽放水幣值
                    string poolVal;
                    string poolName;
                    if (poolType == 0) //常規水庫
                    {
                        if (pumpIn)
                        {
                            logType = "1"; //常規放水
                            (poolName, poolVal) = poolData.SetPumpInData(value, KiosMode);
                        }
                        else
                        {
                            logType = "0"; //常規抽水
                            (poolName, poolVal) = poolData.SetDrainOutData(value, KiosMode);
                        }
                    }
                    else //if (poolType == 1) //獨立買水庫
                    {
                        if (pumpIn)
                        {
                            logType = "3"; //獨立放水
                            (poolName, poolVal) = poolData.SetPumpInDataIndep(value, KiosMode);
                        }
                        else
                        {
                            logType = "2"; //獨立抽水
                            (poolName, poolVal) = poolData.SetDrainOutDataIndep(value, KiosMode);
                        }
                    }

                    //Update大水庫
                    Dictionary<string, string> updateData = new Dictionary<string, string> { { poolName, poolVal } };
                    //OperTionDBBox TempOperTionDBBox1 = new OperTionDBBox(OpertionCode.update1, "GameServerBigWaterPool", updateData, "Server", sServerCode);
                    OperTionDBBox TempOperTionDBBox1 = new OperTionDBBox(OpertionCode.update1, "GameServerBigWaterPool", updateData, "SerId", poolData.SerId.ToString());
                    lock (Program.opertionDBBoxs)
                    {
                        Program.opertionDBBoxs.Add(TempOperTionDBBox1);
                    }

                    //寫入Log紀錄
                    SetBigWaterPumpDrainLogData(pumpInfo.ManagerUID,
                                                sServerCode,
                                                logType,
                                                value,
                                                pumpInfo.IP_Address,
                                                KiosMode);
                    return true;
                }
            }
            return false;
        }

