        public Dictionary<string, SystemTextColor> RandomText()
        {
            Dictionary<string, SystemTextColor> Text = new Dictionary<string, SystemTextColor>();
            Random rand = new Random(Guid.NewGuid().GetHashCode());
            List<int> indexList = new List<int>(Enumerable.Range(1, 18));
            indexList = indexList.OrderBy(num => rand.Next()).ToList<int>();

            foreach (var temp in SystemTextDataList)
            {
                for (int i = 0; i < indexList.Count; i++)
                {
                    if (temp.SystemTextUID == indexList[i])
                        Text.Add(temp.SystemText, SystemTextColor.Bluegreen);
                }
            }

            return Text;
        }


        string ServiceNotificationCh;
        string ServiceNotificationEng;
        int ServiceNotiAdvanceTime;
        int ServiceNotiIntervalTime;
        /// <summary>系統維護時間</summary>
        DateTime ServiceNotiTime;
        /// <summary>提前預報時間</summary>
        DateTime ServiceNotiTimeCheck;

        /// <summary>獲取系統維護公告訊息</summary>
        private void GetServiceNotificationData()
        {
            var datalist = myAcess.select("ServiceNotificationTable", "*");
            if (datalist.Count > 0)
            {
                ServiceNotificationCh = datalist[0]["MessageCh"];
                ServiceNotificationEng = datalist[0]["MessageEng"];
                ServiceNotiTime = Convert.ToDateTime(datalist[0]["ServiceTime"]);
                ServiceNotiAdvanceTime = Convert.ToInt32(datalist[0]["AdvanceTime"]);
                ServiceNotiIntervalTime = Convert.ToInt32(datalist[0]["IntervalTime"]);
                ServiceNotiTime = Convert.ToDateTime(string.Format("{0:yyyy-MM-dd} {1:HH:mm}", DateTime.Now, ServiceNotiTime)); //啟動時設為今日
            }
        }
        /// <summary>設定預報時間</summary>
        public void SetServiceNotiTimeCheck()
        {
            ServiceNotiTimeCheck = ServiceNotiTime.AddMinutes(-ServiceNotiAdvanceTime);
            //MyConsole.WriteLine("廣播系統下一次預報時間:{0:MM-dd HH:mm}, 中止時間:{1:MM-dd HH:mm}", ServiceNotiTimeCheck, ServiceNotiTime);
        }
        /// <summary>設定下一次維護時間</summary>
        public void SetServiceNotiTimeNext()
        {
            ServiceNotiTime = ServiceNotiTime.AddHours(ServiceNotiIntervalTime);
            //ServiceNotiTime = ServiceNotiTime.AddMinutes(IntervalTime);  //測試用
        }
        /// <summary>比對預報時間</summary>
        public int CompareServiceAdvanceTime(DateTime now)
        {
            return ServiceNotiTimeCheck.CompareTo(now);
        }
        /// <summary>比對維護時間</summary>
        public int CompareServiceTime(DateTime now)
        {
            return ServiceNotiTime.CompareTo(now);
        }
        /// <summary>取得系統維護訊息字串</summary>
        public List<string> GetServiceNotificationMessage()
        {
            List<string> text = new List<string>();
            text.Add(ServiceNotificationCh);
            text.Add(ServiceNotificationEng);
            return text;
        }
