        /// <summary>獲取遊戲全部機台RANK資料</summary>
        public List<MachineRankStru> GetMachineRankData(GameServerCode gServer)
        {
            List<MachineRankStru> tempdata = new List<MachineRankStru>();
            int numOfOpen = 0;
            int machUid = 0;

            var gs = GetGSInstance(gServer);
            if (gs != null)
            {
                numOfOpen = gs.GlobalSettingData.NumberOfOpen;
                machUid = gs.MachineStartNumber;
            }
            else
            {
                if (machineDataList.ContainsKey(gServer))
                {
                    numOfOpen = GetMachineNumberOfOpen(gServer);
                    machUid = machineDataList[gServer].MachineStartNumber();
                }
            }

            if (numOfOpen > 0 && machUid > 0)
            {
                for (int i = 0; i < numOfOpen; i++, machUid++)
                {
                    MachineRankStru temp = new MachineRankStru();
                    if (MachineRankDataDic.ContainsKey(machUid))
                    {
                        temp.RankData = MachineRankDataDic[machUid].RankData;
                        temp.RankList = MachineRankDataDic[machUid].CountList;
                        temp.RankType = 1;
                    }
                    else
                    {
                        temp.RankData = "";
                        temp.RankList = "";
                        temp.RankType = 0;
                    }
                    tempdata.Add(temp);
                }
            }
            return tempdata;
        }
