        int CheckTopPlayKeepDelayTimer = 0;
        /// <summary>重置TOP-PLAY押分排行資訊時間</summary>
        DateTime TopPlayClearDay;
        bool TopPlayClearDaySetFg = false;
        /// <summary>檢查並重置全部玩家押分排行資訊</summary>
        public void CheckTopPlayKeepDay()
        {
            if (CheckTopPlayKeepDelayTimer > 0)
            {
                CheckTopPlayKeepDelayTimer--;
                return;
            }

            //1.製作 重置比對日期
            //DateTime clearday = topGameRankSettingData.ClearRankTime.AddDays(topGameRankSettingData.Top_Player * 7);
            if (!TopPlayClearDaySetFg)
            {
                TopPlayClearDaySetFg = true;
                TopPlayClearDay = topGameRankSettingData.ClearRankTime.AddDays(topGameRankSettingData.Top_Player * 7);
            }

            DateTime today = DateTime.Now;

            //MyConsole.WriteLine("檢查並清除玩家押分排行紀錄:[現在:" + today + "], [清除:" + TopPlayClearDay + "]");

            //2.比對日期, 若超過則重置
            if (today.CompareTo(TopPlayClearDay) > 0)
            {
                ResetTopPlay100Info();

                //3.重置後 修改最後重置日期為 -> "前次重置日期+設定的週數" (必須大於目前日期)
                while (true)
                {
                    DateTime nextClearday = TopPlayClearDay.AddDays(topGameRankSettingData.Top_Player * 7); //加上設定週期天數
                    //MyConsole.WriteLine("重置日期:[現:" + today + "], [清:" + nextClearday + "]");
                    if (today.CompareTo(nextClearday) < 0)  //必須大於目前日期
                    {
                        break;
                    }
                    TopPlayClearDay = nextClearday;
                }

                //3.寫入最後重置時間
                SetDBClearRankTime(TopPlayClearDay);
            }
            else
            {
                TimeSpan tdiff = TopPlayClearDay.Subtract(today);
                if (tdiff.TotalMinutes > 60.0)
                    CheckTopPlayKeepDelayTimer = 30 * 60; //延時60分鐘
                else if (tdiff.TotalMinutes > 2.0)
                    CheckTopPlayKeepDelayTimer = 30 * (tdiff.Minutes - 2); //延時剩餘分鐘
                else
                    CheckTopPlayKeepDelayTimer = 10; //剩不到2分鐘, 延時20S

                //MyConsole.WriteLine("檢查時差: 剩 " + tdiff.TotalMinutes + "分");
            }
        }
        /// <summary>重置TOP-PLAY全部玩家押分排行資訊</summary>
        public void ResetTopPlay100Info()
        {
            //清除Local Cache
            lock (RankRecordTableList)
            {
                foreach (RankRecordTable info in RankRecordTableList)
                {
                    info.ResetRankRecord();
                    //info.update = true;  //RankRecordDBCommend線程會自動Update DB紀錄   Luke:2022/09/12 取消線程Update, 因為人數太多會造成線程卡住
                }
            }
            //寫入DB排行紀錄資訊  Luke:2022/09/12 改為直接下Update命令
            Dictionary<string, string> updatadata = new Dictionary<string, string> { { "TotalBet", "0" }, { "TotalWin", "0" } };
            OperTionDBBox TempOperTionDBBox = new OperTionDBBox(OpertionCode.update2, "RankRecordtable", updatadata, "RankUID > 0");
            lock (Program.opertionDBBoxs)
            {
                Program.opertionDBBoxs.Add(TempOperTionDBBox);
            }
        }
        /// <summary>寫入TOP-PLAY最後重置時間</summary>
        public void SetDBClearRankTime(DateTime lastClearTime)
        {
            //設定Local Cache
            topGameRankSettingData.ClearRankTime = lastClearTime;
            TopPlayClearDaySetFg = false;
            CheckTopPlayKeepDelayTimer = 0;
            //寫入最後重置時間
            Dictionary<string, string> updata = new Dictionary<string, string> { { "ClearRankTime", "'" + lastClearTime.ToString("yyyy-MM-dd HH:mm:00") + "'" } };
            OperTionDBBox TempOperTionDBBox = new OperTionDBBox(OpertionCode.update1, "TopBoardSetting", updata, "ID", "1");
            lock (Program.opertionDBBoxs) { Program.opertionDBBoxs.Add(TempOperTionDBBox); }
        }
