        /// <summary>每個陪玩機器人的成就紀錄數量</summary>
        int fakeBotRankLength = 5;
        /// <summary>更新陪玩機器人成就紀錄</summary>
        public void UpdateFakeBotRankData(Dictionary<string, string> insertData, string sBuildTime)
        {
            DateTime buildTime = Convert.ToDateTime(sBuildTime);
            int userUid = Convert.ToInt32(insertData["UserUID"]);
            int machUid = Convert.ToInt32(insertData["GameMachine"]);
            int rankType = Convert.ToInt32(insertData["RankType"]);
            string rankData = insertData["RankData"];
            string gameName = insertData["GameName"];

            //字串格式加入單引號
            insertData["GameName"] = "'" + insertData["GameName"] + "'";
            insertData["RankData"] = "'" + insertData["RankData"] + "'";
            insertData.Add("Buildtime", "'" + sBuildTime + "'");  //加入目前時間 

            //搜尋此機器人全部紀錄, 並找出最舊的紀錄位置
            bool pexist = false;
            if (FakeBotRankTableList.ContainsKey(userUid))
            {
                pexist = true;
                List<FakeBotRankTable> templist = FakeBotRankTableList[userUid];
                if (templist.Count >= fakeBotRankLength)
                {
                    //紀錄足夠, 更新舊紀錄
                    int idx = 0;
                    int dts = (int)(DateTime.Now - RankCompareTime).TotalSeconds;
                    for (int i = 0; i < templist.Count; i++)
                    {
                        if (templist[i].BuildSecond < dts) //If時間比較舊 (BuildSecond越大時間越新)
                        {
                            dts = templist[i].BuildSecond;
                            idx = i;
                        }
                    }

                    FakeBotRankTable tmpTab = templist[idx];
                    tmpTab.GameMachine = machUid;
                    tmpTab.GameName = gameName;
                    tmpTab.RankType = rankType;
                    tmpTab.RankData = rankData;
                    tmpTab.BuildTime = sBuildTime;
                    tmpTab.BuildSecond = (int)(buildTime - RankCompareTime).TotalSeconds;

                    //myAcess.update("FakeBotRankTable", insertData, "RecordUid", tmpTab.RecordUid.ToString());
                    OperTionDBBox TempOperTionDBBox = new OperTionDBBox(OpertionCode.update1, "FakeBotRankTable", insertData, "RecordUid", tmpTab.RecordUid.ToString());
                    lock (Program.opertionDBBoxs)
                    {
                        Program.opertionDBBoxs.Add(TempOperTionDBBox);
                    }
                    return;
                }
            }

            //沒有此機器人紀錄, 或紀錄不足5筆 --> 新增
            try
            {
                FakeBotRankTable tmpTab = new FakeBotRankTable
                {
                    GameMachine = machUid,
                    GameName = gameName,
                    RankType = rankType,
                    RankData = rankData,
                    BuildTime = sBuildTime,
                    BuildSecond = (int)((buildTime - RankCompareTime).TotalSeconds)
                };
                int nguid = myAcess.insert("FakeBotRankTable", insertData);
                tmpTab.RecordUid = nguid;

                if (pexist)
                {
                    FakeBotRankTableList[userUid].Add(tmpTab);
                }
                else
                {
                    List<FakeBotRankTable> templist = new List<FakeBotRankTable> { tmpTab };
                    FakeBotRankTableList.Add(userUid, templist);
                }
            }
            catch (Exception ex)
            {
            }
        }
