        /// <summary></summary>
        public GameTypeCode _GameTypeNameToGameTypeCode(string gameTypeName)
        {
            if (gameTypeName == "押分机")
                return GameTypeCode.Arcade;
            else if (gameTypeName == "老虎机")
                return GameTypeCode.Slot;
            //else if (gameTypeName == "捕鱼机")
            else if (gameTypeName == "打鱼机")
                return GameTypeCode.Fish;
            else if (gameTypeName == "扑克机")
                return GameTypeCode.Poker;
            else
                return GameTypeCode.Other;
        }
        /// <summary></summary>`
        public string _GameTypeCodeToGameTypeName(GameTypeCode gameTypeName)
        {
            if (gameTypeName == GameTypeCode.Arcade)
                return "押分机";
            else if (gameTypeName == GameTypeCode.Slot)
                return "老虎机";
            else if (gameTypeName == GameTypeCode.Fish)
                return "打鱼机";
            //return "捕鱼机";
            else if (gameTypeName == GameTypeCode.Poker)
                return "扑克机";
            else
                return "";
        }
        /// <summary></summary>
        public GameServerCode GameNameToGameServerCode(string gameName)
        {
            foreach (KeyValuePair<GameServerCode, CommonGame> info in GameServerCodeTable)
            {
                //if (info.Value.GameNameCd == gameName)
                if (info.Value.GameNameChs == gameName)
                {
                    return info.Key;
                }
            }

            foreach (KeyValuePair<GameServerCode, GameNameLangData> info in GameNameLangInfo)
            {
                if (info.Value.CN == gameName)
                {
                    return info.Key;
                }
            }

            return GameServerCode.None;
        }
        /// <summary></summary>
        public string GameServerCodeToGameName(GameServerCode gServerCode)
        {
            var gs = GetGSInstance(gServerCode);
            if (gs != null)
            {
                return gs.GameNameChs;
            }

            if(GameNameLangInfo.ContainsKey(gServerCode))
            {
                return GameNameLangInfo[gServerCode].CN;
            }

            return "";
        }
