        /// <summary>計算能量條</summary>
        public Equipment EnergyCount(double totalBet, int UserUID)
        {
            Equipment userEquipment = new Equipment();

            bool bechange = false;

            lock (UserDataList)
            {
                if (UserDataList.ContainsKey(UserUID))
                {
                    //double energy = UserDataList[UserUID].Energy + totalBet;
                    //int star = UserDataList[UserUID].Star;

                    UserDataList[UserUID].EnergyToEnergyBar(totalBet, CoinPerStar);
                    //UserDataList[UserUID].EnergyToEnergyBar(ref energy, ref star, CoinPerStar);
                    //UserDataList[UserUID].Energy = energy;
                    //UserDataList[UserUID].Star = star;

                    if (UserDataList[UserUID].FirstBetTime == 0)
                    {
                        UserDataList[UserUID].FirstBetTime = Program.GetLogTimeStamp(DateTime.Now);
                        UpdateUsertable(UserUID, new Dictionary<string, string> { { "FirstBetTime", UserDataList[UserUID].FirstBetTime.ToString() } });
                    }

                    userEquipment.Energy = UserDataList[UserUID].EnergyBar;
                    userEquipment.Star = UserDataList[UserUID].Star;
                    bechange = true;
                }
            }

            if (bechange == true)
            {
                AddUserdataUpdateList(UserUID);
            }

            return userEquipment;
        }
