        /// <summary>將幣值轉換為顯示字串</summary>
        public string HistoryConvertRatioForText(double score)
        {
            if (CountrySetting.HistoryDispMode == 1)
            {
                double sMoney = Math.Round(score * CountrySetting.HistoryScoreRatio, 4); //小數點精度調整 四捨五入取自第四位 避免原整數 因極小浮點數誤差 被無條件捨去 而沒進位至原整數
                double tMoney = Math.Floor(sMoney);
                return string.Format("{0:N0}", tMoney);
            }
            else
            {
                double dPoint = Math.Pow(10, CountrySetting.HistoryDispDigits);
                double sNumber = Math.Round((score * CountrySetting.HistoryCoinRatio * dPoint), 4); //小數點精度調整  四捨五入取自第四位 避免原整數 因極小浮點數誤差 被無條件捨去 而沒進位至原整數
                double tNumber = Math.Floor(sNumber) / dPoint;
                //string Format = "{0:N" + CountrySetting.HistoryDispDigits + "} " + CountrySetting.CurrencyStr;
                string Format = CountrySetting.Currency;
                return string.Format(Format, tNumber);
            }
        }


