                        totalRateRange += SetGameRedEnvelopeSelectTable(info.Bonus5, info.Bonus5Rate);
                        totalRateRange += SetGameRedEnvelopeSelectTable(info.Bonus6, info.Bonus6Rate);
                        totalRateRange += SetGameRedEnvelopeSelectTable(info.Bonus7, info.Bonus7Rate);
                        totalRateRange += SetGameRedEnvelopeSelectTable(info.Bonus8, info.Bonus8Rate);
                        totalRateRange += SetGameRedEnvelopeSelectTable(info.Bonus9, info.Bonus9Rate);
                        totalRateRange += SetGameRedEnvelopeSelectTable(info.Bonus10, info.Bonus10Rate);
                        totalRateRange += SetGameRedEnvelopeSelectTable(info.Bonus11, info.Bonus11Rate);
                        totalRateRange += SetGameRedEnvelopeSelectTable(info.Bonus12, info.Bonus12Rate);
                        totalRateRange += SetGameRedEnvelopeSelectTable(info.Bonus13, info.Bonus13Rate);
                        totalRateRange += SetGameRedEnvelopeSelectTable(info.Bonus14, info.Bonus14Rate);
                        totalRateRange += SetGameRedEnvelopeSelectTable(info.Bonus15, info.Bonus15Rate);
                        totalRateRange += SetGameRedEnvelopeSelectTable(info.Bonus16, info.Bonus16Rate);
                        totalRateRange += SetGameRedEnvelopeSelectTable(info.Bonus17, info.Bonus17Rate);
                        totalRateRange += SetGameRedEnvelopeSelectTable(info.Bonus18, info.Bonus18Rate);
                        totalRateRange += SetGameRedEnvelopeSelectTable(info.Bonus19, info.Bonus19Rate);
                        totalRateRange += SetGameRedEnvelopeSelectTable(info.Bonus20, info.Bonus20Rate);
                        totalRateRange += SetGameRedEnvelopeSelectTable(info.Bonus21, info.Bonus21Rate);
