        private class GameRedEnvelopeBox
        {
            public int BonusRate;
            public double Bonus;

            public GameRedEnvelopeBox(int rate, double bonus)
            {
                BonusRate = rate;
                Bonus = bonus;
            }
        }

        private readonly object BnsLockey1 = new object();
        private List<GameRedEnvelopeBox> GameRedEnvelopeSelectTable;
        private int GameRedEnvelopeSelectTotalRange = -1;
        private double GameRedEnvelopeNextBonus = 0.0;
        private double GameRedEnvelopeBonusComp = 0.0;
        private double GameRedEnvelopeNextHalf = 0.0;
        private double GameRedEnvelopeNextQuar = 0.0;
        /// <summary>遊戲紅包押分累積</summary>
        private double GameRedBetAccum = 0;
        private int GameRedEnvelopePassRange = 0;
        private int GameRedEnvelopeTimer = 0;
        private int GameRedEnvelopeStage = 0;

        private Random rEnvRnd = new Random(Guid.NewGuid().GetHashCode());

        /// <summary>選擇要出的遊戲紅包</summary>
        private double SelectGameRedEnvelopeBonus()
        {
            double bonus = 0;
            if (GameRedEnvelopeSelectTotalRange < 0)
            {
                GameRedEnvelopeSelectTotalRange = GetGameRedEnvelopeTotalRate();
                //MyConsole.WriteLine("重取紅包設定值:" + GameRedEnvelopeSelectTotalRange);
            }

            if (GameRedEnvelopeSelectTotalRange > 0) // && GameRedEnvelopeSelectTable.Count > 0)
            {
                int resortrnd;
                int selrange;
                lock (rEnvRnd)
                {
                    resortrnd = rEnvRnd.Next(50);
                    selrange = rEnvRnd.Next(GameRedEnvelopeSelectTotalRange);
                }

                if (resortrnd == 1)
                {
                    //重新打亂紅包選取表
                    int totcnt = GameRedEnvelopeSelectTable.Count;
                    for (int i = 0; i < totcnt; i++)
                    {
                        int idx;
                        lock (rEnvRnd) { idx = rEnvRnd.Next(totcnt); }
                        GameRedEnvelopeBox tmp = GameRedEnvelopeSelectTable[i];
                        GameRedEnvelopeSelectTable[i] = GameRedEnvelopeSelectTable[idx];
                        GameRedEnvelopeSelectTable[idx] = tmp;
                    }
                }

                //if (selrange <= 0) { mRnd = new Random(Guid.NewGuid().GetHashCode()); }
                int addrange = 0;
                foreach (GameRedEnvelopeBox info in GameRedEnvelopeSelectTable)
                {
                    addrange += info.BonusRate;
                    if (selrange < addrange)
                    {
                        bonus = info.Bonus;
                        //MyConsole.WriteLine("下一次要出的遊戲紅包:" + bonus + ", Rate=" + selrange);
                        break;
                    }
                }
            }
            return bonus;
        }
        /// <summary>選擇下一次要出的遊戲紅包</summary>
        private void SelectNextBonus()
        {
            lock (BnsLockey1)
            {
                if (GameRedEnvelopeNextBonus <= 0)
                {
                    GameRedEnvelopeNextBonus = SelectGameRedEnvelopeBonus();
                }
            }

            if (GameRedEnvelopeNextBonus > 0)
            {
                double bnsMaxLimit = TransLocalCurrency(500.0);
                double bnsMinLimit = TransLocalCurrency(5.0);
                if (GameRedEnvelopeNextBonus >= bnsMaxLimit) GameRedEnvelopeBonusComp = bnsMaxLimit;
                else if (GameRedEnvelopeNextBonus <= bnsMinLimit) GameRedEnvelopeBonusComp = bnsMinLimit;
                else GameRedEnvelopeBonusComp = GameRedEnvelopeNextBonus;

                GameRedEnvelopeNextHalf = GameRedEnvelopeBonusComp / 2.0;
                GameRedEnvelopeNextQuar = GameRedEnvelopeBonusComp / 4.0;
            }

            GameRedEnvelopeStage = 0;
            GameRedBetAccum = 0;
        }

        //private int GreDbuCnt1 = 0;  //UNDONE: 遊戲紅包 DEBUG 用
        //private int GreDbuCnt2 = 0;
        //private int GreDbuCnt3 = 0;
        /// <summary>遊戲紅包機率計算</summary>
        public double GameRedEnvelopeCalculate(double bet)
        {
            //MARKLU: 遊戲紅包機率計算
            double bonus = 0;

            if (GameRedEnvelopeNextBonus <= 0)
            {
                SelectNextBonus();
            }

            //GreDbuCnt1++;
            if (GameRedEnvelopeNextBonus > 0)
            {
                GameRedBetAccum += (bet / 150.0);
                //GameRedBetAccum += (bet / 150000.0); //UNDONE: 紅包機率 TEST ==========

                int passRand;
                lock (rEnvRnd) { passRand = rEnvRnd.Next(1000); }
                if (passRand < 150)
                {
                    double nextBonus = GameRedEnvelopeNextBonus;
                    double bonusComp = GameRedEnvelopeBonusComp;
                    double nextHalf = GameRedEnvelopeNextHalf;
                    double nextQuar = GameRedEnvelopeNextQuar;
                    double betAccum = GameRedBetAccum;

                    //if (passRand <= 0) { mRnd = new Random(Guid.NewGuid().GetHashCode()); }
                    //GreDbuCnt2++;
                    switch (GameRedEnvelopeStage)
                    {
                        case 0:
                            {
                                //GameRedEnvelopeDiff = bonusComp * 60.0;
                                GameRedEnvelopePassRange = ConvDoubleToHInt(bonusComp * 60.0);
                                GameRedEnvelopeTimer = 0;
                                GameRedEnvelopeStage = 1;
                            }
                            break;
                        case 1:
                            {
                                GameRedEnvelopeTimer++;
                                if (GameRedEnvelopeTimer >= 7)
                                {
                                    //GameRedEnvelopeDiff = bonusComp * 35.0;
                                    GameRedEnvelopePassRange = ConvDoubleToHInt(bonusComp * 35.0);
                                    GameRedEnvelopeStage = 2;
                                }
                            }
                            break;
                        case 2:
                            {
                                if (betAccum >= nextQuar)
                                {
                                    //GameRedEnvelopeDiff = bonusComp * 22.0;
                                    GameRedEnvelopePassRange = ConvDoubleToHInt(bonusComp * 22.0);
                                    GameRedEnvelopeStage = 3;
                                }
                            }
                            break;
                        case 3:
                            {
                                if (betAccum >= nextHalf)
                                {
                                    //GameRedEnvelopeDiff = bonusComp * 13.0;
                                    GameRedEnvelopePassRange = ConvDoubleToHInt(bonusComp * 13.0);
                                    GameRedEnvelopeStage = 4;
                                }
                            }
                            break;
                        case 4:
                            {
                                if (betAccum >= (nextHalf + nextQuar))
                                {
                                    //GameRedEnvelopeDiff = bonusComp * 7.0;
                                    GameRedEnvelopePassRange = ConvDoubleToHInt(bonusComp * 7.0);
                                    GameRedEnvelopeStage = 5;
                                }
                            }
                            break;
                        case 5:
                            {
                                if (betAccum >= bonusComp)
                                {
                                    //GameRedEnvelopeDiff = bonusComp * 3.5;
                                    GameRedEnvelopePassRange = ConvDoubleToHInt(bonusComp * 3.5);
                                    GameRedEnvelopeStage = 6;
                                }
                            }
                            break;
                        case 6:
                            {
                                if (betAccum >= (bonusComp + nextQuar))
                                {
                                    //GameRedEnvelopeDiff = bonusComp * 2.5;
                                    GameRedEnvelopePassRange = ConvDoubleToHInt(bonusComp * 2.5);
                                    GameRedEnvelopeStage = 7;
                                }
                            }
                            break;
                        case 7:
                            {
                                if (betAccum >= (bonusComp + nextHalf))
                                {
                                    //GameRedEnvelopeDiff = bonusComp * 1.5;
                                    GameRedEnvelopePassRange = ConvDoubleToHInt(bonusComp * 1.5);
                                    GameRedEnvelopeStage = 8;
                                }
                            }
                            break;
                        case 8:
                            {
                                if (betAccum >= (bonusComp + nextHalf + nextQuar))
                                {
                                    //GameRedEnvelopeDiff = bonusComp * 1;
                                    GameRedEnvelopePassRange = ConvDoubleToHInt(bonusComp * 1);
                                }
                            }
                            break;
                        default:
                            {
                                GameRedEnvelopeStage = 0;
                                GameRedBetAccum = 0;
                                GameRedEnvelopeNextBonus = 0;
                                nextBonus = 0;
                            }
                            break;
                    }

                    if (nextBonus > 0)
                    {
                        int passRange = GameRedEnvelopePassRange;

                        double bnsMinLimit = TransLocalCurrency(30.00);
                        double betMaxLimit;
                        if (nextBonus < bnsMinLimit) betMaxLimit = bnsMinLimit;
                        else betMaxLimit = TransLocalCurrency(90.00);
                        double betcomp;
                        if (bet > betMaxLimit) betcomp = betMaxLimit;
                        else betcomp = bet;

                        int showUpRate = ConvDoubleToHInt(betcomp);

                        int passRate;
                        lock (rEnvRnd) { passRate = rEnvRnd.Next(passRange); }

                        //if (mRnd.Next(1000) < 200) //UNDONE: 發紅包測試(出現率)
                        if (passRate < showUpRate) //MARKLU: 發紅包出現率
                        {
                            bonus = nextBonus;
                            GameRedEnvelopeNextBonus = 0;
                            //GreDbuCnt3++;
                            //MARKLU: 遊戲紅包機率計算
                            //MyConsole.WriteLine(String.Format("遊戲紅包:{0}, TBET={1:0.000}, STG={2}, COMP={3}, RANG={4}-{5}, SHOW={6}, DBCnt({7},{8},{9})", 
                            //                                nextBonus, 
                            //                                betAccum, 
                            //                                GameRedEnvelopeStage, 
                            //                                bonusComp, 
                            //                                passRange, passRate, 
                            //                                showUpRate, 
                            //                                GreDbuCnt1, GreDbuCnt2, GreDbuCnt3)); // + ", CNT=" + GameRedEnvelopeCalCnt);
                        }
                    }
                }
            }
            return bonus;
        }

        /// <summary>將 通用幣值 轉換為 地區幣值</summary>
        private double TransLocalCurrency(double money)
        {
            return money * CountrySetting.CurrencyFactor;
        }
        /// <summary>Double轉成百倍Int</summary>
        public int ConvDoubleToHInt(double dVal)
        {
            int iVal = (int)Math.Round((dVal * 100d), 4);
            return iVal;
        }
        /// <summary>百倍Int轉成Double</summary>
        public double ConvHIntToDouble(int iVal)
        {
            double dVal = ((double)iVal) / 100d;
            return dVal;
        }

