        /// <summary>
        /// 更新RedEnvelopeLog
        /// Type-Game Mission Star1 Star3 Star5 Star8 Star10
        /// </summary>
        /// <param Type="Game Mission Star1 Star3 Star5 Star8 Star10"></param>
        /// <param Coin="紅包幣值"></param>
        /// <param AddCnt="加次數"></param>
        public void UpdataGameRedEnvelopeLog(string Type, int Coin, int AddCnt)
        {
            Dictionary<string, string> updatadata = new Dictionary<string, string>();

            string ColName = "Type";

            if (Type == "Game")
            {
                lock (GameRedEnvelopeLog)
                {
                    if (GameRedEnvelopeLog.ContainsKey(Coin))
                    {
                        GameRedEnvelopeLog[Coin] += AddCnt;
                    }
                    else
                    {
                        GameRedEnvelopeLog.Add(Coin, AddCnt);
                    }

                    string log = "";

                    int cnt = 0;

                    foreach (KeyValuePair<int, int> p in GameRedEnvelopeLog)
                    {
                        cnt += 1;

                        log = log + p.Key.ToString() + "," + p.Value.ToString();

                        if (cnt < GameRedEnvelopeLog.Count)
                        {
                            log = log + ";";
                        }
                    }

                    log = "'" + log + "'";

                    updatadata.Add("LogContent", log);

                    string TypeValue = "'" + Type + "'";

                    OperTionDBBox TempOperTionDBBox = new OperTionDBBox(OpertionCode.update1, "RedEnvelopeLog", updatadata, ColName, TypeValue);

                    lock (Program.opertionDBBoxs)
                    {
                        Program.opertionDBBoxs.Add(TempOperTionDBBox);
                    }
                }
            }
        }
