        #region 紅包炒場 //#250211
        const bool FRBnsDbuFg = false;   //_UNDONE: 紅包炒場 DEBUG
        const bool FRBnsDbuFg2 = false; //_UNDONE: 紅包炒場 DEBUG
        //紅包炒場
        //  因為玩家可能不會立即將紅包炒場的紅包提領，所以需要有一個機制來處理這個問題
        //  當發出紅包炒場的紅包時, 須先將紅包值預先扣除, 若此紅包取消時, 需將紅包值還原
        //
        private Random rfEnvRnd = new Random(Guid.NewGuid().GetHashCode());
        private int RfEnvRnd(int rang) { lock (rfEnvRnd) { return rfEnvRnd.Next(rang); } }
        private int RfEnvRnd(int rngMin, int rngMax) { lock (rfEnvRnd) { return rfEnvRnd.Next(rngMin, rngMax); } }

        /// <summary>紅包炒場出牌資訊</summary>
        class FRBonusPack
        {
            /// <summary>機台號碼</summary>
            public int MachineUid;
            /// <summary>紅包值</summary>
            public double RedBonus;
        }
        /// <summary>紅包炒場 等待出牌列表資訊</summary>
        class FeverRedBonusInfo
        {
            /// <summary>紅包炒場出牌列表 (key:UserUid) </summary>
            Dictionary<int, FRBonusPack> BonusList = new();

            /// <summary>加入一組待出的紅包</summary>
            public bool AddBonus(int userUID, int machineUid, double bonus)
            {
                if (BonusList.ContainsKey(userUID))
                {
                    return false;
                }

                lock (BonusList)
                {
                    BonusList.Add(userUID, new FRBonusPack() { MachineUid = machineUid, RedBonus = bonus });
                }
                return true;
            }
            /// <summary>移除待出的紅包</summary>
            public bool RemoveBonus(int userUID)
            {
                if (BonusList.ContainsKey(userUID))
                {
                    lock (BonusList)
                    {
                        BonusList.Remove(userUID);
                    }
                    if (FRBnsDbuFg2) MyConsole.WriteLine($"紅包炒場: 移除玩家[{userUID}]待出的紅包");
                    return true;
                }
                return false;
            }
            /// <summary>取得玩家紅包值</summary>
            public double GetBonus(int userUID)
            {
                if (BonusList.ContainsKey(userUID))
                {
                    return BonusList[userUID].RedBonus;
                }
                return 0;
            }
            /// <summary>取得待出的紅包總額</summary>
            public double TotalPreTakeBonus()
            {
                double total = 0;
                lock (BonusList)
                {
                    foreach (var item in BonusList)
                    {
                        total += item.Value.RedBonus;
                    }
                }
                return total;
            }
            /// <summary>玩家已有待出紅包</summary>
            public bool CheckBonusAlready(int userUID, int machineUid)
            {
                if (BonusList.ContainsKey(userUID)) //此玩家已經有待出紅包
                {
                    if (BonusList[userUID].MachineUid == machineUid) //且是同一台機台
                    {
                        return true; //此玩家已經有待出紅包, 不可再出
                    }
                    else //玩家已換機台
                    {
                        lock (BonusList)
                        {
                            BonusList.Remove(userUID); //移除舊的紅包
                        }
                    }
                }

                return false; //可出
            }

        }
        /// <summary>紅包炒場 等待出牌列表資訊</summary>
        FeverRedBonusInfo FRBonusPushInfo = new FeverRedBonusInfo();


        /// <summary>紅包炒場機率計算 (押分驗證時, 且有要求紅包時 呼叫)</summary>
        public double FeverRedBonusCalculate(UserData userData, double bet, GameTypeCode gameType, GameServerCode serverCode, int machineUid, EntityData entity)
        {
            if (userData.FRBLockFg)
            {
                return 0;
            }

            //if (!EntityDataList.ContainsKey(userData.EntityId))
            //{
            //    return 0; //找不到代理商
            //}
            //var entity = EntityDataList[userData.EntityId];
            if (entity == null)
            {
                return 0; //找不到代理商
            }

            if (!entity.FeverRedBonusIsEnabled())
            {
                if (FRBnsDbuFg2) MyConsole.WriteLine($"紅包炒場: 代理商未啟用 (玩家[{userData.UserID}])");
                return 0; //代理商 紅包炒場未啟用
            }

            if (!entity.CheckServerCode(serverCode))
            {
                if (FRBnsDbuFg2) MyConsole.WriteLine($"紅包炒場: 非代理商指定遊戲 ({serverCode})"); //非代理商指定遊戲
                return 0; //代理商 紅包炒場未啟用
            }

            //if (userData.FeverRedBonusFg == false)
            //{
            //    if (FRBnsDbuFg2) MyConsole.WriteLine($"紅包炒場: 玩家[{userData.UserID}]禁制不出");
            //    return 0; //玩家 紅包炒場未啟用
            //}
            //
            //if (userData.CalFg == true)
            //{
            //    if (FRBnsDbuFg2) MyConsole.WriteLine($"紅包炒場: 玩家[{userData.UserID}]強控不出");
            //    return 0; //玩家 已強控
            //}

            //若有Server鎖紅包炒場判斷 加在此


            //userData.FRBCalCnt ++;
            //userData.FRBTotalBet += bet;
            //
            //if (userData.FRBCalModeCnt > 0)
            //{
            //    userData.FRBCalModeCnt--;
            //
            //    if (userData.FRBCalMode >= 2)
            //    {
            //        if (userData.FRBCalModeCnt > 0)
            //        {
            //            return 0; //玩家 紅包炒場 延遲中
            //        }
            //    }
            //}
            //CalFRBCalMode(userData);

            DateTime now = DateTime.Now;

            if (userData.CheckPlayTimeAndBetError(gameType, entity, bet, now))
            {
                if (FRBnsDbuFg2) MyConsole.WriteLine($"紅包炒場: 玩家[{userData.UserID}]停機時間 或 押分 未過");
                return 0;
            }

            if (FRBonusPushInfo.CheckBonusAlready(userData.UserUID, machineUid))
            {
                if (FRBnsDbuFg) MyConsole.WriteLine($"紅包炒場: 玩家[{userData.UserID}]已經有待出紅包");
                return 0; //此玩家已經有待出紅包
            }

            int oResu = userData.IsFRBOut(gameType, entity, machineUid, bet, now);
            if (oResu != 0)
            {
                if (FRBnsDbuFg2) MyConsole.WriteLine($"紅包炒場: 玩家[{userData.UserID}]不可取用");
                return 0;
            }

            //取得紅包炒場水庫值
            double entityPool = entity.FeverRedBonusPool; //實際水庫值
            double availPool = entityPool - FRBonusPushInfo.TotalPreTakeBonus(); //可用水庫值 (扣去待出的錢)

            if (FRBnsDbuFg2) { if (RBPoolSave != availPool) { RBPoolSave = availPool; MyConsole.WriteLine($"紅包炒場: 取得代理商可用水庫值[{availPool}]"); } }

            if (availPool < entity.FREnvMinBonus)
            {
                return 0; //水庫沒錢
            }

            //取得紅包值
            double redBonus = entity.GetFeverRedEnvelope(availPool);

            if (redBonus <= 0)
            {
                if (FRBnsDbuFg) MyConsole.WriteLine($"紅包炒場: 挑不到可用紅包!");
                return 0;
            }

            //出牌機率計算 (由Entity計算)
            //if (!entity.FRateCalcProc(bet, userData.FRBCalCnt))
            //{
            //    return 0; //機率沒過
            //}

            //if (!FRBCalcProc(userData, bet, redBonus))
            //{
            //    return 0; //機率沒過
            //}


            if (!FRBonusPushInfo.AddBonus(userData.UserUID, machineUid, redBonus))
            {
                if (FRBnsDbuFg) MyConsole.WriteLine($"紅包炒場: 玩家[{userData.UserID}]新增失敗, 不出");
                return 0;
            }

            //設定下次可出紅包時間
            //SetPlayerNextBonusTime(userData, entity);

            //userData.FRBCalCnt = 0;
            entity.RedEnvelopeOut();

            if (FRBnsDbuFg) MyConsole.WriteLine($"紅包炒場: 玩家[{userData.UserID}]出[{redBonus}]幣");
            return redBonus;
        }

