        /// <summary>紅包炒場 取用後程序</summary>
        public void FeverRedBonusTakeProc(GameServerCode gameServer, int userUID, double bonus)
        {
            if (bonus <= 0) return;

            UserData userData = Getuser(userUID);

            if (FRBnsDbuFg2) MyConsole.WriteLine($"紅包炒場: 玩家[{userData.UserID}]已領取[{bonus}]幣");

            if (EntityDataList.ContainsKey(userData.EntityId))
            {
                double pbonus = FRBonusPushInfo.GetBonus(userUID);

                if (FRBnsDbuFg)
                {
                    if (bonus != pbonus) MyConsole.WriteLine($"紅包炒場: ERROR: 玩家[{userData.UserID}] 領取[{bonus}]和計算[{pbonus}] 值不同");
                }

                var entity = EntityDataList[userData.EntityId];

                //代理商水庫取用
                double playBeforeHype = entity.FeverRedBonusPool;
                entity.FeverRedBonusPool -= bonus;
                double playAfterHype = entity.FeverRedBonusPool;

                //更新代理商 紅包炒場DB水庫值
                UpdateDBFeverRedBonusPool(userData.EntityId, entity.FeverRedBonusPool);

                //玩家取用累計紀錄
                userData.FRBTakeCounts++;
                userData.FeverRedBonusTotalWin += bonus;

                //設定下次可出紅包時間
                SetPlayerNextBonusTime(userData, entity);

                //更新DB玩家取用紀錄
                Dictionary<string, string> updatadata = new();
                userData.FRBAddUpdateData(ref updatadata);
                UpdateUsertable(userUID, updatadata);

                //寫入Log
                WriteEntityFeverRedBonusBigWaterLog(userData.EntityId, bonus, playBeforeHype, playAfterHype, userUID, gameServer, 1); //1=遊戲

                //RBTestCnt++;
                //RBTestSce += bonus;
                //if (FRBnsDbuFg) MyConsole.WriteLine($"紅包炒場總結: 玩家[{userData.UserID}]: 總押[ {userData.FRBCalCnt} 局, {userData.FRBTotalBet.ToString("f3")} 幣], 總出[ {userData.FRBTakeCounts} 次, {userData.FRBTotalWin.ToString("f3")} 幣]"); //UNDONE: 紅包炒場取用累計紀錄
                if (FRBnsDbuFg) MyConsole.WriteLine($"紅包炒場總結: 玩家[{userData.UserID}]: 本日總得[ {userData.FRBTakeCounts} 次, {userData.FeverRedBonusTotalWin.ToString("f3")} 幣]");
            }

            FRBonusPushInfo.RemoveBonus(userData.UserUID); //取用後移除
        }
        /// <summary>紅包炒場 玩家未領取程序</summary>
        public void FeverRedBonusFailProc(int userUID)
        {
            UserData userData = Getuser(userUID);

            if (FRBnsDbuFg) MyConsole.WriteLine($"紅包炒場: 玩家[{userData.UserID}]未領取");

            RemoveFRBBonusPushInfo(userData); //未領取移除
        }

        /// <summary>移除玩家紅包炒場出牌列表</summary>
        public void RemoveFRBBonusPushInfo(UserData userData)
        {
            if (EntityDataList.ContainsKey(userData.EntityId))
            {
                //var entity = EntityDataList[userData.EntityId];
                //SetPlayerNextBonusTime(userData, entity);
            }
            else //找不到代理商
            {
                userData.OffFRBBonus();
            }

            FRBonusPushInfo.RemoveBonus(userData.UserUID);
        }
        /// <summary>設置玩家下次出紅包時間</summary>
        public void SetPlayerNextBonusTime(UserData userData, EntityData entity)
        {
            //設定下次可出紅包時間
            int nextSec = entity.GetNextFeverRedBonusOutTimes();
            DateTime now = DateTime.Now;
            userData.NextBonusTime = now.AddSeconds(nextSec);
            if (FRBnsDbuFg2) MyConsole.WriteLine($"紅包炒場: 玩家[{userData.UserID}] 下次{nextSec}秒後出, NB時間={userData.NextBonusTime.ToLongTimeString()}");
        }

        /// <summary>更新代理商 紅包炒場DB水庫值</summary>
        void UpdateDBFeverRedBonusPool(int entityId, double poolValue)
        {
            Dictionary<string, string> updata = new Dictionary<string, string>();
            updata.Add("FeverRedBonusPool", poolValue.ToString("f4"));
            OperTionDBBox TempOperTionDBBox = new OperTionDBBox(OpertionCode.update1, "Entity", updata, "id", entityId.ToString());
            lock (Program.opertionDBBoxs)
            {
                Program.opertionDBBoxs.Add(TempOperTionDBBox);
            }
        }

        /// <summary>計算Entity紅包炒場當前水庫抽放水</summary>
        public bool CountEntityFeverRedBonusBigWater(int EntityId, double hypeBigWaterBase, double bigWaterLimit)
        {
            //if (FRBnsDbuFg2) MyConsole.WriteLine($"紅包炒場水庫抽放水: 代理={EntityId}, 補水={hypeBigWaterBase}, 限制={bigWaterLimit}");
            if (EntityDataList.ContainsKey(EntityId))
            {
                double beforeHypeBigWater;
                double afterHypeBigWater;

                lock (EntityDataList)
                {
                    beforeHypeBigWater = EntityDataList[EntityId].FeverRedBonusPool;
                    afterHypeBigWater = beforeHypeBigWater + hypeBigWaterBase;

                    if (bigWaterLimit > 0 && afterHypeBigWater > bigWaterLimit)
                    {
                        MyConsole.WriteLine($"紅包炒場水庫抽放水: 失敗-超過限制 補水後={afterHypeBigWater}, 限制={bigWaterLimit}");
                        return false; //Over Limit
                    }

                    if (afterHypeBigWater < 0)
                    {
                        afterHypeBigWater = 0; //水庫不會出現負值
                    }

                    EntityDataList[EntityId].FeverRedBonusPool = afterHypeBigWater;
                }

                //更新DB水庫值
                UpdateDBFeverRedBonusPool(EntityId, afterHypeBigWater);
                //寫入HypeBigWaterLog紀錄
                WriteEntityFeverRedBonusBigWaterLog(EntityId, hypeBigWaterBase, beforeHypeBigWater, afterHypeBigWater, 0); //0=網頁
                return true;
            }
            return false; //No Entity
        }

        /// <summary>寫入Entity紅包炒場水庫Log紀錄 (抽放水)</summary>
        public void WriteEntityFeverRedBonusBigWaterLog(int EntityId, double WaterValue, double BeforeHypeBigWater, double AfterHypeBigWater, int Type)
        {
            int userUID = 0;
            GameServerCode serverCode = GameServerCode.None;
            WriteEntityFeverRedBonusBigWaterLog(EntityId, WaterValue, BeforeHypeBigWater, AfterHypeBigWater, userUID, serverCode, Type);
        }
        /// <summary>寫入Entity紅包炒場水庫Log紀錄</summary>
        public void WriteEntityFeverRedBonusBigWaterLog(int EntityId, double WaterValue, double BeforeHypeBigWater, double AfterHypeBigWater, int UserUID, GameServerCode GameServerCode, int Type)
        {
            Dictionary<string, string> updata = new Dictionary<string, string>();
            updata.Add("EntityId", EntityId.ToString());
            updata.Add("WaterValue", WaterValue.ToString());
            updata.Add("BeforeHypeBigWater", BeforeHypeBigWater.ToString());
            updata.Add("AfterHypeBigWater", AfterHypeBigWater.ToString());
            updata.Add("UserUID", UserUID.ToString());
            //updata.Add("GameLogUID", GameLogUID.ToString());
            updata.Add("Type", Type.ToString()); //操作類型 0網頁 1遊戲
            updata.Add("GameServerCode", ((int)GameServerCode).ToString());
            //updata.Add("MachineUid", MachineUid.ToString());

            OperTionDBBox TempOperTionDBBox = new OperTionDBBox(OpertionCode.insert, "FeverRedBonusBigWaterLog", updata);
            lock (Program.opertionDBBoxs)
            {
                Program.opertionDBBoxs.Add(TempOperTionDBBox);
            }
        }

        /// <summary>歸零全部玩家每日紅包炒場所得</summary>
        public void FeverRedBonusOverDayProc()
        {
            if (UserDataList.Count == 0) return;
            MyConsole.WriteLine("歸零全部玩家 FeverRedBonusTotalWin !!");

            lock (UserDataList)
            {
                foreach (UserData udata in UserDataList.Values)
                {
                    udata.FRBLockFg = false;
                    udata.FRBTakeCounts = 0;
                    udata.FeverRedBonusTotalWin = 0;
                }
            }

            Dictionary<string, string> frbUpdata = new Dictionary<string, string>()
            {
                { "FeverRedBonusTotalWin", "0" }
            };
            OperTionDBBox TempOperTionDBBoxFR = new OperTionDBBox(OpertionCode.update2, "Usertable", frbUpdata, "FeverRedBonusTotalWin > 0");
            //將更新包 加入佇列
            lock (Program.opertionDBBoxs)
            {
                Program.opertionDBBoxs.Add(TempOperTionDBBoxFR);
            }
        }
