        public void GetDBLockGameData()
        {
            lock (LockGameList)
            {
                var datalist = myAcess.select("LockGameTable", "*");
                if (datalist.Count > 0)
                {
                    LockGameList.Clear();

                    for (int i = 0; i < datalist.Count; i++)
                    {
                        LockGameList.Add(Convert.ToInt32(datalist[i]["GameServerCode"]), Convert.ToInt32(datalist[i]["LockStatus"]));
                    }
                }

                foreach (GameServerCode gservo in Enum.GetValues(typeof(GameServerCode)))
                {
                    if (gservo != GameServerCode.None && gservo != GameServerCode.Login)
                    {
                        int gcode = (int)gservo;
                        if (!LockGameList.ContainsKey(gcode))
                        {
                            //MyConsole.WriteLine("重建LockGameTable:" + gservo);
                            Dictionary<string, string> updateData = new Dictionary<string, string>();
                            updateData.Add("GameServerCode", gcode.ToString());
                            updateData.Add("GameServer", "'" + gservo + "'");
                            int serId = myAcess.insert("LockGameTable", updateData);
                            LockGameList.Add(gcode, 0); //內定為0(未鎖)
                        }
                    }
                }
            }
        }

        public Dictionary<int, int> GetLockGameData()
        {
            lock (LockGameList)
            {
                Dictionary<int, int> temp = new Dictionary<int, int>();

                foreach (KeyValuePair<int, int> d in LockGameList)
                {
                    temp.Add(d.Key, d.Value);
                }

                return temp;
            }
        }
