        private void GetVnpayBankList()
        {
            VnpayIDInfo IDInfo = new VnpayIDInfo();

            int result1 = 0;

            result1 = GetVnpayIDInfo(ref IDInfo);

            if (result1 == 1)
            {
                if (ShowInitMsg) Console.WriteLine("Init:Get Vnpay Bank List");

                var task = VnpayApi.PayoutBankList(IDInfo.ProjectID, IDInfo.SecretKey);

                APIResult result = task.Result;

                string banklistcontext = "";

                if (result.status == "0")
                {
                    banklistcontext = result.data["bank_list"];
                }

                if (banklistcontext != "")
                {
                    var Info = JsonSerializer.Deserialize<List<Dictionary<string, Object>>>(banklistcontext);

                    foreach (var info in Info)
                    {
                        VnpayBankInfo temp = new VnpayBankInfo();

                        temp.STT = info["STT"].ToString();
                        temp.English_name = info["English_name"].ToString();
                        temp.Vietnamese_name = info["Vietnamese_name"].ToString();
                        temp.Bank_code = info["Bank_code"].ToString();
                        temp.BIC_code = info["BIC_code"].ToString();

                        VnpayBankList.Add(temp);
                    }
                }
            }
        }

        public List<VnpayBankInfo> GetVnpayBankListTemp()
        {
