            return JsonSerializer.Serialize(vnpayBankInfos);
        }


        public string GetThaiJustPayBankListContext(string channel, string type = "")
        {
            if (type == "")
            {
                type = "deposit";
            }

            EEGetwayResult getwayresult = new EEGetwayResult();

            if (type == "deposit")
            {
                var getway = EEPay.EEGetPaymentGetway();

                getwayresult = getway.Result;
            }
            else if (type == "withdraw")
            {
                var getway = EEPay.EEGetWithdrawalGetway();

                getwayresult = getway.Result;
            }

            VnpayBankList vnpayBankInfos = new VnpayBankList();

            string Finalchannel = "";

            vnpayBankInfos.mChannelList = getwayresult.Result;

            if (getwayresult.Result.Count > 0)
            {
                if (getwayresult.Result.Contains(channel))
                {
                    Finalchannel = channel;
                }
                else
                {
                    Finalchannel = getwayresult.Result[0];
                }

                EEBankListResult result;

                var task = EEPay.EEBankList(Finalchannel);

                result = task.Result;

                string banklistcontext = "";

                if (result.LGTResult == "10002")
                {
                    banklistcontext = result.Result;
                }

                if (banklistcontext != "")
                {
                    var Info = JsonSerializer.Deserialize<List<Dictionary<string, Object>>>(banklistcontext);

                    List<VnpayBankInfo> banklist = new List<VnpayBankInfo>();

                    foreach (var info in Info)
                    {
                        VnpayBankInfo temp = new VnpayBankInfo();

                        temp.English_name = info["bank"].ToString();
                        temp.Bank_code = info["bankCode"].ToString();

                        banklist.Add(temp);
                    }

                    int seat = banklist.Count;

                    VnpayBankInfo[] TempData = new VnpayBankInfo[seat];

                    for (int i = 0; i < banklist.Count; i++)
                    {
                        TempData[i] = banklist[i];
                    }

                    vnpayBankInfos.mBankList = TempData;
                }

                var datalist = myAcess.select("PaymentLimitInfoTable", "*");

                for (int i = 0; i < datalist.Count; i++)
                {
                    if (Finalchannel == datalist[i]["Name"])
                    {
                        vnpayBankInfos.info = datalist[i]["Data"];

                        break;
                    }
                }

                vnpayBankInfos.info = vnpayBankInfos.info + "," + Finalchannel;

                if (type == "deposit")
                {
                    vnpayBankInfos.info = vnpayBankInfos.info + ",deposit";
                }
                else if (type == "withdraw")
                {
                    vnpayBankInfos.info = vnpayBankInfos.info + ",withdraw";
                }
            }

            return JsonSerializer.Serialize(vnpayBankInfos);
        }

        public string GetVnpayTransactionListContext(int userUID, string startDate, string endDate)
        {
            VnpayTransactionList vnpayTransactionList = new VnpayTransactionList();

            try
            {
                DateTime stdate = Convert.ToDateTime(startDate);

                DateTime eddate = Convert.ToDateTime(endDate);

                int rr = DateTime.Compare(stdate, eddate);

                if (rr != -1)
                {
                    stdate = eddate;
                }

                DateTime basedate = new DateTime(2020, 1, 1);

                long SearchDate_L_Limit = 0;
                long SearchDate_U_Limit = 0;

                SearchDate_L_Limit = (long)((userUID * 100000) + (stdate.Date - basedate).Days);
                SearchDate_U_Limit = (long)((userUID * 100000) + (eddate.Date - basedate).Days);

                var datalist = myAcess.select("MangerToUserTradeRecord", "*", String.Format("SearchIndex >= {0} and SearchIndex <= {1}", SearchDate_L_Limit, SearchDate_U_Limit));

                if (datalist.Count > 0)
                {
                    int seat = datalist.Count;

                    VnpayTransactionInfo[] infos = new VnpayTransactionInfo[seat];

                    for (int i = 0; i < datalist.Count; i++)
                    {
                        infos[i] = new VnpayTransactionInfo();
                        infos[i].TransactionID = datalist[i]["TransactionID"];
                        infos[i].Type = "Bank";
                        infos[i].Amount = double.Parse(datalist[i]["Amount"]).ToString("f2");
                        infos[i].Status = datalist[i]["Status"];
                    }

                    vnpayTransactionList.mTransactionList = infos;
                }

                return JsonSerializer.Serialize(vnpayTransactionList);
            }
            catch (Exception ex)
            {
                return JsonSerializer.Serialize(vnpayTransactionList);
            }
        }

