        public int GetDepositClientTransactionID(ref string transactionid)
        {
            lock (GetDepositTransactionIDlock)
            {
                try
                {
                    var datalist = myAcess.select("VnpayTable", "*");

                    string LastID = "";

                    int IDflag = 0;

                    if (datalist.Count > 0)
                    {
                        if (datalist[0]["DClientTransactionID"] != "")
                        {
                            IDflag = 1;
                        }
                    }

                    if (IDflag == 0)
                    {
                        DateTime currenttime = DateTime.Now;

                        string currentstamp = (currenttime.Year % 100).ToString("D2") + currenttime.Month.ToString("D2") + currenttime.Day.ToString("D2");

                        transactionid = "LGTDP" + currentstamp + "000001";

                        Dictionary<string, string> updatadata = new Dictionary<string, string>();

                        updatadata.Add("DClientTransactionID", "'" + transactionid + "'");

                        OperTionDBBox TempOperTionDBBox = new OperTionDBBox(OpertionCode.insert, "VnpayTable", updatadata, "ID");

                        MysqlTest test = new MysqlTest();

                        test.insert(TempOperTionDBBox.TableName, TempOperTionDBBox.Data);

                        return 1;
                    }
                    else
                    {
                        LastID = datalist[0]["DClientTransactionID"];

                        LastID = LastID.Replace("LGTDP", "");

                        string datevale = LastID.Substring(0, 6);

                        DateTime currenttime = DateTime.Now;

                        string currentstamp = (currenttime.Year % 100).ToString("D2") + currenttime.Month.ToString("D2") + currenttime.Day.ToString("D2");

                        if (datevale != currentstamp)
                        {
                            transactionid = "LGTDP" + currentstamp + "000001";
                        }
                        else
                        {
                            int count = Int32.Parse(LastID.Substring(6, 6));

                            count += 1;

                            transactionid = "LGTDP" + currentstamp + count.ToString("D6");
                        }

                        Dictionary<string, string> updatadata = new Dictionary<string, string>();

                        updatadata.Add("DClientTransactionID", "'" + transactionid + "'");

                        OperTionDBBox TempOperTionDBBox = new OperTionDBBox(OpertionCode.update1, "VnpayTable", updatadata, "ID", datalist[0]["ID"]);

                        MysqlTest test = new MysqlTest();

                        test.update(TempOperTionDBBox.TableName, TempOperTionDBBox.Data, TempOperTionDBBox.Col, TempOperTionDBBox.Value);

                        return 1;
                    }
                }
                catch (Exception ex)
                {
                    MyConsole.WriteLine("{0}", ex.Message);
                    MyConsole.WriteLine(ex.StackTrace);
                    return -1;
                }
            }
        }

