        /// <summary>
        /// 新增一筆VnpayDepost紀錄
        /// </summary>
        public int InsertVnpayDepositLog(int UserUID, string UserID, string TransactionID, string ClientTransactionID, decimal Amount, double Credit, string Status, int StatusValue, string IP_Address, long SearchIndex, int TimeIndex, int ExtraBonusFg, string TransChannel)
        {
            UserData Userdata = Getuser(UserUID);

            var datalist = new Dictionary<string, string>();

            datalist.Add("TradeType", "'PlayerBalanceDeal'");
            datalist.Add("TransactionType", "'1'");
            datalist.Add("OperationType", "'Deposit'");
            datalist.Add("OperatorId", "'" + Userdata.AspNetUserId + "'");
            datalist.Add("OperatorEntityId", "'" + Userdata.EntityId.ToString() + "'");
            datalist.Add("EntityID", "'" + Userdata.EntityId.ToString() + "'");
            datalist.Add("UserUID", UserUID.ToString());
            datalist.Add("UserID", "'" + UserID + "'");
            datalist.Add("TransactionID", "'" + TransactionID + "'");
            String value = Regex.Replace(TransactionID, "[^0-9]", "");
            value = value.Insert(0, "1");
            datalist.Add("TransactionIDValue", "'" + value + "'");
            datalist.Add("ClientTransactionID", "'" + ClientTransactionID + "'");
            datalist.Add("Cash", Amount.ToString("f2"));
            datalist.Add("Amount", Credit.ToString("f2"));
            datalist.Add("IP", "'" + IP_Address + "'");
            datalist.Add("Status", "'" + Status + "'");
            datalist.Add("StatusValue", StatusValue.ToString());
            datalist.Add("SearchIndex", SearchIndex.ToString());
            datalist.Add("TimeStamp", TimeIndex.ToString());

            switch (TransChannel.ToLower())
            {
                case "payessence": datalist.Add("TransChannel", "1"); break;
                case "digi": datalist.Add("TransChannel", "2"); break;
                case "maxis": datalist.Add("TransChannel", "3"); break;
                case "celcom": datalist.Add("TransChannel", "4"); break;
                case "umobile": datalist.Add("TransChannel", "5"); break;
                case "tng": datalist.Add("TransChannel", "6"); break;
                case "thaijustpay": datalist.Add("TransChannel", "7"); break;
                case "paymentpro": datalist.Add("TransChannel", "8"); break;
                case "bitpayz": datalist.Add("TransChannel", "9"); break;
                case "i1bayar": datalist.Add("TransChannel", "10"); break;
                case "heropay": datalist.Add("TransChannel", "11"); break;
                case "banktransfer": datalist.Add("TransChannel", "20"); break;
                default: datalist.Add("TransChannel", "0"); break;
            }


            if (ExtraBonusFg == 1)
            {
                datalist.Add("ExtraBonus", CountrySetting.ExtraBonusValue.ToString("f2"));
            }

            try
            {
