        public void TelcoDeposit(int UserUID, string UserID, VnpayDepositInfo data, ref string requeststatus, ref string ret_msg, ref string call_back_url, ref SocketManager m_ListenLoginSocket)
        {
            try
            {
                TelcoIDInfo IDInfo = new TelcoIDInfo();

                string ClientTransactionID = "";

                double MoneyCoinRatio = 0;

                int result1 = 0;

                result1 = GetTelcoIDInfo(ref IDInfo);

                int result2 = 0;

                result2 = GetDepositClientTransactionID(ref ClientTransactionID);

                int result3 = 0;

                result3 = GetCountryCoinRatio(ref MoneyCoinRatio);

                MoneyCoinRatio = Math.Round(MoneyCoinRatio, 5);

                double CashValue = data.Amount;

                double Credit = 0;

                UserData TempData = Getuser(UserUID);

                if (result1 == 1 && result2 == 1 && result3 == 1 && TempData != null)
                {
                    var task = TelcoPay.TelcoSendPin(IDInfo.ProjectID, IDInfo.SecretKey, ClientTransactionID, data.Gateway, data.PinCode, "");

                    TelcoSendPinResult result = task.Result;

                    ret_msg = "";

                    requeststatus = result.LGTResult;

                    ret_msg = "";

                    if (result.LGTResult == "10001" || result.LGTResult == "10002")
                    {
                        ret_msg = "TelcoPayment";

                        DateTime basetime = new DateTime(2020, 1, 1);

                        DateTime currenttime = DateTime.Now;

                        int timeIndex = (currenttime.Date - basetime).Days;

                        long searchIndex = ((long)UserUID * 100000) + (long)timeIndex;

                        timeIndex = ((DateTime.Now.Year * 10000) + (DateTime.Now.Month * 100) + DateTime.Now.Day);

                        string StatusTxt = "Pending";

                        int StatusValue = 1;

                        if (result.LGTResult == "10001")
                        {
                            StatusTxt = "Approved";

                            StatusValue = 2;
                        }

                        decimal AmountValue = (decimal)(double.Parse(result.VoucherFaceValue) / 100.00d);

                        Credit = (double)((decimal)AmountValue * (decimal)MoneyCoinRatio);

                        //Credit = (double)((decimal)Credit * (decimal)((double)(100 - Int32.Parse(IDInfo.Discount)) / 100.00d));

                        Credit = Math.Round(Credit, 2);

                        if (result.LGTResult == "10001")
                        {
                            UserData Tempdata = Getuser(UserUID);

                            double Balance = Tempdata.UserBalance;

                            //更新玩家DB資料
                            UpdateUserBalance(Credit, UserUID, CacheManeger.UpdateBalanceSource.Web);
                            UpdateKeyInOutRec(Tempdata, Credit); //#251112 (TelcoDeposit)

                            Dictionary<string, string> info = new Dictionary<string, string>();

                            info.Add("Creadit", Credit.ToString("f2"));

                            CheckDayMissionScheduled(UserUID);

                            //MARKLU: SessionID 開分時產生
                            double sessionID = Message.GetSessionID();

                            UpdataUserSessionID(sessionID, UserUID);

                            InsertVnpayDepositLog(UserUID, UserID, ClientTransactionID, ClientTransactionID, AmountValue, Credit, Balance, StatusTxt, StatusValue, data.Client_IP_Address, searchIndex, timeIndex, 0, data.Gateway);

                            //修改Server中儲存玩家餘額資料,查看玩家有沒有上線
                            GameData tmpdata = Message.Pack(OperationCode.ManagerChangeClientCridet,
                                                        ActorUpdataCode.UpdateCredit,
                                                        UserUID,
                                                        Math.Round(Credit, 2), 0);

                            tmpdata.userData.SessionID = Tempdata.SessionID;

                            m_ListenLoginSocket.SendMessage(m_ListenLoginSocket.AsyncLoginServer.ConnectedLoginServer, Message.SerializrToStream(tmpdata));
                        }
                        else
                        {
                            InsertVnpayDepositLog(UserUID, UserID, ClientTransactionID, ClientTransactionID, AmountValue, Credit, StatusTxt, StatusValue, data.Client_IP_Address, searchIndex, timeIndex, 0, data.Gateway);
                        }


                        call_back_url = "";
                    }

                }
                else
                {
                    requeststatus = "LGTError9001";

                    ret_msg = "vnpayid or clienttransactionid get error";
                }
            }
            catch (Exception ex)
            {

                MyConsole.WriteLine("{0}", ex.Message);
                MyConsole.WriteLine(ex.StackTrace);
                requeststatus = "LGTError9002";

                ret_msg = ex.Message;
            }
        }

        public void EEDeposit(int UserUID, string UserID, VnpayDepositInfo data, ref string requeststatus, ref string ret_msg, ref string call_back_url, string channel)
        {
            try
            {
                VnpayIDInfo IDInfo = new VnpayIDInfo();

                string ClientTransactionID = "";

                double MoneyCoinRatio = 0;

                //int result1 = 0;

                //result1 = GetVnpayIDInfo(ref IDInfo);

                int result2 = 0;

                result2 = GetDepositClientTransactionID(ref ClientTransactionID);

                int result3 = 0;

                result3 = GetCountryCoinRatio(ref MoneyCoinRatio);

                MoneyCoinRatio = Math.Round(MoneyCoinRatio, 5);

                double CashValue = data.Amount;

                double Credit = 0;

                UserData TempData = Getuser(UserUID);

                if (result2 == 1 && result3 == 1 && TempData != null && EntityDataList.ContainsKey(TempData.EntityId))
                {
                    decimal AmountValue = (decimal)CashValue;

                    Credit = (double)((decimal)CashValue * (decimal)MoneyCoinRatio);

                    Credit = Math.Round(Credit, 2);

                    if (CountrySetting.ExtraBonusFg == true && TempData.KeyInAward == false &&
                       Credit >= CountrySetting.ExtraBonusUnitKeyIn &&
                       TempData.UserBalance <= CountrySetting.ExtraBonusThreshold)
                    {
                        requeststatus = "LGTError9003";

                        ret_msg = "extra bonus restriction";
                    }
                    else
                    {

                        EEDepositResult result;

                        if (channel == "banktransfer")
                        {
                            var task = EEPay.EEBankTransferDeposit(TempData.UserID, EntityDataList[TempData.EntityId].Name, ClientTransactionID, AmountValue.ToString("f2"));

                            result = task.Result;
                        }
                        else
                        {
                            var task = EEPay.EEDeposit(TempData.UserID, EntityDataList[TempData.EntityId].Name, ClientTransactionID, AmountValue.ToString("f2"), data.Bank_Code, data.Bank_Account_Name, data.Bank_Account_Number, "", channel);

                            result = task.Result;
                        }

                        requeststatus = result.LGTResult;

                        ret_msg = result.LGTRemarks;

                        if (result.LGTResult == "10002")
                        {
                            DateTime basetime = new DateTime(2020, 1, 1);

                            DateTime currenttime = DateTime.Now;

                            int timeIndex = (currenttime.Date - basetime).Days;

                            long searchIndex = ((long)UserUID * 100000) + (long)timeIndex;

                            if (channel == "thaijustpay")
                            {
                                ret_msg = "ThaiJustPay";
                            }
                            else if (channel == "paymentpro")
                            {
                                ret_msg = "PaymentPro";
                            }
                            else if (channel == "bitpayz")
                            {
                                ret_msg = "BitPayZ";
                            }
                            else if (channel == "heropay")
                            {
                                ret_msg = "HeroPay";
                            }
                            else if (channel == "banktransfer")
                            {
                                ret_msg = "BankTransfer";
                            }

                            timeIndex = ((DateTime.Now.Year * 10000) + (DateTime.Now.Month * 100) + DateTime.Now.Day);

                            InsertVnpayDepositLog(UserUID, UserID, ClientTransactionID, result.teansid, AmountValue, Credit, "Initial", 0, data.Client_IP_Address, searchIndex, timeIndex, 0, ret_msg);

                            call_back_url = result.paymentUrl;
                        }

                    }
                }
                else
                {
                    requeststatus = "LGTError9001";

                    ret_msg = "vnpayid or clienttransactionid get error";
                }
            }
            catch (Exception ex)
            {

                MyConsole.WriteLine("{0}", ex.Message);
                MyConsole.WriteLine(ex.StackTrace);
                requeststatus = "LGTError9002";

                ret_msg = ex.Message;
            }
        }

