        public void HandleVnpayDeposit(string PayCenter, int UserUID, string UserID, VnpayDepositInfo data, ref string requeststatus, ref string ret_msg, ref string call_back_url, ref SocketManager m_ListenLoginSocket)
        {
            try
            {
                MyConsole.WriteLine("GetPEDeposit");
                MyConsole.WriteLine(PayCenter);
                MyConsole.WriteLine("PayCenter");
                if (PayCenter == "Vnpay")
                {
                    VnpayDeposit(UserUID, UserID, data, ref requeststatus, ref ret_msg, ref call_back_url);
                }
                else if (PayCenter == "PayEssence")
                {
                    PEDeposit(UserUID, UserID, data, ref requeststatus, ref ret_msg, ref call_back_url);
                }
                else if (PayCenter == "TelcoPayment")
                {
                    TelcoDeposit(UserUID, UserID, data, ref requeststatus, ref ret_msg, ref call_back_url, ref m_ListenLoginSocket);
                }
                else if (PayCenter == "ThaiJustPay")
                {
                    EEDeposit(UserUID, UserID, data, ref requeststatus, ref ret_msg, ref call_back_url, "thaijustpay");
                }
                else if (PayCenter == "PaymentPro")
                {
                    EEDeposit(UserUID, UserID, data, ref requeststatus, ref ret_msg, ref call_back_url, "paymentpro");
                }
                else if (PayCenter == "BitPayZ")
                {
                    EEDeposit(UserUID, UserID, data, ref requeststatus, ref ret_msg, ref call_back_url, "bitpayz");
                }
                else if (PayCenter == "i1bayar")
                {
                    i1bayarDeposit(UserUID, UserID, data, ref requeststatus, ref ret_msg, ref call_back_url);
                }
                else if (PayCenter == "HeroPay")
                {
                    EEDeposit(UserUID, UserID, data, ref requeststatus, ref ret_msg, ref call_back_url, "heropay");
                }
                else if (PayCenter == "BankTransfer")
                {
                    EEDeposit(UserUID, UserID, data, ref requeststatus, ref ret_msg, ref call_back_url, "banktransfer");
                }
            }
            catch (Exception ex)
            {

                MyConsole.WriteLine("{0}", ex.Message);
                MyConsole.WriteLine(ex.StackTrace);
                requeststatus = "LGTError9002";

                ret_msg = ex.Message;
            }
        }


        /// <summary>
        /// 取得玩家儲金紀錄
        /// </summary>
        public List<VnpayDepositLog> GetPlayerVnpayDepositList(int UserUID)
        {
            List<VnpayDepositLog> DepositList = new List<VnpayDepositLog>();

            try
            {
                var datalist = myAcess.select("MangerToUserTradeRecord", "*", String.Format("UserUID = {0} and TransactionType ={1} and StatusValue <= {2}", UserUID, 1, 1));

                if (datalist.Count > 0)
                {
                    foreach (Dictionary<string, string> data in datalist)
                    {
                        VnpayDepositLog temp = new VnpayDepositLog();

                        temp.ID = Int32.Parse(data["TradeRecordUID"]);
                        temp.UserUID = Int32.Parse(data["UserUID"]);
                        temp.UserID = data["UserID"];
                        temp.TransactionID = data["TransactionID"];
                        temp.ClientTransactionID = data["ClientTransactionID"];
                        temp.Amount = double.Parse(data["Cash"]);
                        temp.Credit = double.Parse(data["Amount"]);
                        temp.Status = data["Status"];
                        temp.StatusValue = Int32.Parse(data["StatusValue"]);
                        temp.IP_Address = data["IP"];
                        temp.SearchIndex = long.Parse(data["SearchIndex"]);
                        temp.TimeIndex = Int32.Parse(data["TimeStamp"]);
                        temp.Buildtime = Convert.ToDateTime(data["Buildtime"]).ToString("yyyy/MM/dd HH:mm:ss");

                        DepositList.Add(temp);
                    }
                }
                else
                {
                    ;
                }

            }
            catch (Exception ex)
            {

            }

            return DepositList;
        }

