        public void CheckDepositOrder(string type, ref SocketManager m_ListenLoginSocket, ref SocketManager m_ListenWebServerSocket, ref AsyncUserToken token, string transactionID)
        {
            try
            {
                string sreachinfo = "";

                if (type == "Web")
                {
                    sreachinfo = String.Format("TradeRecordUID = '" + transactionID + "'");
                }
                else
                {
                    sreachinfo = String.Format("ClientTransactionID = '" + transactionID + "'");
                }
                var datalist = myAcess.select("MangerToUserTradeRecord", "*", sreachinfo);

                int TradeRecordUID = 0;
                int UserUID = 0;
                string UserID = "";
                string TransactionID = "";
                string ClientTransactionID = "";
                double Cash = 0;
                double Amount = 0;
                string Status = "";
                int StatusValue = 0;
                string IP_Address = "";
                double ExtraBonusValue = 0;
                int TransChannel = 0;

                if (datalist.Count > 0)
                {
                    TradeRecordUID = Int32.Parse(datalist[0]["TradeRecordUID"]);
                    UserUID = Int32.Parse(datalist[0]["UserUID"]);
                    UserID = datalist[0]["UserID"];
                    TransactionID = datalist[0]["TransactionID"];
                    ClientTransactionID = datalist[0]["ClientTransactionID"];
                    Cash = double.Parse(datalist[0]["Cash"]);
                    Amount = double.Parse(datalist[0]["Amount"]);
                    Status = datalist[0]["Status"];
                    StatusValue = Int32.Parse(datalist[0]["StatusValue"]);
