                    ExtraBonusValue = double.Parse(datalist[0]["ExtraBonus"]);
                    TransChannel = Int32.Parse(datalist[0]["TransChannel"]);

                    if (TransChannel == 1)
                    {
                        VnpayIDInfo IDInfo = new VnpayIDInfo();

                        int result1 = 0;

                        result1 = GetVnpayIDInfo(ref IDInfo);

                        if (result1 == 1)
                        {
                            MyConsole.WriteLine(ClientTransactionID);

                            var task = PayEssenceApi.CheckDeposit(ClientTransactionID, IDInfo.MerchantCode, IDInfo.MerchantSecretKey);

                            PEDepositStatusCheckResult result = task.Result;

                            MyConsole.WriteLine("DepositResult:{0}", result.Result);

                            if (result.Result == "1201" || result.Result == "1202" || result.Result == "1203" ||
                               result.Result == "1204" || result.Result == "1301" || result.Result == "1302" ||
                               result.Result == "2001")
