                                        case "2101": newStatusValue = 2; newStatus = "Approved"; break;
                                        case "2102": newStatusValue = -1; newStatus = "Failed"; break;
                                        case "2201": newStatusValue = 1; newStatus = "Pending"; break;
                                        case "2202": newStatusValue = 2; newStatus = "Approved"; break;
                                        case "2203": newStatusValue = -1; newStatus = "Failed"; break;
                                    }

