        public void CheckTelcopaymentOrder(ref SocketManager m_ListenLoginSocket, string transactionID, string Result)
        {
            try
            {
                VnpayIDInfo IDInfo = new VnpayIDInfo();

                int result1 = 0;

                result1 = GetVnpayIDInfo(ref IDInfo);

                transactionID = Regex.Replace(transactionID, "[^0-9]", "");

                transactionID = transactionID.Insert(0, "2");

                var datalist = myAcess.select("MangerToUserTradeRecord", "*", String.Format("TransactionIDValue = '" + transactionID + "'"));

                int TradeRecordUID = 0;
                int UserUID = 0;
                string UserID = "";
                string TransactionID = "";
                string ClientTransactionID = "";
                double Cash = 0;
                double Amount = 0;
                string Status = "";
                int StatusValue = 0;
                string IP_Address = "";
                double ExtraBonusValue = 0;

                if (datalist.Count > 0)
                {
                    TradeRecordUID = Int32.Parse(datalist[0]["TradeRecordUID"]);
                    UserUID = Int32.Parse(datalist[0]["UserUID"]);
                    UserID = datalist[0]["UserID"];
                    TransactionID = datalist[0]["TransactionID"];
                    ClientTransactionID = datalist[0]["ClientTransactionID"];
                    Cash = double.Parse(datalist[0]["Cash"]);
                    Amount = double.Parse(datalist[0]["Amount"]);
                    Status = datalist[0]["Status"];
                    StatusValue = Int32.Parse(datalist[0]["StatusValue"]);
                    IP_Address = datalist[0]["IP"];
                    ExtraBonusValue = double.Parse(datalist[0]["ExtraBonus"]);

                    int TStatusValue = 0;

                    switch (Result)
                    {
                        case "Success": TStatusValue = 2; break;
                        case "Failed": TStatusValue = -1; break;
                        case "Unknown": TStatusValue = 1; break;
                    }

                    if (StatusValue == 1 && TStatusValue != StatusValue)
                    {
                        int newStatusValue = 0;

                        string newStatus = "";

                        switch (TStatusValue)
                        {
                            case 1: newStatusValue = 1; newStatus = "Pending"; break;
                            case 2: newStatusValue = 2; newStatus = "Approved"; break;
                            case -1: newStatusValue = -1; newStatus = "Failed"; break;
                        }

                        if (newStatus == "Approved")
                        {
                            UserData Tempdata = Getuser(UserUID);

                            double Balance = Tempdata.UserBalance;

                            Dictionary<string, string> updatadata2 = new Dictionary<string, string>();

                            updatadata2.Add("BeforeBalance", "'" + Balance.ToString("f2") + "'");

                            updatadata2.Add("Status", "'" + newStatus + "'");

                            updatadata2.Add("StatusValue", newStatusValue.ToString());



                            if (CountrySetting.ExtraBonusFg == true && ExtraBonusValue > 0 &&
                               Tempdata.KeyInAward == false)
                            {
                                updatadata2.Add("ExtraBonus", CountrySetting.ExtraBonusValue.ToString("f2"));
                                //更新玩家DB資料
                                UpdateUserBalance((Amount + CountrySetting.ExtraBonusValue), UserUID, CacheManeger.UpdateBalanceSource.Web);
                                EnableUserExtraBonusFg(UserUID);
                            }
                            else
                            {
                                updatadata2.Add("ExtraBonus", "0");
                                //更新玩家DB資料
                                UpdateUserBalance(Amount, UserUID, CacheManeger.UpdateBalanceSource.Web);
                            }

                            UpdateKeyInOutRec(Tempdata, Amount); //#251112 (CheckTelcopaymentOrder)

                            Dictionary<string, string> info = new Dictionary<string, string>();

                            info.Add("Creadit", Math.Round(Amount, 2).ToString("f2"));

                            CheckDayMissionScheduled(UserUID);

                            //MARKLU: SessionID 開分時產生
                            double sessionID = Message.GetSessionID();

                            UpdataUserSessionID(sessionID, UserUID);

                            DateTime basetime = new DateTime(2020, 1, 1);
                            DateTime currenttime = DateTime.Now;
                            int timeIndex = (currenttime.Date - basetime).Days;
                            long searchIndex = ((long)UserUID * 100000) + (long)timeIndex;
                            updatadata2.Add("SearchIndex", "'" + searchIndex.ToString() + "'");

                            updatadata2.Add("TimeStamp", ((DateTime.Now.Year * 10000) + (DateTime.Now.Month * 100) + DateTime.Now.Day).ToString());

                            updatadata2.Add("Buildtime", "'" + currenttime.ToString("yyyy/MM/dd HH:mm:ss") + "'");

                            OperTionDBBox TempOperTionDBBox = new OperTionDBBox(OpertionCode.update1, "MangerToUserTradeRecord", updatadata2, "TradeRecordUID", TradeRecordUID.ToString());

                            MysqlTest test = new MysqlTest();

                            test.update(TempOperTionDBBox.TableName, TempOperTionDBBox.Data, TempOperTionDBBox.Col, TempOperTionDBBox.Value);

                            Tempdata = Getuser(UserUID);

                            //修改Server中儲存玩家餘額資料,查看玩家有沒有上線
                            GameData tmpdata = Message.Pack(OperationCode.ManagerChangeClientCridet,
                                                        ActorUpdataCode.UpdateCredit,
                                                        UserUID,
                                                        Math.Round(Amount, 2), 0);

                            tmpdata.userData.SessionID = Tempdata.SessionID;

                            m_ListenLoginSocket.SendMessage(m_ListenLoginSocket.AsyncLoginServer.ConnectedLoginServer, Message.SerializrToStream(tmpdata));
                        }
                        else
                        {
                            Dictionary<string, string> updatadata = new Dictionary<string, string>();

                            updatadata.Add("Status", "'" + newStatus + "'");

                            updatadata.Add("StatusValue", newStatusValue.ToString());

                            OperTionDBBox TempOperTionDBBox = new OperTionDBBox(OpertionCode.update1, "MangerToUserTradeRecord", updatadata, "TradeRecordUID", TradeRecordUID.ToString());

                            MysqlTest test = new MysqlTest();

                            test.update(TempOperTionDBBox.TableName, TempOperTionDBBox.Data, TempOperTionDBBox.Col, TempOperTionDBBox.Value);

                        }
                    }
                }
                else
                {

                }
            }
            catch (Exception ex)
            {

            }
        }


        public void PEPayout(ref SocketManager m_ListenLoginSocket, UserData userData, VnpayPayoutInfo data, ref string requeststatus, ref string ret_msg, ref string transaction_id, ref Dictionary<string, string> ManegerLog)
        {
            VnpayIDInfo IDInfo = new VnpayIDInfo();

            string ClientTransactionID = "";

            double MoneyCoinRatio = 0;

            int result1 = 0;

            result1 = GetVnpayIDInfo(ref IDInfo);

            int result2 = 0;

            result2 = GetPayoutClientTransactionID(ref ClientTransactionID);

            int result3 = 0;

            result3 = GetCountryCoinRatio(ref MoneyCoinRatio);

            MoneyCoinRatio = Math.Round(MoneyCoinRatio, 5);

            double CashValue = data.Amount;

            double Credit = 0;

            MyConsole.WriteLine("PEPayout");

            if (result1 == 1 && result2 == 1 && result3 == 1)
            {
                decimal AmountValue = (decimal)CashValue;

                Credit = (double)((decimal)CashValue * (decimal)MoneyCoinRatio);

                Credit = Math.Round(Credit, 2);

                //檢查玩家Balance夠不購除值
                FixUserBalancePrecision(userData.UserUID);

                double beforeBalacve = userData.UserBalance;

                double tempBalacve = userData.UserBalance;

                tempBalacve -= Credit;

                if (tempBalacve >= 0)
                {
                    var task = PayEssenceApi.PEUserPayout(ClientTransactionID, IDInfo.MerchantCode, data.Bank_Code, data.Bank_Account_Name, data.Bank_Account_Number, AmountValue, "1", data.Client_IP_Address, IDInfo.MerchantSecretKey);

                    PEPayoutResult result = task.Result;

                    requeststatus = result.Result;

                    ret_msg = "payout is pending";

                    if (result.Result == "35001")
                    {
                        ret_msg = "PayEssence";

                        requeststatus = "10002";

                        double TempCredit = 0.00d - Credit;

                        UpdateUserBalance(TempCredit, userData.UserUID, CacheManeger.UpdateBalanceSource.Web);
                        UpdateKeyInOutRec(userData, TempCredit); //#251112 (PEPayout)

                        //修改Server中儲存玩家餘額資料,查看玩家有沒有上線
                        GameData tmpdata = Message.Pack(OperationCode.ManagerChangeClientCridet,
                                                    ActorUpdataCode.UpdateCredit,
                                                    userData.UserUID,
                                                    Math.Round(TempCredit, 2), 0);
                        tmpdata.userData.SessionID = userData.SessionID;

                        m_ListenLoginSocket.SendMessage(m_ListenLoginSocket.AsyncLoginServer.ConnectedLoginServer, Message.SerializrToStream(tmpdata));

                        DateTime basetime = new DateTime(2020, 1, 1);

                        DateTime currenttime = DateTime.Now;

                        int timeIndex = (currenttime.Date - basetime).Days;

                        long searchIndex = ((long)userData.UserUID * 100000) + (long)timeIndex;

                        timeIndex = ((DateTime.Now.Year * 10000) + (DateTime.Now.Month * 100) + DateTime.Now.Day);

                        InsertVnpayPayoutLog(userData.UserUID, userData.UserID, ClientTransactionID, result.PayoutId, data.Bank_Code, data.Bank_Account_Name, data.Bank_Account_Number, beforeBalacve, AmountValue, Credit, "Pending", 1, data.Client_IP_Address, searchIndex, timeIndex, "PayEssence");

                        transaction_id = ClientTransactionID;
                    }
                }
                else
                {
                    requeststatus = "LGTError9001";

                    ret_msg = "player balance not enough";
                }
            }
            else
            {
                requeststatus = "LGTError9001";

                ret_msg = "vnpayid or clienttransactionid get error";
            }
        }

        public void EEPayout(ref SocketManager m_ListenLoginSocket, UserData userData, VnpayPayoutInfo data, ref string requeststatus, ref string ret_msg, ref string transaction_id, ref Dictionary<string, string> ManegerLog, string channel)
        {
            try
            {
                VnpayIDInfo IDInfo = new VnpayIDInfo();

                string ClientTransactionID = "";

                double MoneyCoinRatio = 0;

                //int result1 = 0;

                //result1 = GetVnpayIDInfo(ref IDInfo);

                int result2 = 0;

                result2 = GetPayoutClientTransactionID(ref ClientTransactionID);

                int result3 = 0;

                result3 = GetCountryCoinRatio(ref MoneyCoinRatio);

                MoneyCoinRatio = Math.Round(MoneyCoinRatio, 5);

                double CashValue = data.Amount;

                double Credit = 0;

                MyConsole.WriteLine("TJPayout");

                if (result2 == 1 && result3 == 1 && EntityDataList.ContainsKey(userData.EntityId))
                {
                    decimal AmountValue = (decimal)CashValue;

                    Credit = (double)((decimal)CashValue * (decimal)MoneyCoinRatio);

                    Credit = Math.Round(Credit, 2);

                    //檢查玩家Balance夠不購除值
                    FixUserBalancePrecision(userData.UserUID);

                    double beforeBalacve = userData.UserBalance;

                    double tempBalacve = userData.UserBalance;

                    tempBalacve -= Credit;

                    if (tempBalacve >= 0)
                    {
                        EEWithdrawResult result;

                        if (channel == "banktransfer")
                        {
                            var task = EEPay.EEBankTransferWithdraw(userData.UserID, EntityDataList[userData.EntityId].Name, ClientTransactionID, AmountValue.ToString("f2"), data.Bank_Code, data.Bank_Account_Name, data.Bank_Account_Number, data.PhoneNumber);

                            result = task.Result;
                        }
                        else
                        {
                            var task = EEPay.EEWithdraw(userData.UserID, EntityDataList[userData.EntityId].Name, ClientTransactionID, AmountValue.ToString("f2"), data.Bank_Code, data.Bank_Account_Name, data.Bank_Account_Number, data.PhoneNumber, channel);

                            result = task.Result;
                        }

                        requeststatus = result.LGTResult;

                        ret_msg = result.LGTRemarks;

                        if (result.LGTResult == "10002")
                        {
                            if (channel == "thaijustpay")
                            {
                                ret_msg = "ThaiJustPay";
                            }
                            else if (channel == "paymentpro")
                            {
                                ret_msg = "PaymentPro";
                            }
                            else if (channel == "bitpayz")
                            {
                                ret_msg = "BitPayZ";
                            }
                            else if (channel == "heropay")
                            {
                                ret_msg = "HeroPay";
                            }
                            else if (channel == "banktransfer")
                            {
                                ret_msg = "BankTransfer";
                            }

                            double TempCredit = 0.00d - Credit;

                            UpdateUserBalance(TempCredit, userData.UserUID, CacheManeger.UpdateBalanceSource.Web);
                            UpdateKeyInOutRec(userData, TempCredit); //#251112 (EEPayout)

                            //修改Server中儲存玩家餘額資料,查看玩家有沒有上線
                            GameData tmpdata = Message.Pack(OperationCode.ManagerChangeClientCridet,
                                                        ActorUpdataCode.UpdateCredit,
                                                        userData.UserUID,
                                                        Math.Round(TempCredit, 2), 0);
                            tmpdata.userData.SessionID = userData.SessionID;

                            m_ListenLoginSocket.SendMessage(m_ListenLoginSocket.AsyncLoginServer.ConnectedLoginServer, Message.SerializrToStream(tmpdata));

                            DateTime basetime = new DateTime(2020, 1, 1);

                            DateTime currenttime = DateTime.Now;

                            int timeIndex = (currenttime.Date - basetime).Days;

                            long searchIndex = ((long)userData.UserUID * 100000) + (long)timeIndex;

                            timeIndex = ((DateTime.Now.Year * 10000) + (DateTime.Now.Month * 100) + DateTime.Now.Day);

                            InsertVnpayPayoutLog(userData.UserUID, userData.UserID, ClientTransactionID, result.teansid, data.Bank_Code, data.Bank_Account_Name, data.Bank_Account_Number, beforeBalacve, AmountValue, Credit, "Pending", 1, data.Client_IP_Address, searchIndex, timeIndex, ret_msg);

                            transaction_id = ClientTransactionID;
                        }
                    }
                    else
                    {
                        requeststatus = "LGTError9001";

                        ret_msg = "player balance not enough";
                    }
                }
                else
                {
                    requeststatus = "LGTError9001";

                    ret_msg = "vnpayid or clienttransactionid get error";
                }
            }
            catch (Exception ex)
            {

                MyConsole.WriteLine("{0}", ex.Message);
                MyConsole.WriteLine(ex.StackTrace);
                requeststatus = "LGTError9002";

                ret_msg = ex.Message;
            }

        }


