        /// <summary>
        /// 玩家除值
        /// </summary>
        public void HandleVnpayPayout(string PayCenter, ref SocketManager m_ListenLoginSocket, UserData userData, VnpayPayoutInfo data, ref string requeststatus, ref string ret_msg, ref string transaction_id, ref Dictionary<string, string> ManegerLog)
        {
            try
            {
                PayCenter = PayCenter.Replace(" ", "");
                PayCenter = PayCenter.Replace(" ", "");

                MyConsole.WriteLine(PayCenter);

                if (EntityDataList.ContainsKey(userData.EntityId))
                {
                    if (EntityDataList[userData.EntityId].CreditReviewFg)
                    {

                        PlayerPayoutRequest(ref m_ListenLoginSocket, userData, data, ref requeststatus, ref ret_msg, ref transaction_id, ref ManegerLog);
                    }
                    else
                    {
                        if (PayCenter == "Vnpay")
                        {
                            VnpayPayout(ref m_ListenLoginSocket, userData, data, ref requeststatus, ref ret_msg, ref transaction_id, ref ManegerLog);
                        }
                        else if (PayCenter == "PayEssence")
                        {
                            PEPayout(ref m_ListenLoginSocket, userData, data, ref requeststatus, ref ret_msg, ref transaction_id, ref ManegerLog);
                        }
                        else if (PayCenter == "ThaiJustPay")
                        {
                            EEPayout(ref m_ListenLoginSocket, userData, data, ref requeststatus, ref ret_msg, ref transaction_id, ref ManegerLog, "thaijustpay");
                        }
                        else if (PayCenter == "PaymentPro")
                        {
                            EEPayout(ref m_ListenLoginSocket, userData, data, ref requeststatus, ref ret_msg, ref transaction_id, ref ManegerLog, "paymentpro");
                        }
                        else if (PayCenter == "BitPayZ")
                        {
                            EEPayout(ref m_ListenLoginSocket, userData, data, ref requeststatus, ref ret_msg, ref transaction_id, ref ManegerLog, "bitpayz");
                        }
                        else if (PayCenter == "HeroPay")
                        {
                            EEPayout(ref m_ListenLoginSocket, userData, data, ref requeststatus, ref ret_msg, ref transaction_id, ref ManegerLog, "heropay");
                        }
                        else if (PayCenter == "BankTransfer")
                        {
                            EEPayout(ref m_ListenLoginSocket, userData, data, ref requeststatus, ref ret_msg, ref transaction_id, ref ManegerLog, "banktransfer");
                        }
                    }
                }
            }
            catch (Exception ex)
            {

                MyConsole.WriteLine("{0}", ex.Message);
                MyConsole.WriteLine(ex.StackTrace);
                requeststatus = "LGTError9002";

                ret_msg = ex.Message;
            }
        }

