            {
                var datalist = myAcess.select("MangerToUserTradeRecord", "*", String.Format("UserUID = {0} and TransactionType = {1} and StatusValue = {2}", UserUID, 2, 0));

                if (datalist.Count > 0)
                {
                    foreach (Dictionary<string, string> data in datalist)
                    {
                        VnpayPayoutLog temp = new VnpayPayoutLog();

                        temp.ID = Int32.Parse(data["TradeRecordUID"]);
                        temp.UserUID = Int32.Parse(data["UserUID"]);
                        temp.UserID = data["UserID"];
                        temp.TransactionID = data["TransactionID"];
                        temp.ClientTransactionID = data["ClientTransactionID"];
                        temp.Bank_Code = data["Bank_Code"];
                        temp.Bank_Account_Name = data["Bank_Account_Name"];
                        temp.Bank_Account_Number = data["Bank_Account_Number"];
                        temp.Amount = double.Parse(data["Cash"]);
                        temp.Credit = double.Parse(data["Amount"]);
                        temp.Status = data["Status"];
                        temp.StatusValue = Int32.Parse(data["StatusValue"]);
                        temp.IP_Address = data["IP"];
                        temp.SearchIndex = long.Parse(data["SearchIndex"]);
                        temp.TimeIndex = Int32.Parse(data["TimeStamp"]);
                        temp.Buildtime = Convert.ToDateTime(data["Buildtime"]).ToString("yyyy/MM/dd HH:mm:ss");

                        PayoutList.Add(temp);
                    }
                }
                else
                {
                    ;
                }

            }
            catch (Exception ex)
            {

            }

            return PayoutList;
        }


