        public void CheckPayoutOrder(string type, ref SocketManager m_ListenLoginSocket, ref SocketManager m_ListenWebServerSocket, ref AsyncUserToken token, string transactionID)
        {
            try
            {
                string sreachinfo = "";

                if (type == "Web")
                {
                    sreachinfo = String.Format("TradeRecordUID = " + transactionID);
                }
                else
                {
                    sreachinfo = String.Format("ClientTransactionID = '" + transactionID + "'");
                }

                var datalist = myAcess.select("MangerToUserTradeRecord", "*", sreachinfo);

                int TradeRecordUID = 0;
                int UserUID = 0;
                string UserID = "";
                string TransactionID = "";
                string ClientTransactionID = "";
                double Cash = 0;
                double Amount = 0;
                string Status = "";
                int StatusValue = 0;
                string IP_Address = "";
                double ExtraBonusValue = 0;
                int TransChannel = 0;

                if (datalist.Count > 0)
                {
                    TradeRecordUID = Int32.Parse(datalist[0]["TradeRecordUID"]);
                    UserUID = Int32.Parse(datalist[0]["UserUID"]);
                    UserID = datalist[0]["UserID"];
                    TransactionID = datalist[0]["TransactionID"];
                    ClientTransactionID = datalist[0]["ClientTransactionID"];
                    Cash = double.Parse(datalist[0]["Cash"]);
                    Amount = double.Parse(datalist[0]["Amount"]);
                    Status = datalist[0]["Status"];
                    StatusValue = Int32.Parse(datalist[0]["StatusValue"]);
                    IP_Address = datalist[0]["IP"];
                    ExtraBonusValue = double.Parse(datalist[0]["ExtraBonus"]);
                    TransChannel = Int32.Parse(datalist[0]["TransChannel"]);

                    if (TransChannel == 1)
                    {
                        VnpayIDInfo IDInfo = new VnpayIDInfo();

                        int result1 = 0;

                        result1 = GetVnpayIDInfo(ref IDInfo);

                        if (result1 == 1)
                        {
                            var task = PayEssenceApi.CheckPayout(ClientTransactionID, TransactionID, IDInfo.MerchantCode, IDInfo.MerchantSecretKey);

                            PEPayoutStatusCheckResult result = task.Result;

                            if (result.Result == "2002" || result.Result == "2003" || result.Result == "2004" || result.Result == "35002" ||
                                result.Result == "35003")
                            {
                                if (StatusValue == 1)
                                {
                                    int newStatusValue = StatusValue;
                                    string newStatus = Status;

                                    switch (result.Result)
                                    {
                                        case "2002": newStatusValue = 1; newStatus = "Pending"; break;
                                        case "2003": newStatusValue = 2; newStatus = "Completed"; break;
                                        case "35002": newStatusValue = 2; newStatus = "Completed"; break;
                                        case "35003":
                                        case "2004":
                                            {
                                                //UserData userData = Getuser(UserUID);

                                                //if (userData != null)
                                                //{
                                                //    if (EntityDataList.ContainsKey(userData.EntityId))
                                                //    {
                                                //        if (EntityDataList[userData.EntityId].CreditReviewFg)
                                                //        {
                                                //            newStatusValue = -4;
                                                //            newStatus = "PayoutReject";
                                                //        }
                                                //        else
                                                //        {
                                                //            newStatusValue = -2;
                                                //            newStatus = "Rejected";
                                                //        }
                                                //    }
                                                //}

                                                newStatusValue = -2;
                                                newStatus = "Rejected";
                                            }
                                            break;
                                    }


                                    if (newStatus != Status)
                                    {
                                        Dictionary<string, string> updatadata = new Dictionary<string, string>();

                                        updatadata.Add("Status", "'" + newStatus + "'");

                                        updatadata.Add("StatusValue", newStatusValue.ToString());

                                        OperTionDBBox TempOperTionDBBox = new OperTionDBBox(OpertionCode.update1, "MangerToUserTradeRecord", updatadata, "TradeRecordUID", TradeRecordUID.ToString());

                                        MysqlTest test = new MysqlTest();

                                        test.update(TempOperTionDBBox.TableName, TempOperTionDBBox.Data, TempOperTionDBBox.Col, TempOperTionDBBox.Value);

                                        if (newStatus == "Rejected")
                                        {
                                            UserData Tempdata = Getuser(UserUID);

                                            double Balance = Tempdata.UserBalance;

                                            //更新玩家DB資料
                                            UpdateUserBalance(Amount, UserUID, CacheManeger.UpdateBalanceSource.Web);
                                            UpdateKeyInOutRec(Tempdata, Amount); //#251112 (CheckPayoutOrder, TransChannel=1)

                                            //MARKLU: SessionID 開分時產生
                                            double sessionID = Message.GetSessionID();

                                            UpdataUserSessionID(sessionID, UserUID);

                                            Tempdata = Getuser(UserUID);

                                            //修改Server中儲存玩家餘額資料,查看玩家有沒有上線
                                            GameData tmpdata = Message.Pack(OperationCode.ManagerChangeClientCridet,
                                                                        ActorUpdataCode.UpdateCredit,
                                                                        UserUID,
                                                                        Math.Round(Amount, 2), 0);

                                            tmpdata.userData.SessionID = Tempdata.SessionID;

                                            m_ListenLoginSocket.SendMessage(m_ListenLoginSocket.AsyncLoginServer.ConnectedLoginServer, Message.SerializrToStream(tmpdata));

                                            //====================== 寫紀錄至DB ======================================
                                            var ManegerLog = new Dictionary<string, string>();
                                            ManegerLog.Add("TradeType", "'PlayerBalanceDeal'");
                                            ManegerLog.Add("OperationType", "'Deposit'");
                                            ManegerLog.Add("TransactionType", "'1'");
                                            ManegerLog.Add("Status", "'Approved'");
                                            ManegerLog.Add("StatusValue", "'2'");
                                            ManegerLog.Add("OperatorId", "'" + Tempdata.AspNetUserId + "'");
                                            ManegerLog.Add("OperatorEntityId", "'" + Tempdata.EntityId.ToString() + "'");
                                            ManegerLog.Add("EntityID", "'" + Tempdata.EntityId.ToString() + "'");
                                            ManegerLog.Add("UserUID", "'" + UserUID.ToString() + "'");
                                            ManegerLog.Add("UserID", "'" + Tempdata.UserID + "'");
                                            ManegerLog.Add("BeforeBalance", "'" + Balance.ToString("f2") + "'");
                                            ManegerLog.Add("Amount", "'" + Math.Abs(Math.Round(Amount, 2)).ToString() + "'");
                                            ManegerLog.Add("IP", "'Rebate'");
                                            DateTime basetime = new DateTime(2020, 1, 1);
                                            DateTime currenttime = DateTime.Now;
                                            int timeIndex = (currenttime.Date - basetime).Days;
                                            long searchIndex = ((long)UserUID * 100000) + (long)timeIndex;
                                            ManegerLog.Add("SearchIndex", "'" + searchIndex.ToString() + "'");
                                            ManegerLog.Add("TimeStamp", ((DateTime.Now.Year * 10000) + (DateTime.Now.Month * 100) + DateTime.Now.Day).ToString());
                                            //myAcess.insert("MangerToUserTradeRecord", ManegerLog);
                                            OperTionDBBox tempOper = new OperTionDBBox(OpertionCode.insert, "MangerToUserTradeRecord", ManegerLog);
                                            lock (Program.opertionDBBoxs)
                                            {
                                                Program.opertionDBBoxs.Add(tempOper);
                                            }
                                        }
                                    }
                                }

                                m_ListenWebServerSocket.SendMessage(token, Message.SerializrToStream(Message.Pack(ErrorCode.Ok)));
                            }
                            else
                            {
                                m_ListenWebServerSocket.SendMessage(token, Message.SerializrToStream(Message.Pack(ErrorCode.InvalidOperation)));
                            }
                        }
                        else
                        {
                            m_ListenWebServerSocket.SendMessage(token, Message.SerializrToStream(Message.Pack(ErrorCode.InvalidOperation)));
                        }
                    }
                    else if (TransChannel == 7 || TransChannel == 8 || TransChannel == 9 || TransChannel == 11 || TransChannel == 20)
                    {
                        string channel = "";

                        if (TransChannel == 11) channel = "heropay";

                        EECheckWithdrawStatusResult result;

                        if (TransChannel == 20)
                        {
                            var task = EEPay.EECheckBankTransferWithdrawStatus(ClientTransactionID);

                            result = task.Result;
                        }
                        else
                        {
                            var task = EEPay.EECheckWithdrawStatus(ClientTransactionID, channel);

                            result = task.Result;
                        }

                        if (result.LGTResult == "10002")
                        {
                            if (StatusValue == 1)
                            {
                                int newStatusValue = StatusValue;
                                string newStatus = Status;

                                switch (result.payoutStatus)
                                {
                                    case "PENDING": newStatusValue = 1; newStatus = "Pending"; break;
                                    case "SUCCESS": newStatusValue = 2; newStatus = "Completed"; break;
                                    case "FAILED":
                                        {
                                            UserData userData = Getuser(UserUID);

                                            if (userData != null)
                                            {
                                                if (EntityDataList.ContainsKey(userData.EntityId))
                                                {
                                                    if (EntityDataList[userData.EntityId].CreditReviewFg)
                                                    {
                                                        newStatusValue = -4;
                                                        newStatus = "PayoutReject ";
                                                    }
                                                    else
                                                    {
                                                        newStatusValue = -2;
                                                        newStatus = "Rejected";
                                                    }
                                                }
                                            }
                                        }
                                        break;
                                }

                                if (newStatus != Status)
                                {
                                    Dictionary<string, string> updatadata = new Dictionary<string, string>();

                                    updatadata.Add("Status", "'" + newStatus + "'");

                                    updatadata.Add("StatusValue", newStatusValue.ToString());

                                    OperTionDBBox TempOperTionDBBox = new OperTionDBBox(OpertionCode.update1, "MangerToUserTradeRecord", updatadata, "TradeRecordUID", TradeRecordUID.ToString());

                                    MysqlTest test = new MysqlTest();

                                    test.update(TempOperTionDBBox.TableName, TempOperTionDBBox.Data, TempOperTionDBBox.Col, TempOperTionDBBox.Value);

                                    if (newStatus == "Rejected")
                                    {
                                        UserData Tempdata = Getuser(UserUID);

                                        double Balance = Tempdata.UserBalance;

                                        //更新玩家DB資料
                                        UpdateUserBalance(Amount, UserUID, CacheManeger.UpdateBalanceSource.Web);
                                        UpdateKeyInOutRec(Tempdata, Amount); //#251112 (CheckPayoutOrder, TransChannel=7,8,9,11,20)

                                        //MARKLU: SessionID 開分時產生
                                        double sessionID = Message.GetSessionID();

                                        UpdataUserSessionID(sessionID, UserUID);

                                        Tempdata = Getuser(UserUID);

                                        //修改Server中儲存玩家餘額資料,查看玩家有沒有上線
                                        GameData tmpdata = Message.Pack(OperationCode.ManagerChangeClientCridet,
                                                                    ActorUpdataCode.UpdateCredit,
                                                                    UserUID,
                                                                    Math.Round(Amount, 2), 0);

                                        tmpdata.userData.SessionID = Tempdata.SessionID;

                                        m_ListenLoginSocket.SendMessage(m_ListenLoginSocket.AsyncLoginServer.ConnectedLoginServer, Message.SerializrToStream(tmpdata));

                                        //====================== 寫紀錄至DB ======================================
                                        var ManegerLog = new Dictionary<string, string>();
                                        ManegerLog.Add("TradeType", "'PlayerBalanceDeal'");
                                        ManegerLog.Add("OperationType", "'Deposit'");
                                        ManegerLog.Add("TransactionType", "'1'");
                                        ManegerLog.Add("Status", "'Approved'");
                                        ManegerLog.Add("StatusValue", "'2'");
                                        ManegerLog.Add("OperatorId", "'" + Tempdata.AspNetUserId + "'");
                                        ManegerLog.Add("OperatorEntityId", "'" + Tempdata.EntityId.ToString() + "'");
                                        ManegerLog.Add("EntityID", "'" + Tempdata.EntityId.ToString() + "'");
                                        ManegerLog.Add("UserUID", "'" + UserUID.ToString() + "'");
                                        ManegerLog.Add("UserID", "'" + Tempdata.UserID + "'");
                                        ManegerLog.Add("BeforeBalance", "'" + Balance.ToString("f2") + "'");
                                        ManegerLog.Add("Amount", "'" + Math.Abs(Math.Round(Amount, 2)).ToString() + "'");
                                        ManegerLog.Add("IP", "'Rebate'");
                                        DateTime basetime = new DateTime(2020, 1, 1);
                                        DateTime currenttime = DateTime.Now;
                                        int timeIndex = (currenttime.Date - basetime).Days;
                                        long searchIndex = ((long)UserUID * 100000) + (long)timeIndex;
                                        ManegerLog.Add("SearchIndex", "'" + searchIndex.ToString() + "'");
                                        ManegerLog.Add("TimeStamp", ((DateTime.Now.Year * 10000) + (DateTime.Now.Month * 100) + DateTime.Now.Day).ToString());
                                        //myAcess.insert("MangerToUserTradeRecord", ManegerLog);
                                        OperTionDBBox tempOper = new OperTionDBBox(OpertionCode.insert, "MangerToUserTradeRecord", ManegerLog);
                                        lock (Program.opertionDBBoxs)
                                        {
                                            Program.opertionDBBoxs.Add(tempOper);
                                        }
                                    }
                                }
                            }

                            m_ListenWebServerSocket.SendMessage(token, Message.SerializrToStream(Message.Pack(ErrorCode.Ok)));
                        }
                        else
                        {
                            m_ListenWebServerSocket.SendMessage(token, Message.SerializrToStream(Message.Pack(ErrorCode.InvalidOperation)));
                        }
                    }
                }
                else
                {
                    m_ListenWebServerSocket.SendMessage(token, Message.SerializrToStream(Message.Pack(ErrorCode.InvalidOperation)));
                }
            }
            catch (Exception ex)
