        public void CheckVnpayPayoutOrder(ref SocketManager m_ListenLoginSocket, string transactionID)
        {
            try
            {
                VnpayIDInfo IDInfo = new VnpayIDInfo();

                int result1 = 0;

                result1 = GetVnpayIDInfo(ref IDInfo);

                transactionID = Regex.Replace(transactionID, "[^0-9]", "");

                transactionID = transactionID.Insert(0, "2");

                if (result1 == 1)
                {
                    var datalist = myAcess.select("MangerToUserTradeRecord", "*", String.Format("TransactionIDValue = '" + transactionID + "'"));

                    int TradeRecordUID = 0;
                    int UserUID = 0;
                    string UserID = "";
                    string TransactionID = "";
                    string ClientTransactionID = "";
                    double Cash = 0;
                    double Amount = 0;
                    string Status = "";
                    int StatusValue = 0;
                    string IP_Address = "";

                    if (datalist.Count > 0)
                    {
                        TradeRecordUID = Int32.Parse(datalist[0]["TradeRecordUID"]);
                        UserUID = Int32.Parse(datalist[0]["UserUID"]);
                        UserID = datalist[0]["UserID"];
                        TransactionID = datalist[0]["TransactionID"];
                        ClientTransactionID = datalist[0]["ClientTransactionID"];
                        Cash = double.Parse(datalist[0]["Cash"]);
                        Amount = double.Parse(datalist[0]["Amount"]);
                        Status = datalist[0]["Status"];
                        StatusValue = Int32.Parse(datalist[0]["StatusValue"]);
                        IP_Address = datalist[0]["IP"];

                        var task = VnpayApi.CheckPayout(IDInfo.ProjectID, TransactionID, IDInfo.SecretKey);

                        APIResult result = task.Result;

                        if (result.status == "0" && (StatusValue == 0))
                        {
                            int newStatusValue = StatusValue;
                            string newStatus = Status;

                            switch (result.data["status"])
                            {
                                case "Pending": newStatusValue = 0; newStatus = "Pending"; break;
                                case "Completed": newStatusValue = 2; newStatus = "Completed"; break;
                                case "Failed": newStatusValue = -1; newStatus = "Failed"; break;
                                case "Rejected": newStatusValue = -2; newStatus = "Rejected"; break;
