                                    Tempdata = Getuser(UserUID);

                                    //修改Server中儲存玩家餘額資料,查看玩家有沒有上線
                                    GameData tmpdata = Message.Pack(OperationCode.ManagerChangeClientCridet,
                                                                ActorUpdataCode.UpdateCredit,
                                                                UserUID,
                                                                Math.Round(Amount, 2), 0);

                                    tmpdata.userData.SessionID = Tempdata.SessionID;

                                    m_ListenLoginSocket.SendMessage(m_ListenLoginSocket.AsyncLoginServer.ConnectedLoginServer, Message.SerializrToStream(tmpdata));

                                    //====================== 寫紀錄至DB ======================================
                                    var ManegerLog = new Dictionary<string, string>();
