        public void CheckVnpayPayoutStatus(ref SocketManager m_ListenLoginSocket, int TradeRecordUID, int userUID, string transactionID, int oldstatusvalue, string oldstatus, double Credit)
        {
            try
            {
                VnpayIDInfo IDInfo = new VnpayIDInfo();

                int result1 = 0;

                result1 = GetVnpayIDInfo(ref IDInfo);

                if (result1 == 1)
                {

                    var task = VnpayApi.CheckPayout(IDInfo.ProjectID, transactionID, IDInfo.SecretKey);

                    APIResult result = task.Result;

                    if (result.status == "0")
                    {
                        int newStatusValue = 0;
                        string newStatus = "";

                        switch (result.data["status"])
                        {
                            case "Pending": newStatusValue = 0; newStatus = "Pending"; break;
                            case "Completed": newStatusValue = 2; newStatus = "Completed"; break;
                            case "Failed": newStatusValue = -1; newStatus = "Failed"; break;
                            case "Rejected": newStatusValue = -2; newStatus = "Rejected"; break;
                        }

                        if (result.data["status"] != oldstatus)
                        {
                            Dictionary<string, string> updatadata = new Dictionary<string, string>();

                            updatadata.Add("Status", "'" + newStatus + "'");

                            updatadata.Add("StatusValue", newStatusValue.ToString());

                            OperTionDBBox TempOperTionDBBox = new OperTionDBBox(OpertionCode.update1, "MangerToUserTradeRecord", updatadata, "TradeRecordUID", TradeRecordUID.ToString());

                            MysqlTest test = new MysqlTest();

                            test.update(TempOperTionDBBox.TableName, TempOperTionDBBox.Data, TempOperTionDBBox.Col, TempOperTionDBBox.Value);

                            if (result.data["status"] != "Completed")
