                                ManegerLog.Add("OperatorEntityId", "'" + Tempdata.EntityId.ToString() + "'");
                                ManegerLog.Add("EntityID", "'" + Tempdata.EntityId.ToString() + "'");
                                ManegerLog.Add("UserUID", "'" + userUID.ToString() + "'");
                                ManegerLog.Add("UserID", "'" + Tempdata.UserID + "'");
                                ManegerLog.Add("BeforeBalance", "'" + Balance.ToString("f2") + "'");
                                ManegerLog.Add("Amount", "'" + Math.Abs(Math.Round(Credit, 2)).ToString() + "'");
                                ManegerLog.Add("IP", "'Redeposit'");
                                DateTime basetime = new DateTime(2020, 1, 1);
                                DateTime currenttime = DateTime.Now;
