        public void GetLobbyBonusList()
        {
            var datalist = myAcess.select("LobbyBonusTable", "*");

            if (datalist.Count > 0)
            {
                lock (LobbyBonusList)
                {
                    if (LobbyBonusList.Count > 0) { LobbyBonusList.Clear(); }
                }

                for (int i = 0; i < datalist.Count; i++)
                {
                    if (Convert.ToInt32(datalist[i]["Status"]) == 0)
                    {
                        LobbyBonusData Temp = new LobbyBonusData();

                        Temp.BonusUID = Convert.ToInt32(datalist[i]["BonusUID"]);
                        Temp.UserUID = Convert.ToInt32(datalist[i]["UserUID"]);
                        Temp.BonusAmount = Convert.ToDouble(datalist[i]["BonusAmount"]);
                        Temp.Status = Convert.ToInt32(datalist[i]["Status"]);

                        lock (LobbyBonusList)
                        {
                            LobbyBonusList.Add(Temp);
                        }
                    }
                }
            }
        }

        public List<LobbyBonusData> GetLobbyBonusTempList()
        {
            List<LobbyBonusData> list = new List<LobbyBonusData>();

            lock (LobbyBonusList)
            {
                foreach (LobbyBonusData data in LobbyBonusList)
                {
                    if (data.Status == 0)
                    {
                        LobbyBonusData temp = new LobbyBonusData();

                        temp.BonusUID = data.BonusUID;
                        temp.UserUID = data.UserUID;
                        temp.BonusAmount = data.BonusAmount;
                        temp.Status = data.Status;

                        list.Add(temp);
                    }
                }
            }

            return list;
        }

