        public string SetPlayerPGSlotSession(int UserUID)
        {
            if (PGSlotSessionList.ContainsKey(UserUID))
            {
                PGSlotSessionList[UserUID].PGSlotPlayerSession = Guid.NewGuid().ToString();
                PGSlotSessionList[UserUID].PGSlotTimestamp = DateTime.Now;

                return PGSlotSessionList[UserUID].PGSlotPlayerSession;
            }
            else
            {
                PGSlotData NewData = new PGSlotData();

                NewData.PGSlotPlayerSession = Guid.NewGuid().ToString();
                NewData.PGSlotTimestamp = DateTime.Now;

                PGSlotSessionList.Add(UserUID, NewData);

                return NewData.PGSlotPlayerSession;
