        public int CheckPlayerPGSlotSession(string SessionCode)
        {
            try
            {
                Console.WriteLine($"SessionList");

                foreach (KeyValuePair<int, PGSlotData> pair in PGSlotSessionList)
                {
                    Console.WriteLine("Player:" + pair.Key.ToString() + " Session:" + pair.Value.PGSlotPlayerSession);
                }

                List<int> UserUID = PGSlotSessionList.Where(x => x.Value.PGSlotPlayerSession == SessionCode).Select(i => i.Key).ToList();

                TimeSpan ts = DateTime.Now - PGSlotSessionList[UserUID[0]].PGSlotTimestamp;

                Console.WriteLine("UserUID:" + UserUID[0]);

                int difference = (int)ts.TotalSeconds;

                Console.WriteLine("difference:" + difference.ToString());

                PGSlotSessionList.Remove(UserUID[0]);

                return UserUID[0];

                if (difference > 0 && difference < 15)
                {
                    return UserUID[0];
                }
                else
                {
                    return -1;
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine("ex:" + ex.Message);
                MyConsole.WriteLine(ex.StackTrace);
                return -1;
            }
        }

        static object SetLobbySessionLock = new object();
        public string SetLobbySession(int UserUID, Walletlocation loction)
        {
            lock (SetLobbySessionLock)
            {
                string Table = GetLobbySessionTableName(loction);

                var datalist = myAcess.select(Table, "*", String.Format("UserUID = {0}", UserUID));

                if (datalist.Count > 0)
                {
                    string guid = Guid.NewGuid().ToString();

                    var datalist2 = myAcess.select(Table, "*", String.Format("Id = '{0}'", guid));

                    while (datalist2.Count > 0)
                    {
                        guid = Guid.NewGuid().ToString();

                        datalist2 = myAcess.select(Table, "*", String.Format("Id = '{0}'", guid));
                    }

                    Dictionary<string, string> updatedata = new Dictionary<string, string>();

                    updatedata.Add("Id", "'" + guid + "'");

                    myAcess.update(Table, updatedata, String.Format("UserUID = {0}", UserUID));

                    return guid;
                }
                else
                {
                    string guid = Guid.NewGuid().ToString();

                    var datalist2 = myAcess.select(Table, "*", String.Format("Id = '{0}'", guid));

                    while (datalist2.Count > 0)
                    {
                        guid = Guid.NewGuid().ToString();

                        datalist2 = myAcess.select(Table, "*", String.Format("Id = '{0}'", guid));
                    }

                    Dictionary<string, string> newdata = new Dictionary<string, string>();
                    newdata.Add("Id", "'" + guid + "'");
                    newdata.Add("UserUID", UserUID.ToString());
                    myAcess.insert(Table, newdata);

                    return guid;
                }
            }
        }

