        public void WritePGSTransferLog(int playerUid, double amount, double balanceBefore, string localTransId, string clientTransId, UserData userData, TransOperType operType, TransOperChannel operCh)
        {
            Dictionary<string, string> data = new Dictionary<string, string>();

            data.Add("TradeType", "'PlayerBalanceDeal'");
            data.Add("StatusValue", "'2'");
            data.Add("Status", "'Approved'");

            data.Add("TransChannel", "'" + ((int)operCh).ToString() + "'");

            if (operType == TransOperType.轉回本地) //將錢轉回來 (存入)
            {
                data.Add("OperationType", "'Deposit'");
                data.Add("TransactionType", "'1'");
            }
            else //將錢轉出去 (取出)
            {
                data.Add("OperationType", "'Withdrawal'");
                data.Add("TransactionType", "'2'");
            }

            data.Add("OperatorId", "'" + userData.AspNetUserId + "'");
            data.Add("OperatorEntityId", "'" + userData.EntityId.ToString() + "'");
            data.Add("EntityID", "'" + userData.EntityId.ToString() + "'");
            data.Add("UserUID", "'" + userData.UserUID.ToString() + "'");
            data.Add("UserID", "'" + userData.UserID + "'");

            data.Add("TransactionID", "'" + localTransId + "'"); //我方交易序號
            data.Add("ClientTransactionID", "'" + clientTransId + "'"); //對方(PGS)交易序號
            data.Add("BeforeBalance", "'" + balanceBefore + "'"); //交易前玩家本地餘額
            data.Add("Amount", "'" + amount.ToString() + "'"); //本次交易金額

            DateTime currenttime = DateTime.Now;
            data.Add("SearchIndex", "'" + Program.GetLogSearchIndex(currenttime, userData.UserUID).ToString() + "'");
            data.Add("TimeStamp", Program.GetLogTimeStamp(currenttime).ToString());

            OperTionDBBox TempData = new OperTionDBBox(OpertionCode.insert, "MangerToUserTradeRecord", data);


            //Dictionary<string, string> data = new Dictionary<string, string>();
            //data.Add("TransferType", type);
            //data.Add("PlayerUid", playerUid.ToString());
            //data.Add("PlayerId", "'" + userData.UserID + "'");
            //data.Add("Amount", result.Amount.ToString());
            //data.Add("BeforeBalance", result.BalanceBefore.ToString());
            ////data.Add("AfterBalance", result.BalanceAfter.ToString());
            //data.Add("TransactionId", "'" + result.TransactionId + "'");
            //data.Add("TransferRefer", "'" + transRefer + "'");
            ////data.Add("Currency", "'" + currency + "'");
            //data.Add("Buildtime", "'" + DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss") + "'");
            //OperTionDBBox TempData = new OperTionDBBox(OpertionCode.insert, "PGSTransferLog", data);

            lock (Program.opertionDBBoxs)
            {
                Program.opertionDBBoxs.Add(TempData);
            }


            //玩家報告 #251203
            if (operType == TransOperType.轉回本地) //將錢轉回來 (存入)
            {
                PlayerReportH5In(userData.UserUID, amount);
            }
            else
            {
                PlayerReportH5Out(userData.UserUID, amount);
            }
        }

        //Double精度調整用
        const double _H5EpsValue = 0.00000001;

        #region PGSlot
        bool PGSDbuFg = false;    //_UNDONE: PGSlot DEBUG
        bool PGSDbuFg2 = false; //_UNDONE: PGSlot DEBUG
        object PGSTILock = new object();
        /// <summary>PGS充值轉帳</summary>
        public (int, UserData) PGSTransferInPlayerBalance(int playerUid)
        {
            UserData userData = Getuser(playerUid);

            if (userData == null) return (0, null); //Error  Player not found

            if (!CanPlayH5(userData))
            {
                MyConsole.WriteLine($"玩家:{userData.UserID} PGS充值失敗: [Bonus can't play H5 game]");
                return (0, null);
            }

            lock (PGSTILock)
            {
                double amount = Math.Truncate((userData.UserBalance * 100) + _H5EpsValue) / 100; //PGS只接受2位小數
                if (amount <= 0)
                {
                    userData.Wallet = Walletlocation.PGS; //但是PGS可能有錢
                    userData.PGS_Ret = true;
                    return (2, null); //玩家本地端沒錢
                }

                string player_name = userData.UserID;
                string currency = CountrySetting.PGSCurrency; //"MYR";
                                                              //同1個轉帳, 若失敗重發api時, localTransId必須相同才能避免重複轉帳意外
                string localTransId = ""; //本地交易序號
                int getIdResult = GetPayoutClientTransactionID(ref localTransId);

                if (getIdResult == 1)
                {
                    //這邊"可能"會有線程堵塞問題, 但是目前先不處理
                    var task = PGSlot.TransferInPlayerBalance(player_name, amount, localTransId, currency);
                    PGSlotResult transResu = task.Result;

                    if (transResu.LGTResult == "0") //轉帳成功
                    {
                        //紀錄玩家的錢目前在PGS
                        userData.Wallet = Walletlocation.PGS;
                        userData.PGS_Ret = true;

                        //將玩家本地Credit歸零, 並更新UserTable
                        double balanceBefore = Math.Round(userData.UserBalance, Program.AccuracyDigitBal);
                        userData.UserBalance -= amount;
                        AddUserdataUpdateList(playerUid);
                        //將轉帳紀錄寫至DBLog
                        WritePGSTransferLog(playerUid, transResu.Amount, balanceBefore, localTransId, transResu.TransactionId, userData, TransOperType.本地轉出, TransOperChannel.PGS);

                        if (PGSDbuFg) MyConsole.WriteLine($"玩家:{player_name} PGS充值: [{amount.ToString("f2")}]");
                        return (1, userData);
                    }
                    else //轉帳失敗, 放棄?重試?
                    {
                        MyConsole.WriteLine($"玩家:{player_name} PGS充值失敗: [{transResu.LGTResult}, {transResu.LGTRemarks}]");
                    }
                }
                return (0, null);
            }
        }

        /// <summary>PGS轉帳回來</summary>
        public GPTransResult PGSTransferOutPlayerBalance(PGSlotTransTask transWork)  //, int playerUid, UserData userData, string localTransId = "")
        {
            //UserData userData = Getuser(playerUid);
            UserData userData = transWork.UserData;
            int playerUid = transWork.PlayerUid;

            if (userData == null)
            {
                //userData.PGS_Ret = false;
                return GPTransResult.本地玩家錯誤; //Error Player not found
            }

            string player_name = userData.UserID;

            //if (userData.Wallet == Walletlocation.LOCAL)
            //if (!userData.PGS_Ret)
            //{
            //    if (PGSDbuFg2) MyConsole.WriteLine($"玩家:{player_name} PGS取回: [已取回]");
            //    userData.PGS_Ret = false;
            //    return GPTransResult.錢包沒錢轉帳;
            //}

            string currency = CountrySetting.PGSCurrency; //"MYR";
            //製作本地交易序號
            //同1個轉帳, 若失敗重發api時, localTransId必須相同才能避免重複轉帳意外
            //string localTransId = ""; //本地交易序號
            int getIdResult = 1;
            string localTransId = transWork.LocalTransId;
            if (localTransId == null || localTransId == "")
            {
                getIdResult = GetDepositClientTransactionID(ref localTransId);
                if (getIdResult == 1)
                {
                    transWork.LocalTransId = localTransId;
                    //MyConsole.WriteLine($"PGS取回: 本地交易序號:{localTransId}");
                }
            }

            if (getIdResult == 1)
            {
                var task2 = PGSlot.TransferOutPlayerBalance(player_name, localTransId, currency);
                PGSlotResult transResu = task2.Result;

                if (transResu.LGTResult == "0") //通訊成功
                {
                    if (transResu.Amount > 0) //轉帳成功
                    {
                        //紀錄玩家的錢目前所在位置
                        //userData.PGS_Ret = false;

                        //將錢加回本地玩家Credit, 並更新UserTable
                        double balanceBefore = Math.Round(userData.UserBalance, Program.AccuracyDigitBal);
                        userData.UserBalance += transResu.Amount;
                        AddUserdataUpdateList(playerUid);
                        //將轉帳紀錄寫至DBLog
                        WritePGSTransferLog(playerUid, transResu.Amount, balanceBefore, localTransId, transResu.TransactionId, userData, TransOperType.轉回本地, TransOperChannel.PGS);

                        if (PGSDbuFg) MyConsole.WriteLine($"玩家:{player_name} PGS取回: [{transResu.Amount.ToString()}]");

                        return GPTransResult.成功;
                    }
                    else
                    {
                        //userData.PGS_Ret = false;

                        if (PGSDbuFg) MyConsole.WriteLine($"玩家:{player_name} PGS取回: [無錢可取回]");
                        return GPTransResult.錢包沒錢轉帳;
                    }
                }
                else if (transResu.LGTResult == "1")
                {
                    //userData.PGS_Ret = false;

                    if (PGSDbuFg2) MyConsole.WriteLine($"玩家:{player_name} PGS取回: [失敗] [{transResu.LGTRemarks}] : [{transResu.LGTResult}]");
                    return GPTransResult.遊戲商玩家錯誤; //PGS無此玩家
                }
                else //轉帳失敗, 放棄?重試?
                {
                    MyConsole.WriteLine($"玩家:{player_name} PGS取回: [失敗] [{transResu.LGTRemarks}] : [{transResu.LGTResult}]");
                }
            }
            return GPTransResult.未完成;
        }
