                //JILIResult ctransResu = ctask.Result;
                //MyConsole.WriteLine($"JILI創建玩家{player_name}:ERR={ctransResu.ErrorCode}, MSG={ctransResu.Message}, DATA={ctransResu.Data}"); //UNDONE: JILI創建玩家 DEBUG
                //if (ctransResu.ErrorCode != "0")
                //{
                //    return (0, null); //創建玩家失敗
                //}


                //string currency = CountrySetting.PGSCurrency; //"MYR";
                //同1個轉帳, 若失敗重發api時, localTransId必須相同才能避免重複轉帳意外
                string localTransId = ""; //本地交易序號
                int getIdResult = GetPayoutClientTransactionID(ref localTransId);

                if (getIdResult == 1)
                {
                    //這邊"可能"會有線程堵塞問題, 但是目前先不處理
                    var task = JILI.TransferInPlayerBalance(player_name, amount, localTransId);
                    JILITransferResult transResu = task.Result;


                    //MyConsole.WriteLine($"JILI充值{player_name}:ERR={transResu.ErrorCode}, MSG={transResu.Message}, DATA={transResu.Data}"); //UNDONE: JILI充值 DEBUG


                    if (transResu.ErrorCode == "0") //通訊成功
                    {
                        if (transResu.Data.Status == 1) //轉帳成功
                        {
                            //紀錄玩家的錢目前在JILI
                            userData.Wallet = Walletlocation.JILI;
                            userData.JILI_Ret = true;

                            //double jamount = Math.Round(transResu.Data.CurrencyAfter - transResu.Data.CurrencyBefore, Program.AccuracyDigitBal);
                            double jamount = transResu.Data.CurrencyAfter - transResu.Data.CurrencyBefore; //充值JILI錢包變多, 所以 充值後(大) 減 充值前(小)
                            jamount = Math.Round(jamount, Program.AccuracyDigitBal);

                            if (JILIDbuFg)
                            {
                                //檢查轉帳金額是否正確
                                if (jamount != amount) MyConsole.WriteLine($"玩家:{player_name} JILI充值 金額錯誤:[原值:{amount.ToString()} 返值:{jamount.ToString()}]");
                            }

                            //將玩家本地Credit歸零, 並更新UserTable
                            double balanceBefore = Math.Round(userData.UserBalance, Program.AccuracyDigitBal);
                            userData.UserBalance -= jamount;
                            AddUserdataUpdateList(playerUid);
                            //將轉帳紀錄寫至DBLog
                            WritePGSTransferLog(playerUid, jamount, balanceBefore, localTransId, localTransId, userData, TransOperType.本地轉出, TransOperChannel.JILI);

                            if (JILIDbuFg) MyConsole.WriteLine($"玩家:{player_name} JILI充值: [{jamount.ToString()}]");
                            return (1, userData);
                        }
                        else //轉帳失敗, 放棄?重試?
                        {
                            if (JILIDbuFg) MyConsole.WriteLine($"玩家:{player_name} JILI充值失敗: [{transResu.ErrorCode}, {transResu.Message}]");
                        }
                    }
                    else if (transResu.ErrorCode == "101") //會員帳號不存在
                    {
                        if (JILIDbuFg) MyConsole.WriteLine($"玩家:{player_name} JILI會員帳號不存在: [{transResu.ErrorCode}, {transResu.Message}]");
                    }
                    else //轉帳失敗, 放棄?重試?
                    {
                        MyConsole.WriteLine($"玩家:{player_name} JILI充值: [失敗] [{transResu.ErrorCode}] : [{transResu.Message}]");
                    }
                }
                return (0, null);
            }
        }

        /// <summary>JILI轉帳回來</summary>
        public GPTransResult JILITransferOutPlayerBalance(PGSlotTransTask transWork)
        {
            //UserData userData = Getuser(playerUid);
            UserData userData = transWork.UserData;
            int playerUid = transWork.PlayerUid;

            if (userData == null)
            {
                return GPTransResult.本地玩家錯誤; //Error Player not found
            }

            string player_name = userData.UserID;

            //if (userData.Wallet == Walletlocation.LOCAL)
            //if (!userData.JILI_Ret)
            //{
            //    if (JILIDbuFg2) MyConsole.WriteLine($"玩家:{player_name} JILI取回: [已取回]");
            //    userData.JILI_Ret = false;
            //    return GPTransResult.錢包沒錢轉帳;
            //}

            //string currency = CountrySetting.PGSCurrency; //"MYR";
            //製作本地交易序號
            //同1個轉帳, 若失敗重發api時, localTransId必須相同才能避免重複轉帳意外
            //string localTransId = ""; //本地交易序號
            int getIdResult = 1;
            string localTransId = transWork.LocalTransId;
            if (localTransId == null || localTransId == "")
            {
                getIdResult = GetDepositClientTransactionID(ref localTransId);
                if (getIdResult == 1)
                {
                    transWork.LocalTransId = localTransId;
                    //MyConsole.WriteLine($"JILI取回: 本地交易序號:{localTransId}");
                }
            }

            if (getIdResult == 1)
            {
                var task2 = JILI.TransferOutPlayerBalance(player_name, 0, localTransId);
                JILITransferResult transResu = task2.Result;

                if (transResu.ErrorCode == "0") //通訊成功
                {
                    if (transResu.Data != null && transResu.Data.Status == 1) //轉帳成功
                    {
                        //紀錄玩家的錢目前所在位置
                        //userData.JILI_Ret = false;

                        //將錢加回本地玩家Credit, 並更新UserTable
                        double balanceBefore = Math.Round(userData.UserBalance, Program.AccuracyDigitBal);
                        double amount = transResu.Data.CurrencyBefore - transResu.Data.CurrencyAfter; //轉回JILI錢包變少, 所以 充值前(大) 減 充值後(小)
                        amount = Math.Round(amount, 6);

                        if (amount != 0) //有轉錢才紀錄 (這裡須要判斷負值嗎??)
                        {
                            double locamount = Math.Truncate((amount * 1000) + _H5EpsValue) / 1000; //本地端只接受3位小數
                            userData.UserBalance += locamount;
                            AddUserdataUpdateList(playerUid);
                            //將轉帳紀錄寫至DBLog
                            WritePGSTransferLog(playerUid, amount, balanceBefore, localTransId, localTransId, userData, TransOperType.轉回本地, TransOperChannel.JILI);

                            //if (JILIDbuFg) MyConsole.WriteLine($"玩家:{player_name} JILI取回: [{amount.ToString("f2")}]");
                            if (JILIDbuFg) MyConsole.WriteLine($"玩家:{player_name} JILI取回: [{amount.ToString()}]");
                        }
                        else
                        {
                            if (JILIDbuFg) MyConsole.WriteLine($"玩家:{player_name} JILI取回: [無錢可取回]");
                        }

                        return GPTransResult.成功;
                    }
                    else
                    {
                        //userData.JILI_Ret = false;

                        if (JILIDbuFg) MyConsole.WriteLine($"玩家:{player_name} JILI取回: [失敗] [{transResu.ErrorCode}] : [{transResu.Message}]");
                        return GPTransResult.錢包沒錢轉帳;
                    }
                }
                else if (transResu.ErrorCode == "101") //會員帳號不存在
                {
                    //userData.JILI_Ret = false;

                    if (JILIDbuFg2) MyConsole.WriteLine($"玩家:{player_name} JILI取回: [失敗] [{transResu.ErrorCode}] : [{transResu.Message}]");
                    return GPTransResult.遊戲商玩家錯誤; //JILI無此玩家
                }
                else if (transResu.ErrorCode == "102") //ID重複
                {
                    if (JILIDbuFg) MyConsole.WriteLine($"玩家:{player_name} JILI取回: [失敗][ID重複({transWork.LocalTransId})] [{transResu.ErrorCode}] : [{transResu.Message}]");
                    transWork.LocalTransId = null;
                }
                else //轉帳失敗, 放棄?重試?
                {
                    MyConsole.WriteLine($"玩家:{player_name} JILI取回: [失敗] [{transResu.ErrorCode}] : [{transResu.Message}]");
                }
            }
            return GPTransResult.未完成;
        }
        #endregion

