                    //MyConsole.WriteLine($"FC充值{player_name}:ERR={transResu.ErrorCode}, MSG={transResu.Message}, DATA={transResu.Data}"); //UNDONE: FC充值 DEBUG

                    if (transResu.Result == 0) //通訊成功
