                        //if (transResu.Data.Status == 1) //轉帳成功
                        {
                            //紀錄玩家的錢目前在JILI
                            userData.Wallet = Walletlocation.FC;
                            userData.FC_Ret = true;

                            //double jamount = Math.Round(transResu.Amount, Program.AccuracyDigitBal);
                            double jamount = transResu.Amount;
