                            }

                            //將玩家本地Credit歸零, 並更新UserTable
                            double balanceBefore = Math.Round(userData.UserBalance, Program.AccuracyDigitBal);
                            userData.UserBalance -= jamount;
                            AddUserdataUpdateList(playerUid);
                            //將轉帳紀錄寫至DBLog
                            WritePGSTransferLog(playerUid, jamount, balanceBefore, localTransId, transResu.TransactionId, userData, TransOperType.本地轉出, TransOperChannel.FC);

                            if (FCDbuFg) MyConsole.WriteLine($"玩家:{player_name} FC充值: [{jamount.ToString()}]");
