        /// <summary>FC轉帳回來</summary>
        public GPTransResult FCTransferOutPlayerBalance(PGSlotTransTask transWork)
        {
            //UserData userData = Getuser(playerUid);
            UserData userData = transWork.UserData;
            int playerUid = transWork.PlayerUid;

            if (userData == null)
            {
                return GPTransResult.本地玩家錯誤; //Error Player not found
            }

            string player_name = userData.UserID;

            //if (userData.Wallet == Walletlocation.LOCAL)
            //if (!userData.FC_Ret)
            //{
            //    if (FCDbuFg2) MyConsole.WriteLine($"玩家:{player_name} FC取回: [已取回]");
            //    userData.FC = false;
            //    return GPTransResult.錢包沒錢轉帳;
            //}

            //string currency = CountrySetting.PGSCurrency; //"MYR";
            //製作本地交易序號
            //同1個轉帳, 若失敗重發api時, localTransId必須相同才能避免重複轉帳意外
            //string localTransId = ""; //本地交易序號
            int getIdResult = 1;
            string localTransId = transWork.LocalTransId;
            if (localTransId == null || localTransId == "")
            {
                getIdResult = GetDepositClientTransactionID(ref localTransId);
                if (getIdResult == 1)
                {
                    transWork.LocalTransId = localTransId;
                    //MyConsole.WriteLine($"FC取回: 本地交易序號:{localTransId}");
                }
            }

            if (getIdResult == 1)
            {
                var task2 = FC.TransferOutPlayerBalance(player_name, localTransId);
                FCTransferResult transResu = task2.Result;
                //MyConsole.WriteLine($" FC取回: Status={transResu.Status}, Result={transResu.Result}");
                if (transResu.Status == 0) //轉帳成功
                {
                    if (transResu.Result == 0) //轉帳成功
                    {
                        //紀錄玩家的錢目前所在位置
                        //userData.FC_Ret = false;

                        //將錢加回本地玩家Credit, 並更新UserTable
                        double balanceBefore = Math.Round(userData.UserBalance, Program.AccuracyDigitBal);
                        double amount = transResu.Amount;
                        amount = Math.Round(amount, Program.AccuracyDigitBal);

                        if (amount != 0) //有轉錢才紀錄
                        {
                            double locamount = Math.Truncate((amount * 1000) + _H5EpsValue) / 1000; //本地端只接受3位小數
                            userData.UserBalance += locamount;
                            AddUserdataUpdateList(playerUid);
                            //將轉帳紀錄寫至DBLog
                            WritePGSTransferLog(playerUid, amount, balanceBefore, localTransId, transResu.TransactionId, userData, TransOperType.轉回本地, TransOperChannel.FC);
                        }

                        //if (FCDbuFg) MyConsole.WriteLine($"玩家:{player_name} FC取回: [{amount.ToString("f2")}]");
                        if (FCDbuFg) MyConsole.WriteLine($"玩家:{player_name} FC取回: [{amount.ToString()}]");
                        return GPTransResult.成功;
                    }
                    else if (transResu.Result == 200)
                    {
                        if (FCDbuFg) MyConsole.WriteLine($"玩家:{player_name} FC取回: [無錢可取回]");
                        return GPTransResult.錢包沒錢轉帳;
                    }
                    else if (transResu.Result == 500) //會員帳號不存在
                    {
                        if (FCDbuFg) MyConsole.WriteLine($"玩家:{player_name} FC取回: [遊戲商會員帳號不存在]");
                        return GPTransResult.遊戲商玩家錯誤;
                    }

                    MyConsole.WriteLine($"玩家:{player_name} FC取回: [錯誤碼:{transResu.Result.ToString()}]");
                }
                else //轉帳失敗, 放棄?重試?
                {
                    MyConsole.WriteLine($"玩家:{player_name} FC取回: [失敗] [{transResu.Result.ToString()}] : [{transResu.Message}]");
                }
            }
            return GPTransResult.未完成;
        }
