                        double balanceBefore = Math.Round(userData.UserBalance, Program.AccuracyDigitBal);
                        double amount = transResu.Data.CurrencyBefore - transResu.Data.CurrencyAfter; //轉回AceWin錢包變少, 所以 充值前(大) 減 充值後(小)
                        amount = Math.Round(amount, 6);

                        if (amount != 0) //有轉錢才紀錄 (這裡須要判斷負值嗎??)
                        {
                            double locamount = Math.Truncate((amount * 1000) + _H5EpsValue) / 1000; //本地端只接受3位小數
                            userData.UserBalance += locamount;
                            AddUserdataUpdateList(playerUid);
                            //將轉帳紀錄寫至DBLog
                            WritePGSTransferLog(playerUid, amount, balanceBefore, localTransId, localTransId, userData, TransOperType.轉回本地, TransOperChannel.AceWin);

                            //if (AceWinDbuFg) MyConsole.WriteLine($"玩家:{player_name} AceWin取回: [{amount.ToString("f2")}]");
                            if (AceWinDbuFg) MyConsole.WriteLine($"玩家:{player_name} AceWin取回: [{amount.ToString()}]");
                        }
                        else
                        {
                            if (AceWinDbuFg) MyConsole.WriteLine($"玩家:{player_name} AceWin取回: [無錢可取回]");
                        }

                        return GPTransResult.成功;
                    }
                    else
                    {
                        if (AceWinDbuFg) MyConsole.WriteLine($"玩家:{player_name} AceWin取回: [失敗] [{transResu.ErrorCode}] : [{transResu.Message}]");
                        return GPTransResult.錢包沒錢轉帳;
                    }
                }
                else if (transResu.ErrorCode == "101") //會員帳號不存在
                {
                    if (AceWinDbuFg2) MyConsole.WriteLine($"玩家:{player_name} AceWin取回: [失敗] [{transResu.ErrorCode}] : [{transResu.Message}]");
                    return GPTransResult.遊戲商玩家錯誤; //AceWin無此玩家
                }
                else //轉帳失敗, 放棄?重試?
                {
                    MyConsole.WriteLine($"玩家:{player_name} AceWin取回: [失敗] [{transResu.ErrorCode}] : [{transResu.Message}]");
                }
            }
            return GPTransResult.未完成;
        }
