        #region JDB
        bool JDBDbuFg = false;   //_UNDONE: JDB DEBUG
        bool JDBDbuFg2 = false; //_UNDONE: JDB DEBUG
        object JDBTILock = new object();
        /// <summary>JDB充值轉帳</summary>
        public (int, UserData) JDBTransferInPlayerBalance(int playerUid)
        {
            UserData userData = Getuser(playerUid);

            if (userData == null) return (0, null); //Error  Player not found

            if (!CanPlayH5(userData))
            {
                MyConsole.WriteLine($"玩家:{userData.UserID} JDB充值失敗: [Bonus can't play H5 game]");
                return (0, null);
            }

            lock (JDBTILock)
            {
                double amount = Math.Truncate((userData.UserBalance * 1000) + _H5EpsValue) / 1000; //JDB只接受3位小數
                //double amount = Math.Round(userData.UserBalance, Program.AccuracyDigitBal);

                if (amount <= 0)
                {
                    userData.Wallet = Walletlocation.JDB; //但是JDB可能有錢
                    userData.JDB_Ret = true;
                    return (2, null); //玩家本地端沒錢
                }

                string player_name = userData.UserID;

                //UNDONE: H5轉帳可能需修改處
                //經測試, 轉帳時若 JDB 會員不存在, 不會自動創建會員
                //    目前先 直接創建玩家然後轉帳 -> 以後要修改為 直接轉帳, 若失敗再創建玩家, 然後再轉帳
                //var ctask = JDB.CreateMember(player_name);
                //JDBResult ctransResu = ctask.Result;
                //MyConsole.WriteLine($"JDB創建玩家{player_name}:ERR={ctransResu.ErrorCode}, MSG={ctransResu.Message}, DATA={ctransResu.Data}"); //UNDONE: AceWin創建玩家 DEBUG
                //if (ctransResu.ErrorCode != "0")
                //{
                //    return (0, null); //創建玩家失敗
                //}


                //string currency = CountrySetting.PGSCurrency; //"MYR";
                //同1個轉帳, 若失敗重發api時, localTransId必須相同才能避免重複轉帳意外
                string localTransId = ""; //本地交易序號
                int getIdResult = GetPayoutClientTransactionID(ref localTransId);

                if (getIdResult == 1)
                {
                    //這邊"可能"會有線程堵塞問題, 但是目前先不處理
                    var task = JDB.TransferInPlayerBalance(player_name, amount, localTransId);
                    JDBTransferResult transResu = task.Result;


                    //MyConsole.WriteLine($"JDB充值{player_name}:ERR={transResu.ErrorCode}, MSG={transResu.Message}, DATA={transResu.Data}"); //UNDONE: AceWin充值 DEBUG


                    if (transResu.ErrorCode == "0") //通訊成功
                    {
                        if (transResu.Message == "Success") //轉帳成功
                        {
                            //紀錄玩家的錢目前在JDB
                            userData.Wallet = Walletlocation.JDB;
                            userData.JDB_Ret = true;

                            //double jamount = Math.Round(transResu.Data.CurrencyAfter - transResu.Data.CurrencyBefore, Program.AccuracyDigitBal);
                            double jamount = transResu.Data.TransAmount;
                            jamount = Math.Round(jamount, Program.AccuracyDigitBal);

                            if (JDBDbuFg)
                            {
                                //檢查轉帳金額是否正確
                                if (jamount != amount) MyConsole.WriteLine($"玩家:{player_name} JDB充值 金額錯誤:[原值:{amount.ToString()} 返值:{jamount.ToString()}]");
                            }

                            //將玩家本地Credit歸零, 並更新UserTable
                            double balanceBefore = Math.Round(userData.UserBalance, Program.AccuracyDigitBal);
                            userData.UserBalance -= jamount;
                            AddUserdataUpdateList(playerUid);
                            //將轉帳紀錄寫至DBLog
                            string JDBTransId = transResu.Data.PId.ToString();
                            WritePGSTransferLog(playerUid, jamount, balanceBefore, localTransId, JDBTransId, userData, TransOperType.本地轉出, TransOperChannel.JDB);

                            if (JDBDbuFg) MyConsole.WriteLine($"玩家:{player_name} JDB充值: [{jamount.ToString()}]");
                            return (1, userData);
                        }
                        else //轉帳失敗, 放棄?重試?
                        {
                            if (JDBDbuFg) MyConsole.WriteLine($"玩家:{player_name} JDB充值失敗: [{transResu.ErrorCode}, {transResu.Message}]");
                        }
                    }
                    else if (transResu.ErrorCode == "7501") //會員帳號不存在
                    {
                        if (JDBDbuFg) MyConsole.WriteLine($"玩家:{player_name} JDB會員帳號不存在: [{transResu.ErrorCode}, {transResu.Message}]");
                    }
                    else //轉帳失敗, 放棄?重試?
                    {
                        MyConsole.WriteLine($"玩家:{player_name} JDB充值: [失敗] [{transResu.ErrorCode}] : [{transResu.Message}]");
                    }
                }
                return (0, null);
            }
        }

        /// <summary>JDB轉帳回來</summary>
        public GPTransResult JDBTransferOutPlayerBalance(PGSlotTransTask transWork)
        {
            //UserData userData = Getuser(playerUid);
            UserData userData = transWork.UserData;
            int playerUid = transWork.PlayerUid;

            if (userData == null)
            {
                return GPTransResult.本地玩家錯誤; //Error Player not found
            }

            string player_name = userData.UserID;

            //string currency = CountrySetting.PGSCurrency; //"MYR";
            //製作本地交易序號
            //同1個轉帳, 若失敗重發api時, localTransId必須相同才能避免重複轉帳意外
            //string localTransId = ""; //本地交易序號
            int getIdResult = 1;
            string localTransId = transWork.LocalTransId;
            if (localTransId == null || localTransId == "")
            {
                getIdResult = GetDepositClientTransactionID(ref localTransId);
                if (getIdResult == 1)
                {
                    transWork.LocalTransId = localTransId;
                }
            }

            if (getIdResult == 1)
            {
                var task2 = JDB.TransferOutPlayerBalance(player_name, 0, localTransId);
                JDBTransferResult transResu = task2.Result;

                if (transResu.ErrorCode == "0") //通訊成功
                {
                    if (transResu.Data != null && transResu.Message == "Success") //轉帳成功
                    {
                        //將錢加回本地玩家Credit, 並更新UserTable
                        double balanceBefore = Math.Round(userData.UserBalance, Program.AccuracyDigitBal);
                        double amount = transResu.Data.TransAmount;
                        amount = Math.Round(amount, 6);

                        if (amount != 0) //有轉錢才紀錄 (這裡須要判斷負值嗎??)
                        {
                            double locamount = Math.Truncate((amount * 1000) + _H5EpsValue) / 1000; //本地端只接受3位小數
                            userData.UserBalance += locamount;
                            AddUserdataUpdateList(playerUid);
                            //將轉帳紀錄寫至DBLog
                            string JDBTransId = transResu.Data.PId.ToString();
                            WritePGSTransferLog(playerUid, amount, balanceBefore, localTransId, JDBTransId, userData, TransOperType.轉回本地, TransOperChannel.JDB);

                            if (JDBDbuFg) MyConsole.WriteLine($"玩家:{player_name} JDB取回: [{amount.ToString()}]");
                        }
                        else
                        {
                            if (JDBDbuFg) MyConsole.WriteLine($"玩家:{player_name} JDB取回: [無錢可取回]");
                        }

                        return GPTransResult.成功;
                    }
                    else
                    {
                        if (JDBDbuFg) MyConsole.WriteLine($"玩家:{player_name} JDB取回: [失敗] [{transResu.ErrorCode}] : [{transResu.Message}]");
                        return GPTransResult.錢包沒錢轉帳;
                    }
                }
                else if (transResu.ErrorCode == "6002")
                {
                    if (JDBDbuFg) MyConsole.WriteLine($"玩家:{player_name} JDB無錢可轉回: [{transResu.ErrorCode}, {transResu.Message}]");
                    return GPTransResult.錢包沒錢轉帳;
                }
                else if (transResu.ErrorCode == "7501") //會員帳號不存在
                {
                    if (JDBDbuFg2) MyConsole.WriteLine($"玩家:{player_name} JDB取回: [失敗] [{transResu.ErrorCode}] : [{transResu.Message}]");
                    return GPTransResult.遊戲商玩家錯誤; //JDB無此玩家
                }
                else //轉帳失敗, 放棄?重試?
                {
                    MyConsole.WriteLine($"玩家:{player_name} JDB取回: [失敗] [{transResu.ErrorCode}] : [{transResu.Message}]");
                }
            }
            return GPTransResult.未完成;
        }
