            int getIdResult = 1;
            string localTransId = transWork.LocalTransId;
            if (localTransId == null || localTransId == "")
            {
                getIdResult = GetDepositClientTransactionID(ref localTransId);
                if (getIdResult == 1)
                {
                    transWork.LocalTransId = localTransId;
                }
            }

            if (getIdResult == 1)
            {
                string userPass = player_name;
                var task2 = HABA.TransferOutPlayerBalance(player_name, userPass, 0, localTransId);
                HABAMemberInfoResult transResu = task2.Result;

                if (transResu.ErrorCode == "0") //通訊成功
                {
                    if (transResu.Data != null && transResu.Data.Count > 0 && transResu.Message == "Success") //轉帳成功
                    {
                        //將錢加回本地玩家Credit, 並更新UserTable
                        double balanceBefore = Math.Round(userData.UserBalance, Program.AccuracyDigitBal);
                        double amount = transResu.Data[0].Amount;
                        amount = Math.Round(amount, 6);

                        if (amount != 0) //有轉錢才紀錄 (這裡須要判斷負值嗎??)
                        {
                            double locamount = Math.Truncate((amount * 1000) + _H5EpsValue) / 1000; //本地端只接受3位小數
                            userData.UserBalance += locamount;
                            AddUserdataUpdateList(playerUid);
                            //將轉帳紀錄寫至DBLog
                            string HABATransId = transResu.Data[0].TransactionId;
                            WritePGSTransferLog(playerUid, amount, balanceBefore, localTransId, HABATransId, userData, TransOperType.轉回本地, TransOperChannel.HABA);

                            if (HABADbuFg) MyConsole.WriteLine($"玩家:{player_name} HABA取回: [{amount.ToString()}]");
                        }
                        else
                        {
                            if (HABADbuFg) MyConsole.WriteLine($"玩家:{player_name} HABA取回: [無錢可取回]");
                        }

                        return GPTransResult.成功;
                    }
                    else
                    {
                        if (HABADbuFg) MyConsole.WriteLine($"玩家:{player_name} HABA取回: [失敗] [{transResu.ErrorCode}] : [{transResu.Message}]");
                        return GPTransResult.錢包沒錢轉帳;
                    }
                }
                else if (transResu.ErrorCode == "9998") //會員帳號不存在
                {
                    if (HABADbuFg) MyConsole.WriteLine($"玩家:{player_name} HABA取回: [失敗(2)] [{transResu.ErrorCode}] : [{transResu.Message}]");
                    return GPTransResult.遊戲商玩家錯誤; //HABA無此玩家
                }
                else //轉帳失敗, 放棄?重試?
                {
                    MyConsole.WriteLine($"玩家:{player_name} HABA Api 取回: [失敗] [{transResu.ErrorCode}] : [{transResu.Message}]");
                }
            }
            return GPTransResult.未完成;
        }
