        /// <summary>FastSpin充值轉帳</summary>
        public (int, UserData) FastSpinTransferInPlayerBalance(int playerUid)
        {
            UserData userData = Getuser(playerUid);

            if (userData == null) return (0, null); //Error  Player not found

            if (!CanPlayH5(userData))
            {
                MyConsole.WriteLine($"玩家:{userData.UserID} FastSpin充值失敗: [Bonus can't play H5 game]");
                return (0, null);
            }

            lock (FastSpinTILock)
            {
                double amount = Math.Truncate((userData.UserBalance * 1000) + _H5EpsValue) / 1000; //FastSpin只接受3位小數
                //double amount = Math.Truncate(userData.UserBalance * 1000) / 1000; //FastSpin只接受3位小數
                //double amount = Math.Round(userData.UserBalance, Program.AccuracyDigitBal);

                if (amount <= 0)
                {
                    userData.Wallet = Walletlocation.FastSpin; //但是FastSpin可能有錢
                    userData.FastSpin_Ret = true;
                    return (2, null); //玩家本地端沒錢
                }

                string player_name = userData.UserID;

                //string currency = CountrySetting.PGSCurrency; //"MYR";
                //同1個轉帳, 若失敗重發api時, localTransId必須相同才能避免重複轉帳意外
                string localTransId = ""; //本地交易序號
                int getIdResult = GetPayoutClientTransactionID(ref localTransId);

                if (getIdResult == 1)
                {
                    //這邊"可能"會有線程堵塞問題, 但是目前先不處理
                    var task = FastSpin.TransferInPlayerBalance(player_name, amount, localTransId);
                    FastSpinMemberInfoResult transResu = task.Result;


                    //MyConsole.WriteLine($"FastSpin充值{player_name}:ERR={transResu.ErrorCode}, MSG={transResu.Message}, DATA={transResu.Data}"); //UNDONE: AceWin充值 DEBUG


                    if (transResu.ErrorCode == "0") //通訊成功
                    {
                        if (transResu.Message == "Success") //轉帳成功
                        {
                            //紀錄玩家的錢目前在FastSpin
                            userData.Wallet = Walletlocation.FastSpin;
                            userData.FastSpin_Ret = true;

                            //double jamount = Math.Round(transResu.Data.CurrencyAfter - transResu.Data.CurrencyBefore, Program.AccuracyDigitBal);
                            //double jamount = transResu.Data[0].Amount;
                            double jamount = amount; //FastSpin不會返回轉帳金額

                            //將玩家本地Credit歸零, 並更新UserTable
                            double balanceBefore = Math.Round(userData.UserBalance, Program.AccuracyDigitBal);
                            userData.UserBalance -= jamount;
                            AddUserdataUpdateList(playerUid);
                            //將轉帳紀錄寫至DBLog
                            string FSTransId = transResu.Data[0].TransactionId;
                            WritePGSTransferLog(playerUid, jamount, balanceBefore, localTransId, FSTransId, userData, TransOperType.本地轉出, TransOperChannel.FastSpin);

                            if (FastSpinDbuFg) MyConsole.WriteLine($"玩家:{player_name} FastSpin充值: [{jamount.ToString()}]");
                            return (1, userData);
                        }
                        else //轉帳失敗, 放棄?重試?
                        {
                            if (FastSpinDbuFg) MyConsole.WriteLine($"玩家:{player_name} FastSpin充值失敗: [{transResu.ErrorCode}, {transResu.Message}]");
                        }
                    }
                    else //轉帳失敗, 放棄?重試?
                    {
                        MyConsole.WriteLine($"玩家:{player_name} FastSpin充值: [失敗] [{transResu.ErrorCode}] : [{transResu.Message}]");
                    }
                }
                return (0, null);
            }
        }

