        bool PlayTechDbuFg = false;   //_UNDONE: PlayTech DEBUG
        object PlayTechTILock = new object();
        /// <summary>PlayTech充值轉帳</summary>
        public (int, UserData, string) PlayTechTransferInPlayerBalance(int playerUid)
        {
            UserData userData = Getuser(playerUid);

            if (userData == null) return (0, null, ""); //Error  Player not found

            if (!CanPlayH5(userData))
            {
                MyConsole.WriteLine($"玩家:{userData.UserID} PlayTech充值失敗: [Bonus can't play H5 game]");
                return (0, null, "");
            }

            lock (PlayTechTILock)
            {
                double amount = Math.Truncate((userData.UserBalance * 100) + _H5EpsValue) / 100; //PlayTech只接受2位小數
                //double amount = Math.Truncate(userData.UserBalance * 1000) / 1000; //PlayTech只接受3位小數
                //double amount = Math.Round(userData.UserBalance, Program.AccuracyDigitBal);

                if (amount <= 0)
                {
                    userData.Wallet = Walletlocation.PlayTech; //但是PlayTech可能有錢
                    userData.PlayTech_Ret = true;
                    return (2, null, ""); //玩家本地端沒錢
                }

                string player_name = userData.UserID;

                //string currency = CountrySetting.PGSCurrency; //"MYR";
                //同1個轉帳, 若失敗重發api時, localTransId必須相同才能避免重複轉帳意外
                string localTransId = ""; //本地交易序號
                int getIdResult = GetPayoutClientTransactionID(ref localTransId);

                if (getIdResult == 1)
                {
                    //這邊"可能"會有線程堵塞問題, 但是目前先不處理
                    var task = PlayTech.TransferInPlayerBalance(player_name, amount, localTransId);
                    PlayTechMemberInfoResult transResu = task.Result;


                    //MyConsole.WriteLine($"PlayTech充值{player_name}:ERR={transResu.ErrorCode}, MSG={transResu.Message}, DATA={transResu.Data}"); //UNDONE: AceWin充值 DEBUG


                    if (transResu.Message == "Success") //轉帳成功
                    {
                        //紀錄玩家的錢目前在PlayTech
                        userData.Wallet = Walletlocation.PlayTech;
                        userData.PlayTech_Ret = true;

                        //double jamount = Math.Round(transResu.Data.CurrencyAfter - transResu.Data.CurrencyBefore, Program.AccuracyDigitBal);
                        double jamount = transResu.Data[0].Amount;
                        //double jamount = amount; //PlayTech不會返回轉帳金額

                        //將玩家本地Credit歸零, 並更新UserTable
                        double balanceBefore = Math.Round(userData.UserBalance, Program.AccuracyDigitBal);
                        userData.UserBalance -= jamount;
                        AddUserdataUpdateList(playerUid);
                        //將轉帳紀錄寫至DBLog
                        string FSTransId = transResu.Data[0].TransactionId;
                        WritePGSTransferLog(playerUid, jamount, balanceBefore, localTransId, FSTransId, userData, TransOperType.本地轉出, TransOperChannel.PlayTech);

                        if (PlayTechDbuFg) MyConsole.WriteLine($"玩家:{player_name} PlayTech充值: [{jamount.ToString()}]");
                        return (1, userData, "");
                    }
                    else //轉帳失敗, 放棄?重試?
                    {
                        string dbuMsg;
                        if (transResu.ErrorCode == "1") //商戶不匹珮
                        {
                            dbuMsg = "Incorrect Certificate Used";
                        }
                        else if (transResu.ErrorCode == "2") //商戶餘額不足
                        {
                            dbuMsg = "Insufficient Balance";
                        }
                        else
                        {
                            dbuMsg = $"API ErrorCode({transResu.ErrorCode})"; //Message:{transResu.Message}";
                        }

                        MyConsole.WriteLine($"玩家:{player_name} PlayTech充值失敗: [{transResu.ErrorCode}, {transResu.Message}]");
                        return (-1, null, dbuMsg);
                    }
                }
                return (0, null, "");
            }
        }

