                        return GPTransResult.成功;
                    }
                    else
                    {
                        if (PlayTechDbuFg) MyConsole.WriteLine($"玩家:{player_name} PlayTech取回: [失敗] [{transResu.ErrorCode}] : [{transResu.Message}]");
                        return GPTransResult.錢包沒錢轉帳;
                    }
                }
                else if (transResu.ErrorCode == "5") //會員帳號不存在
                {
                    if (PlayTechDbuFg) MyConsole.WriteLine($"玩家:{player_name} PlayTech取回: [失敗(帳號不存在)] [{transResu.ErrorCode}] : [{transResu.Message}]");
                    return GPTransResult.遊戲商玩家錯誤; //PlayTech無此玩家
                }
                else //轉帳失敗, 放棄?重試?
                {
                    MyConsole.WriteLine($"玩家:{player_name} PlayTech Api 取回: [失敗] [{transResu.ErrorCode}] : [{transResu.Message}]");
                }
            }
            return GPTransResult.未完成;
        }
