        /// <summary>CP充值轉帳</summary>
        public (int, UserData) CPTransferInPlayerBalance(int playerUid)
        {
            UserData userData = Getuser(playerUid);

            if (userData == null) return (0, null); //Error  Player not found

            if (!CanPlayH5(userData))
            {
                MyConsole.WriteLine($"玩家:{userData.UserID} CP充值失敗: [Bonus can't play H5 game]");
                return (0, null);
            }

            lock (CPTILock)
            {
                double amount = Math.Truncate((userData.UserBalance * 100) + _H5EpsValue) / 100; //CP只接受2位小數
                //double amount = Math.Truncate(userData.UserBalance * 1000) / 1000; //CP只接受3位小數
                //double amount = Math.Round(userData.UserBalance, Program.AccuracyDigitBal);

                if (amount <= 0)
                {
                    userData.Wallet = Walletlocation.CP; //但是CP可能有錢
                    userData.CP_Ret = true;
                    return (2, null); //玩家本地端沒錢
                }

                string player_name = userData.UserID;

                //string currency = CountrySetting.PGSCurrency; //"MYR";
                //同1個轉帳, 若失敗重發api時, localTransId必須相同才能避免重複轉帳意外
                string localTransId = ""; //本地交易序號
                int getIdResult = GetPayoutClientTransactionID(ref localTransId);

                if (getIdResult == 1)
                {
                    //這邊"可能"會有線程堵塞問題, 但是目前先不處理
                    var task = CP.TransferInPlayerBalance(player_name, amount, localTransId);
                    var transResu = task.Result;


                    //MyConsole.WriteLine($"CP充值{player_name}:ERR={transResu.ErrorCode}, MSG={transResu.Message}, DATA={transResu.Data}"); //UNDONE: AceWin充值 DEBUG


                    if (transResu.ErrorCode == "0") //通訊成功
                    {
                        if (transResu.Message == "Success") //轉帳成功
                        {
                            //紀錄玩家的錢目前在CP
                            userData.Wallet = Walletlocation.CP;
                            userData.CP_Ret = true;

                            //double jamount = Math.Round(transResu.Data.CurrencyAfter - transResu.Data.CurrencyBefore, Program.AccuracyDigitBal);
                            //double jamount = transResu.Data[0].Amount;
                            double jamount = amount; //CP不會返回轉帳金額

                            //將玩家本地Credit歸零, 並更新UserTable
                            double balanceBefore = Math.Round(userData.UserBalance, Program.AccuracyDigitBal);
                            userData.UserBalance -= jamount;
                            AddUserdataUpdateList(playerUid);
                            //將轉帳紀錄寫至DBLog
                            //string FSTransId = transResu.Data[0].TransactionId;
                            WritePGSTransferLog(playerUid, jamount, balanceBefore, localTransId, localTransId, userData, TransOperType.本地轉出, TransOperChannel.CP);

                            if (CPDbuFg) MyConsole.WriteLine($"玩家:{player_name} CP充值: [{jamount.ToString()}]");
                            return (1, userData);
                        }
                        else //轉帳失敗, 放棄?重試?
                        {
                            if (CPDbuFg) MyConsole.WriteLine($"玩家:{player_name} CP充值失敗: [{transResu.ErrorCode}, {transResu.Message}]");
                        }
                    }
                    else //轉帳失敗, 放棄?重試?
                    {
                        MyConsole.WriteLine($"玩家:{player_name} CP充值: [失敗] [{transResu.ErrorCode}] : [{transResu.Message}]");
                    }
                }
                return (0, null);
            }
        }

        /// <summary>CP轉帳回來</summary>
        public GPTransResult CPTransferOutPlayerBalance(PGSlotTransTask transWork)
        {
            //UserData userData = Getuser(playerUid);
            UserData userData = transWork.UserData;
            int playerUid = transWork.PlayerUid;

            if (userData == null)
            {
                return GPTransResult.本地玩家錯誤; //Error Player not found
            }

            string player_name = userData.UserID;

            //string currency = CountrySetting.PGSCurrency; //"MYR";
            //製作本地交易序號
            //同1個轉帳, 若失敗重發api時, localTransId必須相同才能避免重複轉帳意外
            //string localTransId = ""; //本地交易序號
            int getIdResult = 1;
            string localTransId = transWork.LocalTransId;
            if (localTransId == null || localTransId == "")
            {
                getIdResult = GetDepositClientTransactionID(ref localTransId);
                if (getIdResult == 1)
                {
                    transWork.LocalTransId = localTransId;
                }
            }

            if (getIdResult == 1)
            {
                var task2 = CP.TransferOutPlayerBalance(player_name, 0, localTransId);
                var transResu = task2.Result;

                if (transResu.ErrorCode == "0") //通訊成功
                {
                    if (transResu.Data != null && transResu.Message == "Success") //轉帳成功
                    {
                        //將錢加回本地玩家Credit, 並更新UserTable
                        double balanceBefore = Math.Round(userData.UserBalance, Program.AccuracyDigitBal);
                        double amount = transResu.Data.Amount;
                        amount = Math.Round(amount, 6);

                        if (amount != 0) //有轉錢才紀錄 (這裡須要判斷負值嗎??)
                        {
                            double locamount = Math.Truncate((amount * 1000) + _H5EpsValue) / 1000; //本地端只接受3位小數
                            userData.UserBalance += locamount;
                            AddUserdataUpdateList(playerUid);
                            //將轉帳紀錄寫至DBLog
                            //string FSTransId = transResu.Data.TransactionId;
                            WritePGSTransferLog(playerUid, amount, balanceBefore, localTransId, localTransId, userData, TransOperType.轉回本地, TransOperChannel.CP);

                            if (CPDbuFg) MyConsole.WriteLine($"玩家:{player_name} CP取回: [{amount.ToString()}]");
                        }
                        else
                        {
                            if (CPDbuFg) MyConsole.WriteLine($"玩家:{player_name} CP取回: [無錢可取回]");
                        }

                        return GPTransResult.成功;
                    }
                    else
                    {
                        if (CPDbuFg) MyConsole.WriteLine($"玩家:{player_name} CP取回: [失敗] [{transResu.ErrorCode}] : [{transResu.Message}]");
                        return GPTransResult.錢包沒錢轉帳;
                    }
                }
                else if (transResu.ErrorCode == "-1")
                {
                    if (CPDbuFg) MyConsole.WriteLine($"玩家:{player_name} CP取回: [失敗(帳號不存在)] [{transResu.ErrorCode}] : [{transResu.Message}]");
                    return GPTransResult.遊戲商玩家錯誤; //CP無此玩家
                }
                else //轉帳失敗, 放棄?重試?
                {
                    MyConsole.WriteLine($"玩家:{player_name} CP Api 取回: [失敗] [{transResu.ErrorCode}] : [{transResu.Message}]");
                }
            }
            return GPTransResult.未完成;
        }
