        #region H5GameToken

        private bool EnsureH5RedisReady()
        {
            if (_h5RedisConn != null && _h5RedisConn.IsConnected && _h5RedisDb != null && _h5RedisServer != null)
                return true;

            lock (_h5TokenRedisLock)
            {
                if (_h5RedisConn != null && _h5RedisConn.IsConnected && _h5RedisDb != null && _h5RedisServer != null)
                    return true;

                if (_h5RedisInitialized)
                    return false;

                _h5RedisInitialized = true;

                try
                {
                    string conn = "";
                    string host = "127.0.0.1";
                    string port = "6379";
                    string password = "";
                    string user = "";
                    bool useSsl = false;
                    int db = 0;

                    if (File.Exists("RedisConnection.txt"))
                    {
                        foreach (var line in File.ReadLines("RedisConnection.txt"))
                        {
                            if (string.IsNullOrWhiteSpace(line)) continue;

                            var parts = line.Split(new[] { ':' }, 2);
                            if (parts.Length < 2) continue;

                            var key = parts[0].Trim();
                            var value = parts[1].Trim();

                            switch (key)
                            {
                                case "Redis":
                                case "RedisConnection":
                                    conn = value;
                                    break;
                                case "RedisIP":
                                    host = value;
                                    break;
                                case "RedisPort":
                                    port = value;
                                    break;
                                case "RedisPWD":
                                case "RedisPassword":
                                    password = value;
                                    break;
                                case "RedisUser":
                                case "RedisUsername":
                                    user = value;
                                    break;
                                case "RedisSSL":
                                    bool.TryParse(value, out useSsl);
                                    break;
                                case "RedisDB":
                                case "RedisDatabase":
                                    int.TryParse(value, out db);
                                    break;
                            }
                        }
                    }

                    ConfigurationOptions options;

                    if (!string.IsNullOrWhiteSpace(conn))
                    {
                        options = ConfigurationOptions.Parse(conn);
                        options.AbortOnConnectFail = false;
                    }
                    else
                    {
                        options = new ConfigurationOptions
                        {
                            AbortOnConnectFail = false,
                            ConnectRetry = 2,
                            ConnectTimeout = 5000,
                            SyncTimeout = 5000,
                            Ssl = useSsl,
                            DefaultDatabase = db
                        };

                        if (int.TryParse(port, out var redisPort))
                        {
                            options.EndPoints.Add(host, redisPort);
                        }
                        else
                        {
                            options.EndPoints.Add(host + ":" + port);
                        }

                        if (!string.IsNullOrWhiteSpace(user))
                            options.User = user;

                        if (!string.IsNullOrWhiteSpace(password))
                            options.Password = password;
                    }

                    _h5RedisConn = ConnectionMultiplexer.Connect(options);
                    _h5RedisDb = _h5RedisConn.GetDatabase();

                    // 立即驗證連線/認證，避免首次查詢才 timeout。
                    _h5RedisDb.Ping();

                    var ep = _h5RedisConn.GetEndPoints().FirstOrDefault();
                    if (ep == null)
                    {
                        MyConsole.WriteLine("H5 Redis endpoint not found.");
                        return false;
                    }

                    _h5RedisServer = _h5RedisConn.GetServer(ep);
                    return true;
                }
                catch (Exception ex)
                {
                    MyConsole.WriteLine("H5 Redis init failed: " + ex.Message);

                    try { _h5RedisConn?.Dispose(); } catch { }
                    _h5RedisConn = null;
                    _h5RedisDb = null;
                    _h5RedisServer = null;
                    _h5RedisInitialized = false;
                    return false;
                }
            }
        }

        static string GuidToBinary16Hex(string guidStr)
        {
            // 去掉 -
            string g = guidStr.Replace("-", "");

            // 前 3 段 Little Endian 轉換
            string data1 = g.Substring(6, 2) + g.Substring(4, 2) + g.Substring(2, 2) + g.Substring(0, 2);
            string data2 = g.Substring(10, 2) + g.Substring(8, 2);
            string data3 = g.Substring(14, 2) + g.Substring(12, 2);
            string data4 = g.Substring(16); // 後 8 bytes 原樣

            return (data1 + data2 + data3 + data4).ToUpper();
        }

        private sealed class H5RedisTokenPayload
        {
            public int UserUID { get; set; }
            public Guid Token { get; set; }
            public Guid GameToken { get; set; }
            public DateTime ExpireTime { get; set; }
            public DateTime CreateTime { get; set; }
            public DateTime LastActiveTime { get; set; }
            public string IpAddress { get; set; }
            public string UserAgent { get; set; }
            public bool IsRevoked { get; set; }
        }

        private static bool TryGetGuidProperty(JsonElement root, string propertyName, out Guid value)
        {
            value = Guid.Empty;
            if (!root.TryGetProperty(propertyName, out var element))
                return false;

            if (element.ValueKind == JsonValueKind.String)
                return Guid.TryParse(element.GetString(), out value);

            return false;
        }

        private static bool TryGetDateTimeProperty(JsonElement root, string propertyName, out DateTime value)
        {
            value = default;
            if (!root.TryGetProperty(propertyName, out var element))
                return false;

            if (element.ValueKind == JsonValueKind.String)
                return element.TryGetDateTime(out value);

            return false;
        }

        private static string TryGetStringProperty(JsonElement root, string propertyName)
        {
            if (!root.TryGetProperty(propertyName, out var element))
                return null;

            if (element.ValueKind == JsonValueKind.Null)
                return null;

            if (element.ValueKind == JsonValueKind.String)
                return element.GetString();

            return element.ToString();
        }

        private static H5RedisTokenPayload BuildH5RedisTokenPayload(JsonElement root, int userUid, Guid loginToken, Guid gameToken)
        {
            var now = DateTime.UtcNow;
            var payload = new H5RedisTokenPayload
            {
                UserUID = userUid,
                Token = loginToken,
                GameToken = gameToken,
                CreateTime = now,
                LastActiveTime = now,
                ExpireTime = now.Add(_h5RedisTokenTtl),
                IpAddress = TryGetStringProperty(root, "IpAddress"),
                UserAgent = TryGetStringProperty(root, "UserAgent"),
                IsRevoked = root.TryGetProperty("IsRevoked", out var revokedElem) && revokedElem.ValueKind == JsonValueKind.True
            };

            if (TryGetDateTimeProperty(root, "CreateTime", out var createTime))
                payload.CreateTime = createTime;

            if (TryGetDateTimeProperty(root, "LastActiveTime", out var lastActiveTime))
                payload.LastActiveTime = lastActiveTime;
            else
                payload.LastActiveTime = payload.CreateTime;

            if (TryGetDateTimeProperty(root, "ExpireTime", out var expireTime))
                payload.ExpireTime = expireTime;

            return payload;
        }

        private void NormalizeH5TokenCache(RedisKey sourceInfoKey, JsonElement root, int userUid, Guid loginToken, Guid gameToken)
        {
            if (_h5RedisDb == null || userUid <= 0 || loginToken == Guid.Empty || gameToken == Guid.Empty)
                return;

            var payload = BuildH5RedisTokenPayload(root, userUid, loginToken, gameToken);
            var effectiveTtl = _h5RedisDb.KeyTimeToLive(sourceInfoKey);
            var ttl = effectiveTtl.HasValue && effectiveTtl.Value > TimeSpan.Zero
                ? effectiveTtl.Value
                : _h5RedisTokenTtl;

            var normalizedJson = JsonSerializer.Serialize(payload);
            var infoKey = "userinfo:" + userUid;
            var tokenUidKey = "tokenuid:" + loginToken;
            var userTokensKey = "user_tokens:" + userUid;
            var gameTokenKey = "gametoken:" + gameToken;

            _h5RedisDb.StringSet(infoKey, normalizedJson, ttl);
            _h5RedisDb.StringSet(tokenUidKey, userUid.ToString(), ttl);
            _h5RedisDb.SetAdd(userTokensKey, loginToken.ToString());
            _h5RedisDb.KeyExpire(userTokensKey, ttl);
            _h5RedisDb.StringSet(gameTokenKey, userUid.ToString(), ttl);
        }

        public UserLoginToken GetH5UserGameToken(string Token)
        {
            try
            {
                if (!Guid.TryParse(Token, out var gameToken))
                    return null;

                if (!EnsureH5RedisReady())
                    return null;

                // 優先使用二級索引：gametoken:{GameToken} -> UserUID(int)
                // 相容舊資料：gametoken:{GameToken} -> LoginToken(Guid)
                var gameTokenIndex = _h5RedisDb.StringGet("gametoken:" + gameToken);
                if (gameTokenIndex.HasValue)
                {
                    // 新格式：gametoken -> UserUID
                    if (int.TryParse(gameTokenIndex.ToString(), out var userUid))
                    {
                        var userInfoRaw = _h5RedisDb.StringGet("userinfo:" + userUid);
                        if (userInfoRaw.HasValue)
                        {
                            using var doc = JsonDocument.Parse(userInfoRaw.ToString());
                            var root = doc.RootElement;

                            var isRevoked = root.TryGetProperty("IsRevoked", out var revokedElem) && revokedElem.GetBoolean();
                            if (isRevoked)
                                return null;

                            int cacheUserUid = userUid;
                            if (root.TryGetProperty("UserUID", out var uidElem))
                            {
                                cacheUserUid = uidElem.GetInt32();
                            }

                            Guid loginToken = Guid.Empty;
                            if (root.TryGetProperty("Token", out var tokenElem))
                            {
                                Guid.TryParse(tokenElem.GetString(), out loginToken);
                            }

                            if (loginToken != Guid.Empty)
                            {
                                NormalizeH5TokenCache("userinfo:" + userUid, root, cacheUserUid, loginToken, gameToken);
                            }

                            return new UserLoginToken
                            {
                                UserUID = cacheUserUid,
                                Token = loginToken,
                                GameToken = gameToken
                            };
                        }
                    }
                    // 舊格式：gametoken -> LoginToken
                    else if (Guid.TryParse(gameTokenIndex.ToString(), out var loginTokenGuid))
                    {
                        var userInfoRaw = _h5RedisDb.StringGet("userinfo:" + loginTokenGuid);
                        if (userInfoRaw.HasValue)
                        {
                            using var doc = JsonDocument.Parse(userInfoRaw.ToString());
                            var root = doc.RootElement;

                            var isRevoked = root.TryGetProperty("IsRevoked", out var revokedElem) && revokedElem.GetBoolean();
                            if (isRevoked)
                                return null;

                            if (!root.TryGetProperty("UserUID", out var uidElem))
                                return null;

                            var legacyUserUid = uidElem.GetInt32();
                            NormalizeH5TokenCache("userinfo:" + loginTokenGuid, root, legacyUserUid, loginTokenGuid, gameToken);

                            return new UserLoginToken
                            {
                                UserUID = legacyUserUid,
                                Token = loginTokenGuid,
                                GameToken = gameToken
                            };
                        }
                    }
                }

                // 相容舊資料：若尚未建立 gametoken 索引，退回掃描 userinfo 並回補索引。
                foreach (var redisKey in _h5RedisServer.Keys(pattern: "userinfo:*", pageSize: 500))
                {
                    var raw = _h5RedisDb.StringGet(redisKey);
                    if (!raw.HasValue)
                        continue;

                    try
                    {
                        using var doc = JsonDocument.Parse(raw.ToString());
                        var root = doc.RootElement;

                        if (!root.TryGetProperty("GameToken", out var gameTokenElem))
                            continue;

                        var gameTokenText = gameTokenElem.GetString();
                        if (!Guid.TryParse(gameTokenText, out var cacheGameToken))
                            continue;

                        if (cacheGameToken != gameToken)
                            continue;

                        var isRevoked = root.TryGetProperty("IsRevoked", out var revokedElem) && revokedElem.GetBoolean();
                        if (isRevoked)
                            return null;

                        if (!root.TryGetProperty("UserUID", out var uidElem))
                            return null;

                        var userLoginToken = new UserLoginToken
                        {
                            UserUID = uidElem.GetInt32(),
                            GameToken = cacheGameToken
                        };

                        if (root.TryGetProperty("Token", out var tokenElem) && Guid.TryParse(tokenElem.GetString(), out var loginToken))
                        {
                            userLoginToken.Token = loginToken;
                        }

                        if (userLoginToken.Token != Guid.Empty)
                        {
                            NormalizeH5TokenCache(redisKey, root, userLoginToken.UserUID, userLoginToken.Token, cacheGameToken);
                        }

                        return userLoginToken;
                    }
                    catch
                    {
                        // Ignore malformed cache payloads and keep searching.
                    }
                }

                MyConsole.WriteLine("Token not found in Redis, Token[" + Token + "]");
                return null;
            }
            catch (Exception ex)
            {
                MyConsole.WriteLine("GetH5UserGameToken Redis error: " + ex.Message);
                return null;
            }
        }
        #endregion
    }
